INSERT INTO `book_pages` VALUES (1,7,1,'02-05-2024','2026-04-14 08:41:41'),(4,10,1,'เหนือในลบสุดขอดพลจานแห่งทกเวรรษ\nกํานำเสนอโดย ก่อทักดี ไหยรักเมีทักติ์\n( วูป ) ทาวนี่ แระเธ์ . แพรัตน์ : เรีขบลียง','2026-04-17 09:49:10'),(5,10,2,'','2026-04-17 09:49:10'),(6,10,3,'หฑาามเทิมหสนที่แสัา\nฟ่านเสียนทราบมาว่ามีหญิงคณิกาหลายนางถูกฆ่าตาย จึงมาสืบคดี\nทีหอโอบจันทร์ การณ์กลับกลายเป็นว่าเจ้าของหอโอบจันทร์เป็นฟ่านซือ\nเจ้อกับองค์ชายสาม โดยมีสตรีของหลีจือเฉิงนามหยวนเมิงเป็นธุระจัดหา\nนางคณิกามาประจําหอ\nฟ่านเสียนสังปิดหอนางโลม คุมตัวฟ่านซือเจ้อกลับตึกตระกูลฟ่าน\nใช้กฎบ้านลงโทษมัน ทั้งซิงเนรเทศมันออกจากมหานครไปยังแควันเปยฉี\nโดยมีเอียนเอ๋อซึ่งเป็นนางคณิกาทีรักใคร่ชอบพอตามไปปรนนิบัติ ส่วนฟ่าน\nเสียนอยู่ในมหานครช่วยแก้ปัญหาที่ตามมาให้กับน้องชาย','2026-04-17 09:49:10'),(7,10,4,'','2026-04-17 09:49:10'),(8,10,5,'ฟ่านเสียนสัมป่าย\nช่วงเวลานี้สำนักตรวจสอบภายใต้การชีนำของฟ่านถีซื้อ และการสัง\nการของคุณชายเอี่ยน กัดขุนนางทีอยู่ฝ่ายองค์ชายรองไม่ปล่อย โดยยก\nเรื่องหอโอบจันทร์เป็นสือนำ ใช้เหตุการณ์ลอบสังหารทีหน้าสำนักว่าการ\nมหานครเป็นฐานราก หันไปต่อสู้ในราชสำนัก ทั้งรูกคืบในทางการค้า\nก่อนอื่นหนึ่งในแปดขุนพลประจําตัวองค์ชายรองเซียปีอันเสียชีวิต\nในคุกของสำนักว่าการมหานคร นี้ย่อมเป็นข้ออ้างให้กับสำนักตรวจสอบ\nหลังการประชุมรวมภายในสำนัก ได้ทําหนังสือกราบทูลสามฉบับ ในที่สุด\nข้าหลวงมหานครเถียนจิงมู่ถูกสังพักราชการรอการไต่สวน\nองค์ชายรองเพราะเพือป้องกันตัว ใช้กระบวนท่าที่โง่เขลาออกมา\nถูกทางสำนักรุกคืบทีละก้าว ลดอิทธิพลในมหานครขององค์ชายรอง อีก\nด้านหนึ่งเอียนปิงหวินเข้าควบคุมจุดสกัดบนเส้นทางจากแดนซินหยาง\nถึงมหานคร สร้างความเสียหายแก่ตระกูลชุยอย่างใหญ่หลวง ได้แต่ระดม\nเงินทุนจากบ้านเกิดที่แดนเจียงหนั้น เพื่อกรุยเส้นทางขึ้นเหนือ ซึ่งถูกปิด\nหลังการเสียชีวิตของเสินจัง ส่งผลให้รายรับขององค์ชายรองลดฮวบลง\nท่าทีของมวลชนที่มีต่อฝ่ายองค์ชายรองก็ไม่เป็นผลดี ถึงแม้ในวัง','2026-04-17 09:49:10'),(9,10,6,'ฆฑ ซ ๑ ไว\nเจ้าก็มีนักวางแผน แต่ไหนเลยสู้กับการปฏิบัติการและความเป็นมือ\nอาชีพของสำนักตรวจสอบได้ หากเปรียบกับเจ้าหน้าทีตึกทีแปด คนของ\nวังเจ้าทีส่งไปยังร้านน้ำชาเหลาสุราไม่สามารถครอบงําจิตใจผู้คน ถึงแม้ที\nผ่านมาสำนักตรวจสอบลงมือด้วยอํามหิต แต่ชาวมหานครยังยืนอยู่ฝ่าย\nตระกูลฟ่าน คิดเห็นว่าเอ้อเส้าแหยของตระกูลฟ่านที่หายสาบสูญ ตกเป็น\nแพะรับบาปขององค์ชายรอง ค่อยกระตุ้นให้ใต้เท้าเสียวฟ่านตอบโต้อย่าง\nดุดัน\nส่วนซือจือของจึงอ้องหลีหงเฉิงยิงมีชือเสียงเน่าเฟะ ผู้ใดให้มันข้อง\nแวะกับหยวนเมิง ชาวมหานครต่างทราบว่าฤดูใบไม้ผลิของปีหน้า หลีหง\nเฉิงจะตบแต่งคุณหนูใหญ่ตระกูลฟ่านเป็นภรรยา แต่มันกลับยุยงให้เด็ก\nหนุ่มอายุสิบสีปีเช่นฟ่านซือเจ้อเปิดซ่องคณิกา กล่าวโทษว่ามันสังฆ่าหญิง\nคณิกา มารดามันเถอะ ในโลกยังมีพีเขยทีหลอกใช้น้องชายภรรยาถึงเพียง\nดังนั้นฝ่ายองค์ชายรองถูกรุกไล่ถอยร่น ไม่มีปัญญาตอบโต้กลับไป\nพวกมันทดลองใช้ตึกตูฉาเอี่ยน ซึ่งอยู่ในความควบคุมของจ่างกงจู่ทําการ\nตอบโต้ แต่ก็เปล่าประโยชน์ ความเคลื่อนไหวของตึกตูฉาเยอี่ยนต้องทําตาม\nกฎหมายรัฐชิง จนใจที่ไม่อาจจับผิดอันใด ส่วนคดีฆ่าปิดปากพยานสำคัญ\nที่ฆ่าหญิงคณิกาหอโอบจันทร์ทั้งสามยิงเป็นคดีปริศนา ต่อให้มีคนคาดเดา\nว่าเป็นการลงมือของสำนักตรวจสอบ แต่ก็ไม่มีหลักฐาน\nท่าทีทีสำนักตรวจสอบมีต่อคดีฆ่าปิดปากนี้รวบรัดยิง คนร้ายทั้ง\nสามถูกคนในบ้านฟ่านถีซือส่งตัวให้กับสำนักว่าการมหานคร เหตุใดจึงถูก\nฆ่าแต่กลางคัน หากบอกว่ามีปัญหา ปัญหาอยู่ทีข้าหลวงมหานครเถียน\nจิงมู่ซึ่งมีการคบหากับองค์ชายรองต่างหาก\nฟ่านเสียนพึงพอใจต่อผลการประลองกำลังครั้งนี้ยิง จะอย่างไรในวัง\nมีเส้นแบ่ง ตนเองไม่อาจขับองค์ชายรองออกจากวัง ขอเพียงสามารถ','2026-04-17 09:49:10'),(10,10,7,'ติดเยแย เกาฑาองเหล่าเอ้อ (อันดับสอง) จนไม่คุกคามต่อตนเอง ทั้งระบาย\n: 1แส้กคราก็พอแล้ว\n\"แก่ตแส หนาดรวจสอบเพียงเปิดเผยขุมกำลังอันน่ากลัวออกมาส่วน\nปยกพหารครวังนี้ที่สะดวกราบรินถึงเพียงนี่ ทางหนึ่งเป็นเฉินผิงผิง\nยอบอาแรสงกานให้กับฟ่านเสียนเป็นการชั่วคราว ประการสำคัญยิงกว่า\nศึก ปฏิกหแรของฟ่านเสียนครั้งนี้ถูกกําหนดขึ้นตั้งแต่ตอนอยู่ทีเมืองสังจิง\nแตกแปแจเ ทกแน้นในหนังสือกราบทูลที่เสนอขึ่นไป กเอยถงความสมพนธิ\nค11คฑายนคงกับจ่างกงจู่ แต่ว่าครั้งนั้นฮ่องเต้ไม่ตอบกลับมา ครา\nคริาไยแวกงของหอโอบจันทร์ ฟ่านเสียนจึงรือฟันเอ่ยถึง\nแปเตแต้งใจจัดการกับคนไม่ทันระวัง ใช้ลมแรงพัดกระโชกเมฆ\nเยบายา1 หพากว่าเคริงนี้สำนักตรวจสอบไม่ชนะ เฉินผิงผิงคงโกรธแค้นจน\nแยะไดคป เพแจากเก้าอิล้อเลือน ดําทอเดยรัจฉานน้อยทั้งหลายรอบหนึ่ง\nไแวงแทษาความสงบไว้ตลอดเวลา รวมทั้งสูกุ้ยเฟยที่เป็นมารดาของ\nตาคฑากวเกง ไทหจือแห่งวังตะวันออก รวมทั้งฮองเฮาต่างระมัดระวังตัว ไม่\nแสดเทวางแพ้นถันใด ทั้งหมดทราบว่านี่แล้วแต่ฮ่องเต้\nตกงเต้ทําอะไร?\nไหแว้งง์ ข่าวว่า ฮ่องเต้เชิญคณะเต้าเคอแดนเจียงหนั้นเข้าวังมาเล่น\n1 6 พะที่ไนมหานครเกิดลมฝนปั้นป่วน ฮ่องเต้รัฐซิ่งกลับประทับอยู่เป็น\nเฟ่อแผกงไทเสา ทอดพระเนตรจิ้วทั้งวัน ไม่ทราบโปรยหว่านเงินออกไป\nเป ไต แหรงแสลําราญเพียงไหน\nไหทีสุตทั้งหมดค่อยเข้าใจ เจ้าชีวิตพระองค์นี้ไม่ทรงเห็นว่าเรื่องเล็ก\nทําเนคู่ค งรกับการดู เด็กหนุ่มทั้งหลายต่อยตีกันวุ่นวาย ไหนเลยน่าดู\nเท่เทหาเหแสดงของคณะงิวอันเลืองชือในแดนเจียงหนั้น?','2026-04-17 09:49:10'),(11,10,8,'หลังจากที่ทําความเข้าใจ ขุนนางที่วางตัวเป็นกลางตลอดมาค่อย\nพบเห็นความจริงข้อหนึ่งว่า ฟ่านเสียนเป็นที่โปรดปรานถึงเพียงไหน\nต่อสู้ของฟ่านเสียนเป็นใคร เป็นองค์ชายรอง เป็นราชโอรสของฮ่องเต้\nฮ่องเตด้กลับไม่ปกป้องฝ่ายหนึ่งฝ่ายใด นี้เป็นพระมหากรุณาต่อฟ่านเสียน\nถึงเพียงไหน\nแต่ว่าคนเหล่านี้ไม่กล้าล่วงเกินองค์ชายรอง ได้แต่ยืนพิงผนั่งกําแพง\nไว้ หยังเท้าอยู่ในดินโคลน ไม่โอนเอนไปทางฝ่ายหนึ่งฝ่ายใด\nความจริงข้อนี่ทําให้องค์ชายรองต้องสูดลมหายใจเข้าไปอย่างหนาว\nเหน็บ ทราบว่าหลายปีที่ตนเองเพาะสร้างกำลังในราชสำนัก ล้วนตกอยู่ใน\nสายพระเนตรของพระบิดา ถึงกับครุ่นคิด ฟ่านเสียนพอกลับถึงมหานคร\nก็มุ่งเป้าต่อตนเอง หรือได้รับการชีนำจากในวัง?\nแต่องค์ชายรองก็เป็นคนดุดันอํามหิต ทราบว่าสถานการณ์ปัจจุบัน\nสุดที่ตนเองจะล่าถอยได้ ต่อให้ตนเองยอมลดตัวขอจับมือกับฟ่านเสียน\nเป็นครังทีสอง ฝ่ายตรงข้ามไม่แน่ว่ามีอารมณ์เช่นนี้ มิหน้าซําท่าทีที\nคลุมเครือของฮ่องเต้ ทําให้องค์ชายรองทราบว่าหากตนเองไม่สามารถ\nโค่นฟ่านเสียนลง ได้แต่รอให้ฟ่านเสียนโค่นตนเองลงมาตามที่ลันปากไว้ใน\nร้านน้ำชา\nภายใต้แรงกดดันอันมหาศาล องค์ชายรองฝืนใจลงมืออีกครั้ง\nขุนนางอวิซีอตึกตูฉาเอี่ยนเข้าชือกันใหม่ ทําการกล่าวโทษฟ่านเสียน ครังนี่\nมีความผิดชัดเจน หลักฐานมัดแน่นหนา ระบูว่าฟ่านเสียนมีส่วนเกี่ยวข้อง\nกับเรื่องของฟ่านซื่อเจ้อ ทั้งยังลากดึงขุนนางสังซูกรมทะเบียนราษฎร์พระ\nกํากับดูแลทักษิณเข้ามา หนังสือกราบทูลส่งข้ามกรมราชทัณฑ์กับตึก\nต้าหลีซือ ส่งตรงมาถึงสำนักเหมินเซียเสิง เรียกร้องให้ลงโทษสองพ่อลูก\nตระกูลฟ่าน\nวันนี้ขุนนางกล่าวโทษหลายสิบท่าน รวมตัวกันมากกว่าครั้งก่อนที','2026-04-17 09:49:10'),(12,10,9,'แแส่ยน พากันคุกเข่าที่หน้าประตูวัง วันนี้ไม่มีฝน บนลานกว้าง\nแนเครื่องแบบขุนนางสีแดงเข้มหลายสิบชุดโชยพัดพลิว เป็น\nเกศุ กัขนางฉาซสำนักหลบเข้าประตูข้าง ไม่กล้ายุ่งเกียวมากความ\nหแหมายรัฐชิง ขุนนางที่ถูกกล่าวโทษต้องแก้ต่าง เช่นเดียวกับ\nคาแปกเพหน้านี้ คราครั้งนี้สองพ่อลูกตระกูลฟ่านต้องเข้าวังมาขออภัยโทษ\nตกลอด์ ต่อจากนั้นอธิบายแก้ต่างกลางท้องพระโรง แต่ฝ่ายองค์ชายรอง\n\"เม่ขุมถําลังกล้าแข็ง เกรงว่าสองพ่อลูกตระกูลฟ่านยากผ่านด่านโต้เถียง\n\"เพาะพักตร์ได้\nเหล่าขุนนางอวิชือตึกตูฉาเอียนมันใจอย่างเต็มเปียม ตระเตรียมโค่น\n\"แนางทุจริต” ที่สุดของรัฐชิง ทั้งพระกํากับดูแลทักษิณกับฟ่านเสียนลง\nเนกงเพราะครั้งนี่ต่างกับครั้งก่อน ครั้งนิพวกมันได้รับความช่วยเหลือจาก\nแทฑายรอง มีหลักฐานกล่าวโทษว่าตระกูลฟ่านกับตึกอีกว้อกงของตระกูล\nหน่งง์ส่วนเกียวข้องกับหอนางโลมอันอือฉาวเช่นหอโอบจันทร์\nถึงแม้ว่าตระกูลฟ่านส่งตัวฟ่านซือเจ้อออกไป ปล่อยหอโอบจันทร์\nพลูตจากมือ มาตรว่าฮ่องเต้ทรงพระกรุณา แต่หลักฐานความผิดชัดแจ้ง\nตฯะกถูลฟ่านต้องจ่ายค่าตอบแทนตามสมควร\nไม่เพียงแต่ขุนนางอวิซีอตึกตูฉาเอี่ยน ยังมีขุนนางจํานวนมากต้อง\nการดูฟ่านเสียนยอมรับผิด ขออภัยโทษ แม้แต่ต้าเสวียซือเช่นซูอู๋ ก็รอดู\nสภาาพอันทุลักทุเลของฟ่านเสียน\nแต่ไม่ว่าผู้ใดก็นึกไม่ถึงว่า ฮ่องเต้มีพระราชกระแสเบิกตัว ฟ่าน\nเสียนกลับไม่เดินทางมา มิเพียงแต่มันไม่มา แม้แต่พระกํากับดูแลทักษิณ\nกิไม่มา สองพ่อลูกนัดแนะกันใช้กระบวนท่าเดียวกันว่าไม่สบาย\nองค์ชายรองพอทราบข่าว ต้องตะลึงลานกับที นึกไม่ถึงว่าตระกูล\nฟ่านกระทําการอย่างเฉียบขาดถึงเพียงนี่ กลับไม่เปิดโอกาสให้ตนเองกู้หน้า','2026-04-17 09:49:10'),(13,10,10,'กลับคืน\nซูต้าเสวียซือซึ่งนั่งดื่มชาอยู่ในห้องพักหลังท้องพระโรงพอทราบข่าว\nถึงกับแทบพ่นน้ำชาออกมา วันนั้นมันเดินหมากกับฟ่านเสียน เด็กน้อยนั้น\nรับปากเป็นมันเหมาะ สุดท้ายกลับก่อเรื่องในมหานครถึงเพียงนั้น ทั้งยัง\nบอกว่าตนเองไม่อาจหักใจ “กินหมาก” สร้างความชขุ่นแค้นแก่ซูต้าเสวียซือ\nจนแทบกระอักโลหิต วันนี้ความจริงหวังว่าจะได้เห็นฟ่านเสียนแสดงความ\nทุเรศออกมา คิดไม่ถึงเด็กน้อยนี่อ้างว่าไม่สบายไม่มา\nข่าวที่สองพ่อลูกตระกูลฟ่านลาป่วยพอถูกส่งมาถึงท้องพระโรง\nฮ่องเต้ซึ่งทรงตรวจหนังสือกราบทูลจากเขตต่างๆ ก็งงงันวูบ จากนั้นขมวด\nพระขนง ไม่ได้รับสังอันใด\nผู้ที่ผิดหวังที่สุดคือเหล่าขุนนางอวีซีอตึกตูฉาเอี่ยนที่คุกเข่าอยู่หน้า\nประตูวัง เมื่อฝ่ายตรงข้ามอ้างว่าล้มป่วยไม่มา ขบวนที่จัดตั้งขึ้นก็ไม่อาจ\nใช้กำลังได้ สร้างความอืดอัดขัดข้อง ได้แต่สลายตัวไป\nผู้คนต้องรับประทานข้าวจึงเติบใหญ่ ทั้งมิใช่เทวราชคงกระพัน ไหน\nเลยไม่เจ็บไข้ได้ป่วย แต่ว่าสองพ่อลูกตระกูลฟ่านล้มป่วยอย่างประจวบ\nเหมาะ ทั้งป่วยหนักถึงเพียงนี้ ฟังว่าไม่สามารถลุกจากเตียงได้ ออกจะน่า\nประหลาดไปแล้ว โดยเฉพาะฟ่านเสียนเป็นศิษย์ของเพยเจี๊ยสำนักตรวจ\nสอบ ถึงแม้ไม่เคยตรวจรักษาคน แต่แม้แต่หมอหลวงในวังยังล่วงรู้ฝีมือ\nของมัน ไหนเลยล้มป่วยลงได้?\nไม่เพียงแต่ขุนนางในราชสำนักไม่เชื่อ ชาวมหานครไม่เชื่อ แม้แต่\nพระชายาในวัง และฮ่องเต้ล้วนไม่เชื่อ ดังนั้นหลังจากเลิกประชุม ปรากฏ\nราชองครักษ์นำหมอหลวง รวมทั้งหงกงกงซึ่งน้อยครั้งจะออกจากวัง ยก\nขบวนไปยังตึกตระกูลฟ่าน มีราชโองการปลอบขวัญ พร้อมทั้งดูว่าสองพ่อ\nลูกตระกูลฟ่านป่วยเป็นโรคอันใด\nมีคนจํานวนมากตามหลังขบวนมา เนื่องเพราะทุกคนเข้าใจว่าสอง','2026-04-17 09:49:10'),(14,10,11,'ปเกตนะถุลฟ่านแสร้งป่วย ดังนั้นพากันครุ่นคิด พ่อลูกคู่นี้คิดหลีกเลียง\nเพพาาแสตงความทุเรศกลางท้องพระโรง กลับกระทําความผิดฐานทูลเท็จ\nเหแคงมโง่เขลาอย่างยิง และอุกอาจอย่างยิง\nกงคชายรองก็ขบคิดไม่เข้าใจ มันเป็นราชโอรส เติบโตขึ้นในวัง\nแวหรมอของหงกงกง ไม่ว่าผู้ใดแสร้งป่วย อย่าคิดหมายตบตาขันทีชรา\nฟ่านเสียนล้มป่วยจริงๆ\nข่าวนี้ได้รับการยืนยันจากหงกงกง ภายหลังเหตุการณ์ฮ่องเต้ไม่มี\nกทลงโทษอันใด จนแพร่กระจายไปทัวมหานคร ไม่มีผู้ใดเคลือบแคลงสงสัย\n) เฟ่านเสียนแสร้งป่วยอีก ถึงแม้ว่าพระกํากับดูแลทักษิณเพียงถูกความเย็น\nแทนกซึม แต่ใต้เท้าเสียวฟ่านล้มหมอนนอนเสือลุกไม่ขึ้นจริงๆ\nในการต่อสู้ช่วงชิงระหว่างสำนักตรวจสอบกับองค์ชายรอง การล้ม\n(ป่วยของฟ่านเสียนออกจะประจวบเหมาะไปแล้ว\nความจริงข้อนี้สะกิดให้ผู้คนเกิดความรู้สึกที่แปลกประหลาดขึ้น นึก\nโยงไปว่าสถานการณ์ในมหานครจะเกิดความเปลี่ยนแปลงหรือไม่ จะ\nอย่างไรในประวัติศาสตร์เคยเกิดเหตุการณ์เช่นนี้ ครั้งกระโน้นฮ่องเต้เปยเว่ย\nเตรียมคิดบัญชีกับตระกูลจ้านซึ่งมีเกียรติประวัติในการรบอย่างโชกโชน\nยอดขุนศึกจ้านชิงฟงบังเอิญท้องร่วงเป็นเวลาสามวัน\nประวัติศาสตร์แม้เหลวไหล แต่ก็เป็นความสัตย์จริง\nฟ่านเสียนมองดูมู่เถียทียืนอยู่หน้าเตียงกล่าวว่า “ไม่ต้องเป็นห่วง\nทุกประการทําตามแผนของคุณชายเอียน\nหลังจากกลับจากสำนักว่าการมหานคร มันก็ล้มป่วยลง ถึงแม้ไม่\nหนกหนา แตภายหลังการต่อสู้กับเซียปอัน ก็เริมควบคุมพลังลมปราณ','2026-04-17 09:49:10'),(15,10,12,'ไม่ได้ ปล่อยให้วิงเตลิดอยู่ในเส้นลมปราณ จนต้องใช้เวลาหลับลึกสงบจิตใจ\nมากกว่าเดิม ใบหน้าที่ขาวซีดและลักษณะที่แปลกประหลาดของเส้น\nลมปราณ กลับตบตาหงกงกงซึ่งมีพลังฝีมือลึกลําสุดจะหยังได้','2026-04-17 09:49:10'),(16,10,13,'ม่ถาพหาบหุมพสับ\nครึ่งคืนหลังของฤดูชิวเทียน จันทราลาลับ อาทิตย์ยังไม่ลอยขึ้น คง\nเหลือแต่ท้องฟ้าสีครามดํา ตึกหลังของตระกูลฟ่านบังเกิดเสียงไออย่าง\nงแผวง ผ่านไปเนินนานยังไม่ขาดหาย สร้างความตื่นตระหนกแก่บ่าวไพร่\nทั้งหลายจนสะท้านตื่นจากความผัน ภายในสวนหลังเกิดความเคลื่อนไหว\nทีใกลาหลอยู่บ้าง\nอาจเป็นเพราะดินฟ้าอากาศ ไม่เพียงแต่พระกํากับดูแลทักษิณถูก\nคงามเย็นแทรกซึม บ่าวไพร่บางคนก็เป็นหวัดนำมูกไหล ถูกส่งตัวไปยังตัว\nต่าเไร่นาทีนอกเมือง ทีหลงเหลือไม่กล้าชะล่าใจ ทุกวันดีมยาทีต้าเส้าแหย\n(นายน้อยคนโต) เขียนเทียบยาให้ ตัวยานี้ได้ผลยิง สกัดโรคหวัดมิให้ระบาด\nกอกไป\nเสียงไอครั้งนี้ที่สร้างความแตกตื่นแก่คนในตระกูลฟ่าน เพราะว่า\nเสียงไอดังออกจากห้องของต้าเส้าแหย สองวันนี้ต้าเส้าแหยป่วยเป็น\nโรคประหลาด ไอหนักอย่างสาหัส แต่ไม่ยอมให้หมอหลวงเจียดยา พาน\nเชือมันฝีมือของตนเอง แต่ว่าผ่านไปหลายวัน อาการยังไม่ลดลง สร้าง\nความวิตกกังวลแก่บ่าวไพร่ในบ้าน กลววาตาเสาแหยซงดตอทุกผูคนจะ','2026-04-17 09:49:10'),(17,10,14,'เป็นไรไป\nหญิงรับใช้ซือซือใช้สายรัดสีแดงคาดหน้าผาก รัดผมเผ้าเอาไว้ ยืน\nอยู่ในห้องครัว ทางหนึ่งสูดดมกลินยาอันฉุนเฉียว ทางหนึ่งร้องสังให้หญิง\nรับใช้เร่งมือเร็วขึ้น นางเป็นคนที่ไหน่ไหนอ่าวต้านโจวส่งมายังมหานคร วัน\nฆ ฆซฑ ะ ๐ »\nหน้าต้องเป็นอนุภรรยาของฟ่านเสียน ดังนั้นคําพูดของนางมีนำหนักเป็น\nพิเศษ เหล่าหญิงรับใช้ทีลืมตางัวเงี่ยทราบว่าอาการป่วยของต้าเส้าแหยมี\nปัญหา พอเห็นนางมีโทสะต่างขบริมฝีปากไม่กล้าโต้เถียง\nซือซือชมดูอยู่ครู่หนึ่ง ในที่สุดไม่ไว้วางใจ จึงขนย้ายม้านั่งเล็กๆ มา\nตัวหนึ่ง นั่งอยู่หน้าหม้อยา มือถือพัดโบกเร่งไฟ จับจ้องมองปากหม้อที่\nปรากฏควันยาพวยพุ่งออกมา ถึงแม้ถูกรมจนตาแดงกํา ยังไม่กล้าชะล่าใจ\nตัวยานี้เตรียมให้ต้าเส้าแหยรับประทาน หากไม่เฝ้าดูด้วยตัวเอง ยากจะ\nวางใจได้\nภายในห้องนอน หลินว่านเอ้อสวมชุดยาวข้างในบูฝ้ายข้างนอกปัก\nทอลวดลาย นวดเฟ้นหน้าอกของฟ่านเสียน กล่าวอย่างระมัดระวังว่า “คิด\nทดลอง เทียบยาทีหมอหลวงเขียนให้หรือไม่?\nฟ่านเสียนไอจนหน้าแดงกํา พลางโบกมือคราหนึ่ง ฝืนยิมพลาง\nกล่าวว่า “มิต้องถึงขันนั้น อีกประการร่างกายของตัวเอง ตัวเองล่วงรู้เป็น\nอย่างดี รับประทานยาของตัวเองจะทุเลาหายดีเอง”\nหลินว่านเอ้อทราบว่าเซียงกงมีวิชาแพทย์เป็นเลิศ ไม่เช่นนั้นคงไม่\nรักษาโรคปอดที่เรือรังของตัวเองจนหายดี แต่ว่าหลายวันนี้มันไออย่าง\nสาหัส สร้างความเป็นห่วงอยู่บ้าง ต้องขบริมฝีปากกล่าวว่า “แม้แต่หง\nกงกงยังตรวจสมุฏฐานของโรคไม่ออก ท่านกลับบอกว่าล่วงรู้เป็นอย่าง\nดี ในความเห็นท่าน ” นางกลอกตาตลบหนึ่งแล้วกล่าว “ให้ข้าพเจ้าเขียน\nจดหมายถึงเฟยเซียนเซิง (ท่านทีแซ่เฟย) ดีหรือไม่?”\nฟ่านเสียนไออีกสองคํา ทราบว่าภรรยาไม่ไว้วางใจ จึงทอดถอนใจ','2026-04-17 09:49:10'),(18,10,15,'เหล่าวว่า “ท่านมิใช่ไม่ทราบว่า เหล่าซือ (อาจารย์) ของข้าพเจ้าออกท่อง\nเทียวไปทุกแห่งหน ต่อให้ท่านผู้เฒ่าคิดเร่งรุดกลับมา ก็ไม่ทราบเป็นวัน\nเวงลาได” มันยิมพลางกล่าวสืบต่อ “อาจบางทีอีกสามสีเดือน เมื่อถึงเวลา\nนนข้าพเจ้าคงกลับกลายเป็นคนตาย ส่วนท่าน ท่านกลายเป็นหญิงม่าย\nทึ่งตงามทีสุดของมหานครแล้ว”\nหลินว่านเอ้อร้องเพียติดต่อกัน กล่าวอย่างขุ่นเคืองว่า “ตอนนี่เป็น\nเงลาใด ยังกล่าวเหลวไหลอีก\nฟ่านเสียนยิมเล็กน้อย มันไม่ตื่นเต้นเท่าคนในบ้าน เนื่องเพราะทราบ\nง่าว่างกายตนเองเกิดเรื่องอันใด ยามนี้ที่ต้มยาหม้อ เพื่อช่วยบํารุงปอดกรุย\nซ่องโพรง สะสางเส้นลมปราณ สะกดอาการป่วยลง แต่ว่าสมุฏฐานของโรค\nต้องพึ่งพาตนเอง ขณะกล่าวปลอบโยนหลินว่านเอ้อ กลับซ่อนมือขวาของ\nตนเองอยู่ในผ้าห่ม\nมือขวาของมันสันระริกเป็นครั้งคราว นับตั้งแต่อยู่หน้าสำนักว่าการ\nเหท ซี\nมหานคร จนบัดนี้อาการยังไม่ดีขึ้น\nแว่วเสียงเคาะประตูคราหนึ่ง ซือซือถือชามยาเดินเข้ามาอย่าง\nระมัดระวัง หญิงรับใช้ซือฉีซึ่งนอนอยู่ห้องข้างลูกขึ้นมา ไขตะเกียงนำมัน\nบนโต๊ะ ยกโต๊ะเตียมาตั้งที่หน้าเตียงของเส้าแหยกับเส้าไหน่ไหน รับชาม\nยามา ใช้ช้อนคนยา ลดอุณหภูมิของยาลง ค่อยป้อนให้กับฟ่านเสียน\nฟ่านเสียนดีมลงไป รู้สึกขมอยูบ้าง ต้องแลบลินเลิยริมฝีปาก ซือซือ\nชิงยัดยาอมให้กับมันเม็ดหนึ่ง ช่วยลดความขมในปาก ฟ่านเสียนอดหัวร่อ\nกล่าวว่า “ข้าพเจ้าเป็นถึงเหล่าแหย ยังต้องปรนนิบัติเช่นนี้หรือ?”\nซือซือยิมเล็กน้อยกล่าวว่า “เส้าแหย เมื่อวัยเด็กท่านกลัวรับประทาน\nยาทีสุด”\nฟ่านเสียนครุ่นคิด ยานำในโลกนี้ไม่สามารถเคลือบนำตาล เวลาดีม\nย่อมต้องขมวดคิวนิวหน้า','2026-04-17 09:49:10'),(19,10,16,'ซือฉีดึงผ้าเช็ดหน้าเนื้อแพรจากในแขนเสือ ช่วยเช็ดมุมปากให้กับ\nฟ่านเสียน กล่าวอย่างขึงขังว่า “เส้าแหย ตอนนี้ท่านเป็นคนไข้ ไม่อาจถือดี\nหลินว่านเอ๋อเห็นเช่นนั้น ไม่อาจทนดูอยู่บ้าง ด่าอย่างยิมแย้มว่า\n“อย่าได้เอาอกเอาใจมันถึงเพียงนี้\" ปากแม้กล่าวเช่นนั้น มือน้อยๆ ยังลูบ\nหลังของมัน ช่วยให้มันสบายขึ้น\nถึงแม้ฟ่านเสียนซ่องเสพกับชีวิตของต้าเส้าแหยเช่นนี้ เห็นว่าเวลา\nไม่สบายได้รับการปรนนิบัติถึงเพียงนี้ยังไม่เลวอยู่ แต่สุดท้ายยังสันศีรษะ\nยืนมือรับชามยามาดีมลงไปรวดเดียวหมดสิน ยกแขนเสือเช็ดมุมปาก ยิม\nพลางกล่าวว่า “ข้าพเจ้ามีอาชีพเสริมเป็นหมอ มิใช่เด็กทารก\nหญิงรับใช้ที่หน้าเตียงทั้งสองสบตากันแย้มยิม ไม่กล่าวว่ากระไร\nฟ่านเสียนเห็นว่าอาการไอของตนเองสร้างความวุ่นวายแก่หญิงรับใช้ในบ้าน\nรู้สึกไม่สบายใจอยู่บ้าง จึงกล่าว “ดีมยานี้แล้วคงไม่ไออีก พวกท่านไปนอน\nเถอะ ให้ยาโถว (คําเรียกหญิงรับใช้) ที่เฝ้าเวรกลางคืนเข้านอนด้วย คืน\nชิวเทียนอากาศหนาวเย็น หากถูกความเย็นแทรกซึมจะทําอย่างไร?”\n“ฟ้าใกล้สว่างแล้ว ยังนอนอันใด?”\n“นอนสักงีบยังดีอยู่”\nซือซือกับซือฉีทราบว่าต้าเส้าแหยผู้นี้เห็นอกเห็นใจผู้คนระดับล่าง\nมิหน้าซํากล่าวคําไหนคํานั้น จึงไม่กล้าโต้แย้ง รับคําแล้วล่าถอยออกจาก\nฟ่านเสียนลงจากเตียง เทน้ำชาถ้วยหนึ่งบ้วนปาก หลินว่านเอ้อเห็น\nเช่นนั้นอดกล่าวมิได้ว่า “ไม่สบายยังดีมชาทีเย็นชีด ไม่เป็นผลดีต่อร่างกาย\nฟ่านเสียนยิมพลางกลับมานั่งลงที่ข้างเตียงกล่าวว่า “บอกแล้วว่าโรค\nนี้มิใช่โรคทัวไป”\nสองสามภรรยาสนทนาอกครูหนง หลินว่านเอ้อเห็นมันไม่ไออีก คอย','2026-04-17 09:49:10'),(20,10,17,'ตแจงลง เก็บความง่วงเหงาขึ้นมา แต่เห็นมันไม่ยอมนอน จึงแข็งใจไม่\nสุดท้ายฟ่านเสียนไม่อาจทนดูได้ ยืนมือนวดไหล่นางเบาๆ ฉวย\nแงไข้กงมือลูบไล้จุดบนศีรษะนาง นางค่อยม่อยหลับไป\nฝฟ่านเสียนมองดูภรรยาทีหลับสนิท ทราบว่าหลายวันนี่นางเป็นห่วง\nตเนหง นูกเคียวกรําทั้งกายและใจ ต้องสันศีรษะคราหนึ่ง โรคของตนเอง\nไม่กางจพายดีเพราะการดูแล แตกต่างกับบิดา ซึ่งได้รับการรักษาจากตนเอง\nโเคควงามเย็นแทรกซึมของพระกํากับดูแลทักษิณค่อยดีขึ้น อีกสองวันก็\n\"งเหพายดี เพียงแต่บิดาอายุมากแล้ว มิใช่คนหนุ่มฉกรรจ์ จึงทุเลาช้ากว่า\nฟ่านเสียนโบกมือวูบ ดับตะเกียงนำมันบนโต๊ะซึ่งอยู่ห่างไปห้าเชซียะ\nกเกในห้องนอนก็ตกอยู่ในความมีด แต่มันยังลืมตาที่สูกใส ไม่สามารถหลับ\nแง เนื่องเพราะหลายวันนี้มันนั่งกรรมฐานเป็นเวลานาน ไม่เกิดความ\nง่วงเหงา\nมันใช้ปลายลินเลียกากยาซึ่งติดอยู่ในซอกพฟัน นึกถึงเทียบยาที\nตเแองเขียนขึ้น ดูเหมือนว่าตัวยาผ่านเข้าทางปอด ช่วยลดอาการไม่สบาย\nตวงตําแหน่งนั้น สร้างความภาคภูมิใจอยู่บ้าง พลางยืนมือดึงผ้าห่มบนร่าง\n1เรรยาขีนมา จากนั้นสอดมือไปยังช่องลับที่ใต้หมอน ล้วงถุงยาใบเล็กๆ\nออกมา ภายในถุงบรรจุยาเม็ดกลมเกลียงอยู่หลายเม็ด\nภายในห้องแม้มีดมิด แต่ฟ่านเสียนทราบว่ายาเม็ดเหล่านี้เป็น\nสีแดง ถึงแม้ว่าตั้งแต่เล็กจนโต เฟยเจียสังให้พกยาเม็ดนี้ติดตัว ป้องกัน\nว่าการฝึกฝีมือของตนเองเกิดบปัญหา ยามใดที่ลมปราณอันกราดเกรียว\nฑลายเส้นลมปราณภายในกายออกมา ยาเม็ดนิจะเป็นตัวยาช่วยชีวิตของ\nฟ่านเสียนเมื่อวัยเด็ก ตอนทีใช้ชีวิตทีอ่าวต้านโจว เฟยเจียก็พบเห็น\nปัญหาข้อนี่ เคล็ดวิชานิรนามซึ่งอู่จู้ทึงให้กับฟ่านเสียน หรอสมควรบอกวา','2026-04-17 09:49:10'),(21,10,18,'เป็นมารดาทิึงให้แก่ฟ่านเสียน หากฝึกปรือสำเร็จ จะเพาะสร้างเป็น\nลมปราณอันกราดเกรียว ปัญหาอยู่ทีลมปราณนี้พยศดร้ายเกินไป หากผู้คน\nทัวไปฝึกปรือ เกรงว่าฝึกปรือไม่นาน เส้นลมปราณภายในกายจะแตกระเบิด\nคนกลับกลายเป็นมนุษย์ผักไป\nแต่หากเปรียบกับผู้คนในโลกนี้ ฟ่านเสียนมีความแปลกพิเศษอย่าง\nหนึ่ง นั้นคือเส้นลมปราณของมันทั้งหยาบและถ่างกว้างกว่าผู้คนทัวไป\nเพราะเหตุนี้มันเริมฝึกเคล็ดวิชานิรนามตั้งแต่วัยแบเบาะ พออายุสีขวบก็มี\nพลังลมปราณที่น่าตระหนก เส้นลมปราณหาแตกระเบิดไม่\nแต่เฟยเจียเคยบอกว่า พลังลมปราณภายในกายของมันยิงสะสม\nมากขีน ยิงจะยิงสมบูรณ์เปียมล้น สักวันหนึ่งเส้นลมปราณตามธรรมชาติ\nไม่อาจรองรับได้ อย่างนั้นฟ่านเสียนจะพบกับความเจ็บปวดทรมานแล้ว\nแต่ว่าผ่านไปสิบกว่าปี ฟ่านเสียนไม่รู้สึกถึงอันตรายส่วนนี่\nลมปราณภายในกายแม้กราดเกรียว แต่ยังอยู่ในความควบคุมของตนเอง\nโดยเฉพาะหลังอายุสิบสองปี ฝึกเคล็ดวิชาท่อนแรก สำเร็จ พลังลมปราณ\nภายในกายก็คล้ายคลืนลมที่สงบนิง เชืองเชือเป็นอย่างดี ไม่ส่งผลในเชิง\nล\"แต่อมันแต่อย่างไร\nดังนั้นฟ่านเสียนค่อยๆ คลายการระวังป้องกัน ถึงกับแทบลืมเรื่องนี้\nไป ทั้งไม่พกตัวยาติดตัว หากทึงอยู่ในบ้าน นอกจากตอนเดินทางขึ้นเหนือ\nไปกังแคว้นเปยฉี กลัวว่าอาจเกิดอุบัติเหตุขึ้น จึงพกตัวยาไปเม็ดหนึ่ง\nสตท้ายไม่ได้ใช้ออก\nแต่ปัญหามักประดังมาในเวลาที่ผู้คนไม่ทันระวังป้องกัน\nหลังจากผ่านการเดินทางทีดูเหมือนปลอดภัย แท้จริงหวาดเสียว\nกนเตรายที่แคว้นเปยฉี พลังการฝึกปรีอและวิชาการต่อสู้ของฟ่านเสียน\nหล่อหลอมรวมเข้าด้วยกัน ทะลุทะลางต่านชันทีเก้า ก้าวสู่จุดสุดยอดของ\nลมปราณอันกราดเกรียวกฝักห กสําเว็จ ถึงกับสามารถปะทะหักหาญ','2026-04-17 09:49:10'),(22,10,19,'กหนเงเตา ซึ่งเป็นศิษย์อันดับแรกของราชศครูขู่เหอ มิคาดหลังจากทีโค่น\nซึ่งเป็นหนึ่งในแปดขุนพลประจําตัวองค์ชายรองที่หน้าสำนัก\nเหาะหานคร ลมปราณภายในกายก็ไม่ยอมอยู่อย่างสงบนิงต่อไป\nเลียบเส้นลมปราณขึ้นมา\nหนที่เชือมโยงเข้าด้วยกันสองสายคล้ายวงกลมสองวงหมูนเวียนอยู่\nกกไนเกายมันในสภาพหนึ่งบนหนึ่งล่าง เริมมีอาการกระสับกระส่าย ไม่\nกคงเหยุดนิงอยู่ในเส้นลมปราณอีกต่อไป หากทดลองยืดขยาย และเจาะ\nทะลวงไปทัวสีทิศแปดทาง\nสองมือของฟ่านเสียนความจริงเป็นส่วนที่ควบคุมพลังลมปราณได้\nคที่สุด ยามนึกลับกลายเป็นปากด่านที่พลังลมปราณภายในกายคิดรัวไหล\nกอกมา มือขวาของมันที่สันระริกไม่หยุดยัง เป็นผลจากการทึกล้ามเนื่อ\nและเส้นลมปราณของมันไม่เชือฟังวาจาอีกต่อไป\nสภาพการณ์ยังไม่รุนแรง อย่างน้อยตอนนี้ยังอยู่ในภาวะที่ควบคุม\nไต้ หลังจากผ่านการหลับลึก ค่อยใช้จิตใจควบคุมลมปราณอันกราดเกรียว\nท่กระเทียนกระหือรือคิดเคลือนไหวไว้ได้ แต่ผลจากลมปราณทั้งสองสาย\nใโคจรย้อนทวน จึงกระทบกระเทือนถึงปอด ต้องส่งเสียงไอไม่หยุด หาก\nสภาพเช่นนี้ดําเนินต่อไป สักวันหนึ่งจะไม่สามารถควบคุมลมปราณอัน\nกราดเกรียวภายในกายได้\nฟ่านเสียนเคยคิดทดลองฝึกเคลิ็ดวิชาคริงหลัง แต่ตอนนี้ไม่มีความ\nคืบหน้าอันใด บางครั้งขณะที่ไออย่างสาหัส อดนกแคนทานอาอูจูทเฉกเชน\nมังกรเทพยดาเห็นหัวไม่เห็นหางมิได้ ครุ่นคิดว่าท่านทิ่งเคล็ดวิชาดูดดาว\nแก่เรา สมควรมีวิธีแก้ไขกระมัง?\nฟ่านเสียนกําถุงยาในมือ พลางขมวดคิวเข้าหากัน ก่อนหน้านี่มัน\nแยกแยะยาเม็ดทีเฟยเหล่าซือทิงไว้ คาดว่าเพราะสะกดลมปราณอันกราด\nยอดวิชาของยิมอิวเกียแห่งกระบีเย็ยยุทธจักร','2026-04-17 09:49:10'),(23,10,20,'เกรียว เฟยเจียคงจ่ายยารุนแรง มันไม่แน่ว่าพอรับประทานยาเม็ดนี้ลงไป\nจะเกิดผลสุดท้ายอย่างไร นี้ใช่เป็นตัวยาสลายพลังหรือไม่?\nหรือว่าพลังลมปราณที่ตนเองใช้เวลาสิบกว่าปีฝึกปรือสำเร็จต้อง\nสลายไปในชั่วพริบตา ต่อให้ไม่สลายพลัง เกรงว่าพลังลมปราณจะมลาย\nหายไปกว่าครึ่ง\nแต่หากว่าไม่รับประทาน หรือจะปล่อยให้พลังลมปราณระเบิดร่าง\nตนเองเป็นผุยผง ต่อให้ไม่น่ากลัวถึงเพียงนั้น แต่มือขวาสันระริกไม่หยุด\nไม่ว่าอย่างไรก็ไม่น่าดู ตนเองอายุยังเยาว์ จะกลายเป็นฟ่านเอ้อที่ป่วยเป็น\nโรคพ่าจินเซิน หรือ?\nระหว่างรับประทานกับไม่รับประทาน เป็นปัญหาใหญ่ประการหนึ่ง\nที่ห่างไกลแว่วเสียงไก่ขัน ปลุกดวงอาทิตย์ตื่นขึ้น และขับไล่รัตติกาล\nไป แต่ผู้คนทั้งหลายยังหลับใหล ฟ่านเสียนเงยหน้าขีน ค่อยทราบว่าตนเอง\nนั่งอยู่ข้างเตียงครึ่งชั่วยาม อดยิมเยาะตนเองมิได้ ตนเองที่กลัวตายเมื่อ\nเผชิญปัญหายุ่งยาก ที่แท้แสดงออกถึงความขลาดเขลาและลังเลถึงเพียง\nมันนึกปลอบใจตัวเอง อาจบางทีนี้เป็นจุดหัวเลียวหัวต่อประการ\nฟ่านเสียนท่องเคล็ดวิชาในใจ ไม่พึงสายนำเชียวหมูนรอบ ชักนำ\nอุทกฟ้ากรอกกายา จากนั้นนั่งอยู่ข้างเตียง เข้าสู่ภวังค์หลับลึกสะกดพลัง\nลมปราณที่วิงพลุ่งพล่านไว้ในเส้นลมปราณ จากนั้นรังกลับคืนสู่ด่านเซวีย\nซานที่ชายโครงด้านหลัง\nแต่แล้วฟ่านเสียนฉุกใจคิด ลืมตาขีนมา หยิบฉวยเสื่อผ้าคลุมกาย\nผลักประตูออกไป เดินถึงซอกมุมทีเปลียวร้างที่สุดในสวนหลัง ซึ่งเป็นลาน\nขนาดเล็กที่ตนเองเคยซักซ้อมวิชาซัดเข็มพิษ\nโรคพาร์กินสัน','2026-04-17 09:49:10'),(24,10,21,'ภาไมเต้องเสาะหา ก็พบเห็นท่านอาประหลาดทีใช้แถบผ้าสีดําผูกตา\nฝีแยู่ข่ เงแขาจําลอง\nฟ่ \"แลี่ยนอดสันศีรษะทอดถอนใจมิได้กล่าวตัดพ้อว่า ทแททานยง\nไงบาสลาเมมา”','2026-04-17 09:49:10'),(25,10,22,'','2026-04-17 09:49:10'),(26,10,23,'ฑูอ่นปีที่ฬาททัน\nข๓บฟ้าขาวโพลนรําไร ลานตึกปรากฏลมโชยเฉือยฉิว ทุกที่ทางมีด\nล ง \' ซ่ ๐ ข้ ๓ & ซื\nตริ้มเล็กนราง คนทีข้างภูเขาจําลองสวมเสื่อผ้าเนื้อหยาบ ข้างเอวเสียบ\nเหน็งเจาะด้ามหนึ่ง ใบหน้าผูกแถบผ้าสีดํา คล้ายหลอมกลืนเข้ากับสิง\nปผูกสร้างรอบข้าง ไม่ส่งเสียงผิดปรกติใด กระทั้งความรู้สึกของการดํารง\nตงแยู่ก็เลือนลอย เกรงว่าต่อให้มีบ่าวไพร่เดินผ่านข้างกายมัน ก็ไม่พบเห็น\nฟ่านเสียนมองดูญาติสนิททีอยู่ร่วมกันทุกเช้าคําเป็นเวลาสิบหกปี\nพกครุ่นคิดว่าไม่ได้พบกันมานาน ในใจกลับบอกไม่ถูกว่ามีรสชาติอย่างไร\nถึงกับคิดทุบตีมันรอบหนึ่ง แต่เป็นที่แน่ใจว่าสู้อีกฝ่ายไม่ได้ คิดโถมเข้าไป\nว1ไห้รําพันหรือ ท่านอาอู่จู๋หาใช่คนทีอารมณ์อ่อนไหวไม่\nดังนั้นมันได้แต่สันศีรษะ สะกดความปีติยินดีไว้ พลางเดินเข้าไป\nจากนั้นพบว่าในมือท่านอาอู่จู้ถือมีดเล่มเล็กๆ กำลังสลักสิงใดอยู่ พอเดิน\nเข้าไป ค่อยพบว่ากำลังแกะสลักแผ่นไม้\nฟ่านเสียนกลันหัวร่อไว้กล่าวว่า “ดีที่ไม่ได้แกะสลักรูปสตรี ไม่เช่น\nนั้นข้าพเจ้าคงยึดถือท่านเป็นทําฮวยตาบอด เป็นลิชิมฮัว นั้น หากแม้น\nลี่ชิมฮัวเป็นตัวเอกของเรื่องเชียวลีปวยตอ มีดบินไม่พลาดเป้า เคยสอบได้เป็นบัณฑิตทําฮวย จึงถูกเรียนขานเป็นลีทําฮวย','2026-04-17 09:49:10'),(27,10,24,'เป็นเช่นนั้น ข้าพเจ้าคงอาเจียนออกมา”\nทีเหนือความคาดหมายคือ ท่านอายอู่จู๋ก บผงกศีรษะกล่าวว่า “\nชิมฮัวเป็นบุคคลทีไร้ยางอายนัก\nคราครังนี้ถึงรอบฟ่านเสียนตะลึงลาน ชั่วครู่จึงกล่าว “ท่านรู้จัก\nอู่จู้ซูกเก็บแผ่นไม้กับมีดน้อยไว้ในอกเสือ กล่าวเสียงเย็นชาว่า “คุณ\nหนูเคยเล่าตํานานเรื่องนี้ให้ฟัง มิหน้าซํานางรังเกียจตัวเอกผู้นี้ที่สุด\nฟ่านเสียนยิมออกมากล่าวว่า “ดูท่าข้าพเจ้ากับท่านแม่คลับคล้าย\nชั่วครู่ให้หลัง ทั้งสองมายังห้องหนังสือที่เว้นลับที่สุดในตึกตระกูล\nฟ่าน ถึงแม้ว่ารอบบริเวณไม่ได้ติดตั้งกลไกอันใด แต่หากไม่ได้รับอนุญาต\nจากฟ่านเสียน ไม่มีผู้ใดสามารถเข้าใกล้ห้องหนังสือหลังนี้ แม้แต่พระกํากับ\nดูแลทักษิณก็ยอมรับกฎข้อนี่\nฟ่านเสียนกล่าวว่า “ลองบอกมาว่าครึ่งปีนี้ไปทําอะไร?”\nฟ่านเสียนเกิดความสนใจต่อวันเวลาทีอู่จู้หายสาบสูญอย่างยิง ถึง\nแม้ว่าแผ่นไม้นั้นยืนยันข้อสันนิษฐานของตนเอง แต่ข่าวปากัว ที่สะท้าน\nโลกเซชนนี้ ต้องให้คู่กรณีบอกออกมา จึงสร้างความเร้าใจเป็นพิเศษ ยาม\nนั้นมันคล้ายลืมเลือนพลังลมปราณทีวิงพลุ่งพล่านอยู่ในกาย และลมเลอน\nว่าตนเองสมควรเรียนถามท่านอาอู่จู้ว่า ตนเองควรรักษาชีวิตไว้อย่างไร\nมันกังจนน้ำชาให้กับตนเองถ้วยหนึ่ง แต่ไม่มีส่วนของอู่จู๋ เนื้อง\nเพราะถู่จูไม่ตันฑา\n“เราไปทางเหนท่อย เหน่ง”\nอู่ลุ่ขบคัดเล็กหตย พล้ 1เผยเคแกาแต่นทางของตนเอง แล้วจึงกล่าว\nถอสซิป','2026-04-17 09:49:10'),(28,10,25,'ขาหนหแนาไปยังแดนใต้เทียวหนึ่ง”\nกแส่ยนคุ้นชินกับรูปแบบความคิดที่ต่างกับผู้คนทัวไปของท่านอา\n1 ไม่ขุ่นข้องใจต่อคําตอบที่ไร้สาระนี้ หากใช้ความอดทนถามว่า “ไป\nพเหพแกท่าอะไร ลงใต้ไปทําอะไร?”\nผู้งูกล่าวว่า “เราขีนเหนือไปหาขู่เหอ” มันกล่าวเสียงราบเรียบ หา\nได้คาค่ดงว่าเรื่องนี้พอเปิดเผยออกไป จะขู่ขวัญผู้คนจนฝ่อตายสักเท่าใด\nปฟูแพเล่างเลืกว่า “ต่อยตีกันรอบหนึ่ง จากนั้นลงไปทางใต้ เสาะหาคนผู้หนึ่ง\nฟ่านเสียนหัวร่อออกมา ราชครูขู่เหอรับบาดเจ็บ ย่อมเป็นฝีมือของ\nฝ่าแกาตาบอดทีเบื่องหน้านี้ จากนั้นนึกถึงปัญหาข้อหนึ่ง ต้องกล่าวด้วย\nพางเถ่ในห่วงว่า “ท่านไม่เป็นไรกระมัง?”\nอู่จู๋เอียงคอมองดูไหล่ซ้ายตนเอง กล่าวว่า “ที่นี้รับบาดเจ็บ\nห เพตีแล้ว”\nยังคงเป็นคําพูดที่กะทัดรัดแต่กินความครอบคลุม แต่ฟ่านเสียนล่วง\n1ถึงความคับขันอันตรายของการนี้ มันเคยประมือกับไห่ถัง ล่วงรู้ขีดความ\nสามารถของซือฟู่เศียรโล้นของไห่ถังเป็นอย่างดี ท่านอาอู่จู๋แม้มีฝีมือสูง\nเที่ยม แต่หากให้ฝ่ายตรงข้ามรับบาดเจ็บ ตนเองคงต้องจ่ายค่าตอบแทน\nกอกไป ตอนนี้ทุเลาหายดีก็ประเสริฐ\nจากนั้นฟ่านเสียนขมวดคิ้วกล่าวว่า “เหตุใดต้องลงมือ?”\nอู่จู้กล่าวว่า “หนึ่งนั้นหากว่ามันอยู่ในแคว้นเปยฉี คาดว่าสร้างความ\nไม่สะดวกแก่ท่านอยู่บ้าง”\nฟ่านเสียนผงกศีรษะรับ ตอนที่ตนเองเดินทางไปเป็นทูตเชื่อม\nสัมพันธ์ หากว่าราชครูขู่เหอประจําการอยู่ที่เมืองสั้งจิง อาศัยกำลังของ\nตนเอง ไม่สามารถจัดการกับกำลังติดอาวุธของแคว้นเปยฉีเช่นนั้น และ\nได้รับข่าวสารที่เป็นประโยชน์ถึงเพียงนั้น\nอูจูกลาวสบตอ “สอง เราเหนวากาลกอนเคยรู้จกขูเหอ ดังนั้นไปหา','2026-04-17 09:49:10'),(29,10,26,'มัน สอบถามว่าครั้งกระโน้นเกิดเรื่องอันใด”\nฟ่านเสียนเงยหน้าขึ้น มองดูมันด้วยความตระหนก ห้วงสมองพลัน\nเกิดปฏิภาณวูบ นึกถึงเซียวเอินก่อนตาย เอ่ยถึงวิหารศักดิสิทธินั้น ต้อง\nขมวดคิวกล่าวเบาๆ ว่า “ อาจบางที สู (ท่านอา รู้จักจริงๆ อย่างน้อย\nเป็นเวลาเมื่อวัยเด็ก\nต่อจากนั้นบอกเล่าเรื่องราวที่ได้ยินจากเซียวเอินต่ออู่จ๋จนหมดสิน\nหวังให้มันสามารถหวนรําลึกถึงเรื่องสำคัญอันใด ยกตัวอย่างความสัมพันธ์\nระหว่างท่านอาอู่จู้กับวิหารศักดิสิทธิ เมื่อวัยเด็กเคยได้ยินท่านอาอู่จู๋บอก\nว่า มันกับมารดาหนืออกจากบ้านด้วยกัน หรือว่า บ้านหลังนั้นเป็นวิหาร\nอู่จู๋เงียบงันนิงนาน ไม่แสดงท่าทีกุมขมับครุ่นคิดจนถึงขันจิกทึ่งผม\nเผ้าตามคําบรรยายในนวนิยายทีเคยอ่านพบมา เพียงกล่าวสันๆ ว่า “เรา\nนึกไม่ออก”\nดังนั้นถึงรอบฟ่านเสียนกุมขมับบ้าง ต้องพืมพาว่า “นี้เป็นเรื่องราว\n?” มันสันศีรษะขับไล่ความผิดหวังในอกไป ถามว่า “หลังจากรับบาดเจ็บ\nไฉนไม่กลับมหานคร เมื่อรับบาดเจ็บยังลงใต้ไปหาผู้คนทําอะไร เอ๊ะ ใช่\nเป็นเพราะเยียหลิวหวินอยู่ทางใต้หรือไม่?”\nอู่จู้สันศีรษะอย่างเฉือยชากล่าวว่า “ทางใต้มีปัญหาอยู่บ้าง หลังจาก\nที่แน่ใจว่าขู่เหอรู้จักเรา เราก็ลงใต้ไป คิดเสาะหาคนที่มีปัญหานั้น น่า\nเสียดายทีหาไม่พบ”\nฟ่านเสียนปวดเศียรเวียนเกล้ากว่าเดิม ครึ่งปีนี้ตนเองอยู่ทางเหนือ\nท่านอาผู้นี่ก็ไม่ได้พักผ่อน หลังจากต่อยตีกับราชครูเปยฉี ทําการพิสูจน์ว่า\nจักกันหรือไม่ ก็ลงใต้ไปเสาะหาคน แต่ขู่เหอเมื่อรู้จักอู่จู๋ ใช่แล้ว เซียว\nเอินบอกว่าขู่เหอมีความสำเร็จทุกวันนี้เพราะมีส่วนเกี่ยวข้องกับการเดิน\nทางไปยังวิหารศักดิสิทธิ ตอนนั้นขู่เหอได้พบกับมารดา แต่ว่าตอนนั้น','2026-04-17 09:49:10'),(30,10,27,'ยเศไม่ได้กย่ว่วมกับอ่จ\nทงได้มีคนมีปัญหา นั้นเป็นผู้ใด ฟ่านเสียนใช้ความคิดอย่างเร่งร้อน\nปฝเพกหว่ แมอตอนอยู่ทีเมืองสังจิง ได้รับรายงานว่าทางใต้เกิดคดีฆาตกรรม\nตยเตค่กเนื่อง เอี่ยนปิงหวินให้ความสำคัญกับเรื่องนี้ ตระเตรียมร้องขอ\nแคกยพิทักษ์ทีเป็นกำลังส่วนตัวของฮ่องเต้ไปตามล่าคน แต่แม้กระทั้งท่าน\nผเยงกังหาคนไม่พบ วันหน้าเสียวเอียนคงคว้านำเหลว\nฟ่านเสียนสูดลมหายใจคําหนึ่ง สลัดเรื่องราวทีไม่ส่งผลกระทบต่อ\nตเแกงพ้นไป รายงานความเคลื่อนไหวของตนเองในครึ่งปีนื้ออกไป แม้แต่\nไพเลงระหว่างตนเองกับไห่ถังซึ่งไม่มีบุคคลที่สามล่วงรู้ออกไป นึกไม่ถึง\nก่แจาถ่จไม่มีปฏิกิริยาใด\nฟ่านเสียนทราบว่าท่านอาอู่จู้ไม่นิยมแสดงออก แต่ตนเองกระทําการ\nแม้แต่เซียวเอินยังถูกกําจัด ทั้งรูกฒาตองค์ชายรองถึงขันนี้ ท่าน\nพงเทาร มีปฏิกิริยาจากการฟังเรื่องราวอยู่บ้าง\nอู่จู้คล้ายรู้สึกถึงความคับข้องใจของฟ่านเสียน หลังจากขบคิดแล้ว\nจ \' ป ฆ ษ์\nจัง1แอกกล่าวว่า “ล้วนเป็นเรื่องเล็กน้อย”\nนั้นก็มิผิด ในสายตาของบุคคลระดับอู่จู๋กับฮ่องเต้ การต่อสู้ช่วงชิง\nฯะหว่างตนเองกับองค์ชายรอง ไม่ต่างกับเด็กทารกทะเลาะวิวาทกัน ส่วน\nข้อตกลงลับนั้น ฮ่องเต้อาจทรงสนพระทัย แต่ท่านอาอู่จู๋ย่อมไม่กังวลสนใจ\nฟ่านเสียนพอขบคิดเข้าใจ ต้องยิมเยาะตนเอง จากนั้นยืนมือขวาออกไป\nกล่าวว่า “ระหว่างนี้มือไม้สัน ท่านช่วยดูให้กับข้าพเจ้า”\nอู่จู๋พอทราบว่าพลังลมปราณภายในกายมีอาการแตกเตลิดออกจาก\nเส้นลมปราณ ยังคงสงบนิงจนไม่คล้ายเป็นผู้คน กล่าวว่า “เราไม่ได้ฝึกปรือ\nไม่ทราบควรทําอย่างไร”\nนี่เป็นเรื่องความเป็นความตาย ดังนั้นฟ่านเสียนอดขู่คํารามเบาๆ\nมิได้ว่า “นิเป็นสิงทีไม่มีหลักประกันความปลอดภัย ข้าพเจ้าพอถือกําเนิด','2026-04-17 09:49:10'),(31,10,28,'เกิดมา ท่านก็ให้ข้าพเจ้าฝึกปรือ หากฝึกจนถึงแก่ชีวิตจะทําอย่างไร?”\nอู่จู๋กล่าวอย่างเฉือยชาว่า “คุณหนูบอกว่านี้เป็นสิงที่ดีที่สุด เพียงแต่\nก่อนหน้านี้ไม่มีคนฝึกปรือสำเร็จ\nฟ่านเสียนจับพิรุธในคําพูดท่านอาอู่จู้ออก กล่าวว่า “แสดงว่ามีคน\nฝึกปรือล้มเหลว”\nอู่จู๋กล่าวโดยไม่ปิดบังว่า “นี้มิใช่ปัญหาใหญ่โต อย่างมากสลายพลัง\nลมปราณ กลายเป็นคนธรรมดา นอกจากท่านโง่เขลาจนถึงขันสุดท้าย ยัง\nคิดรักษาสิงทีเรียกว่าพลังลมปราณเอาไว้\nฟ่านเสียนขุ่นข้องใจยิง ท่านเป็นตัวประหลาด ย่อมไม่ทราบว่า\nาหรับผู้ฝึกวิชาบู๊ พลังลมปราณมีความสำคัญถึงเพียงไหน หากว่าตนเอง\n๑, เซ เจ\nญเสียลมปราณอันกราดเกรียว อย่าว่าแต่ต้องถูกไห่ถังสะกดไว้ แมแตศตรู\nแค้นจํานวนมากก็สามารถปลิดปลงตนเองได้ทุกเมื่อ\nฟ่านเสียนชูมือขวาทีสันระริกเล็กน้อยขืนกล่าวว่า “อย่างนั้นตอนนี่\nจะทําอย่างไร หรือจะปล่อยให้มันสันเทิมราวกับอู๋เมิงต๊ะ ตอนนี้เพียงแค่\nมือสัน รอจนพลังลมปราณภายในกายข้าพเจ้าพอกพูน เกรงว่ากระทั้งก้น\nยังบิดส่ายแล้ว”\nอู่จู้เงยหน้าขึ่น ดวงตาหลังแถบผ้าสีดําคล้ายมองดูฟ่านเสียนอย่าง\nเย้ยหยัน กล่าวว่า “ท่านไม่ฝึกปรือ พลังลมปราณย่อมไม่พอกพูนขึ้น\nคําพูดนี้ปลูกผู้คนตื่นจากความฝัน\nฟ่านเสียนคุ้นกับการหลับลึกฝึกลมปราณวันละสองครัง ไม่ได้นึกถึง\nการหยุดฝึก ยามนี้ค่อยได้คิด ก่อนที่จะค้นพบวิธีแก้ไข สิงทีตนเองพึงกระทํา\nคือหยุดการฝึกลมปราณอันกราดเกรียว ถึงแม้ว่าตอนต่อสู้ พลังลมปราณ\nภายไนกายจะขยายตัวตามธรรมชาติ แต่ยังดีกว่าตนเองคอยหล่อเลียงอยู่\nทุกเช้าคํา','2026-04-17 09:49:10'),(32,10,29,'ฟ่ \"แสล่ยนผงกศีรษะ ทอดถอนใจกล่าวว่า “ดูท่าได้แต่ทําเช่นนี่ ยืด\nเดาเขกากานแตกระเบิดช้าลง”\nกู่งพลันกล่าวว่า “เฟยเจียเคยทึงตัวยาให้กับท่าน\nฟ่ \"แสียนงงงันวูบ คิดไม่ถึงว่ามันยังจดจําเหตุการณ์เมื่อวัยเด็กของ\nตาแกงาได้ จึงผงกศีรษะรับ อธิบายว่า “ตัวยานั้นรุนแรงเกินไป ข้าพเจ้ากลัว\nเพอ็ประทานลงไป จะสลายพลังภายในกายจนหมดสิน”\nงงก้มศีรษะ คล้ายนึกถึงเรื่องอันใด จากนั้นกล่าวว่า “สมควรมี\nแปะไกซน ถึงแม้ว่ารักษาที่ปลายเหตุก็ตาม”\nยามนี้ฟ่านเสียนไม่กล้าเชือท่านอาผู้นี่ทั้งหมด จะอย่างไรเคล็ด\nแงหปราณนิรนามอาจทําร้ายคนถึงตาย แต่อีกฝ่ายทิงอยู่บนหมอนของ\n\"หแลง จึงฝืนยิมพลางกล่าวว่า “เรื่องนิรอไว้ภายหน้าแล้วค่อยว่ากล่าว ยัง\nหาเล่ยถึงเรื่องของท่านก่อน สู (ท่านอา) หลังจากนี้ก่อนที่ท่านจะหาย\nฯ \"แสญ สามารถบอกต่อข้าพเจ้าสักคําหรือไม่?”\nอู่จู้ถามอย่างขึงขังว่า “มีความจําเป็นเช่นนี่หรือ?\nฟ่านเสียนตอบว่า “มี ระหว่างทีเดินทางสู่แคว้นเปียฉี ข้าพเจ้าเข้าใจ\nง่าท่านอยู่ข้างกาย หีบสีดําใบนั้นก็สมควรอยู่ข้างกาย ดังนั้นข้าพเจ้ากล้า\nท่จะข่มเหงไห่ถังตว่อตวอ ไหนเลยคาดคิดว่าท่านไม่อยู่ หากเกิดเรื่องเช่น\n( อาจถึงแก่ความตาย”\nจู๋ลังเลเล็กน้อยแล้วค่อยกล่าว “อืมม์ ทราบแล้ว”\nฟ่านเสียนค่อยโล่งอก นับตั้งแต่เล็กจนโต มนคุนกบสภาพทลอูจอยู่\nห่างจากตนเองไม่ไกล เช่น อยู่ในรถม้า อยู่ในร้านเบ็ดเตล็ด อยู่บนหน้าผา\nริมทะเล หลังจากที่เข้าสู่มหานคร ช่วงเวลาที่ท่านอาอู่จู๋อยู่ข้างกายมันจะ\nลดลง ถึงแม้ว่าด้วยขีดความสามารถของตนเอง สามารถป้องกันตัว แต่\nมันทราบว่าพร้อมกับการพัฒนาการของตนเอง มันจะเผชิญการท้าทาย\nเซ ส ส เซ เข \'\nกวาน เมอมทานอาเซชนนอยูขางกาย จะให้ความรู้สึกว่าโลกนี้เส้นทางโปร่ง','2026-04-17 09:49:10'),(33,10,30,'โล่ง มีความปลอดภัยกว่าเดิม\nฟ่านเสียนส่งเสียงกระแอมกล่าวว่า “ข้าพเจ้าคิดย้ายออกไป การพัก\nอยู่ทีตึกหลังไม่สะดวกอยู่บ้าง เมื่อมีคนมาก ท่านก็ไม่อาจพักอยู่กับพวก\nถูจูเอยงศรษะ คลายตงขอสงสยวาตนเองพอเขาพก ไยต้องย้ายบ้าน\nฟ่านเสียนอธิบายว่า “ว่านเอ้อยังไม่ได้กราบสูสู (ท่านอา) ท่านเป็น\nตัฒ พล ณั ”\nคนทีข้าพเจ้าใกล้ชิดที่สุด ย่อมต้องพบกับภรรยาข้าพเจ้า\nอู่จู้กล่าวช้าๆ ว่า “เราเคยพบแล้ว”\nฟ่านเสียนฝืนยืมพลางกล่าวว่า “นางยังไม่ได้พบกับท่าน มิหน้าซํา\nทานเรรอนอยูขางนอก ข้าพเจ้าไม่ทราบว่าท่านพักอยู่ที่ใด ปรกติทําอะไร\nความรู้สึกนี้ทําให้ข้าพเจ้า ไม่สบายใจอยู่บ้าง\nอู่จู๋เอียงหน้าอีกครั้ง คล้ายค่อยเข้าใจว่าฟ่านเสียนคิดแสดงออกอัน\nใด มูมปากต้องสันกระตุกเล็กน้อย แต่ไม่ได้หัวร่อออกมา เพียงกล่าวช้าๆ\nว่า “ท่านจัดการตามสมควร แต่นอกจากภรรยาท่านแล้ว เราไม่ต้องการให้\nผู้ใดล่วงรู้ว่าเราอยู่ข้างกายท่าน”\nฟ่านเสียนผงกศีรษะด้วยความยินดี จากนั้นนึกถึงเรื่องหนึ่ง จึงกล่าว\n“กระทั้งเย่อเย่อก็ไม่ได้หรือ ข้าพเจ้าความจริงต้องการให้นางพบกับท่าน\nอู่จู๋ตอบว่าไม่ได้ จากนั้นกล่าวว่า “เช่นนี่เถอะ ท่านทํางานของท่าน\nถือว่าเราไม่ได้กลับมา”\nฟ่านเสียนทอดถอนใจ ได้ยินทีนอกห้องหนังสือบังเกิดเสียงบ่าวไพร่\nลูกจากเตียง ได้แต่นวดข้อมือพลางเดินออกจากห้องหนังสือ\nภายในห้องหนังสือ ใบหน้าที่ปราศจากความรู้สึกตลอดมาของอู่จู๋\nค่อยปรากฏรอยยิมขึื่นในรอบห้าร้อยปี มิหน้าซําเป็นรอยยิมที่ขบขัน คล้าย\nหัวร่อเยาะฟ่านเสียนไม่ล่วงรู้เรื่องบางประการ','2026-04-17 09:49:10'),(34,10,31,'ภายในสวนหลัง ปรากฏนำค้างแข็งเกาะบนยอดหญ้า แสงอาทิตย์\nฟ่านเสียนห่มผ้าห่มผืนหนึ่ง เอนกายบนตั้งเตียงภายในสวน บาง\nควาาส่งเสียงไอเป็นครั้งคราว แต่ดีกว่าเมื่อคืนมากนัก\nว เซ๑ม\nที่มุมสวนจัดตั้งชิงช้าอันหนึ่ง หญิงรับใช้หลายนางเล่นโล้ชิงช้า\nเจะโปรงสีอ่อนบานอยู่บนแผ่นไม้ทีผูกติดกับเชือกยาวราวกับกลีบดอก ที\nข่ เงข่งซ้ายืนไว้ด้วยซือซือกับซื้อฉี สีหน้าทอแววอิจฉาเลือมใส แต่ถือดีใน\nศัเตฐานะ ไม่คิดเล่นสนุกสักครา\nฟ่านเสียนหยีตามองดูกระโปรงของหญิงรับใช้บนชิงช้าบานออก\n\"ผ้ายกลีบดอกของดอกไม้ คล้ายร่มที่กระโดดลงจากกลางอากาศเมื่อชาติ\nป เงก่อน เผยเห็นกางเกงในสีขาวทีใต้กระโปรงอยู่รําไร อดนึกถึงภาพยนตร์\nเวียงขงเชวีย (นกยูง) มิได้\nมือข้างหนึ่งยืนจากด้านข้าง ป้อนผลจ๊อดําทีฝานจนเบาบางแก่มัน\nขนแหนง ฟ่านเสียนขบเคียวอยู่หลายครา สงเสยงออวา ็ไม่ไปปรนนิบัติ\nท่านพ่อ ไฉนมาหาข้าพเจ้า?”\nหลินว่านเอ๋อกับฟ่านเย่อเย่อแยกย้ายนั่งอยู่ข้างกายมัน ปรนนิบัติ\nคนไข้ผู้นี้ ฟ่านเย่อเย่อยืมพลางกล่าวว่า “เอาแต่จับเจ่าอยู่ในห้อง ข้าพเจ้า\nรู้สึกเบื่อ เกอเกอไม่สบาย ยังมีกะใจออกมาชมดูยาโถวทั้งหลายโล้ชิงช้า\nไนสวน”\nหลินว่านเอ้อกล่าวสัพยอกว่า “มันไหนเลยดูชิงช้า หากแต่มองดูคน\n\"นซิงซ้ามากกว่า”\nฟ่านเสียนไม่คิดอธิบาย ยิมพลางกล่าวว่า “เมื่อชมทิวทัศน์ ย่อมต้อง\nผนวกทั้งคนและทิวทัศน์เข้าไป” จากนั้นร้องบอกว่า “ซือซืออย่าได้วางตัว\nเป็นสะใภ้เล็ก คิดโล้ชิงช้าก็ขึ้นไป”\nคําพูดนี้ก่อให้เกิดความเข้าใจผิด คําพูดพอกล่าวจากปากค่อยรู้สึก','2026-04-17 09:49:10'),(35,10,32,'ตัว ดีทีหญิงสาวข้างกายฟังไม่ออก มันได้แต่ยิมอย่างกระอักกระอ่วน\nส่งเสียงกระแอมกลบเกลือน จากนั้นนึกได้เรื่องหนึ่ง จึงกล่าวกับหลินว่าน\nเอ้อว่า “ชิวเทียนยิงมายิงหนาวเหน็บ ท่านดู เบญจมาศในสวนเริมเหียว\nเฉา ครั้งก่อนบอกว่าในวังเตรียมจัดเทศกาลชมเบญจมาศ ไฉนไม่มีข่าว\nคราว รอจนหิมะแรกตกลงมา คิดชมดูก็ไม่สามารถชมดูแล้ว”\nหลินว่านเอ้อค้อนมันวงหนึ่ง กล่าวว่า “ปีนี้ซ้ากว่าปีที่ผ่านมา แต่มี\nข่าวมาว่าจะไปชมเบญจมาศด้ายทองที่วัดฮุ่ยคง เบญจมาศเหล่านั้นทนต่อ\nความหนาว ยังไม่โรยรา”\nฟ่านเสียนสันศีรษะ ทราบว่าการชมเบญจมาศที่เนินช้าออกไป\nสมควรเกียวข้องกับเหตุการณ์ในมหานคร ระหว่างนี้สถานการณ์ใน\nมหานครค่อยสงบลง ตนเองแสรังเป็นไม่สบาย ไม่เข้าประชุมในท้อง\nพระโรง ทําการแก้ต่าง คาดว่าทางองค์ชายรองคงร้อนใจขึ้นมา\nโล้สูงกว่านี้\nฟ่านเสียนเอนกายบนตั้งเตียง มองดูซือซื่อโล้ชิงช้า ยิงโล้ยิงสูงขึ้น\nคลายกบลอยขามกานแ พงตึกออกไป อดสงเสยงรองกระตุนม ได้','2026-04-17 09:49:10'),(36,10,33,'สานศุทยานเนหน\nชิงข้ายิงโล้ยิงสูง ซือซือที่อยู่กลางอากาศคล้ายเห็นอันใด ไม่เร่ง\nความเรวของชงชาอก ปล่อยให้ชิงช้าผ่อนช้าลง ชิงช้าไม่ทันหยุดนิง นาง\nก็รีบกระโดดลงมา กระทั้งรองเท้าที่อยู่บนพื้นหญ้าก็ไม่สวมใส่ รีบวิงมาทาง\nฟ่านเสียน\nเหล่าหญิงรับใช้ทีอยู่ด้านข้างสะดุ้งเฮือก ซื้อฉีขณะจะสัพยอกนาง\nแต่พอเห็นสีหน้านางก็ปิดปากลง จู่จือ (นาย) ทางด้านนี้ก็บังเกิดความ\nเคลือบแคลงสงสัย ยาโถวนี้ไฉนแตกตื่นลนลานถึงเพียงนี้ ด้วยบารมีของ\nตระกูลฟ่านยังกลัวแขกเหรืออันใด นอกจากปรากฏขันทีนำทหารรักษา\nพระองค์มายึดทรัพย์\nทีหน้าประตูตึก มีรถม้าของจิงอ้องแหย (ท่านอ๋องจิง)\nซือซือวิงกระหืดกระหอบถึงหน้าตั้งเตียง บอกกล่าวคําหนึ่ง ฟ่าน\nเสียนงงงันวูบแล้วค่อยได้คิด กระโดดปราดขืนจากตั้งเตียงร้องบอกว่า “รีบ\nถอย” ทางหนึ่งวิงไปหลังสวน ทางหนึ่งไม่ลืมเหลียวหน้ามาชมเชยซื่อซื่อ\nว่า “ยาโถวมีไหวพริบปราดเปรียว”\nดูจากความเคลือนไหวอันคล่องแคล่วของมัน ไหนเลยคล้ายคนป่วย\nทีเข้าร่วมประชุมในทั องพระโรงไม่ได้ หลินว่านเอ้อกับฟ่านเย่อเย่อสบตา','2026-04-17 09:49:10'),(37,10,34,'กนจูบ จากนั้นค่อยได้คิด รบลุกขนมา สังการให้บ่าวไพร่ออกจากตัวตึก\nและร้องบอกให้เถิงจือจิงจัดเตรียมรถม้า\nก่อนหน้านี้ยังเป็นสวนหลังทีสรวลเสเฮฮา ชั่วพริบตาก็กลายเป็น\nสมรภูมกอนการศก ทุกคนวุ่นวายเป็นการใหญ่ ทเกบตงเตยงกเกบตงเตยง\nเท ซั ซู ข\nทหลบหน้ากหลบหน้า ฝ่ายทีจัดเสือผ้าให้กับจู่จือ (นาย) รบรอนทสุด ใน\nทสุดจดการแล้วเสรจ ห้อมล้อมฟ่านเสียนมาถึงประตูหลังของติกหลัง ขณะ\nเดียวกันเถิงจือจิงขับรถม้ามาถึงหน้าประตูด้วยตนเอง\nหลินว่านเอือคลุมเสือคลุมลงบนร่างฟ่านเสียน ปากกล่าวตัดพ้อว่า\n“เสียวจิวจิว (พีชายคนเล็กของมารดา) ช่างเป็นไปเสียได้ บอกแล้วว่า\nไม่ต้องมาเยียม”\nฟ่านเสียนไหนเลยมีเวลาตอบคําได้ ชิงมุดเข้ารถม้าราวกับหน่วย\nจรยุทธ์ก็มิปาน\nหลินว่านเอ้อเห็นเสียวกู (นองสาวสาม) กมสหน้าตนเต็นตงเครยด\nโอบเตาใบเล็กๆ มุดตามฟ่านเสียนขึ้นรถไป รู้สึกเหนือความคาดหมาย\nต้องกล่าวว่า “เย่อเย่อ ท่านหลบหน้าอันใด?”\nซือซือพอเห็นรถม้าของวังเจ้าจิ้งอ้อง ฟ่านเสียนก็หลบลี้หนี้หน้า\nหลินว่านเอ้อเป็นภรรยา ย่อมเข้าใจสาเหตุความนัย ระหว่างนี้ตระกูลฟ่าน\nอยตีกับองค์ชายรอง หลี่หง เฉิงถูกฟ่านเสียนสาดน้าครําใส่ ระหว่างนี้ถูก\nจิงอ้องกั ภักขังอยู่ในวัง การมาของจิ้งอ๋องครั้งนี้ หนึ่งนั้นคิดสอบถามพระ\nกากบดู แลทักษิณว่าเป็นเรื่องราวใด สองคิดเจรจากับฟ่านเสียน สามเตรียม\nไกล่เกลียทั้งสองฝ่ายเลิกรากัน\nจึงอ๋องมีศักดิเป็นพระอนุชาฮ่องเต้ หลายปมานี้ลูกหลานตระกูล\nฟ่านให้ความเคารพต่อจิงอ้อง หากว่าอีกฝ่ายมาไกล่เกลีย ฟ่านเสียนยังมี\nหนทางใด แต่ฟ่านเสียนพานไม่อาจหย่าศึกกับฝ่ายองค์ชายรอง อย่าว่าแต่\nหากกลาวมากความ ด้วยสติปัญญาของคนสวนเพาะต้นกล้าผู้นี้ ไหนเลย','2026-04-17 09:49:10'),(38,10,35,'ตาตเตาไม่ออกว่าฟ่านเสียนคิดยัดเยียดของกลางป้ายผิดหลีหงเฉิง ฟ่าน\nเสียเเก้งเกรงกลัวผู้อาวุโสทีกล่าวคําหยาบคายผู้นี่จับใจ ดังนั้นได้แต่สะบัด\nในสามสิบหกกลยุทธ์ หนี้เป็นยอดกลยุทธ์\nฟ่านเย่อเย่อพอฟังวาจาของพีสะใภ้ต้องฝืนยิมออกมา กล่าวว่า “เส้า\n(พั่ละใภ้) พบกันยามนี้สร้างความกระอักกระอ่วนนัก”\nหลินว่านเอ้อค่อยได้คิดว่า เซียงกงโจมตีหลีหงเฉิง หากฟ่านเย่อเย่อ\nไม่พแก้บกงกง (พ่อสามี) ในอนาคต นับว่าไม่เหมาะสมจริงๆ หวนนึกถึง\nเซ่กงกงกับเสียวกูล้วนหลบหน้า ตัวเองรังอยู่ในตึกจะทําอย่างไร เมื่อนึกถึง\nป นาของเสียวจิวจิว ต้องสยิวกายอย่างหนาวเหน็บ หันไปหยิบฉวยชุดยาว\nขกงตัวเองจากมือซื่อฉีมูดขึ้นรถอีกคนหนึ่ง\nสองซงเม่ย (พี่ชายน้องสาว) ภายในรถงงงันวูบ ถามว่า “ท่านไฉน\nหลินว่านเอ้อค้อนทั้งสองวงหนึ่งกล่าวว่า “เสียวจิวจิวรุดมาคาดโทษ\nพวกท่านคิดให้ข้าพเจ้ายันไว้แต่ผู้เดียว ข้าพเจ้าจึงไม่โง่งมถึงเพียงนั้น\nบ่าวไพร่หญิงรับใช้ของตระกูลฟ่านล่วงรู้นิสัยใจคอของจึงอ้องแหย\nเป็นอย่างดี เห็นนายน้อยทั้งสามตื่นตระหนกถึงเพียงนี้ อดหัวร่อเบาๆ มิได้\nไนเสียงหัวร่อ เถิงจือจิงหวดแส้ม้าขับรถม้าทีไม่ได้ประทับเครืองหมายออก\nไปอย่างเงียบเชียบ\nรถม้าไม่ออกถนนใหญ่ หากอ้อมทางหลบหน้าบ่าวไพร่วังเจ้าจึงอ้อง\nไม่นานให้หลัง แว่วเสียงดังกังวานปานระฆังมหึมาดังลอดออกจากสวนหลัง\nมาว่า “เราถล่มมารดามัน ตัวบัดซบน้อยเหล่านั้นทราบว่าบิดามาแล้ว ล้วน\nสะบัดก้นหลบหนี้ เราน่ากลัวถึงเพียงนี้หรือ?\nนางหลิวซือซึ่งออกไปต้อนรับ พอฟังคํา “เราถล่มมารดามัน” ของ\nจึงอ้อง ต้องลอบขมวดคิว ลดสุ้มเสียงเบาลง กล่าวว่า “อ้องแหย เราบอก\nแล้วว่าเด็กทั้งหลายไปหาหมอที่ตัวเมืองตะวันตก”','2026-04-17 09:49:10'),(39,10,36,'จึงอ้องมองดูชิงช้าที่ยังแกว่งไกวเล็กน้อย ร้องเพ้ยกล่าวว่า “อากา-\nป่วยของฟ่านเจียนเป็นฟ่านเสียนรักษาทุเลา มันยังต้องไปหาหมออุบาท 3\nหนุ่มสาวภายในรถทั้งสามพอหลบหนืออกจากตึกตระกูลพ่าน รู้สึก\nตัวเบาสบาย แม้กระทั้งอากาศในมหานครก็สดชีนกว่าเดิม\nนับตั้งแต่ฟ่านเสียนกลับจากแคว้นเปียฉีก็เกิดเรื่องราวติดต่อกัน อย่า\nว่าแต่นำครอบครัวไปพักร้อนบนเขาชังซาน หรือพักผ่อนที่ตัวตึกทีนานอก\nเมือง ถึงกับไม่ได้ออกมาเดินเล่นในมหานคร หลายวันนี้เหตุการณ์สงบลง\nพอมีเวลาว่างอยู่บ้าง ก็ต้องแสร้งป่วยไม่เข้าประชุมในท้องพระโรง\nวันนี้จึงอ้องรุดมา คาดว่าพระกํากับดูแลทักษิณคงไม่มีโทสะที่ฟ่านเสียน\nหลบหนี้แล้ว\nฟ่านเสียนนั่งในรถม้า เลิกม่านหน้าต่างรถขึ้นเป็นช่อง มองดูทิวทัศน์\nและผู้คนบนท้องถนนร่วมกับหญิงสาวทั้งสอง เห็นแผงลอยข้างทางขาย\nอาหารทานเล่น ที่มูมถนนยังขายของแปลกทีหายาก ทุกทีทางสงบสันติ\nหลินว่านเอ๋อเชิดปากน้อยๆ กล่าวว่า “หลบหนี้นั้นหลบหนืออกมา\nแล้ว แต่ไม่สะดวกกับการลงจากรถ หรือจะทนอุดอู้อยู่ในรถ?”\nฟ่านเย่อเย่อก็ขมวดคิวกล่าวว่า “ตอนนี่เกอเกอไม่สะดวกกับการเผย\nโฉแแ เกอเกอท่านปลอมแปลงโฉมสักครังดีหรือไม่?”\nฟ่านเสียนยิมพลางกล่าวว่า “ต่อให้ชาวบ้านจดจําข้าพเจ้าไม่ออก\nแหว่อจตจําบูปผาทั้งสองช่อในมหานครไม่ได้?”\nหลินว่านเอ้อกับฟ่านเย่อเย่อแม้ทราบว่ามันจงใจยกยอ แต่ยังเกิด\nหลินว่านเอ้อเสนอว่า “ไปรับประทานอาหารทีเรือนอิสือจวีเถอะ\nเพม เห็กงพิเศษบนชันสามสักห้อง ไม่มีผู้ใดพบเห็นพวกเรา ทั้งยังจะได้ชม','2026-04-17 09:49:10'),(40,10,37,'เน่างไปประจวบเหมาะนัก ตอนนี้รถม้าพอดีแล่นถึงหน้าเรือนอิ๊สือ\nจุไป แส่ยนมองลอดหน้าต่างรถออกไป นึกถึงตนเองออกจากอ่าวต้าน\nไจ เถื่แห แคร ครั้งแรกที่ออกมาเดินเล่นก็รับประทานอาหารกับเม่ยเม่ย\nแผตี่ตทเขือนอิสือจวี ตอนนั้นกล่าวว่ากระไรลืมไปแล้ว ดูเหมือนเกียวข้อง\nคับทแต่ห แต่ต่อยหมัดทมิฬใส่คนของกว่อเป่าคุน ทั้งยังซื่อหนังสือ\nกนทแของก้อนหินฉบับละเมิดลิขสิทธิจากสตรึกลางคนเล่มหนึ่ง\nตฯะกูลกว้อถูกตนเองโค่นล้มลง ขุนนางสังซูกรมพิธีการกว้อโยวจือ\nทุ\"พการสอบแข่งขันฤดูชุนเทียนถูกประหารชีวิตในคุก แต่คดีรายนี้ไม่ได้\nปา:หางทั้งตระกูล ดังนั้นไม่ทราบว่ากว้อเป่าคุนระหกระเหินถึงที่ใด\nฟ่านเสียนไม่ตอบคําของหลินว่านเอฮ้อ หากกล่าวด้วยความเสียดาย\nแก่ห้างว่า “ที่หน้าร้าน ไฉนไม่มีคนเร่ขายหนังสือ?\nฟ่านเย่อเย่อเหลือบมองมันแวบหนึ่ง กล่าวเบาๆ ว่า “เกอเกอเปิด\n\" แหนังสือมิแสวงหา ซือเจ้อไปหาบุคคลหลายคน ทางการจึงเพิ่มความ\nเข้ยเงวด คนเร่ขายหนังสือในมหานครลดลงมากนัก”\n\" ; ซัซี ะ\nฟ่านเสียนงงงันวูบ ค่อยนึกออกว่าตี๋ตีเคยบอกว่าจะดําเนินการทั้ง\nทางตรงกับทางลับ ตัดการค้าละเมิดลิขสิทธิไป พอนึกถึงตอนนี้ต้องนึกถึง\nฟ่านซือเจ้อซึ่งเดินทางขึ้นเหนือ จึงกล่าว “ต้นเดือนหน้าซือเจ้อสมควรไป\nถึงเมืองสังจิง”\nภายในรถเงียบสงบลง หลินว่านเอ้อกับฟ่านเย่อเย่อสบตากันวูบ\nชั่วครู่จึงกล่าวเบาๆ ว่า “ทางเหนือเหน็บหนาวยิง ไม่ทราบนำเสือผ้าไป\nเพียงพอหรือไม่?”\nฟ่านเสียนยิมเล็กน้อยกล่าวว่า “อย่าได้เป็นห่วงเรื่องนี้ มันอายสิบ\nแลว สามารถดูแลตัวเองได้\nปากแม้กล่าวเซนนี้ ในใจนึกถึงเรื่องอื่น อยางน้อยนิกรังเกียจฝาย\nขององคชายรองกวาเดม เหลยวดูเรอนอสอจว ยิงเห็นเป็นทิขัดตา','2026-04-17 09:49:10'),(41,10,38,'เสียงเย็นชาว่า “ตระกูลชุยจัดส่งเงินทองแก่เหล่าเอ้อ (อันดับสอง)\nจะไม่อุดหนุนกิจการของตระกูลมัน”\nหลินว่านเอ้อไม่สะดวกกับการกล่าวกระไร จะอย่างไรองค์ชายรถง\nกับนางอยู่ร่วมกันในวังเกือบสิบปี มีความรู้สึกผูกพันอยู่บ้าง ถึงแม้ว่าใน\nการต่อสู้ช่วงชิงระหว่างเซียงกงกับเปียวเกอ (ลูกพีลูกน้องทีเป็นบุรุษ) นาง\nเลือกอยู่ข้างฟ่านเสียน แต่ก็ไม่สะดวกกับการกล่าวโจมตืองค์ชายรอง ยาม\nนี้เห็นบรรยากาศน่าอึดอัด จึงหัวร่อพลางกล่าวว่า “เมื่อไม่สนับสนุนธุรกิจ\nของมัน ก็สนับสนุนธุรกิจของพวกเรา มิสู้ไปยังหอโอบจันทร์เถอะ”\nฟ่านเสียนสะดุ้งเฮือก ให้นำภรรยากับเม่ยเม่ยไปเที่ยวหอนางโลม\nหรือ ยามนั้นส่งเสียงกระแอมกล่าวว่า “หอโอบจันทร์มิใช่ธุรกิจของข้าพเจ้า\nหากเป็นของซีอฉ่างล\nหลินว่านเอ้อค้อนมันวงหนึ่ง กล่าวว่า “ผู้ใดไม่ทราบว่านั้นเป็นม่าน\nบังตา ท่านคิดเปิดหอนางโลมก็เปิดไป ข้าพเจ้าไม่มีความเห็นใด”\nฟ่านเย่อเย่อทีด้านข้างต้องกลันหัวร่อไว้\nฟ่านเสียนเลิกคิวขึ้นกล่าวว่า “เหตุใดบอกว่าข้าพเจ้าเปิดหอนางโลม\nท่านก็ทราบว่าข้าพเจ้าตามล้างตามเช็ดให้กับตี่ติ\nหลินว่านเอ้อกล่าวอย่างไม่ยินยอมว่า “สรุปแล้วเป็นการค้าพวกเรา\nเถง ท่านมิใช่บอกว่าทีนั้นมีอาหารเป็นเลิศหรอกหรือ พวกเราไม่ได้ไปหา\nหเญิงสาว เพียงรับประทานอาหารกลัวอะไร?”\nฟ่านเสียนกล่าวอย่างยืนกรานว่า “ท่านต้องการรับประทาน ก็ให้\nพผ่๓ครัวของหอปรุงแล้วส่งมาทีบ้าน หญิงสาวนางหนึ่งไปนั่งที่หอนางโลม\nงะใช้ได้อย่างไรกัน?”\nหลินว่านเอ้อแลบลินอย่างซุกซน กล่าวว่า “อาหารปรุงเสร็จแล้ว\nส4ฬา11 1 คงเยนชดแลว\nฟ่านเสียนกล่าวว่า “อย่างนั้นเรียกพ่อครัวมาทีนี้ พอใจแล้วกระมฆัง?”','2026-04-17 09:49:10'),(42,10,39,'หนลนว่าแแอ้อเห็นมันยืนกราน จึงทอดถอนใจคําหนึ่ง กล่าวว่า “ความ\nจรเคิดไปหังที่หอโอบจันทร์ ดูว่าเสียวสู (อาเล็ก) เปิดหอนางโลมอย่างไร”\nพเย พาเตากลมโตกล่าวว่า “ขอบอกตามตรง ข้าพเจ้าเกิดความสงสัย\n“ แพต่กสถานที่เช่นนั้น”\nฟ \"แย่อเย่อนิงเงียบงันตลอดเวลาพลันกล่าวว่า “ไปท่องเทียวก็ไป\nง พ เซีอ 0 ง ง 1 0 แผล๓๐5\nฟผกทยวง เห็นฟ่านเสียนคิดกล่าวกระไร จึงชิงกล่าวว่า “หญิงสาวไปนั่ง\nที่หกนางโลม จะใช้ได้อย่างไร หรือว่าพวกท่านบรรดาเหล่าแหย (นาย\n) ไปนั่งถือว่าใช้ได้?”\nนางยกมือเท้าขอบหน้าต่าง ยิมพลางกล่าวว่า “อีกประการ ได้ยิน\nแพหแทหบอกว่า ท่านให้แม่นางซังเหวินดูแลหอโอบจันทร์ ข้าพเจ้าไม่ได้ยิน\nนเหรืองเพลงขับกล่อมมาครึ่งปีแล้ว หากไม่ไปหอโอบจันทร์ จะไปฟังจาก\nหลินว่านเอ้อเห็นเสียวกูสนับสนุนความคิดของตัวเอง จึงขวัญกล้า\nกล่าวกับฟ่านเสียนว่า “ท่านก็ทราบว่าข้าพเจ้าชมชอบฟังเสียงร้อง\nขกงซังเหวิน ผ่านไปครึ่งปีไม่พบหน้าผู้คน ยามนิค่อยทราบว่าเป็นเสียวสู\nทีน่าชังแย่งชิงไปยังหอโอบจันทร์ ท่านนำพวกเราไปเถอะ”\nฟ่านเย่อเย่อกล่าวเสริมว่า “บุรุษไปเที่ยวได้ พวกเราไฉนไปไม่ได้?”\nฟ่านเสียนอับจนถ้อยคํา สํารวจดูเม่ยเม่ยเป็นพิเศษ พบว่ายาโถว\nนางนี้ยิงมายิงอุกอาจ มิหน้าซําความคิดอ่านต่างกับหญิงสาวอื่นในโลกนี้\nตูจากคําพูดก่อนหน้านี่ นางแสดงว่าโอ่อ่าผ่าเผย มีเหตุผลกว่า ถือสิทธิสตรี\nมากกว่าหลินว่านเอ้อ แน่นอน นิต้องโทษว่าตนเองให้การศึกษาแก่นาง\nตั้งแต่แรก แต่ก็มีความรู้สึกว่ายาโถวนี้ มีบุคลิกลักษณะไม่ธรรมดา คล้าย\nมาจากด้านอื่น\nฟ่านเสียนฝืนยืมพลางกล่าวว่า “ความจริงแล้วไปชมดูไม่เป็นไร\nพวกท่านก็ทราบว่าข้าพเจ้าไม่อยู่ในกรอบของทางโลก แตวา ระหวางน','2026-04-17 09:49:10'),(43,10,40,'มหานครไม่สงบเรียบร้อย ข้าพเจ้าไม่ต้องการให้ขุนนางกล่าวโทษมีข้ออ้าง\nมากกว่านี้”\nหลินว่านเอ้อกับฟ่านเย่อเย่อพอฟังมันเอ่ยถึงเรื่องสำคัญ ล้วนสงบ\nปากคําไว้\nฟ่านเสียนกวาดตามองออกนอกรถ ต้องงงงันวูบ พบว่าเบื่องหน้าที่\nห่างไปเป็นหอโอบจันทร์ ต้องด่าเถิงจือจิงทีทําหน้าทีขับรถอย่างยิมแย้มว่า\nท่านขับมายังทีนี่จริงๆ รู้จักแต่เอาอกเอาใจนายหญิง ไม่รู้จักคล้อยตาม\nความคิดของข้าพเจ้า”\nเถิงจือจิงหัวร่ออย่างโง่งม ไม่กล่าวว่ากระไร กลับเป็นหลินว่านเอื้อ\nและฟ่านเย่อเย่อล้วนปิดปากหัวร่อออกมา\nรถม้าตระกูลฟ่านมาถึงหน้าหอโอบจันทร์ ถึงแม้ยังไม่ทราบว่าคนที่\nนั่งในรถเป็นฟ่านเสียน แต่แผนกต้อนรับไหนเลยกล้าไม่คารวะ แม้แต่สือชิง\nเอ้อทีนอนพักรักษาตัวจากการถูกฟาดโบยอยู่ในห้องบนชันสามยังเดิน\nกะโผลกกะเผลกลงมา พอเห็นคนในรถเป็นฟ่านถีซือซึ่งมีข่าวว่าป่วยหนัก\nสือชิงเอ๋อต้องสะดุ้งเฮือกใหญ่\nคุณหนูสูงศักดิในรถได้เห็นเหล่าเปา อายุเยาว์ของหอโอบจันทร์\nรู้สึกพึงพอใจอยู่บ้าง แต่ทีสร้างความผิดหวังแก่พวกนางคือ ซังเหวินไม่ได้\nอยู่ในหอ ฟังว่าตระกูลขุนนางเชิญนางไปร้องขับขาน\nเมื่อไม่มีข้ออ้าง ฟ่านเสียนย่อมไม่อนุญาตพวกนางขืนหอไป แต่ใน\nใจสงสัยอยู่บ้าง ตอนนี้ซังเหวินเป็นอิสระแล้ว ทั้งยังเข้าสำนักตรวจสอบ\nเป็นการลับ ไม่ต้องไว้หน้าเชือพระวงศ์สูงศักดิ ไฉนยังไปร้องขับขานทีบ้าน\nผู้ใดมีหน้ามีตาถึงเพียงนี่?\nรถม้าแล่นออกจากหอโอบจันทร์ ฟ่านเสียนมองดูหญิงสาวทีผิดหวัง\nทั้งสอง ยืมพลางกล่าวว่า “เมื่อออกมาท่องเทียว ย่อมต้องหาความสําราญ\nแม่เจ้า','2026-04-17 09:49:10'),(44,10,41,'ไส่ต์! หกโคบจันทร์มิใช่สถานทีเลิศหรูที่สุด พ่อครัวของทีนี่ก็ไม่ได้ปรุง\nผาพาวไกฑะที่สุด”\nภ์1เไม่ทันกล่าวจบ หลินว่านเอ้อชิงกล่าวว่า “อย่าคิดหมายหลอก\nพยแวง ตอนนี้หอโอบจันทร์มีชือเสียงเรียงนาม หากบอกว่าหอหลังนี้ยัง\nไต้ไม่ไห้ .นอกจากท่านหมายถึงในวัง” นางหัวร่อฮิฮะกล่าวว่า “ข้าพเจ้าไม่\nกือพ เข้าเว้งไปหาเหนี้ยงเหนี้ยง (คําเรียกพระชายา แต่ว่าเซียงกงท่าน\nไม่กลงฝ่าบาทเห็นท่านแสร้งป่วย จะกริวหรือ?”\nฟ่านเสียนยืนมือบิดปลายจมูกของนาง กล่าวอย่างยิมแย้มว่า “อย่า\nไง\"ทปแซ่งข้าพเจ้า สถานทีซึ่งข้าพเจ้าจะนำพวกท่านไป ยังสะดวกสบาย\nอาหารที่ปรุงออกมาก็โอซะกว่าห้องเครื่องอีก\nหญิงสาวทั้งสองสงสัยใจยิง ครุ่นคิดขึ่น ทัวทั้งโลกหล้าไม่มีที่ใดมิใช่\nกแต่นฮ่องเต้ ไหนเลยยังมีสถานทีเลิศหรูกว่าในวัง ต่อให้พ่อค้าเกลือมีขีด\nกาายสามารถเช่นนี้ ก็ไม่มีผู้ใดกล้าอุกอาจไป\nรถม้าแล่นออกจากประตูเมืองด้านทิศใต้ พอถึงชานเมืองผู้คนบางตา\nทําลังกลุ่มย่อยของหวังฉีเหนี้ยนกับองครักษ์ตระกูลฟ่านได้แต่แสดงตน\nข่น. สบตากันอย่างงุนงง จากนั้นติดตามรถม้าคันนั้นไปยังภูเขาเล็กๆ\n1เวณชานเมืองลูกหนึ่ง\nยิงเข้าใกล้ภูเขา ทางภูเขาไม่คับแคบลง ยังคงตัดทางเท่ากับ\nทางหลวงของรัฐชิง แต่ว่าทิวทัศน์ข้างทางยิงร่มรีน ในพื้นหญ้าเหลืองซีด\nของชิวเทียนแทรกแซมด้วยดอกไม้ป่าบางตา หลังพื้นหญ้าเป็นต้นไม้\nเปลือกขาวกิงใบหรือมแหร็ม จัดลําดับเป็นชันๆ คล้ายภาพวาดของจิตรกร\nก็มิปาน\nหลินว่านเอฮ้อกับฟ่านเย่อเย่อทอดถอนใจชมเชย ทีนี่มีทิวทัศน์งดงาม\nแต่ว่ายามปรกติไฉนไม่ได้ยินผู้คนเอ่ยถึง แม้กระทั้งกาลก่อนออกมาท่อง','2026-04-17 09:49:10'),(45,10,42,'เที่ยวที่ชานเมืองก็ไม่ได้ผ่านมายังทีนี้ ตามเหตุผลสถานที่เช่นนี้สมควรทู\nในวังหรือขุนนางใหญ่ใดยืดครองไว้ ปลูกสร้างบ้านเรือนอยู่อาศัย\nตัวเองไม่ทราบว่าเป็นบ้านของผู้ใด?\nเห็นฟ่านเสียนแสร้งเป็นมีลับลมคมใน สร้างความขุ่นข้องใจแก่หญิงง\nสาวทั้งสอง พานไม่สนทนากับมัน เพียงชีนชมทิวทัศน์รอบข้าง\nเมื่อมาถึงสุดทางภูเขา รถม้าลดเลี้ยวผ่านดงไม้แถบหนึ่ง สวน\nอุทยานที่กินบริเวณกว้างขวางก็ปรากฏแก่สายตา คล้ายเป็นที่สถิตของ\nเซียนวิเศษก็มิปาน สิงปลูกสร้างในสวนอุทยานไม่ใหญ่โต แต่กระจาย\nตัวอย่างเหมาะสม สอดรับกับพุ่มไม้หินเขียวในสวน สะท้อนความสูงสง่า\nออกมา\nฟ่านเสียนถามอย่างยิมแย้มว่า “เปรียบกับวังหลวงเป็นอย่างไร?”\nหลินว่านเอ้อกล่าวว่า “ดีเลิศไปคนละแบบ แต่นี้มิใช่สถานที่ของ\nพวกเรา ท่านกระหยิมยินดีอันใด?”\nฟ่านเสียนโบกมือกล่าวว่า “เจ้าของทีนี้บอกว่าภายหน้าจะยกให้แก่\nข้าพเจ้า เพียงแต่ข้าพเจ้าตําหนิว่าทีนี้มีของสิงหนึ่งมากเกิน ไม่คิดขนย้าย\nมาอยู่อาศัย”\nยามนี้แม้แต่ฟ่านเย่อเย่อก็เกิดความตื่นตระหนก ถามว่า “ยังมี\nอันใดไม่ดี?”\nฟ่านเสียนกล่าวอย่างขึงขังว่า “มีสตรีมากเกินไป สวนอุทยานแห่ง\nนี้ไม่ทราบซูกซ่อนหญิงงามอยู่มากน้อยเท่าใด”\nกล่าวจบไม่สนใจหญิงสาวทั้งสอง สังให้รถม้าหยุดลง ตนเองลงจาก\nล้วงป้ายประจําตัวของถีซือ (ผู้บัญชาการ) จากข้างเอว ยืนไปในพง\nหเข้าข้างทาง\nในพงหญ้าปรากฏคนผู้หนึ่งแสดงตนขึื่นราวกับวิชามายากล คนผู้นี่\nสวมใส่เสือผ้าธรรมดา คล้ายคนตัดฟืนในป่าเขา คนตัดฟืนนั้นตรวจสอบ','2026-04-17 09:49:10'),(46,10,43,'ตเพยปาะจาเด้วกันนั้น จากนั้นมองดูฟ่านเสียนอยู่ครึ่งค่อนวัน ค่อยกล่าว\nผูฝา เสียไว11 \"ใต้เท้า นี้เป็นกฎข้อบังคับ ขอท่านโปรดให้อภัย”\nฟ่ แส่ยนตอบว่า “ข้าพเจ้าไม่โทษว่าท่าน คนในรถเป็นภรรยาและ\nเขยเอยร์ เพเจ้า”\nกาเตด็ด ฟันนั้นไม่กล้ากล่าวอันใด หากล่าถอยกลับไป หาทีซ่อนตัว\nแฟงไหง\nเหม้าแล่นต่อไป เลียบทางภูเขาไปยังสวนอุทยาน ตลอดรายทาง\nแต่ยามนี้หญิงสาวภายในรถทั้งสองดูออกว่า เส้นทางสายนี้ไม่ได้\nยตแพลแายกว่าในวัง กล่าวได้ว่ามีอันตรายทุกฝีก้าว แม้แต่กองกำลังทหาร\nศิดแยเข้ามา ต้องพกความล้มเหลวกลับไป\nแน่นอน หญิงสาวทั้งสองฉลาดหลักแหลม คาดเดาออกว่าเจ้าของ\nศาแททกานนี้เป็นใคร\nผู้ท่สามารถเสพสุขเช่นเจ้าชีวิต เข้าพักในสวนอุทยาน วางกำลัง\nใหหาการณ์อย่างเข้มงวดถึงเพียงนี้ นอกจากหัวหน้าสำนักตรวจสอบแล้ว\n\'ที่หลังรถม้า กำลังอารักขาทั้งสองขบวนหยุดยังชะงักเท้า ย่อกายลง\nม เวไคมาถึงทีนี้ ไหนเลยต้องให้พวกมันติดตามอารักขาอีก?\nหัวหน้าขบวนของกำลังกลุ่มย่อยของหวังฉีเหนี้ยนในวันนี้คือซูเหวิน\nมันผงกศีรษะต่อหัวหน้าองครักษ์ตระกูลฟ่านคราหนึ่ง หัวหน้าองครักษ์\nแแเก็คํานับตอบต่อมัน\nซูเหวินเม่ากล่าวกับเพื่อนร่วมงานว่า “สามารถเข้าใกล้ตัวตึกของ\nได้เท้าเอียนจ่าง (หัวหน้าสำนัก) ถึงเพียงนี้ ล้วนแต่พึงพาวาสนาของใต้เท้า\nหัวหน้าองครักษ์นั้นคล้อยตามคําหนึ่ง พลางกวาดมองสวนอุทยาน\nแห่งนั้นด้วยความอิจฉาเลือมใส','2026-04-17 09:49:10'),(47,10,44,'ต่อจากนั้นผู้คนทั้งสองขบวนนั่งลงในพงหญ้า ถอนดึงต้นหญ้า\nสนทนาด้วยเรื่องสัพเพเหระกัน\nสวนอุทยานอันงดงามแห่งนี้ฬานักด้วยเฉินผิงผิง นอกจากฮ่องเต้\nแล้ว นับเฒ่าขาเป่นี้ทรงอิทธิพลทีสูด ต่างกับขุนนางบุ้นบู๊ทัวไป ที่ผ่านมา\nอ้างว่าไม่สบาย ไม่ยอมเข้าประชุมในท้องพระโรง จึงมีเวลาพํานักอยู่ใน\nสวนอุทยานทีนอกเมือง ขณะที่บ้านพักในมหานครแทบไม่ได้เข้าพักมาก่อน\nวันนี้ฟ่านเสียนที่แสร้งป่วยน้อยมาหาเฉินผิงผิงที่แสร้งป่วยใหญ่\nจะอย่างไรเคยแวะเวียนมาหลายครัง จึงคุ้นเคยกับเส้นทางเป็นอย่างดี\nจวบจนมาถึงหน้าประตูสวนอุทยาน เห็นป้ายขวางจารึกอักษรคําเฉิน\nหยวน (อุทยานเฉิน) นี้เป็นลายพระราชหัตถเลขาของฮ่องเต้องค์ก่อน เป็น\nความลําค่าอย่างสูง\nฟ่านเสียนเห็นหน้าประตูจอดไว้ด้วยรถม้าสองคัน ต้องขมวดคิว\nเข้าหากัน คิดไม่ถึงวันนี่มีแขกมาเยือนสวนอุทยาน ด้วยนิสัยอันโดดเดียว\nของเฉินผิงผิง บวกกับชือเสียงอันยอือฉาวของสำนักตรวจสอบ คาดว่า\nขุนนางในราชสำนักต้องไม่มาดีมชาในที่นี้ แขกเหรือในวันนี้เป็นใคร?\nหลินว่านเอฮ้อลงจากรถตามหลังมัน เพียงกวาดมองแวบหนึ่ง ก็จดจํา\nสัญลักษณ์บนรถม้าคันแรกออก จึงยิมพลางกล่าวว่า “เป็นคนในวัง”\nฟ่านเสียนรับฟังจนงงงันวูบ\nบ่าวชราทีเฝ้าประตูอุทยานเฉินรีบลงบันไดมาต้อนรับตั้งแต่แรก มัน\nทราบว่าใต้เท้าฟ่านทีเบืองหน้าต่างกับขุนนางทั้งหลาย เป็นผู้เยาว์ทีใต้เท้า\nเอี่ยนจ่างให้ความสำคัญ ทั้งยังได้รับการวางตัวเป็นผู้สืบตําแหน่งต่อจาก\nใต้เท้าเยอียนจ่าง จึงไม่กล้าเพิกเฉย แสดงความเคารพแล้วกระซิบบอกว่า\nเป็นเหอชิงอ้อง กับใต้เท้าเสียวฉินแห่งมนตรีแห่งรัฐ\n. ส ลสั้,\nคําซิงอ้องเป็นคําเยแทพ ก คคลทฑี่ได้วิทควยยศเป็นอ้อง มีโอกาสได้ขึ้นครองราชย์','2026-04-17 09:49:10'),(48,10,45,'ฟ่านเสียนเกาต้นคอคราหนึ่ง เป็นองค์ชายใหญ่กับเสียวฉิน (ฉิน\n) จัแทราบว่าใต้เท้าเสียวฉินนั้นได้เข้าสู่ศูนย์กลางอํานาจ ประจําการ\n\"นเงงซูเสิง ประการสำคัญคือเหนือเสียวฉินยังมีเหล่าฉิน (ผู้สูงอายุแซ่\n( ) เป็นมนตรีแห่งรัฐ มีอิทธิพลในฝ่ายทหารอย่างสูง องค์ชายใหญ่สู้รบ\nคยผู่กางตะวันตกหลายปี มีความสัมพันธ์อันดีกับตระกูลฉิน บุคคลทั้งสอง\nงแก้นมายังสวนอุทยานเฉินทําอะไร?\nฟ้านเสียนยืนอยู่ทีเชิงบันได ไม่รีบร้อนเข้าไป หากครุ่นคิดว่าอีกฝ่าย\nม แพ่อนครั้งนี้ใช่เกี่ยวข้องกับตนเองหรือไม่ ถึงแม้ว่าฝ่ายทหารกับสำนัก\nตวงจสอบสนิทสนมกลมเกลียว แต่เรื่องนี่ยังน่าประหลาดอยู่บ้าง\nมันยิมเล็กน้อย ไม่นำพาว่าการท่องชานเมืองของตนเองถูกราช\n\"เก็กล่วงรู้ ดังนั้นนำภรรยากับเม่ยเม่ยเดินเข้าสวนอุทยาน ต้องการดูว่า\n. เมะซี\nแงคชายใหญ่ผู้นี้มีความคิดอันใด\nหลังจากตัดผ่านสวนอุทยานหอเก๋งที่ตกแต่งอย่างวิจิตรงดงาม ใน\nท่สตมาถึงห้องโถงทีเฉินผิงผิงใช้รับแขก มันไม่รอให้ผู้คนเข้าไปรายงาน\nก้าวยาวๆ เข้าไป\nความจริงแล้วมันไม่คิดกล่าวอันใด แต่พบเห็นมุมห้องโถงนั่งไว้ด้วย\nแม่นางซังเหวิน ร้องขับขานด้วยสีหน้าไม่สบายใจ ต้องหัวร่อฮาฮากล่าวว่า\n\"ข้าพเจ้าคาดเดาแต่แรกว่า ทัวทั้งมหานคร ผู้ทีกล้าฉุดดึงแม่นางซังเหวิน\nมาร้องขับกล่อม มีแต่ตระกูลท่านเท่านั้น”\nทีแท้ซังเหวินไม่อยู่ในหอโอบจันทร์ กลับอยู่ในสวนอุทยานเฉิน\nซังเหวินเป็นผู้จัดการของหอโอบจันทร์ ทั้งยังเข้าสำนักตรวจสอบ\nเฉินผิงผิงฉุดลากนางมา ให้ร้องเพลงขับกล่อม ย่อมไม่มีปัญหาแต่อย่างไร\nเฉินผิงผิงนั่งอยู่ในตําแหน่งผู้เหย้า พอได้ยินเสียงหัวร่อ ก็ช้อนตา\n¥ \' ง แฉะ ง\nขึ้นมา มองดูหนุ่มสาวทั้งสามทีมาโดยไม่รับเชิญ ดวงตาทีเยียบเย็นเพิม\nความอบอุนวูบหนง ยืนมือซูบผอมลูบไล้พรมขนแกะสีเทาทีคลุมอยู่บน','2026-04-17 09:49:10'),(49,10,46,'หัวเข่า ด่าอย่างยิมแย้มว่า “ท่านมิใช่รังเกียจว่าทีนี้มีสตรีมากมายหรยก\nหรือ วันนี้ไฉนมาแล้ว มาก็มาเถอะ ยังนำภรรยากับเม่ยเม่ยมาด้วย หรือ\nกลัวว่าเราจะบอกให้สตรีเหล่านั้นมารับประทานท่านทั้งเป็น?”\nคนหนุ่มทีนั่งประจําทีอาคันตุกะทั้งสองใจหายวาบ เหลียวมองมาที\nประตูห้องโถง ต้องตะลึงลานกับที่ กลับเป็นซังเหวินหยุดการขับร้อง ยิม\nพลางผูดลุกขึ้น คารวะต่อฟ่านเสียนกับหญิงสาวทั้งสอง\nชั่วครู่ให้หลังคนหนุ่มที่สวมชุดลําลอง แต่ยังแผ่ซ่านกลินอายของ\nนายทหารนั้นค่อยผุดลูกขึ้น ก่อนอื่นคารวะหลินว่านเอ้อทีด้านหลังฟ่าน\nเสียน จากนั้นคํานับฟ่านเย่อเย่ออย่างอ่อนโยน แล้วค่อยทักทายฟ่าน\nเสียนอย่างยิมแย้มว่า “ใต้เท้าเสียวฟ่าน ยินดีที่ได้พบ\nฟ่านเสียนเคยพบกับฉินเหิง ทราบว่าอีกฝ่ายมีชาติตระกูลสูง ทั้งเป็น\nทีโปรดปรานของฮ่องเต้ ถือเป็นดาวรุ่งดวงใหม่ของรัฐชิง มือนาคตยาวไกล\nจึงประสานมือกล่าวว่า “คํานับใต้เท้าเสียวฉิน\nถึงแม้ศักดิฐานะของฉินเหิงยังสูงกว่าฟ่านเสียน แต่ทั้งสองฝ่ายต่าง\nล่วงรู้ขมกำลังของอีกฝ่าย จึงไม่จําเป็นต้องกล่าวถ่อมตน ฉินเหิงยิมอย่าง\nอ่อนโยนกล่าวว่า “วันนี้มาเยือนใต้เท้าเอียนจ่าง คิดไม่ถึงยังได้พบกับใต้เท้า\nถีซือ เราผู้แซ่ฉินโชคดีไม่เบา\nฟ่านเสียนเห็นรอยยิมของมันปราศจากการเสแสร้ง สร้างความ\nสบายใจยิง ขานรับว่า “อย่าว่าแต่วันหน้าจะได้ใกล้ชิดกัน วันนี้เมื่อพบพาน\nย่อมต้องดีมสักหลายจอก”\nฉินเหิงหัวร่อฮาฮากล่าวว่า “ฟ่านถีซือวิเศษแท้ กระทําการเหนือ\nความคาดหมายผู้คน ไม่เอ่ยถึงเรื่องที่ลั้มปวย ไม่เข้าประชุมในท้องพระโรง\nกลับชักชวนให้ดีมสุรา ทําให้ข้าพเจ้าคิดกล่าวสัพยอกสักหลายคํายังทํา\nไม่ได้”\nฟ่านเสียนเหลือบมองเฉินผิงผิงทีนั่งในตําแหน่งผู้เหย้าแวบหนึ่ง ฝืน','2026-04-17 09:49:10'),(50,10,47,'ฝี่แพนางกล่าวว่า “แน่นอน พวกเราทีเป็นผู้เยาว์ต้องดูว่าเจ้าบ้านยอมนำ\nสุาเคฉ่งเหลียงแขกหรือไม่?\nเฉแนผงผงดาวา “ผูเยาวเซนทานยงมเงนมากกวาเราอก\n4เนเทิงเปลือกนอกยังแย้มยิม ในใจกลับบังเกิดความตื่นตระหนก 11\nฝ \"แมาขุนนางในราชสำนักเข้าใจว่าฟ่านเสียนที่เข้ารับตําแหน่งในสำนัก\nตาวงสอถบ เป็นฮ่องเต้ทรงพระกรุณาและปลูกฝังเป็นพิเศษ แต่ยามนี้เห็น\nฟ่ \"แล่ยนสนทนากับเฉินเอี่ยนจ่าง (หัวหน้าสำนักแซ่เฉิน) ที่ทุกคนล้วน\nแทงขาม กลับไม่มีสัมมาคารวะถึงเพียงนี้ เฉินเอี่ยนจ่างก็ตอบตามสบาย\nตกพทงเกิดความรู้สึกแปลกประหลาดประการหนึ่ง ดูทําความสัมพันธ์\nหว่างเฉินเยอี่ยนจ่างกับฟ่านถีซือผู้นี่ต้องไม่ธรรมดา\nถึงแม้ว่าฮ่องเต้โปรดและให้ความสำคัญ แต่คิดควบคุมสำนักตรวจ\nยังต้องขึ้นอยู่กับท่าทีของเฉินผิงผิง จนบัดนี่ฉินเหทิงค่อยได้คิดว่า ใน\nก ลากาคหน้าคนหนุ่มเช่นฟ่านเสียนจะได้ควบคุมสำนักตรวจสอบ อย่างนั้น\nท เงฝ่ายทหารต้องเร่งความเร็วในการคบค้ากับคนผู้นี้กว่าเดิม\nเพียงคําโต้ตอบไม่กีคํา ได้แลกเปลี่ยนข่าวสารทีเป็นประโยชน์มาก\nหนลาย ฟ่านเสียนค่อยเข้าใจว่าเฉินผิงผิงถือโอกาสนี้แสดงท่าทีแท้จริงของ\nมั“เต่อฝ่ายทหาร เพิมเบียที่หน้าตักให้กับฟ่านเสียน\nทั้งสองสนทนาอีกหลายคํา ฟ่านเสียนค่อยหันกายไป เตรียมทีจะ\n\"ทาจวะต่อองค์ชายใหญ่ทีด้านข้าง\nตามเหตุผลท่าทีของมันถือว่าเสียมารยาทอยู่บ้าง แต่คนในห้องโถง\nลงนทราบว่า ครั้งแรกทีมันกับองค์ชายใหญ่พบหน้าก็ไม่ลงรอยกัน ส่วนฉิน\nเพหิงสนิทสนมกับองค์ชายใหญ่ คงไม่ถือสาหาความ สำหรับเฉินผิงผิง มัน\nยิงไม่สนใจพิธีรีตองอันใด\nขณะที่ฟ่านเสียนเข้าใจว่าองค์ชายใหญ่จะมีโทสะ พอเหลียวหน้าไป\nตนเองกลับชุ่นเคืองใจขึ้นมา เห็นภรรยานั่งอยู่ข้างกายองค์ชายใหญ่','2026-04-17 09:49:10'),(51,10,48,'สนทนากับมันอย่างยิมแย้ม ถึงแม้ทราบว่าหลินว่านเอ๋อเติบโตขึ้นมาภาย\nใต้การเลี่ยงดูของหนิงไฉเหยิน เท่ากับว่าองค์ชายใหญ่เฝ้าดูนางจนเติบใหญู\nทั้งสองสนิทสนมกันฉันพีชายน้องสาว แต่พอเห็นฉากนี่ ฟ่านเสียนยัง\nขุ่นข้องใจอยู่บ้าง\nแต่น่าขุ่นข้องใจยิงกว่าคือ แม้แต่ฟ่านเย่อเย่อก็นั่งอยู่ตํากว่า รับฟัง\nคําบอกเล่าขององค์ชายใหญ่อย่างออกรส\nฟ่านเสียนเงียหูฟังดู ค่อยทราบว่าองค์ชายใหญ่ใหญ่บอกเล่าเรื่อง\nพิชิตตะวันตก แย่งชิงม้ากับชนชาติหู ชาวชิงนิยมการต่อสู้ องค์ชายใหญ่\nเติบโตที่ชายแดน ยิงเป็นวีรบูรุษในใจมวลชน แม้แต่ว่านเอ๋อกับเย่อเย่อ\nก็ไม่มีข้อยกเว็้น\nฟ่านเสียนรู้สึกเป็นรสชาติที่สุดทนทาน พลางครุ่นคิด เราเส้าแหย\n(นายน้อย เป็นผู้ถือลัทธิสันติภาพ ไม่เช่นนั้นจะออกศึกสักหลายเทียว\nให้พวกท่านเหล่ายาโถวชมดูเป็นขวัญตา มันแม้ขุ่นข้องใจ เปลือกนอกกลับ\nหัวร่อ น้อมคํานับต่อองค์ชายใหญ่ กล่าวว่า “ขุนนางผู้น้อยคํานับต้าเตียน\nเซีย อืมม์ เหอชิงอ้อง\nองค์ชายใหญ่พอเห็นฟ่านเสียน ก็เกิดความอัดอันตันใจ\nได้ยินนำเสียงของมัน ต้องกล่าวว่า “ฟ่านเสียน เราผู้เป็นอ้องล่วงเกินท่าน\nทีใด พอพบหน้าท่านก็กล่าวแดกดันเราผู้เป็นอ้องอยู่หลายคํา” พลางหัน\nไปทางหลินว่านเอ้อ กล่าวว่า “เฉินเอ้อ เซียงกงของท่านไม่นับเป็น\nหลินว่านเอ้อกับองค์ชายใหญ่สนิทสนมจนไม่อาจสนิทสนมกว่านี้\nเห็นมันตําหนิติเตียนเซียงกงตัวเอง ไหนเลยยินยอมได้ จึงหยิบผลไม้\nบนโต๊ะเตียยัดใส่ปากมัน กลาววา ไหนเลยพอพบหน้าก็วิจารณ์เม่ยฟู\nซาวจีนเรียกคนต่างชาติเป็นพวกหู\nชื่อเล่นของหลินว่านเอือ','2026-04-17 09:49:10'),(52,10,49,'เข่นแด\nฟ่านเสียนรู้สึกว่าคําเม่ยฟู (น้องเขย) น่าฟังกว่า จึงหัวร่อพลางนั่ง\nตเคู่กาเฟ่านเย่อเย่อ ปรากฏบ่าวไพร่ในสวนอุทยานเฉินส่งผ้าขนหนูร้อน\nกํากเท เมา ถึงแม้มันทราบว่าองค์ชายใหญ่กับฉินเหิงมาหาเฒ่าขาเป๋ คง\nต้อามเวืกงสำคัญ แต่มันพานหน้าด้านนั่งอยู่ในห้องโถง ไม่เปิดโอกาสให้\nฝ่เพตรงข้ามกล่าววาจา\nหลินว่านเอ้อทราบเรื่องที่คณะทูตแย่งชิงเส้นทางกับทัพตะวันตกที\nแยแแล่1คง กล่าวถึงที่สุดฟ่านเสียนเป็นฝ่ายผิด แต่นางล่วงรู้สาเหตุทีฟ่าน\nเฝฟาเท่าเช่นนี้ ตอนนี้เมื่อมุ่งเป้าไปที่องค์ชายรอง ฟ่านเสียนก็ไม่จําเป็น\nตกฯล่วงเกินองค์ชายใหญ่อีก มิหนำซํานางไม่ต้องการให้เซียงกงตัวเอง\nข่๓แก้งกับพระเชษฐาทีสนิทสนมที่สุด จึงชวนสนทนากับทั้งสอง เพื่อผ่อน\nฑาเยความตงเครยด\nทั้งหมดทราบแน่แก่ใจว่าเป็นเรื่องราวใด แต่ไม่กล่าวเปิดโปงออกมา\nกงค์ชายใหญ่จึงนั่งแน่วนิง ส่วนฟ่านเสียนเอาแต่สนทนากับฉินเหทิง\nแกหเถามถึงสุขภาพของฉินเหล่าเจียงจวิน (แม่ทัพผู้เฒ่าแซ่ฉิน) ไม่ทราบ\nแก่ไคใดจึงไปเยียมคํานับได้\nเฉินผิงผิงคล้ายหลับใหลบนเก้าอิล้อเลือนแล้ว กล่าวไปประหลาด\nถึงแม้อยู่ในบ้านที่สุขสบาย มันยังคงนั่งเก้าอิล้อเลือนแทนที่จะนอนบน\nต่งเตียง หลินว่านเอ้อเห็นเช่นนั้นก็อับจนปัญญา ฟ่านเย่อเย่อที่ด้านข้างก็\nหวข่อออกมา คนหนึ่งเป็นองค์ชายใหญ่ทีออกรบอย่างโชกโชน คนหนึ่งเป็น\nขุแนางหนุ่มที่กระเดืองดัง กลับทะเลาะเบาะแว้งราวกับเด็กชายสองคน เป็น\nทนำขบขันอยู่บ้าง\nสุดท้ายแม้แต่ฉินเหิงยังเห็นว่าไม่มีหัวข้อสนทนากับฟ่านเสียนอีก\nกงค์ชายใหญ่พลันกล่าวเสียงเย็นชาว่า “ฟังว่าระหว่างนี้ฟ่านถีซือนอนป่วย\nพบนเตียง ไม่สามารถเข้าประชุมในท้องพระโรง ไม่สามารถแก้ต่างคําฟ้อง','2026-04-17 09:49:10'),(53,10,50,'ร้องกล่าวโทษของตึกตูฉาเยี่ยน วันนึกลับมีอารมณ์ออกท่องเที่ยว\nฟ่านเสียนอ้าปากหาวคําหนึ่งกล่าวว่า “วันพรุงนิจะเข้าประชุม วัน\nพรุ่งนี้เถอะ\nฉินเทิงงงงันวูบ ครุ่นคิดว่าท่านไม่คิดลาป่วยหลบหน้าหรือ แต่ว่า\nตนเองถูกองค์ชายใหญ่ฉุดลากมายังสวนอุทยานเฉินด้วยเรื่องนี้เอง เมื่ออยู่\nต่อหน้าฟ่านเสียน จึงไม่สะดวกกับการเอ่ยปาก\nมันไม่สะดวกกับการเอ่ยปาก องค์ชายใหญ่กลับไม่ปิดบัง เรียนต่อ\nเฉินผิงผิงว่า “สูฟู (ท่านอา) เรื่องของเหล่าเอ้อ (อันดับสอง) ขอท่านแสดง\nความเห็นสักคํา ” มันเหลือบมองฟ่านเสียนแวบหนึ่ง กล่าวสืบต่อ\n“ข้าพเจ้าความจริงไม่สนใจเรื่องในราชสำนัก แต่ข่าวลือในมหานครออกจะ\nเหลวไหลไป มิหน้าซําขุนนางในสังกัดเหล่าเอ้อก็มีผู้มีความรู้ความสามารถ\nอยู่บ้าง หากถูกกวาดลงจากเวที ถือเป็นความสูญเสียของราชสำนัก”\nฉินเหิงครุ่นคิดท่านกลับเปิดเผยนัก กลับคิดฉีกหน้าฟ่านเสียนต่อ\nหน้าฟ่านเสียน แต่เหตุการณ์ถึงขันนี้ ได้แต่กัดฟันกล่าวว่า “ใช่แล้ว ใต้เท้า\nจนบัดนี้ฝ่าบาทไม่ยอมรับสังอันใด หากท่านไม่ออกหน้า ราช\nสำนักคงปันป่วนวุ่นวายแล้ว”\nฟ่านเสียนยิมเล็กน้อย คนทั้งสองนี้ล้วนโอ่อ่าผ่าเผย เจตนาการมา\nขององค์ชายใหญ่กับฉินเหิงชัดแจ้งยิง ฝ่ายขององค์ชายรองถูกสำนักตรวจ\nสอบกดดันจนโงหัวไม่ขึ้น องค์ชายรองเองก็ไม่สะดวกกับการออกหน้า ได้\nแต่ขอความช่วยเหลือจากพีใหญ่ ทั้งฉุดลากตระกูลฉินแห่งมนตรีแห่งรัฐมา\nอีกฝ่ายมาหาเฉินผิงผิงนับว่าดีดลูกคิดรางแก้วไม่เลว หากว่าเฉินผิงผิงบอก\nให้ฟ่านเสียนหยุดมือ มันได้แต่ปฏิบัติตาม\nแต่ว่าประโยชน์ที่พึงมีพึงได้ล้วนได้มาแล้ว ข้าหลวงมหานครก็ถูกสั่ง\nพักราชการ คนขององค์ชายรองในหกกรมก็รับเคราะห์โดยทั่วหน้า ฟ่าน\nเสียนไม่ติดใจเอาความ กลับให้ความสนใจต่อคําเรียกหาขององค์ชายใหญ่','2026-04-17 09:49:10'),(54,10,51,'มันเรียกหาเฉินผิงผิงเป็นสูฟู่ (ท่านอา)\nถึงแม้ว่าเฉินผิงผิงมีขุมกำลังอันลึกล้า ทั้งใกล้ชิดกับฮ่องเต้ แต่\nผาค์ฑายองค์โตกลับเรียกหามันเป็นท่านอา ออกจะขัดกับประเพณี บอกไป\nแหงงว่าเจะขู่ขวัญผู้คนจนตาย ท่านอาของท่านเป็นจิ้งอ้อง หาใช่ขุนนางใหญ่\nศุ นไม่\nขณะทมนครุนคัด เฉนผงผงกลมตาทขุนมวขน ส่งเสียงกระแอมไอ\nแน่าวงว่า “เรื่องของเหล่าเอ้อ (อันดับสอง) รอสักครู่ค่อยว่ากล่าว ที่เราคิด\nเนล่าวคือ ” พลางชีมือไปยังหลินว่านเอ๋อกับฟ่านเย่อเย่อ กล่าวสืบต่อ\n\"พาไทวทั้งสองมายังอุทยานของเราเป็นครั้งแรก ไฉนไม่กล่าวทักทายเราที\n(เป็เแจ้าบ้านสักคํา”\nซึ่งความจริงชนชาวโลกน้อยคนที่ไม่กลัวเฉินผิงผิง ตามคําเล่าลือ\nแนผิงผิงถูกมองเป็นหมอกุ่ย ยามรัตติกาล หลินว่านเอ้อกับฟ่านเย่อเย่อ\nส!แน็กครันคร้าม ดังนั้นนับตั้งแต่เข้าห้องโถงมา ต่างก็นั่งอยู่ข้างกายของ\nกงคชายใหญ่\nยามนี้ท่านผู้เฒ่าเมื่อเอ่ยปาก หลินว่านเอ๋อกับฟ่านเย่อเย่อได้แต่\nแตลูกขึ้น เดินถึงเบื่องหน้าเฉินผิงผิง ย่อกายคารวะในฐานะผู้เยาว์\nเฉินผิงผิงยิมพลางกล่าวว่า “กลัวอันใด พวกท่านคนหนึ่งมีมารดา\nคนหนึ่งมีบิดา หาได้ดีเลิศกว่าเราเท่าใด\" ที่มันเอ่ยถึงคือจ่างกงจู่กับ\nพระกํากับดูแลทักษิณ ต่อจากนั้นกล่าวกับองค์ชายใหญ่ว่า “เรื่องทีท่านเอ่ย\nถึง เมื่อเจ้าของเรื่องมาแล้ว ท่านก็บอกต่อมันโดยตรง มันสามารถตัดสิน\nไจได้ จวินจู่เหนี้ยงเหนี้ยง คุณหนูฟ่านช่วยเข็นเก้าอิล้อเลือนให้กับเรา เรา\nจะนำพวกท่านไปชมดูของวิเศษในอุทยานเฉิน”\nหญิงสาวทั้งสองรวมทั้งซังเหวินพากันเข็นเก้าอีล้อเลือนของเฒ่า','2026-04-17 09:49:10'),(55,10,52,'ขาเป๋ออกจากห้องโถง ปล่อยให้ฟ่านเสียน องค์ชายใหญ่กับฉินเหิงมองห1!\nกัน ครุ่นคิดว่าเฒ่าผู้นี่ไม่ทําหน้าทีเจ้าบ้าน ยกบ้านตัวเองให้เหล่าผู้เผา1\nต่อยตีกัน ตนเองนำหญิงสาวที่สะคราญปานบุปผาสามนางออกไปท่องฑง!\nสวนอุทยาน','2026-04-17 09:49:10'),(56,10,53,'ปตการเซรชา\nฉินเทิงเป็นคนฉลาด ไม่เช่นนั้นต่อให้ตระกูลฉินของมันทรงอิทธิพล\nในฝ่ายทหาร มันที่มีอายุสามสิบเศษคงไม่สามารถมีส่วนร่วมบริหารราชการ\nแฝผ่นติน ดังนั้นผุดลุกขึ้นประสานมือต่อองค์ชายใหญ่กับฟ่านเสียน\n) \"คนมีสามเร่งรีบ พวกท่านสนทนาไปก่อน”\nกล่าวจบไม่รอให้ทั้งสองตอบคํา ก็สาวเท้าถึงประตูข้างของห้องโถง\nไห้บ่าวไพร่ชักนำไปยังห้องนำ\nฟ่านเสียนอดหัวร่อมิได้ หวนนึกถึงตอนทีตนเองอาละวาดในกรม\nเซทัณฑ์ ขุนนางยศเส้าชิงตึกต้าหลีซือซึ่งเป็นตัวแทนของฝ่ายทหารเห็น\nงามขัดแย้งเพิ่มสูงขึ้น ก็หาข้ออ้างไปปลดทุกข์ ดูท่าตระกูลฉินฝึกกระบวน\nท่าแจนชําชองชํานาญแล้ว\nบรรยากาศในห้องโถงน่าอืดอัดอยู่บ้าง ยังคงเป็นองค์ชายใหญ่กล่าว\nทําลายความเงียบสงัดว่า “ฉินเหิงกับเราล้วนแต่ผ่านศึกสมรภูมิมา พวก\nเจาเหล่าทหารมีนิสัยเปิดเผย คําพูดก็บอกตรงๆ เราไม่ยินดีทีให้เหล่า\nไพร่พลหลังโลหิตพลีชีวิตที่ข้างนอก คนบุญหนักศักดิใหญ่ในมหานครกลับ\nใจมตีกันเอง เพาะสร้างกลุ่มของตัวเองขึ้น ไม่ว่าสุดท้ายผู้ใดแพ้ผู้ใดชนะ','2026-04-17 09:49:10'),(57,10,54,'ล้วนสร้างความเสียหายแก่ราชสำนัก”\nฟ่านเสียนนั่งแน่วนิง หายใจเข้าออกหลายครา คล้ายครุ่นคิดว่า\nสมควรกล่าวอย่างไร แล้วค่อยเอ่ยปาก นำเสียงเย็นชาอยู่บ้าง กล่าวว่า\n“เราขุนนางผู้น้อยเข้าใจความหมายของ เหอซิงอ้อง แต่ท่านคงล่วงรู้\nต้นสายปลายเหตุของเรื่องนี่ เหล่าไพร่พลหลังโลหิตพลีชีวิตทีข้างนอก\nหรือว่า เจ้าหน้าทีสำนักตรวจสอบไม่ได้เป็นเช่นนี้ ในความเห็นข้าพเจ้า\nหน่วยสอดแนมที่ทางสำนักส่งไปยังต่างแดน ต้องเผชิญอันตรายไม่น้อย\nกว่าทัพตะวันตก ข้าพเจ้าเป็นส่วนหนึ่งของสำนักตรวจสอบ แม้ไม่ได้มีนิสัย\nเทียงตรง แต่ก็ไม่ชมชอบดําเนินอุบาย หากให้ข้าพเจ้าขึ้นเหนือไปทํางาน\nให้กับราชสำนัก ข้าพเจ้ายังยินดีกว่า แต่หากมีคนคิดตอแยข้าพเจ้า ถึง\nแม้ว่ากำลังส่วนนี้มาจากในราชสำนัก ข้าพเจ้าก็ไม่มืออ่อน\nองค์ชายใหญ่เงยหน้าขึ้น คิดกล่าวว่ากระไร ฟ่านเสียนชิงโบกมือ\nกล่าวว่า “นี้เพียงเป็นเรื่องของผลประโยชน์ ข้าพเจ้ารังตําแหน่งถีซือ\nสำนักตรวจสอบ หากกระทั้งผลประโยชน์ของตัวเองยังปกป้องไม่ได้\nไหนเลยมีความสามารถปกป้องผลประโยชน์ของราชสำนัก และผล\nประโยชน์ของฝ่าบาท?” มันแค่นหัวร่อกล่าวอีกว่า “ต้าเตียนเซียอย่าได้\nใช้คําว่าผู้ใดแพ้ผู้ใดชนะ หากว่าตอนนี้อีกฝ่ายรุกคืบเข้ามา ข้าพเจ้าไม่มี\nปัญญาตอบโต้กลับไป หรือว่า ท่านยินยอมเป็นคนกลางเจรจาให้กับ\nองค์ชายใหญ่ขมวดคิว ใบหน้าสีคลําอยู่บ้างยิงเคร่งเครียดกว่าเดิม\nกล่าวว่า “ฟ่านเสียน ท่านสมควรเข้าใจฐานะของตัวเอง ท่านเป็นขุนนาง\nทฑาทารนไต ต้องเพลามือไว้”\nไหสาคตาพองจองค์ชายทั้งหลาย ความเคลือนไหวของฟ่านเสียน\nศศพะนพทไข หแนะขุนนาง การแสดงออกของมันออกจะ\n1 0 กงกระตุ้นเตือนอีกฝ่าย ถือ','2026-04-17 09:49:10'),(58,10,55,'(ใหเรแสดงไมตรีอย่างหนึ่ง หารู้ไม่ว่าฟ่านเสียนพอนึกถึงชาติกําเนิด\nตาแกง เหล้บรู้สึกระคายหูเป็นพิเศษ\nฟ่านเสียนจับจ้องมองตาขององค์ชายใหญ่ กล่าวว่า “ข้าพเจ้าเป็น\nยุนวง แต่ในสายตาข้าพเจ้า ข้อแตกต่างระหว่างเจ้าชีวิตกับขุนนาง\nยยูที่ไบาท และไพจือซึ่งเป็นฮ่องเต้ในอนาคต นอกจากทั้งสองท่านนี้\nแล้ว ข้าพเจ้าเห็นว่าแม้แต่ท่านล้วนเป็นขุนนาง ไม่มีข้อแตกต่างอันใด?”\nองค์ชายใหญ่มองดูฟ่านเสียนด้วยความตระหนก คล้ายนึกไม่ถึงว่า\nฝึกคเพกล้ากล่าวเช่นนี้ ต้องหยีตาลง ดวงตาทอประกายเย็นเยียบวูบหนึ่ง\nหน่าวว่า “เห็นแก่หน้าเฉินเอ้อ ต้องตักเตือนท่านอีกครั้ง หากยุ่งเกียวกับ\nเรี่ยงภายในของเจ้าชีวิตเกินไป หาเป็นผลดีต่อตระกูลฟ่านท่านไม่”\nฟ่านเสียนยิมพลางกล่าวว่า “เจ้าชีวิตไม่มีเรื่องภายใน ต้าเตียนเซีย\nยงไม่เข้าใจเหตุผลข้อนี้หรือ?”\nองค์ชายใหญ่ถูกคําพูดนี้สะกดตรึงไว้ ต้องยกมือตบที่เท้าแขนของ\nเก้อด้วยโทสะคราหนึ่ง\nฟ่านเสียนกล่าวเสียงอ่อนโยนว่า “เครื่องเรือนของเยียนจ่าง (หัวหน้า\nสำนัก) ล้วนเป็นโบราณวัตถุ ต้าเตียนเซียลงมือเบากว่านี้\nองค์ชายใหญ่งงงันวูบ เงียบงันชั่วขณะ จึงสันศีรษะกล่าวว่า “ฟ่าน\nเสียน อาจบางทีข้าพเจ้าประเมินท่านตําเกินไป”\nฟ่านเสียนกล่าวถามว่า “คําพูดนี้กล่าวเริมจากทีใด?\nองค์ชายใหญ่กล่าวว่า “จิตปณิธานเราอยู่บนหลังม้า หากว่าทาง\nทหารคิดบุกตะลุยไปทุกสารทิศ ต้องมีแนวหลังทีมันคง ข้าพเจ้าอยู่ทาง\nตะวันตก ยังทราบว่าราชสำนักไม่สงบอยู่บ้าง แต่ยังสามารถควบคุมไว้\nงวบกระทั้งท่านมาถึงมหานคร”\nฟ่านเสียนสันศีรษะยิมเล็กน้อย ไม่ทราบสมควรเอ่ยปากอย่างไร\nองค์ชายใหญ่กล่าวว่า “ท่านปรากฏขีนอย่างกะทันหัน ผุดเด่นขึ้น','2026-04-17 09:49:10'),(59,10,56,'อย่างกะทันหัน กะทันหันจนผู้คนส่วนใหญ่ในราชสำนักไม่ทันเตรียม๓\nขณะที่ท่านมีขีดความสามารถในการทําลายความสมดุลไป\nสุดท้ายองค์ชายใหญ่บอกความคิดอ่านในวันนี้ออกมาว่า “มีคน\nจํานวนมากหวังว่า ท่านสามารถรักษาความสมดุลในมหานคร มิใช่กวา๓\nทําลายทุกสิง”\nฟ่านเสียนนิงเงียบงันไป ทราบว่าอีกฝ่ายกล่าววาจาประดานี้ ไม\nเพียงแสดงออกถึงท่าทีของมัน ทั้งยังเป็นตัวแทนของฝ่ายทหาร\nตนเองออกจากอ่าวต้านโจวถึงมหานคร ใช้เวลาไม่ถึงสองปี ก็เข้า\nควบคุมสำนักตรวจสอบ อย่าเพิงเอ่ยถึงเรื่องดูแลท้องพระคลังในปีหน้า\nเพียงแต่ตอนนี้ก็คุมกำลังทั้งบุ่นและบู๊ สามารถเรียกลมเรียกฝนในแวดวง\nม ร เว เว\nขุนนาง คราครังนี่ต่อสู้ช่วงซิงกับฝ่ายองค์ชายรองจนใกล้ปรากฏผลแพ้ชนะ\nขอถามขุนนางหนุ่มผู้หนึ่งมีขีดความสามารถโค่นทําลายองค์ชายสูงศักด์\nย่อมสร้างความครันคร้ามแก่ขุมกำลังอื่นในราชสำนัก\nฝ่ายทหารขอให้ตนเองยังมือไว้ไมตรีต่อองค์ชายรอง มิใช่เป็นการ\nข่มขู่ และไม่ได้ปกป้องศักดิศรีของเชือพระวงศ์ หากเป็นการหยังเชิงดูว่า\nตนเองซึ่งได้รับการวางตัวเป็นผู้ดูแลสำนักตรวจสอบ เป็นบุคคลทกอปรด้วย\nสติสัมปชัญญะ มีความจริงใจในการรักษาความสมดุลของรัฐชิงหรือไม่ จะ\nอย่างไรทางทหารกับสำนักตรวจสอบมีความสัมพันธ์อันดี ถึงกับเป็นทัพ\nหน้าให้กับไพร่พลรัฐชิง เหล่าทหารหาญมีชีวิตรอดกลับมาเท่าใด มีส่วน\nเกี่ยวข้องโดยตรงกับสติปัญญาของผู้นำสำนักตรวจสอบ\nฟ่านเสียนกล่าวว่า “ท่านครุ่นคิดหรือไม่ เหตุใดข้าพเจ้าจึงเปิดศึก\nมันไม่เรียกอีกฝ่ายเป็นเตียนเซีย (องค์ชาย) หากย้อนถามคํา\nหนึ่ง\nองค์ชายใหญ่ขมวดคิว มันความจริงไม่ได้นึกถึงปัญหาข้อนี้ในเชิง','2026-04-17 09:49:10'),(60,10,57,'ยพกฟังคําถามของฟ่านเสียน ค่อยฉุกใจคิด ที่ผ่านมาสำนักตรวจ\nตตไอก้เวก่ายการต่อสู้ช่วงชิงระหว่างองค์ชายมาก่อน ดังนั้นเงยหน้าขึ้น\nผดงตูฟ \"แล่ยนอย่างเคลือบแคลงสงสัยแวบหนึ่ง\nฟ \"แสียนก็นึกไม่ถึงว่าองค์ชายใหญ่ไม่เข้าใจเล่ห์อุบายในแวดวง\nงํงล่าว “ข้าพเจ้าเพียงคิดระบายแค้น และให้บุคคลบางคนมีสติ\nแจ่ยใสขันเมา”\nหลังความนิงเงียบงัน องค์ชายใหญ่พลันเลิกคิวขึ้น คล้ายเข้าใจเรื่อง\nจ: เฉหนึ่ง ดังนั้นกล่าวว่า “ (น้องรอง) ของเราเป็นคนชาญฉลาด\nต1ทหไพลาดท่าเสียทีแก่ท่าน คงสร้างความตื่นตัวแก่มัน ไม่แน่ว่าจะเกิด\nผูสใบอคก่างคาดไม่ถึง”\nต่างฝ่ายต่างเป็นคนชาญฉลาด ดังนั้นฟ่านเสียนเข้าใจความหมายที\nขาแจ้นอยู่ในคําพูดนี้ ดังนั้นกล่าวเสียงอ่อนโยนว่า “อาจบางที เจตจํานง\nขาขุนนางกับต้าเตียนเซียพ้องต้องกัน แต่ว่าเอ้อเตียนเซีย (องค์ชายรอง)\nง:ได้วิบผลดีหรือไม่ ขืนอยู่กับท่านจะเกลียกล่อมอย่างไร\nองค์ชายใหญ่กวาดมองมันด้วยความสนใจแวบหนึ่ง กล่าวว่า “เรา\nผู้เป็นก่องไม่เข้าใจ เหตุใดท่านจึง วุ่นวายใจกับเรื่องนี้ถึงเพียงนี้\nฟ่านเสียนครุ่นคิด ถึงอย่างไรเป็นพีน้องกัน ตนเองกลับชาติมา\nเก็ตใหม่อย่างยากเย็น หรือจะซํารอยเหตุการณ์ที่ประตูเสียนอู่ แต่ว่า\nเหตุผลข้อนี้ไม่ว่าอย่างไรไม่อาจกล่าวจากปาก จึงหัวร่อพลางกลบเกลื่อน\nก่านไป มิหน้าซํามันยังเกิดความตื่นตัวต่อองค์ชายใหญ่ ถึงแม้ว่ามีคํา\nเล่าวว่าองค์ชายผู้นี้มีจิตใจกว้างขวาง ทั้งนิยมการต่อสู้ ไม่คิดขึ้นครอง\nกสล้งก์ แต่ถึงอย่างไรเป็นราชโอรสฮ่องเต้ ผู้ใดทราบว่ามันคิดอ่าน\nเม็ตวี ค.ศ. 626 ถังไท่จงฮ่องเต้ซึ่งตอนนั้นมีศักดิเป็นฉินอ้อง วางกำลังดักซุ่ม จู๋โจมสังหารไทจือหลีเจียนเฉิงผู้เป็นพีชายกับ\nหผ่ทหย 1แจี่ผู้เป็นน้องชาย ภายหลังเหตุการณ์ถังไท่จงฮ่องเต้ก็ขึ้นเป็นไทจือสืบแทน','2026-04-17 09:49:10'),(61,10,58,'๕ \' กล่าวว่า “อภัง\nองค์ชายใหญ่จับจ้องมองฟ่านเสียนอย่างลึกซึ่ง กล่าวว่า “อภัยคแ\nได้ควรอภัยเถอะ” ด้วยศักดิฐานะของมัน ย่อมกล่าววาจาเช่นนี้ให้กั1!\nองค์ชายรอง ถือว่าไม่ง่ายดาย\nฟ่านเสียนยิมพลางผงกศีรษะรับ มันทราบแน่แก่ใจว่าตนเองไม่อาจ\nเพนนต์ ญี ด\nรุกฆาตต่อองค์ชายรอง จึงยินดีหยิบยืนนำใจให้ การตัดสินใจนี้ไม่เกียวข้อง\nกับท่าทีขององค์ชายใหญ่กับฝ่ายทหาร หากสืบเนื่องจากฮ่องเต้ในวัง\nกำลังจับจ้องตนเองอยู่\nฟ่านเสียนให้เกียรติแก่ทางทหาร องค์ชายใหญ่ก็ไม่สะดวกกับการ\nกล่าวกระไรอีก มันเองก็ทราบว่าน้องรองของตนเองมิใช่คนถือศีลกินเจ\nเรื่องนี่กล่าวถึงที่สุด ตระกูลฟ่านจ่ายค่าตอบแทนอย่างใหญ่หลวง หากไม่\nได้ผลประโยชน์อันใดกลับมา ย่อมไม่ยอมเลิกรา แต่ว่าเรื่องราวกล่าวจบ\nแล้ว บูคคลที่ไม่ใคร่คุ้นเคยทั้งสองนั่งอยู่ในห้องโถงของสวนอุทยานเฉิน\nยามกะทันหันไม่ทราบสนทนาอันใดดี\nฉินเหิงไปปลดทุกข์นานเป็นพิเศษ ทั้งสองนั่งบนเก้าอิ จิบชาอย่าง\nไว้รสชาติ จากนั้นฟ่านเสียนสอบถามว่า “ไม่ทราบองค์หญิงใหญ่เป็นอย่างไร\nค บษ & ซ่ !\nเราขุนนางผู้น้อยมีภารกิจวุ่นวาย ไม่ได้ไปกราบพบ ขอต้าเตียนเซียถ่ายทอด\nความรําลึกถึงให้ด้วย\nเมื่ออยู่ในแวดวงขุนนาง การเลือกหัวข้อสนทนาเป็นความรู้อย่าง\nหนึ่ง ฟ่านเสียนเลือกเรื่องนี้ขึ้นมา ย่อมมีความคิดของมัน จริงดังคาดหมาย\nองค์ชายใหญ่กล่าวอย่างจริงจังว่า “ใต้เท้าฟ่านคุ้มครององค์หญิงใหญ่ลงใต้\nเราผู้เป็นอ้องขอขอบคุณ ณ ทีนี่\nนี้เป็นความร้ายกาจของฟ่านเสียน เมื่อเลือกหัวข้อสนทนาทีเหมาะ\nสม ก็สามารถย่นระยะห่างของทั้งสองฝ่าย ทั้งยังให้อีกฝ่ายรับนำใจของ\nตดนเอง ยามนั้นยิมพลางกล่าวถ่อมตนอยู่หลายคํา แล้วจึงสนทนาถึง','2026-04-17 09:49:10'),(62,10,59,'ตตแคเหพของแคว้นเปยฉี\nพิบสยุมพรขององค์ชายใหญ่กับองค์หญิงใหญ่แห่งแคว้นเปียฉีก็ถูก\nกเหนตขึ้นในฤดูใบไม้ผลิปีหน้า ตอนนืองค์หญิงใหญ่พํานักอยู่ในวัง เคย\nพบหน้าองคัชายใหญ่หลายครัง ฟังว่าบุรุษสตรีทีถูกจับคู่แต่งงานด้วย\nเหตุแลทางการเมืองยังพึงพอใจในกันและกัน ครั้งก่อนฟ่านเสียนเป็นทูต\nที่มีคํานาจเต็ม ถือเป็นพ่อสือขององค์ชายใหญ่\nหลังจากสนทนากันรอบหนึ่ง ความทรงจําที่ฟ่านเสียนมีต่อองค์ชาย\nไหญ่ค่อยเปลี่ยนไป ในฐานะองค์ชายสูงศักดิ การที่มีนิสัยโอ่อ่าเปิดเผย\nเท่นนี้ ถือเป็นเรื่องที่หายากยิง อาจเป็นเพราะมารดาผู้ให้กําเนิดมันมีศักดิ์\nง\'แะไม่สูงส่งเท่าใด เพียงเป็นเชลยหญิงของนครตงอืนางหนึ่ง องค์ชาย\nใหผูไม่มีลักษณะอันสูงศักดิเช่นองค์ชายรองกับองค์ชายสามและไทจือ จึง\nเฟ่ตเผยเทียงตรงกว่า\nมิน่าเล่าภรรยาตนเองสนิทสนมกับองค์ชายผู้นี้ที่สุด. ฟ่านเสียนคิด\nคก่าแชซ่นนี่ พลางสนทนาปราศรัยกับอีกฝ่าย พบว่าอีกฝ่ายพอเอ่ยถึงการ\nพัฑัยสงคราม ก็กระตือรือรันคึกคัก ฟ่านเสียนมีความสํานึกตัวว่า ตนเอง\nไม่มี\'พรสวรรค์ด้านการทหาร เมื่อเปรียบกับผู้นำทัพเช่นนี้ ยังคงนิงเฉย\nตําล่งทอง\nองค์ชายใหญ่พลันกล่าวด้วยสีหน้านิยมเลือมใสว่า “ใต้เท้าเคยพบ\nกับสังซาหู่มาหรือไม่?”\nฟ่านเสียนงงงันวูบจึงกล่าว “ตอนอยู่ในวังเปยฉีเคยพบหน้าแต่ไกล\nแต่ไม่มีความทรงจําอันใด”\nองค์ชายใหญ่ตบต้นขาฉาดหนึ่งกล่าวว่า “ขุนนางไม่รู้จักท่าน ท่าน\nไม่รู้จักขุนนาง กลับปล่อยให้โอกาสคบหาผ่านเลยไป”\nฟ่านเสียนส่งเสียงดังอ้อ กล่าวว่า “ต้าเตียนเซียไฉนให้ความสำคัญ\nเกบสังซาห้ถึงเพยงน?','2026-04-17 09:49:10'),(63,10,60,'องค์ชายใหญ่หยีตาลงกล่าวว่า “นี้เป็นยอดขุนศึกแห่งยุค รักษา\nแนวรบทางเหนือของแคว้นเปียฉี ซึ่งมีความยาวสามพันลี ยันพวกเปียม่าง\n(คนเถื่อนเหนือ) ไว้เป็นเวลาสิบกว่าปี ทั้งเคยจัดทัพพิสดาร รูกเข้าแดแ\nหิมะ ตัดศีรษะพวกเปียม่างพันกว่าหัว ใต้เท้าฟ่านอาจยังไม่ทราบ พวกซีห\n(ชนชาติหูตะวันตก) เปรียบกับพวกเปยม่าง ยังอ่อนต้อยกว่ามาก หลายป\nนี้เราสู้รบกับชนชาติหูทางชายแดนตะวันตก ยิงพบว่าในขณะทีราชสำนัก1\nเปียฉีไม่มันคงเท่าทีควร สังซาหู่สามารถยันข้าศึกไว้ได้นานปี นับเป็น\nเรื่องทีน่ากลัวยิง”\nฟ่านเสียนยิมพลางกล่าวว่า “น่าเสียดายที่สังซาหู่ถูกเรียกตัวกลับ\nเมืองสังจิง ไม่แน่ว่าวันหน้าอาจได้พบกับต้าเตียนเซียในสมรภูมิ”\nองค์ชายใหญ่กล่าวช้าๆ ว่า “หากว่าวันหน้าพบกันทีพรมแดน ถึง\nแม้เราผู้เป็นอ้องจะนิยมเลือมใสกลยุทธ์อันลิลับของอีกฝ่าย แต่อย่างน้อย\nต้องทุ่มเทวิชาความรู้ทีเล่าเรียนมาเข้าต่อกรกับมันสักครา”\nนี้คือความฮีกเหิม ฟ่านเสียนมองดูกลินอายทีแผ่ซ่านจากร่างองค์\nชายใหญ่ ส่วนลึกของจิตใจเกิดความเลือนลอย ทราบว่าตนเองรําเรียนวิชา\nแนวเฉียงตั้งแต่เล็ก บวกกับมโนทัศน์จากชาติปางก่อน เกรงว่าในชีวิตนี้\nยากจะเพาะสร้างความฮึกเหิมจากไฟสงครามเช่นนี้\nแต่ฟ่านเสียนก็มีความเชือมันของตนเอง จึงกล่าว “ถึงแม้ไม่ได้\nศึกษากลยุทธ์ของสังซาหู่ แต่ดูจากเหตุการณ์จู่โจมสังหารเสินจังในคืนฝน\nตก แสดงว่าคนผู้นี้กล้าที่จะปฏิบัติการอย่างคาดไม่ถึง ฆ่าฟันอย่างดุดัน นับ\nเนยอดคนจริงๆ”\nองค์ชายใหญ่คล้ายยิมไม่เชิงยิม กลาววา “ผูบญชาการองครกษ\nเท ฮ็โ1ืโโไสจ0 ะ\nเสื่อแพรเสินจังหรือ เกรงว่ามีส่วนเกี่ยวข้องกับฟ่านถีซีอกระมัง?”\nการตายของเสินจังเป็นก้าวแรกในแผนการร่วมระหว่างฟ่านเสียน\nกับไห่ถัง ความจริงแล้วมีคนระแวงสงสัยว่ารัฐชิงมีส่วนด้วย แต่ยามนี้','2026-04-17 09:49:10'),(64,10,61,'ผูจคท เกไหเประบุบอกออกมา ฟ่านเสียนยังใจสันสะท้าน ปากกล่าวว่า “ต้า\nเตี้ยเแข่กสมควรทราบ พวกเราหทั้งหลายกระทําเรื่องที่ไม่อาจเห็นแสงสว่าง\nไข่คากเจเท่ากับต้าเตียนเซียและสังซาเจียงจวิน (แม่ทัพแซ่สังซา) แต่บาง\nตงร่าม่ล่แช่วยต่อราชสำนัก”\nกงค์ซายใหญ่จับจ้องมองตาของฟ่านเสียนกล่าวว่า “เพราะเหตุนี้\nเง กเป็นค่องบอกว่าประเมินท่านตําเกินไป สังซาหู่แม้ยิงใหญ่ กลับถูก\nฟ แแผ่ฑ่๓จับเชิดราวหุ่นกระบอก ใต้เท้าฟ่านมีพฤติการณ์ลึกลําสุดจะหยัง\nสังซาหู่ลู่โจมสังหารเสินจังกลางถนนคืนฝนตก เป็นการจัดการของ\nฝ่ก เต้นปยฉีกับไห่ถัง แต่หากชนชาวโลกเข้าใจผิดคิดว่าตัวมันมีบทบาท\nผาเกยู ประเมินภาพลักษณ์อันน่ากลัวของมันอยู่เหนือขุมกำลังที่แท้จริง ก็\nเฟ๋แคงามยินดีของฟ่านเสียน จึงยิมรับไว้\nคงค์ชายใหญ่มองดูฟ่านเสียนแวบหนึ่งกล่าวว่า “ฟังว่า ใต้เท้าฟ่าน\nเปแกนขมแข้งชนทเก้า?”\nฟ่านเสียนหัวร่อเบาๆ กล่าวว่า “ต้าเตียนเซีย ข้าพเจ้าไม่มีอารมณ์\nต่พตีกับท่าน ไม่ว่าผู้ใดแพ้ผู้ใดชนะ ล้วนสร้างความเสียหายแก่ราช\nพฟาเน”\nองค์ชายใหญ่คิดไม่ถึงว่าฟ่านเสียนกลอกกลิงถึงเพียงนี้ กลับยกอ้าง\n\" เพดของตนเองเมื่อก่อนหน้านี้ปิดปากของตนเอง สรางความอดอน\nตําไจยิง มันเป็นคนนิยมวิชานู้ ย่อมคิดพิสูจน์ฝีมือกับฟ่านเสียนดู\nฟ่านเสียนกล่าวว่า “คนทีคิดสังสอนข้าพเจ้ามีอยู่มากมาย” หวน\nแทงอิกสักครูอาจต้องเผชิญกับอิงจิอ (เงา) นั้น จึงฝนยิมพลางกล่าวว่า\nตคําเตยนเซียปล่อยปละละเว้นข้าพเจ้าเถอะ\nองค์ชายใหญ่งงงันอีกครา มันผู้นิมีนิสัยเปิดเผย ชมชอบคบหาสหาย\nแต่จงะอย่างไรเป็นองค์ชาย บวกกับหลายปีมานี้มันกรําศึกในสมรภูมิ ไหน','2026-04-17 09:49:10'),(65,10,62,'เลยเคยมีขุนนางกล้ากล่าวกับตนเองเช่นนี้ ฟ่านเสียนทีเบื่องหน้านี้ตอนแก่\nนอกเมืองก็ไม่คารวะต่อตนเอง วันนี้พบกันในสวนอุทยานเฉิน ก็ทั้งแย้ง!\nเท เ ๑ ๕ ๕\nยิมทั้งด่าทอ คล้ายไม่ยืดถือตนเองเป็นองค์ชายผู้หนึ่ง\nองค์ชายใหญ่สูดลมหายใจคําหนึ่ง รู้สึกว่าโลกใบนี้เปลี่ยนไป อย่าง\nน้อยยามอยู่เบื่องหน้าคนหนุ่มเช่นฟ่านเสียนผู้นี่ โลกนี้คล้ายกับไม่เหมือแ\nต้องกล่าวว่า “ใต้เท้ากล่าววาจามีความหมายนัก เราชมชอบสนทน1\nกับท่าน”\nเห็นฉินเหิงกลับมาแล้ว จึงผุดลุกขึ้นกล่าวว่า “ท่านเห็นแก่หน้าเรา\nเรื่องการแย่งชิงเส้นทางทีนอกเมืองเป็นว่าเลิกรา แต่ว่า หากวันหน้าเรา\nผู้เป็นอ๋องคิดสนทนากับท่าน ท่านอย่าได้ หาข้ออ้างปลดทุกข์หรือไม่\nสบายหลบลิหนี้หน้า\nฟ่านเสียนน้อมคํานับอย่างยิมแย้มกล่าวว่า “น้อมรับคําสัง คํากล่าว\nของต้าเตียนเซียมีความหมายกว่าอีกหลายท่าน” ทีว่าอีกหลายท่านย่อม\nหมายถึงราชโอรสอืนของฮ่องเต้\nองค์ชายใหญ่ไม่ได้ลําลาเฉินผิงผิง มันทราบว่าใต้เท้าเอียนจ่าง\n(หัวหน้าสำนัก) ผู้นี้ไม่ถือพิธีรีตอง จึงชักชวนฉินเหิงออกจากสวนอุทยาน\nเฉิน ก่อนออกจากสวนอุทยาน ฉินเหิงกระซิบบอกต่อฟ่านเสียน นัดหมาย\nเวลาพบกันที่ตึกตระกูลฉิน\nหลังจากขึ้นรถม้า ผ่านทางภูเขานอกสวนอุทยานเฉินทีวางกำลัง\nรักษาการณ์อย่างเข้มงวด ทั้งตัดผ่านกำลังกลุ่มย่อยที่หวังฉีเหนี้ยนฝึก\nขืนกับองครักษ์ตระกูลฟ่านที่ลับๆ ล่อๆ ราวกับโจรภูเขา องค์ชายใหญ่\nค่อยลดม่านหน้าต่างรถลง กล่าวเสียงเย็นชาว่า “ฟ่านเสียนไม่ธรรมดา\nจริงๆ”\nฉินเหทิงยิมพลางกล่าวว่า “ในความเห็นของท่านพ่อ ฟ่านเสียนยิง','2026-04-17 09:49:10'),(66,10,63,'แสแข้งทึงด์ ไม่เช่นนั้นวันหน้าสำนักตรวจสอบตกเป็นของเศษสวะตน\nตฝีจ เหน่าผู้เฒ่าในมนตรีแห่งรัฐคงขุ่นแค้นจนคลังใจตาย พี่น้องในกองทัพ\nแจเก็ไม่สหาายใจ”\nคงค์ชายใหญ่ผงกศีรษะ พลันทอดถอนใจกล่าวว่า “ออกจากมหานคร\n! พอกลับมายังปรับตัวไม่ได้ กระทั้งคู่สนทนายังไม่มี”\nทหารคนสนิทของมันถูกกระจายตัวออกไป กรมกลาโหมส่งกำลังไป\nเกักษาชายแดนตะวันตกแทน ตอนนี่มันอยู่ในมหานคร มีส่วนคล้ายกับ\nยคต๒ขุนพลทางเหนืออยู่บ้าง แต่มันจะอย่างไรเป็นองค์ชาย จึงมีสภาพดี\nแจงฯหาหูมากนัก\n4ในเหิงกล่าวถามว่า “การสนทนากับฟ่านถีซือเป็นอย่างไร?\nกงค์ชายใหญ่กล่าวว่า “ยังไม่เลว บิดาท่านสมควรวางใจได้ ต่อให้\nพ์แแก่ยนจ่างปลดเกษียณ ด้วยขีดความสามารถของฟ่านเสียน เชือว่า\nเนทตรวจสอบยังรักษาสมรรถนะชันสูงไว้ สามารถช่วยงานทางฝ่าย\nททหาว”\n\' \' ฆ \' เท ฆข่ ข ๆส่ 1\nฉินเหทิงกล่าวว่า “ข้าพเจ้าเชื่อ แต่ในสายตาข้าพเจ้า ใต้เท้าเสียวฟ่าน\nผุ้เคาจยังเหนือลํากว่า ”\nมันกล่าวแยกแยะว่า “ใต้เท้าเสียวฟ่านคิดอ่านรอบคอบ มีการคบหา\nกังต่างแดน วิชาฝีมืออยู่ชันทีเก้า ทั้งดูแลกิจการของสำนักตรวจสอบเป็น\n\"ก่างดี ยังมีมันมีศักดิฐานะเป็นเซียนกวี ได้รับกํานัลหนังสือจากจวงม่อ\nหาน นับเป็นความสำเร็จที่ไม่เคยมีคนเสมอเหมือน คาดว่ามือนาคตยาว\nไกลกว่าเฉินผิงผิงเอียนจ่างอีก\nองค์ชายใหญ่ทอดถอนใจกล่าวว่า “ปีหน้ามันต้องรับช่วงดูแล\nท้คงพระคลัง เท่ากับถูกวางตัวอยู่บนยอดคลืน ถูกผู้คนทั้งแผ่นดินจับตา\nทั้งต้องเผชิญกับธนูลับ ไม่ทราบว่าฟู่หวง (พระบิดา) คาดคิดอย่างไร','2026-04-17 09:49:10'),(67,10,64,'เมื่อเอ่ยถึงฮ่องเต้ ฉินเหิงย่อมไม่สะดวกกับการตอบคํา องค์ชายใหกป\nทวาดมองมันแวบหนึ่ง กล่าวสืบต่อ “แต่ฟ่านเสียนถึงอย่างไรอายุยังเยา1\nมิหน้าซําเปรียบกับใต้เท้าเอียนจ่าง มีจุดอ่อนที่สาหัสข้อหนึ่ง คาดว่ามัน\nเองก็รู้สึกตัว ครั้งนี้จึงอาศัยเหล่าเอ้อ (อันดับสอง) ประกาศศักดาต่อชนชา.\nโลก ปกปิดจุดอ่อนของตัวเองไว้”\nฉินเหทิงกล่าวด้วยความสงสัยอยากรู้ว่า “จุดอ่อนอันใด?”\nองค์ชายใหญ่หยีตาลงกล่าวว่า “จิตใจมันมีข้อผูกมัด ต่างกับสูฟู่\n(ท่านอา) สูฟู่ไร้บุตรไร้หลาน บิดามารดาเสียชีวิตแต่แรก ไม่มีเครือญาติ\nและไม่มีสหาย ในสวนอุทยานแม้มีหญิงงามมากมาย แต่หาได้เหลือบแล\nไม่ ถือเป็นไม้โดดเดียวต้นหนึ่ง ศัตรูไม่อาจค้นหาจุดอ่อนของสูฟู ไหนเลย\nโค่นท่านผู้เฒ่าลงได้ ฟ่านเสียนผิดแผกแตกต่าง มันมีภรรยา มีเม่ยเม่ย มี\nคาเหครัว มีสหาย เหล่านี่ล้วนเป็นจุดอ่อนของมัน\nฉินเหิงครุ่นคิดดูเห็นพ้องด้วย ทัวทั้งรัฐชิงไม่มีผู้ใดทราบว่าเฉินผิง\nทิงไส่ใจผู้ใด นอกจากฮ่องเต้เท่านั้น\n“นเหิงจะอย่างไรเป็นคนหนุ่ม ต้องกล่าวด้วยความสะท้อนไจว่า “ไร้\nเบเต่งดรไว้ความรัก ไม่ทราบผ่านวันเวลาได้อย่างไร”\n๓งค์ชายใหญ่กล่าวยกย่องว่า “สูฟู่เป็นบุคคลที่หายากยิง ฟ่านเสียน\nคตาเนางถึงขอบเขตขันนี้ ยังอยู่ห่างไกลอีกมากนัก”\nงกากไหเสวนอุทยาน แว่วเสียงเพลงกับเสียงเครื่องสายขับกล่อม\nเห แนแขแค้แอ่อนนุ่มล่องลอยอยู่ในอากาศ หญิงงามสิบกว่านางร่ายรํา\nขานทฑาเกกพินสูงขีนกลางบึงนำ เฉินผิงผิงนั่งบนเก้าอิล้อเลือน โดยมีหลิน\nวพแค่กท้าแฟ แแค่ลเย่ออยู่เป็นเพื่อน ส่วนซังเหวินโอบพิณตั้ง ตัวหนึ่ง ดีด\nขนาแลงแล่เงไห้กับนางรําทั้งหลาย','2026-04-17 09:49:10'),(68,10,65,'1เป็นชีวิตเช่นเชือพระวงศ์สูงศักดิ แต่คนหนุ่มทางฝ่ายทหารของรัฐ\nตีเที่ไทกสารรถม้าออกจากสวนอุทยานทั้งสอง กลับแสดงความเห็นใจต่อ\nตฮ่าตควาเป็นอยู่ของเฉินผิงผิง\nฟ่านเสียนเดินมาจากอีกทางหนึ่ง เฉินผิงผิงพลันปรบมือเบาๆ การ\nยบจําฟ้อนพลันยุติลง สาวงามนางหนึ่งนำแขกสตรีหลายนางไปพักผ่อน\n\"แหล้ง หลินว่านเอ้อทราบว่าฟ่านเสียนคงมีคําพูดคิดสนทนากับเฉิน\nเตี๋ยแจง่าง (หัวหน้าสำนักแซ่เฉิน) จึงติดตามสาวงามนั้นไป เพียงแต่ก่อน\nไฟแงเตมองฟ่านเสียนเป็นเชิงสอบถามว่า มันกับพระเชษฐาสนทนาเป็น\nฟ่านเสียนยิมพลางผงกศีรษะ เป็นการปลอบใจภรรยา พลางเดินถึง\nงแหล่งของเฉินผิงผิง วางมือลงบนพนักพิงของเก้าอีล้อเลือนถามว่า “ไป\nเฉินผิงผิงยกมือทีผอมซูบขืน ชีไปยังดงไม้ด้านตะวันออกของสวน\nฟ่านเสียนเข็นเก้าอิล้อเลือนไปทางด้านนั้นอย่างเงียบงัน ทั้งชรา\nเมหางล้วนไม่เอ่ยปาก ยามนี้เวลายังเช้า อาทิตย์ชิวเทียนสาดลอดดงไม้\nแงง11 ทอทาบเงาของเก้าอิ๊ล้อเลือนกับผู้คนบนพื้น ล้อเลือนของเก้าอี\nเพล่กแต้งเอียดอ๊้าดบดผ่านเงาเหล่านั้นไป\nฟ่านเสียนกล่าวขึ้นก่อนว่า “มันเรียกท่านเป็นสูฟู่ (ท่านอา) ท่านไม่\nแนวต่กตดูฉาเอี่ยนกล่าวโทษหรือ นี้ถือเป็นความผิดร้ายแรง\nเฉินผิงผิงกล่าวด้วยสีหน้าไร้ความรู้สึกว่า “ท่านกลัวตึกตูฉาเอี่ยน\nเล่างโทษหรือ หนังสือกล่าวโทษเราหากเก็บรักษาไว้ สมควรอัดแน่นห้อง\nทวงพระอักษรแล้ว” หยุดเล็กน้อยจึงกล่าวอิกว่า “มันเรียกเราเป็นสูฟู่ เป็น\nซๆเซ ๐\n(แหเทอนุญาต ไม่ว่าผู้ใดก็ไม่มีคําพูดจะกล่าว\nฟ่านเสียนกล่าวด้วยความประหลาดใจว่า “ฝ่าบาทอนุญาต?”','2026-04-17 09:49:10'),(69,10,66,'เฉินผิงผิงเหลียวมองมันแวบหนึ่ง กล่าวอย่างเฉือยชาว่า “\nกระโน้นหนิงไฉเหยินเป็นเชลยหญิงสาวตงอี ในการกรีธาทัพขึ้นเหนือค5\nฝ่าบาทแทบทิึงชีวิตอยู่ในป่าเขาทางเหนือ เป็นหนิงไฉเหยินคอก\nปรนนิบัติ ค่อยรอดมาได้ ต่อมาจึงให้กําเนิดองค์ชายใหญ่”\nฟ่านเสียนเคยได้ยินตํานานเรื่องนี้ ทราบว่าตอนนั้นฝ่าบาทตกอยู่ไห\nจุดอับ เป็นชายชราซูบผอมที่ตนเองกำลังเข็นเก้าอิล้อเลือนให้นำทัพทมิพ\nดําชิงตัวกลับมาจากทางเหนือ การนึกโยงเช่นนี่ช่วยให้เข้าใจเรื่องราวอยู่\nบ้าง จึงกล่าว “ท่านกับหนิงไฉเหยินมีความสัมพันธ์ทีไม่เลว?\nเฉินผิงผิงกล่าวว่า “ตลอดรายทางที่หลบหนึกลับมา สภาพการณ์\nเลวร้ายยิง จึงประทับอยู่ในความทรงจําอย่างลึกลํา ความสัมพันธ์หลังจาก\nนั้นย่อมใกล้ชิดกว่าเดิม” มันกล่าวเสริมว่า “สถานการณ์ในตอนนั้นไม่\nสามารถนำเชลยหลบหนี้ ขณะที่หนิงไฉเหยินจะถูกตัดศีรษะ เราได้ออกปาก\nคําหนึ่ง อาจบางทีเพราะนึกถึงข้อนี้ นางจึงให้ความเคารพต่อเรา\nฟ่านเสียนกล่าวด้วยความยินดีว่า “ที่แท้ท่านเป็นผู้มีพระคุณช่วย\nชีวิตหนิงไฉเหยิน”\nเฉินผิงผิงหลับตาลงกล่าวว่า “ตอนนั้นฝ่าบาทรับบาดเจ็บ ร่างแข็ง\nที่อราวท่อนไม้ ไม่อาจขยับเคลื่อนไหว เรื่องการเช็ดตัว การขับถ่าย ย่อม\nต้องมีสตรีนางหนึ่งคอยดูแล”\nฟ่านเสียนกล่าวว่า “ต่อมาฟังว่าการเข้าวังของหนิงไฉเหยินก็ก่อ\nเกิดเป็นมรสุม ตอนนั้นฝ่าบาทยังไม่อภิเษกสมรส คิดรับเชลยหญิงชาว\nตงอื๋นางหนึ่งเข้าวัง ไทเฮาจึงไม่ยินดี ท่านใช่ช่วยเหลือนางหรือไม่?”\nเฉินผิงผิงอิ้มออกมา รอยย่นบนใบหน้าอยิ้มคล้ายผิวของซาลาเปา\nกล่าวว่า “คําพูดของเราตอนนั้นยังไม่มีน้าหนักเช่นวันนี้ ตอนนั้นเป็น\nคุณหนูออกปาก หนิงไฉเหยินค่อยเข้าวังได้”\nฟ่านเสียนทอดถอนใจกล่าวว่า “ที่แท้ไม่ว่าเรื่องใด มารดาชราของ','2026-04-17 09:49:10'),(70,10,67,'่เพเจ้าซมชอบสอดมือเข้ามา”\nเฉ็นผิงผิงกล่าวว่า “นางชมชอบยุ่งเกียวเรื่องไร้สาระ แต่ว่า นี้\nไยหเห่ในเรื่องไร้สาระ จนกระทั้งนางเอ่ยปาก ฝ่าบาทค่อยตัดสินใจ\nผูฏิเพกสมรส”\nฟ่านเสียนทําท่าแสยะหน้าล้อเลียนทีด้านหลังมัน กล่าวว่า “ตํานาน\nจกขกงคนรุ่นเก่า ข้าพเจ้ายังคงอย่าได้รับฟังแล้ว”\nเฉินผิงผิงยิมอย่างเยือกเย็นกล่าวว่า “รับฟังไว้ก็ดี อย่างน้อยตอนนี้\nๆ \"เทราบแล้วว่าในวังยังมีคนที่ไว้วางใจได้คนหนึ่ง\nฟ่านเสียนกล่าวว่า “หนิงไฉเหยินหรือ นี้เป็นบุญคุณเล็กๆ\nข้าพเจ้าไม่เชือว่าจะเกิดประสิทธิผลถึงทุกวันนี่\nเฉินผิงผิงกล่าวว่า “สตรีชาวตงอิมีนิสัยเผ็ดร้อนดุร้าย จําแนกบุญ\nตุแความแค้นชัดแจ้ง มิหน้าซําเมื่อสิบสามปีก่อน ในเหตุการณ์ล้างแค้น\nไห้กําคุณหนู นางออกแรงแข็งขันที่สุด เพราะเหตุนี้จึงล่วงเกินไทเฮา ถูก\nแพจกําติฐานะเป็นไฉเหยิน จนบัดนี้ยังไม่ฟืนฟูสู่ตําแหน่งเดิม”\nจากหนิงไฉเหยินนึกถึงองค์ชายใหญ่ ดังนั้นฟ่านเสียนกล่าวถามว่า\n\"ค่าแแน่ใจว่าต้าเตียนเซียไม่คิดช่วงชิงบัลลังก์?\nเฉินผิงผิงกล่าวอย่างเฉือยชาว่า “มันเป็นคนชาญฉลาด ดังนั้นใน\nาพเด็กเลือกวิธีหลบหนี้ จากมารดาพิสูจน์เห็นถึงบุตรชาย องค์ชายที่หนิง\nไหเหยินฝึกอบรมออกมา ยังเปิดเผยกว่าเหล่าเอฮ้อ (อันดับสอง) กับ\nฟ่านเสียนนิงเงียบงันไป ชั่วครู่ให้หลังพลันกล่าวว่า “หนิงไฉเหยิน\nทาราบเรื่องของข้าพเจ้าหรือไม่?\nเฉินผิงผิงตอบว่าไม่ทราบ จากนั้นอบรมสังสอนว่า “เมื่อถือไพ่อยู่ใน\nไม่อาจทิงออกไปทั้งหมด ควรซ่อนอยู่ในแขนเสือสักหลายใบ\n“ฝ่าบาท ทราบว่าข้าพเจ้าทราบหรือไม่?”','2026-04-17 09:49:10'),(71,10,68,'“ไม่ทราบ”\n“นี่ถือเป็นการทูลเท็จหรือไม่?”\n“ฝ่าบาทเมื่อไม่ได้ถาม พวกเราทีเป็นขุนนางย่อมไม่สะดวกกับกา.\nกล่าวอันใด”\nหนึ่งชราหนึ่งเยาว์วัยพากันหัวร่อออกมา หัวร่อราวกับสุนัขจึงจ\nสองตัว\nฟ่านเสียนกล่าวถามว่า “เรื่องของเหล่าเอ้อ (อันดับสอง) จะยุติแต่\nเพียงนี้หรือ?\nเฉินผิงผิงย้อนถามว่า “ท่านบรรลูเป้าหมายแล้วหรือไม่?”\nฟ่านเสียนงอนิวนับแล้วกล่าว “จัดการกับขุนนางทั้งสินสิบเจ็ดคน\nลิดรอนกำลังในราชสำนักของมันไปส่วนหนึ่ง เพียงแต่ยังไม่ลงมือต่อระดับ\nขุนนางสังซูกรมพลเรือน ส่วนตระกูลชุยก็ได้รับความเสียหายไม่น้อย ตาม\nจายงานข่าวจากทางเหนือ แขนขาของพวกมันถูกบังคับให้เคลือนไหวแล้ว\nคัดตัดมือของพวกมัน สามารถกระทําได้โดยง่ายดาย”\nเฉินผิงผิงกระตุ้นเตือนว่า “อย่าให้ผู้คนดูออกว่าเป้าหมายของท่าน\nค่๓ตระกูลชุย” ต่อจากนั้นกล่าวอีกว่า “ในการประชุมวันพรุ่งนี้ ฝ่าบาทจะมี\nข้อวินิจฉัย เหล่าเอฮ้อคงยากพลิกฟื้นได้\nฟ่านเสียนถามว่า “ตระกูลฟ่านเราจะมีปัญหาหรือไม่?”\n“ท่านนำพากับบรรดาศักดิหนั้นเจียหรือไม่?”\n“ข้าพเจ้าไม่นำพา”\nเฉินผิงผิงกล่าวว่า “อย่างนั้นก็ไม่มีปัญหา วางใจเถอะ บิดาท่าน\nเลลกกลิ้งกว่าผู้ใด ไหนเลยปล่อยให้ท่านพลาดท่าเสียที” มันไม่ทราบนึก\nได้อันใด ต้องกล่าวอย่างแค้นเคืองว่า “ฉวยโอกาสที่เราไม่อยู่ กลับเรียกตัว\nท่านกลับมาจากอ่าวต้านโจว ผีสางจึงทราบว่ามันคิดอะไร”\nฟ่านเสียนอดกล่าวมิได้ว่า “นั้นเป็นบิดาเรา”','2026-04-17 09:49:10'),(72,10,69,'เ4ในผิงผิงยกมือตบที่เท้าแขนของเก้าอิล้อเลือน กล่าวประชด\nแตเเต่แว่า “มันทําหน้าทีบิดาได้ไม่เลว”\nฟ่านเสียนไม่ยินดีทีได้ยินคําพูดเช่นนี้ จึงเงียบงันไป เฉินผิงผิงคล้าย\n(ไม่ถึงว่าเด็กผู้นี้จะให้ความเคารพพระกํากับดูแลทักษิณถึงเพียงนี่ จึงยืม\nแย ๒ห ลาบปลื่มประโลมใจ ถามว่า “วันนี้ท่านมาทําอะไร?”\nฟ่านเสียนฝืนยิมพลางกล่าวว่า “นำภรรยากับเม่ยเม่ยมาขอ\nจบระทานข้าวสักมือ ถือโอกาสให้พวกนางเปิดหูเปิดตาว่า เฒ่าชราเดียว\nตาแท่านชุบเลียงหญิงงามจํานวนมาก”\nมันพลันไม่คิดหยอกล้อกับชายชราผู้นี้สืบต่อไป เปลี่ยนเป็นถามว่า\n\"ข้าพเจ้ามีคําถามหนึ่งคิดถามท่าน”\n“บอกมา”\nฟ่านเสียนถามราวกับไร้เดียงสาว่า “ท่าน คิดเป็นขุนนางตงฉิน\nผุ้หนังจริงๆ?”\nเฉินผิงผิงระมัดระวังต่อการตอบคําถามข้อนี้ ผ่านไปเนินนานจึง\nแล่าวอย่างจริงจังว่า “เราภักดีต่อฝ่าบาท ภักดีต่อรัฐชซิง มิหนำซําตอนนี่\nท่าแคงทราบแล้วว่า ไม่ว่าท่านทําอะไร ฝ่าบาทล้วนเฝ้าดูท่านอยู่\nพระองค์อนุญาตให้ท่านกระทํา ท่านค่อยกระทําได้ ดังนั้นการภักดีต่อ\nฝ่าบาท แท้จริงแล้วเป็นความซือสัตย์ต่อตัวเอง ท่านต้องจดจําข้อนี้ให้มัน\nภัทดต่อฝ่าบาทตลอดไป”\nที่แท้ภักดีต่อฮ่องเต้ หรือว่าซือสัตย์ต่อตนเอง ฟ่านเสียนไม่คิด\nหทถึงปัญหาข้อนี่อีกต่อไป\nเฉินผิงผิงกล่าวว่า “แต่ครั้งนี้ท่านลงมือเร็วเกินไป เร็วกว่าแผนการ\nที่ฝ่าบาทวางไว้” มันหลับตาลงแล้วกล่าว “มิหนำซําลักษณะการกระทําของ\nท่านสูดโต่งเกินไป ฝ่าบาทไม่ทราบว่าท่านคาดเดาชาติกําเนิดของตัวเองได้\nหรือไม่ จึงนึกระแวงสงสัยตัวท่าน','2026-04-17 09:49:10'),(73,10,70,'ฟ่านเสียนนิงเงียบงันไป ทราบว่าเรื่องนี้นำมาซึ่งปัญหายุ่งยาก\nเฉินผิงผิงกล่าวเบาๆ ว่า “ไม่ต้องเป็นห่วง เราจะจัดการเอง”\nฟ่านเสียนไม่วิตกกังวลอีก เข็นเก้าอิล้อเลือนออกจากดงไม้ทีทั้ง\nงดงามทั้งโศกซึ่ง ยามนี่ทั้งสองมุ่งไปทางตะวันออก เงาที่ด้านหลังถูกลาก\nยาวออกไป แต่ล้อเลือนของเก้าอิยังคงพัวพันเงาร่างไว้\nวันทีสองเริมการประชุมตามกําหนดเวลา สองพ่อลูกตระกูลฟ่านซึ่ง\nลาป่วยหลายวันปรากฏตัวขึ้นในท้องพระโรง ตระเตรียมรับการกล่าวโทษ\nหนังสือกราบทูลของตึกตูฉาเยี่ยนยืนขึ้นมาเป็นเวลานานแล้ว ขุนนางสังซู\nกรมทะเบียนราษฎร์พระกํากับดูแลทักษิณยอมรับว่าอบรมหย่อนยาน เป็น\nเหตุให้เกิดบูตรอกตัญญูเช่นฟ่านซือเจ้อ ฟ่านเสียนก็ทําหนังสือยอมรับผิด\nเรื่องคดีฆาตกรรมในหอโอบจันทร์ เป็นเพราะตนเองปล่อยปละละเลยผู้น้อง\nส่วนข้อหาอย่างอืน ตระกูลฟ่านไม่ยอมรับ จะอย่างไรเรื่องให้ร้าย\nข้าหลวงมหานคร ตลอดจนการฆ่าคนปิดปากกลางสายฝน ทั้งสองฝ่าย\nไม่มีหลักฐานอันใด ทั้งไม่ทึ่งร่องรอยใดไว้ สามารถปิดปากขุนนางกล่าว\nโทษได้\nในทางกลับกัน ตระกูลฟ่านกล่าวหาฝ่ายขององค์ชายรอง ฝ่ายตรง\nข้ามยากจะรับมือได้ จะอย่างไรผู้ที่ฆ่าคนหน้าสำนักว่าการมหานครเป็น\n4 0 ท้ายเซี่ยปี้อั\nหนึ่งในแปดขุนพลประจําตัวองค์ชายรองนามเซียปีอัน สุดท้ายเซียปีอัน\nเสียชีวิตในคุก ผู้ต้องสงสัยล้วนเป็นองค์ชายรอง\nทีสร้างความประหลาดใจแก่เหล่าขุนนางคือ การโจมตีของฝ่ายองค์\nชายรองไม่รุนแรง เพียงตอบโต้เล็กน้อยก็หยุดมือ ต่อจากนั้นทั้งหมดค่อย\nคาดเดาว่า ทั้งสองฝ่ายคงบรรลูข้อตกลงลับอันใด ซึ่งก็หมายความว่าองค์\nชายรองยอมรับความพ่ายแพ้แล้ว','2026-04-17 09:49:10'),(74,10,71,'ห่องเต้ประทับนั่งบนบัลลังก์มังกร ทรงสดับตรับฟังอย่างสงบ มีแต่\nตยก1เที่ฟ่านเสียนเดินออกมายอมรับผิด พระเนตรของพระองค์ค่อยทอ\nประกายวูบหนึ่ง\nหลังจากนั้นฮ่องเต้ทรงวินิจฉัย ในที่สุดเรื่องราวมีข้อยุติ\nขุนนางสังซูกรมทะเบียนราษฎร์พระกํากับดูแลทักษิณฟ่านเจียน\nตบวมเหย่อนยาน ปล่อยให้บุตรคนเล็กก่อการร้าย แต่เห็นแก่คุณงามความ\nต่ท่ผ่านมา ทั้งแจ้งความล่วงหน้า จึงลงโทษสถานเบา ตัดเงินเดือนสามปี\nแตฯ1เวรดาศักดิสองขัน ให้กักตัวเองสํานึกผิด\nเจ้าหน้าทีถีซือสำนักตรวจสอบควบตําแหน่งขุนนางเฟิงเจิึงสถาน\nทเหษาไท่เสวียฟ่านเสียนประพฤติตัวไม่เหมาะสม ใช้กำลังของสำนักโดย\nพลการ ถึงแม้ยอมรับผิดแทนผู้น้อง แต่ความผิดไม่อาจละเว้น จึงถอดถอน\nแววตาศักดิลดเงินเดือน ทําคุณไถ่โทษโดยการตรวจสอบชําระหนังสือหนัง\nพหาทีจวงม่อหานให้ให้แล้วเสร็จภายในสามปี\nกรมราชทัณฑ์ออกประกาศ ติดตามจับกุมบุตรคนเล็กของตระกูล\nฟ่านนามฟ่านซือเจ้อที่หนี้คดี\nข้าหลวงมหานครถูกจับกุมคุมขังแล้ว ให้ปลดออกจากตําแหน่งและ\nไต่สวนความผิด\nยังมีกว้อกง (เจ้าพระยา) อีกหลายท่าน\nสุดท้ายค่อยตัดสินความผิดขององค์ชายรองว่าประพฤติตัวไม่\nเหมาะสม ให้ลดบรรดาศักดิ กักบริเวณขัดเกลาจริยะ เป็นเวลาทั้งสินหก\nเตือน\nในที่สุดผลออกมาแล้ว ทุกถ้อยคําควรแก่การตีความ แต่ไม่ว่า\nกย่างไร สองพ่อลูกตระกูลฟ่านถูกลดบรรดาศักดิตัดเงินเดือน แท้จริงแล้ว\nไม่ได้รับความเสียหายอันใด กลับเป็นฝ่ายองค์ชายรองสูญเสียขุนนางมาก\nหลาย ตนเองยังถูกกักบริเวณหกเดือน ถือเป็นบทลงโทษสถานหนัก','2026-04-17 09:49:10'),(75,10,72,'หมายความว่าการศึกครังนี้ตระกูลฟ่านเป็นฝ่ายชนะ\nแต่ผู้ที่ตั้งใจจําแนกราชโองการของฮ่องเต้ พบเห็นความบังเอิน\nประการหนึ่ง ความผิดของฟ่านเสียนกับองค์ชายรองล้วนคลุมเครือ ใช้คํา\nว่าประพฤติตัวไม่เหมาะสม แต่ในฐานะเจ้าหน้าทีถีซือสำนักตรวจสอ1!\nการประพฤติตัวไม่เหมาะสมไม่เป็นไร แต่ว่าองค์ชายสูงศักดิถูกตัดสินว่า\nประพฤติตัวไม่เหมาะสม อย่างนั้นก็ส่งผลกระทบมากแล้ว\n๕ ซู เ เเฑูร่ 1\nทั้งหมดเห็นว่าองค์ชายรองไม่เป็นทีโปรดปรานของฮ่องเต้เช่นกาล\nก่อน แต่ว่าฮ่องเต้ก็ไม่เบิกตัวฟ่านเสียนเข้าวังอีก ดังนั้นทั้งหมดครุ่นคิด\nหรือว่าเสือสองตัวต่อสู้กัน ล้วนได้รับบาดเจ็บ ฟ่านเสียนก็ไม่เป็นที่โปรด\nปรานอีก\nแต่ว่าฟ่านเสียนคล้ายไม่มีปฏิกิริยาใด ตลอดทั้งวันจับเจ่าที่สถาน\nศึกษาไท่เสวีย ตรวจชําระหนังสือหนังหาร่วมกับครูสอนหนังสือ บางครั้ง\nแวะไปที่สำนักตรวจสอบ ทั้งยังหาเวลาว่างสองวัน เข้าพบฉินเหล่าเจียง\nจวินแห่งมนตรีแห่งรัฐ ทั้งนำว่านเอฮ้อกับเม่ยเม่ยเข้าวังไปกราบพระชายา\nทั้งหลาย บังเอิญพบกับองค์ชายใหญ่ทีตําหนักน่วนฟาง ซึ่งองค์หญิงใหญ่\nแห่งเปียฉีพักอาศัยอยู่ แน่นอน การเข้าวังครังนี้ไม่ได้เข้าเฝ้าฮ่องเต้\nฟ่านเสียนยังหารือลับกับเอียนปิงหวินหลายครั้ง คํานวณเส้นทาง\nการค้าของเถือนของท้องพระคลังออก รอเวลาตัดมือของตระกูลชุย ตัด\nเส้นทางทางการเงินของจ่างกงจู่กับองค์ชายรอง ทั้งควบคุมพลังลมปราณ\nภายในกายมิให้แตกเตลิด ขณะเดียวกันก็รอจดหมายตอบจากเพยเจียเฟย\nเหล่าซือว่าให้รับประทานตัวยานั้นหรือไม่\nผ่านไปอีกสองวัน ใต้ลมหนาวของปลายชิวเทียน เทศกาลชม\nเบญจมาศซึ่งถูกเลือนมานานวันในที่สุดเริมขืนแล้ว แต่ว่าฟ่านเสียนห่อหุ้ม\nตนเองราวกับขนมจ้าง มองดูใบไม้ร่วงที่นอกหน้าต่างอย่างขลาดเขลา\nครุ่นคิดว่าอากาศหนาวเช่นนี้ ยังมีเบญจมาศใดให้ทอดทัศนาอีก?','2026-04-17 09:49:10'),(76,10,73,'เบพหมาห พาทระบี (1)\nชาวจงหยวน (ภาคกลางของประเทศ) ให้คํานิยามเบญจมาศว่าหยิง\nทะนงในศักดิศรี สูงสง่าท้านำค้างแข็ง ระหว่างที่ฟ่านเสียนใช้ชีวิตที่อ่าว\nด้านโจว ก็พบเห็นดอกไม้ชนิดนี้ ผลผลิตของเบญจมาศต้านโจวมีชือเลือง\nแต่ละปีตึกตระกูลฟ่านนำเข้าจากอ่าวด้านโจวมายังมหานครเป็นจํานวน\nเพราะเหตุนี้ฟ่านเสียนคุ้นกับดอกไม้ชนิดนี้เป็นอย่างดี บางครั้งนึกถึง\nตกนอยู่บนหน้าผาชายฝังทะเล พบเห็นดอกไม้เหลืองเบ่งบาน มันทราบว่า\nเพบจมาศแม้ทนทานความหนาว ในบทกวีของหยวนเจิน เมื่อชาติปาง\nกหนยังรจนาว่าหลังจากดอกไม้นี้ไม่มีดอกไม้บานอีก แต่ถึงอย่างไรมิใช่\nตกกเหมยฤดูหนาว ในช่วงเวลาปลายชิวเทียนที่หนาวเย็นเช่นนี้ เบญจมาศ\nกงร่วงโรยราจนหมดสิน\nรถม้าแล่นผ่านการรักษาการณ์อย่างเข้มงวดที่เชิงเขา ถูกจับตามอง\nงากราชองครักษ์กับทหารรักษาพระองค์ หนุ่มสาวของตระกูลฟ่านทั้งหลาย\nลงจากรถ ปืนป่ายไปตามภูเขาเป็นเวลานาน หลังจากอ้อมธารนำตกซึ่ง\n\" แว้ในยุคราชวงศ์ถัง','2026-04-17 09:49:10'),(77,10,74,'ไม่ไหลแรงเท่าฤดูใบไม้ผลินี้ ก็เห็นวิหารปลูกสร้างบนผนั่งผาลาดชัน\nวิหารปลูกอิงภูเขา อาศัยเสาไม้คํายันต่อขึ้นไปชันแล้วชันเล่า ส่วน\nที่กว้างที่สุดเพียงวาเศษ คล้ายกับผู้คนใช้กระดาษแปะติดไว้ บนภูเขาลม\nชิวเทียนพัดแรง สร้างความอกสันขวัญแขวนแก่ผู้ชมดู หวันวิตกว่าวิหาร\nใช่ถูกหอบพัดพาไปหรือไม่ ตามคําเล่าลือ นี้เป็นวิหารหลังแรกของรัฐชซิง\nสร้างจากพลังศรัทธาของผู้บําเพ็ญทุกรกิริยาทีเลือมใสในวิหารศักดิสิทธิ ใช้\nเวลาก่อสร้างหลายร้อยปี เพื่อเผยแผ่แสงธรรมอันเรื่องรอง สอนให้ผู้คน\nกระทําความดี\nธิไม่ย่\nทีผ่านมาวิหารศักดิสิทธิไม่ย่งเกียวกับเรื่องทางโลก คงความลึกลับ\nไว้ แต่หลายพันปีมานี้ คล้ายมีอิทธิพลต่อการรวมรังแยกตัวของแผ่นดิน\nใหญ่แถบนี้ มีคําเล่าลือมากมายทีสะท้อนภาพของวิหารศักดิสิทธิ บวกกับ\nผู้บําเพ็ญทุกรกิริยาแม้มีไม่มาก แต่ก็รักษาความเทียงธรรมไว้ ดังนั้นใน\nสายตาของปวงประชา วิหารศักดิสิทธิมีศักดิฐานะอันสูงส่ง\nสำหรับกับราชสำนักฝ่ายปกครอง ก็ให้ความเคารพต่อวิหารศักดิสิทธิ\nดังนั้นเทศกาลชมเบญจมาศซึ่งจัดขึ้นทุกสามปีครัง จะจัดขึ้นที่วิหารฮุ่ยคง\n(กลางอากาศ) แหงน\nเทศกาลชมเบญจมาศยังเป็นการกระชับความสัมพันธ์กับเชือพระ\nวงศ์สูงศักดิ เพิ่มความเข้าใจกว่าเดิม จะได้หลีกเลี่ยงจากความขัดแย้ง\nอย่างน้อยไม่เกิดเหตุการณ์เมื่อหลายสิบปีก่อนทีชิงอ๋องสองท่านถูก\nลอบสังหาร เป็นเหตุให้รัฐชิงเกิดสภาพสูญญากาศ หาผู้สืบราชบัลลังก์\nไม่ได้\nตอนนี้ราชวงศ์ชิงมีสมาชิกไม่มากนัก ดังนั้นเทศกาลชมเบญจมาศ\nยังเชิญญาติพีน้องที่เกี่ยวดอง ตลอดจนตระทกูลทิใกล้ชิดกับราชวงศ์เข้าร่วม\nตามกฎเกณฑ์ ในหลายปีนี้ตระกูลฉินกับตระกูลเยียซึ่งเป็นเสาหลักของ\nกองทัพจะมีส่วนร่วม ตระกูลฉินมีขุมกำลังในกองทัพ ส่วนตระกูลเยียทํา','2026-04-17 09:49:10'),(78,10,75,'หน้าที่วักษามหานคร ในตระกูลยังมีปรมาจารย์ท่านหนึ่ง จึงมีศักดิฐานะ\nพิเศษ\nนอกจากนี้เป็นเหล่ากว้อกง (เจ้าพระยา) ที่ได้รับบรรดาศักดิเมื่อ\nตกแวกตั้งประเทศหลายท่าน ยังมีตระกูลทีเข้ามาใหม่ เช่นตระกูลเยินซึ่ง\nตบเแต่งจวินจู่สายนอกนางหนึ่งไปเป็นภรรยา ส่วนตระกูลฟ่านที่อยู่ในข่าย\nจนเซ มิใช่เพราะตระกูลฟ่านตอนนี้ทรงอํานาจ และมิใช่ฟ่านเสียนตบแต่ง\nหน่นเง่านเอ้อเป็นภรรยา หากแต่เป็นเพราะไหน่ไหน (ท่านย่า) ของตระกูล\nฟ่ แแคยเลียงดูฮ่องเต้กับจึงอ้องจนเติบใหญ่ หากเอ่ยถึงความสัมพันธ์ส่วน\nตระกูลฟ่านถือเป็นตระกูลทีใกล้ชิดกับราชวงศ์ที่สุด\nฟ่านเสียนยืนเท้าสะเอวอยู่หน้าวิหารฮุ่ยคง มองดูผู้ทรงอํานาจของ\n\'จุซิงที่ยืนประปรายอยู่รอบข้าง อดพืมพํามิได้ว่า “ชมเบญจมาศ ชม\nเบพจมาศ เบญจมาศอยู่ที่ใด?\nยามนี้พระกํากับดูแลทักษิณถูกเชิญไปยังทีอับลมแล้ว เหล่าผู้อาวุโส\nก่องเมืสิทธิพิเศษ รถม้าก็จอดอยู่ที่เชิงเขา องครักษ์ทัวไปถูกกันอยู่นอกแนว\n1ไกงกันของทหารรักษาพระองค์ ดังนั้นคนของตระกูลฟ่านมีเพียงหนึ่ง\n1บุจษสองสตรี หลินว่านเอ้อซึ่งเป็นหนึ่งในจํานวนนั้นชีมือไปยังเบืองล่าง\nเหเล่าวว่า “อยู่ทีนี้”\nฟ้านเสียนงงงันวูบ สืบเท้าไปยังริมหน้าผาหนึ่งก้าว ลมชิวเทียนก็\nไหยมาปะทะหน้า ต้องหยีตาลง จากนั้นสูดลมหายใจเข้าไปคําหนึ่ง ชมเชย\nง่า “สถานทีอันงดงามนัก”\nหน้าผาทีก่อสร้างวิหารฮุ่ยคงเว้าเข้าไปเล็กน้อย ลักษณะเป็นรูปตัว\nทู ทางภูเขาตัดผ่านด้านข้างไป ดังนั้นตอนขึ่นมา ฟ่านเสียนไม่ได้สังเกตว่า\nพนที่ข้างทางภูเขามีสภาพอย่างไร ยามนี้ขึ่นมายังที่สูงมองลงไป การมอง\nเห็นจึงขยายกว้างออก เห็นข้างทางภูเขาดาดาษด้วยเบญจมาศ สีของ\nแบจมาศเหลานคอนขางเขม เป็นสีเหลองทอง กลิบดอกก็เรียวยาวกว่า','2026-04-17 09:49:10'),(79,10,76,'ฟ่านเสียนยืนอยู่ริมหน้าผา ทอดถอนใจชมเชยว่า “เบญจมาคย\nเหลืองทองสอดคล้องกับท่วงทํานองของเชือพระวงศ์ ท่ามกลางอากาก\nหนาวยังบานสะพรังถึงเพียงนี้ นับเป็นปรากฏการณ์พิเศษจริงๆ\nหลินว่านเอ้ออธิบายว่า “นี้เป็นเบญจมาศด้ายทอง ฟังว่าหลังจากพ่\nวิหารฮุ่ยคงปลูกสร้างแล้วเสร็จ มหาสมณะเกินเฉินแห่งสำนักฟ้าเอกะแควห\nเปยเว่ยเพาะปลูกด้วยตนเอง นับแต่นั้นมากลายเป็นทิวทัศน์พิเศษขถง\nมหานคร”\nฟ่านเสียนทวนคําว่า “เกินเฉิน? เป็นอาจารย์ปู่ของขู่เหอหรือ?”\n“ถูกแล้ว”\nฟ่านเสียนสันศีรษะคราหนึ่ง ยังคงมองลงไป หลังจากมองดูค่อยพบ\nว่าเบญจมาศพันธุ์พิเศษนี้ไม่ดกดืนเท่าใด เนื่อดินบริเวณภูเขาไม่อุดม\nสมบูรณ์ ทุกระยะหลายเชียะค่อยปลูกเบญจมาศต้นหนึ่ง เพียงแต่คนชม\nบุปผาถูกยืดระยะห่างออกไป จนเกิดภาพลวงตาว่ากลีบดอกสีทองปกคลุม\n\'ทวปาเขา บวกกับทัวทัศน์ภูเขาสีทับขับเน้น ดูไปจึงงดงามตระการตาเป็น\nพิเศษ\nยามนั้นมีคนเข้ามาทักทาย แต่เนื่องจากตอนนี้ฮ่องเต้ทรงชีดชาต่อ\nฟ่านเสียน บวกกับศักดิฐานะของหลินว่านเอื้อ ไม่อนุญาตให้คุณชายตระกูล\nไหยญ่กล่าวมากความ ดังนั้นเพียงทักทายแล้วจากไป ฟ่านเสียนทางหนึ่ง\nสนทนากับทั้งหมดอย่างอ่อนโยน ทางหนึ่งถือโอกาสสํารวจภูมิประเทศรอบ\nข้างตามลักษณะนิสัยของตนเอง\nวิหารฮุ่ยคงแขวนอยู่กลางอากาศ หลังฉากเป็นหน้าผาลาดชัน มี\nเจนทางขึ้นเขาเพียงสายเดียว วันนี้เชือพระวงศ์รัฐชิงชุมนุมอยู่ทีนี้ ทีเชิง\nเขาจงกระจายด้วยทหารรักษาพระองค์เป็นชันๆ ส่วนรอบในเป็นราช\nกงครักษ์วังหลวงภายใต้การนำของกงเตียน สำหรับเหล่าขันทีที่หลุบคิวก้ม\n) มีลูกหลานของหงกงกงอยู่ด้วยหรือไม่ไม่ทราบได้ แต่ไม่พบเห็น','2026-04-17 09:49:10'),(80,10,77,'จู่ตจากกขางพยัคฆ์พิทักษ์ สร้างความประหลาดใจแก่ฟ่านเสียนอยู่บ้าง แต่\nดูจ แน เตาการรักษาความปลอดภัยเฉพาะหน้า อย่าว่าแต่คนร้ายอันใด ต่อ\nหนึ่งคิดเล็ดลอดขึ้นเขายังยากเย็นยิง\nมันเยิมพลางทักทายขุนนางยศเส้าซิงตึกไท่ฉังซือนามเยินเส้าอัน\nเผ็นก่แฟ่ายถูกผู้คนฉุดลากตัวไป รู้สึกน่าหัวร่ออยู่บ้าง พ่อตาของตนเอง\nยตตแจ แหพาชการเป็นเวลานาน สายสัมพันธ์กับคนเหล่านี่ล้วนจางเบาบาง\nฟ่านเสียนหยีตามองขึ้นไป เห็นผู้ทรงอํานาจที่สุดของรัฐชิงหลาย\nท่แขงเนมอยู่ในวิหารที่สร้างจากไม้ มองแต่ไกลเห็นชันบนสุดมีบูคคลชุด\nเหน่คงเกาะราวลูกกรง ทอดทัศนาทิวทัศน์ ย่อมเป็นฮ่องเต้แล้ว\nฟ่านเสียนดูไปดูไป บังเกิดความรู้สึกที่แปลกประหลาด ใช้สมอง\nนึกภาพเหตุการณ์ว่าหากตอนนี้ปรากฏยอดฝีมือแคว้นเปียฉีหรือ\nแพวตงอิจุดไฟเผาวิหารฮุ่ยคงหลังนี่ แผ่นดินจะกลับกลายเป็นเช่นใด?\nแน่นอน ฟ่านเสียนทราบว่าวันนี้มหานครรักษาการณ์อย่างเข้มงวด\nตหงไม่เกิดเรื่องเช่นนี่ขึ่น แต่ยังนึกจินตนาการอย่างอุกอาจว่า หากว่าตนเอง\nทตขนไปยังวิหารหลังนี้ สมควรเลือกที่หยังเท้าใด ใช้เส้นทางไหน ค่อยขึ้น\nนี้เป็นความเคยชินของมืออาชีพทั้งสิน\nพลันปรากฏขันทีผู้หนึ่งเดินออกจากในวิหาร คนหนุ่มสูงศักดิบน\nผานที่ว่างหน้าวิหารรีบเปิดทางสายหนึ่ง ขันทีนั้นเดินถึงเบืองหน้าคนของ\nตาะกถูลฟ่านทั้งสาม กล่าวเบาๆ อย่างนอบน้อมว่า “ฝ่าบาทเบิกตัวแม่นาง\nว่านแอ้อเข้าเฝ้า\nหลินว่านเอ้องงงันวูบ เหลือบมองฟ่านเสียนแวบหนึ่ง ถามเสียง\nแมนวลวา “ไต้กงกง เพียงเบิกตัวข้าพเจ้าคนเดียวหรือ?\nได้กงกงเป็นคนคุ้นเคยกับฟ่านเสียน ทั้งทราบว่าในสภาพที่ถูกจับตา','2026-04-17 09:49:10'),(81,10,78,'มองเซ่นนี้ หากฟ่านเสียนไม่ได้เข้าวิหาร จะเกิดข้อวิพากษ์วิจารณ์อันใด 4\nกวาดมองฟ่านเสียนอย่างเสียใจแวบหนึ่ง กล่าวว่า “ฝ่าบาทไม่ได้มีพระ2า9\nกระแสอย่างอืน”\nฟ่านเสียนยิมออกมา กล่าวกับหลินว่านเอ้อว่า “อย่างนั้นท่านไ1\nเถอะ” หยุดเล็กน้อยจึงหัวร่อเบาๆ กล่าวว่า “ข้าพเจ้าทราบว่าจิวจิว\nเอ็นดูหลานสาวที่สุด”\nมันมองดูหลินว่านเอ๋อหายลับกับประตูวิหารอันดํามีด จากนั้นน่\nเม่ยเม่ยเดินไปยังอีกมูมหนึ่ง คิดเสาะหาตําแหน่งมูมชมทิวทัศน์ มิคา๓\nบงเกดสุมเสยงหนงร้องเรยกว่า “ซือฟู (ทานอาจารย)\nฟ่านเสียนเหลียวหน้ามอง เห็นเป็นเยียหลิงเอ้อ อีกฝ่ายมีสีหน้าไม่\nสบายใจอยู่บ้าง ฟ่านเสียนทราบว่าเป็นเพราะเหตุใด ปีหน้าเยียหลิงเอือ\nต้องแต่งกับองค์ชายรอง ตนเองกับองค์ชายรองกลับต่อสู้อย่างดูเดือด นาง\nเมื่อเป็นบุตรีของเยียฉง ไหนเลยไม่ล่วงรู้เหตุผลกลในได้\nฟ่านเสียนยิมอย่างอ่อนโยน ถามว่า “คิดอะไร ใช่โทษว่าข้าพเจ้า\nรังแกเซียงกง ในอนาคตของท่านอย่างสาหัสหรือไม่?\nเยียหลิงเอ้อเห็นมันกล่าวสัพยอก ค่อยกลับคืนสู่นิสัยใจคออันเบิก\nบานแจ่มใส ร้องเพ้ยกล่าวว่า “เพียงหวันวิตกว่าท่านไม่ยอมพูดจากับ\nข้าพเจ้า\nฟ้านเย่อเย่อทีด้านข้างหัวร่อพลางกล่าวว่า “นี้เป็นวาจาใดกัน?”\nเยียหลิงเอ้อทอดถอนใจกล่าวว่า “เหล่าเอ้อ (อันดับสอง) ไม่ทราบ\nไปที่ใด หลังจากนี้ขาไพ่ขาดไปคนหนึ่ง รู้สึกไม่คุ้นเคยอยู่บ้าง”\nที่สวนหลังของตึกตระกูลฟ่านมักตั้งวงไพ่นกกระจอก ขาไพ่\nประกอบด้วยฟ่านเย่อเย่อ ฟ่านซือเจ้อสองพีน้อง กับหลินว่านเอ้อและเยีย\nในที่นี้หมายถึงฮ่องเต้\nในที่นี่หมายถึงองค์ชายรอง','2026-04-17 09:49:10'),(82,10,79,'หติ แก่กที่หัในเพื่อนสนิท\nฟ่านแสียนอยิ้มพลางกล่าวว่า “ที่ผ่านมาท่านกับเย่อเย่อมักเล่นเสียให้\nศันขึกเจ้กและว่านเอือ วงไพ่เมื่อล่มสลาย ท่านจะได้เล่นเสียน้อยลง สมควร\nฝันต่จํงถูกต้อง”\nเถ่ยถึงตอนนี้ ฉินเหิงเดินเข้ามาสมทบ คนยังไม่มาถึงก็รําร้องว่า\nเนหลบซ่อนอยู่ที่นี้ทําอะ 3?”\nตูจากสุ้มเสียงอันกังวานของมัน เกรงว่าจงใจให้ทั้งหมดได้ยิน ฟ่าน\nเศีกแจ็งฝันอิ้มพลางกล่าวว่า “เป็นเรื่องเกี่ยวกับไพ่นกกระจอก”\n“ในเหทิงตบไหล่ฟ่านเสียนกล่าวว่า “นี้เป็นความจัดเจนของข้าพเจ้า”\nพแวงเหงาดตามองรอบข้าง ขมวดคิวพลางกล่าวว่า “เทศกาลชมเบญจมาศ\nเป็นฝ่าบาทเปิดโอกาสให้ลูกหลานตระกูลใหญ่ใกล้ชิดกัน ทีข้างกายท่าน\nไหแแง่ยบเหงาถึงเพียงนี้?” ด้วยอิทธิพลอํานาจของฟ่านเสียน สมควรมีคน\nเจข้เยแทหประจบสอพลอสักหลายคน ต้องไม่เงียบเหงาถึงเพียงนี้\nฟ่านเสียนกล่าวเสียงราบเรียบว่า “วันนี้ค่อยทราบว่าเบญจมาศได้\nแต่งแลงไกล ไม่อาจเข้าใกล้ไป ท่านก็ล่วงรู้นิสัยใจคอข้าพเจ้า ความจริง\nแจะสนทนากับผู้คน ยิงไม่มีอารมณ์ใกล้ชิดสนิทสนม\nในสายตาของมัน เทศกาลชมบูปผาคล้ายงานจิวฮุ่ย เมื่อชาติปาง\nทน ถือโอกาสแสดงความสัมพันธ์ถีห่างกับเชือพระวงศ์ ยกระดับฐานะของ\nตเแคง แต่สำหรับกับฟ่านเสียน ย่อมไม่ลดตัวลงเข้าหาอํานาจ จึงรู้สึกไร้\nสาระยิง\nฉินเหิงมีอายุสามสิบปี ตบแต่งภรรยาแต่แรก แต่ว่าตระกูลฉินทุก\nสามปีต้องมาชมดอกไม้เหลืองหนึ่งครั้ง ไม่ทราบชมดูกีครั้ง จนเบื่อหน่าย\nแต่แรก พอฟังจึงผงกศีรษะรับ\nวันนี้ื้องค์ชายรองกับซือจือไม่ได้รับอนุญาตออกจากวัง ยงคงถูก\n\' ฟาร์ต','2026-04-17 09:49:10'),(83,10,80,'จํากัดบริเวณไว้ ไม่ได้มาทีวิหารฮุ่ยคง\nเยียหลิงเอ้อกะพริบตาทีสุกใส กลาววา “ซอฟูทีนี้ ทิวทัศน์ไม่เล!\nกบทเถอะ”\nแต่งกวีแล้ว”\nเยี่ยหลิงเอ้อเรียกมันเป็นซือฟู่ มองว่าเป็นการล้อเล่นของศิษย์สต4\nแต่ฟ่านเสียนกลับวางก้ามเป็นซือฟู่ ออกจะน่าขบขันอยู่บ้าง ฉินเหิงกับฟ่าน\nเย่อเย่ออดหัวร่อมิได้\nฉินเหิงกล่าวว่า “ใต้เท้าเสี่ยวฟ่านแต่งทํานองเพลงสั้นที่แคว้นเปียฉี\nแพร่กระจายไปทั่วแผ่นดินแล้ว ยังคิดตบตาพวกเราอีก?”\nฟ่านเสียนรู้สึกปวดเศียรเวียนเกล้า ได้แต่เอื้อนกวีสอดรับกับ\nบรรยากาศสองประโยค จากนั้นกล่าวว่า “อย่าได้เผยแพร่ออกไป ตอนนี้\nข้าพเจ้ารังเกียจการแต่งกวีที่สุด”\nฟ่านเย่อเย่อกำลังนึกทบทวนคํา “มิใช่เพียงรักชอบเบญจมาศ หลัง\nดอกไม้นี้ไร้ดอกไม้บานอีก ” ซึ่งฟ่านเสียนเอื้อนออกมา พอฟังอดถามมิได้\nว่า “เพราะเหตุใด?”\nฟ่านเสียนกล่าวว่า “เพราะว่าการถูกผู้คนไล่กวดตาม ร้องขอให้แต่ง\nกวี เป็นเรื่องที่ปวดร้าวที่สุด”\nกล่าวพลางหัวร่อฮาฮาออกมา หัวร่ออย่างไม่มีต้นไม่มีปลาย หัวร่อ\nด้วยความเบิกบานใจที่สุด\nเหล่าผู้สูงศักดิ์ที่ชุมนุมอยู่หน้าวิหารฮุ่ยคงพอได้ยินเสียงหัวร่อนี้\nต่างเหลียวมองมาคค่างงุนงง ค่อยพบเห็นหนุ่มสาวที่ริมหน้าผาทั้งสี จาก\nนั้นจดจําศักดิฐานะของทั้งส่ถก อดสะท้านใจมิได้ ใต้เท้าเสียวฟ่านมี\n” วรรคทองของหยวนแจ่นสมัยวาฑาเงทกัง','2026-04-17 09:49:10'),(84,10,81,'แวมกวะเตืองเลืองแผ่นดิน แต่ว่ามันกระชากองค์ชายรองลงจากหลังม้า\nแต้) ตกนนี้ยังยืนอยู่กับหนุ่มสาวตระกูลฉินและเยียสองคน หรือหมายถึง\nฟ่านเสียนไม่สนใจสายตาของผู้อืน แต่แล้วรู้สึกแสบจมูกอยู่บ้าง\nที่แท้สุตได้กลินเผาไหม้ชนิดหนึ่ง ต้องครุ่นคิด หรือว่าอาหารหลักในวันนี่\nเป็นหมูแฮม มันเหลียวหน้าไป เห็นมุมหนึ่งของวิหารฮุ่ยคงปรากฏควันดํา\nศายแหแงลอยขน\nในบริเวณผู้ทีมีประสาทสัมผัสไวที่สุดย่อมเป็นฟ่านเสียน แต่ผู้อื่นไม่\nพเห็นความผิดปรกติ แม้แต่ราชองครักษ์วังหลวงทีรักษาการณ์อยู่รอบ\nขาาก็ไม่มีปฏิกิริยาใด\nลมชิวเทียนโชยพัดผ่าน ควันดําสายนั้นคล้ายถูกเลิกขึ้น พลันแผ่\nกกะจายออก ในม่านสีดําเผยเห็นเปลวไฟ ขณะที่ร่างของฟ่านเสียนคล้าย\nยูจงเชิวเทียนหอบพัดไปยังหน้าวิหารฮุ่ยคง\nะ ขะรด\n“ฉินเทิง คุ้มครองยาโถวทั้งสองให้ดี\nเสียงขาดคํา ร่างของฟ่านเสียนมาถึงหน้าวิหาร เห็นเปลวอัคคี\nพวยผพุ่งออกมา รู้สึกถึงคลื่นความร้อนที่มาปะทะหน้า ปรากฏราชองครักษ์\nผุหนังฟาดฟันดาบใส่มันวุ่นวาย ฟ่านเสียนต้องฟาดฝ่ามือกระแทกคนพั้น\nหท่าง ด่าทอว่า “ตาบอดหรือไม่?”\nเนื่องจากวิหารฮุ่ยคงสร้างจากไม้ ดังนั้นอัคคีลูกลามอย่างรวดเร็ว\nบวกกับคนหนุ่มสูงศักดิที่เข้าว่วมเทศกาลชมเบญจมาศรําร้องพลางหนี้\nเตลิตเปิดเปิง สร้างความโกลาหลวุ่นวายขึ้น ถึงแม้ว่าฤดูชิวเทียนวัตถุแห้ง\n” เงเยม ส ขะ จั ๕\nแล่ง แต่ว่าอัคคีครังนิเกิดขินอย่างประหลาด ผูบญชาการราชองครกษก\nเนชนสูงสุดของวหาร เหล่าราชองครักษ์ทีเบืองล่างจึงแตกตื่นลนลาน\nหพู่ท้าง','2026-04-17 09:49:10'),(85,10,82,'ฟ่านเสียนตวาดใส่เหล่าราชองครักษ์และขันทีว่า “หินทรายที่จั๓\nเตรียมไว้อยู่ที่ใด?”\nมันพอเอ่ยปาก คนเหล่านั้นค่อยมีสติแจ่มใสกว่าเดิม ทั้งล่วงรู้ศักต์\nฐานะของฟ่านเสียน จึงทําตามคําสังการของมัน ก่อนอื่นเชิญขุนนางใหญ่\nทีสูงอายุออกจากชันล่างของวิหาร จากนั้นส่งราชองครักษ์ขึ่นไปอารักขา\nพร้อมทั้งจัดยอดฝีมือสิบกว่าคนเฝ้ารักษาอยู่รอบบริเวณ\nเป็นปฏิกิริยาทีรวดเร็ว ความ เคลือนไหวรวบรัดห มดจด ถงแมเหลา\nสูงศกดเกดความแตกตนตระหนก แต่เหล่าราชองครักษ์กับขันทียังดับไฟ\nอย่างกล้าหาญ ไม่นานก็ควบคุมเพลิงที่ชั้นล่างได้ เหล่าใต้เท้าสูงอายุรวม\nทั้งพระกํากับดูแลทักษิณฉวยโอกาสล่าถอยออกจากชั้นล่าง แต่ว่าบันได\nของวิหารฮุ่ยคงคับแคบ คนส่งข่าวขึ้นไปชักช้า ผู้คนที่ชั้นบนยังไม่ลงมา\nฟ่านเสียนเห็นบิดาปลอดภัย ค่อยคลายใจลง แต่ยังอกสั้นขวัญแขวน\nไม่คลาย คิดไม่ถึงมโนภาพของตนเองกลับกลายเป็นจริง หากว่าอัคคีครั้ง\nนี้ลูกลามออกไป ฮ่องเต้ที่ทอดทัศนาทิวทัศน์อยู่ชั้นบนสุด คงต้อง\nสวรรคตแล้ว\nเป็นที่แน่ใจว่ามีคนวางเพลิง เพียงไม่ทราบว่าฝ่ายตรงข้ามปกปิด\nศักดิฐานะ มาถึงหน้าวิหารทีรักษาการณ์อย่างเข้มงวดได้อย่างไร เพียงแต่\nฝีมือวางเพลิงเลวเกินไป กลับถูกตนเองพบเห็น\nเรื่องราวคงไม่รวบรัดเพียงนี้ ฟ่านเสียนรักษาความสงบเยือกเย็น\nแยกแยะเหตุการณ์ที่เกิดขึ่น แต่ไม่พบเส้นสนกลในใด จากนั้นนึกถึงหลิน\nว่านเอ๋อยังอยู่ชันบน ต้องว้าวุ่นใจขึ้นมา ยากทีจะสงบลงได้ ในใจเกิดลาง\nสังหรณ์อันอัปมงคลขึ้น แต่ว่าตอนนี้ไม่กล้าขืนวิหารไปโดยผลีผลาม กลัว\nถูกผู้คนหลอ กใช้เป็นปาระโยชน์\nพระกํากับดูแลทักษันแตนถึงเบืองหน้ามัน กล่าวเสียงหนักๆ ว่า\n«ฟ่านเสียน ขึ้นไปถวายการอาว์ทกฆา”','2026-04-17 09:49:10'),(86,10,83,'ฟ่านเสียนรับคําคราหนึ่ง ไม่ทันแยกแยะแววตาที่สุดจะหยังของบิดา\nจุบนเว เซองครักษ์ฝีมือดีสองคนรุดไปยังวิหารฮุ่ยคง\nแต่ว่ามันไม่ขึ้นบันได หากสะกิดเท้ากับพิ่น ร่างกลับกลายเป็นเงา\nต่เผาผหนึ่ง เหยียบยําชายคาวิหารอันคับแคบจํากัด ปืนป่ายขึ้นไปยังชัน\nยบนสุตของวิหาร','2026-04-17 09:49:10'),(87,10,84,'','2026-04-17 09:49:10'),(88,10,85,'เทพหมาหต เพาทระบพี่ (2\nก ก็ ฬาณะ \"\nฟ่านเสียนสอดนิวไปยังรอยร่องของชายคาวิหาร พาตัวขึ้นไป ปลาย\nเท้าสะกิดด้านนอกของราวไม้ซึ่งยืนออกมาหลายนิว ใช้ท่าร่างอันแยบคาย\nสถานการณ์บนลานทีว่างเบื่องล่างกลับคืนสู่ความสงบ อัคคีถูก\nเหล่าคนบุญหนักศักดิใหญ่ของรัฐชิงล้วนผ่านศึกมาอย่างโชกโชน\nหนงความวุ่นวายเล็กน้อย ก็กลับคืนสู่ความสงบ พากันเงยหน้าขึ้น พอดี\nเห็นข่างของฟ่านเสียนเคลื่อนไหวดุจประกายสายฟ้าขึ้นถึงชันบนสุด คิดไม่\nก็1ว่าฟ่านถีซือมีฝีมือร้ายกาจถึงเพียงนี้ ต้องร้องชมเซยออกมา\nฟ่านเสียนใช้มือขวาข้างเดียวเหนี้ยวมุมชายคาของวิหารชันบนสุด\nง งล ซ ห\nเซ้ายงอเล็กน้อย วางมือซ้ายบนด้ามมีดสันสีดําทีซ่อนอยู่ในซอกรองเท้า\nเงแกว่งไกวอยู่ในลมภูเขา ชันบนสุดของวิหารกลับเงียบสงบ ฟ่านเสียน\nไม่แล้าบุกเข้าไปโดยผลีผลาม หากร้องบอกว่า “เฉิน ฟ่านเสียน”\nชันบนสุดของวิหารคล้ายมีคนกล่าววาจาใด ฟ่านเสียนหยีตามอง\nแผทตหน้าต่างระบายลมเข้าไป เห็นประกายเย็นเยียบหลายสายสลายวับ\nจากนั้นบังเกิดสุ้มเสียงหนึ่งดังว่า “เข้ามา\nเสยงแอดคราหนง หน้าต่างไม้ถูกผลักเปิดออก','2026-04-17 09:49:10'),(89,10,86,'ฟ่านเสียนไม่กล้าชักช้า บังคับกล้ามเนื้อบริเวณชายโครงท้องน้อย\nร่างดีดตัวขึ้น ทะลวงผ่านหน้าต่างเข้าไปยังชันบนสุดของวิหาร สองเท้าพก\nแตะสัมผัสพืน หางตาเหลือบเห็นเหล่าราชองครักษ์ที่ตระเตรียมพร้อม\nถอยกายไปหนึ่งก้าว ทราบว่าก่อนหน้านี้หากตนเองบุกรุกเข้าไปโดยไม่\nรายงาน ที่ต้อนรับตนเองคงเป็นดาบเย็นเยียบนับไม่ถ้วน\nสายตายามกวาดมอง ไม่เกิดเหตุการณ์ประทูษร้ายดังที่ตนเอง\nคาดคิดไว้ ฟ่านเสียนค่อยคลายใจลง จากนั้นเห็นเงาร่างของฮองไทเฮาลด\nเลี้ยวไปทางมุมระเบียง หลินว่านเอ้อที่ตนเองห่วงใยที่สุดประคองพระนาง\nไว้ ส่วนหงกงกงที่ลึกลําสุดจะหยังงอร่างลง อารักขาอยู่รังท้าย\nทีเบืองล่างเกิดเพลิงไหม้ ฮองไทเฮากับสตรีในวังล่าถอยไปก่อน\n“เจ้าไฉนมาแล้ว?”\nพระสุรเสียงที่ทรงอํานาจแต่สงบเยือกเย็นเสียงหนึ่งดังขึ้น ฟ่าน\nเสียนงงงันวูบค่อยหันกายไป ถวายบังคมต่อบุรุษกลางคนทีวางพระหัตถ์\nซ้ายบนราวลูกกรง กราบทูลว่า “ข้างล่างเกิดเพลิงไหม้ สมควรเป็นการ\nกระทําของคน เฉินเป็นห่วงความปลอดภัยของฝ่าบาท”\nวันนี้ฮ่องเต้รัฐชิงฉลองพระองค์สีเหลืองทีสวมใส่สบาย ทอด\nพระเนตรไปนอกราวไม้ ที่นี้อยู่ทีสูง สามารถเห็นทิวทัศน์รอบข้าง\nเบญจมาศสีเหลืองทองกลับแผ่ซ่านกลินอายฆ่าพฟันชนิดหนึ่ง ฮ่องเต้คล้าย\nไม่ทรงเป็นห่วงความปลอดภัยของพระองค์ ทอดพระเนตรแผ่นดินทีอยู่ใน\nความปกครองอย่างสงบ มุมพระโอษรฐ์เชิดขีน คล้ายทรงเย้ยหยันขุนนางที่\nแตกตินลนลานทางเบืองล่าง\nยามนั้นฮองไทเฮากับเหนี้ยงเหนี้ยงทั้งหลายจากไปแล้ว ราช\nองครักษ์บนชันสามกับที่ขึ้นมาจากชันล่างสมทบรวมกัน ล่าถอยลงไปอย่าง\nระมัดระวัง ชันบนสุดของวิหารซีงอากาศถ่ายเทสะดวก นอกจากประทับ\nดวยฮองเตททรงเยอกเยนผดธรรมดาแลว ยังมีไทจือ องค์ชายใหญ่กับ','2026-04-17 09:49:10'),(90,10,87,'ผาค์ขายสาม ราชองครักษ์พกพาดาบสิบกว่านาย และขันทีน้อยตามเสด็จ\nฝีแผห้าคน\nฟ่านเสียนกวาดมองแวบหนึ่ง ก็เห็นกำลังอารักขาที่ชั้นบนอย่าง\nขัตเงน หว่างคิ้วต้องทอแวววิตกกังวลขึ้น อัคคีที่ชั้นล่างแสดงว่ามีเลศนัย\nเพียงแต่ตนเองประสบพบเหตุ ชิงดับไฟก่อน ไม่เปิดโอกาสให้ผู้คนฉวย\nไหหเสท่อความวุ่นวาย แต่ว่าคนร้ายทีซ่อนเร้นยังอยู่ในวิหาร เพียงไม่ทราบ\nเต้งพขุมกำลังอันกล้าแข็งของรัฐชซิง ไฉนยังมีคนเร้นกายเข้ามา มันรั\nต่แพน่งถีซือสำนักตรวจสอบ มีความเชือมันต่อกำลังป้องกันของรัฐชิง\nห ว่ามีคนร้ายซ่อนตัวอยู่ ต้องเป็นสุดยอดฝีมือทีใช้กระบีเดียวสร้าง\nคาหแว่นวายทัวแผ่นดิน คาดว่ามีไม่เกินสามคน\nแต่ว่ากงเตียนไม่อยู่ชันบนสุด ความจริงข้อนี่ทําให้ฟ่านเสียนใจเขมึง\nต่าเคยดขึ้น หงกงกงอารักขาฮองไทเฮาลงจากชันบนแล้ว หรือว่าคนร้าย\nเเงเพล่ง เพียงเพื่อหลอกล่อยอดฝีมืออันดับหนึ่งของวังหลวงเช่นกงเตียน\nแงจากซันบน?\nยามนี้ทีซันบนนอกจากเหล่าราชองครักษ์พกพาดาบแล้ว ยอดฝีมือ\nทแท้งริงคงมีแต่ตนเอง นี้เป็นการประเมินสถานการณ์ทีถือดีของมัน ใน\nพาดาของมัน องค์ชายใหญ่แม้เจนศึก แต่หากเผชิญเหตุการณ์ลอบสังหาร\nฝ่มีกขององค์ชายใหญ่ยังอยู่ห่างจากนักฆ่าที่โดดเด่นผู้หนึ่ง\nดูจากพระพักตร์ฮ่องเต้ คล้ายไม่ใส่พระทัยกับเรื่องนี้ อาจบางทีนี้เป็น\nความสุขุมหนักแน่นทีเจ้าชีวิตพึงมี แต่ฟ่านเสียนไม่ต้องการให้บูรูษกลาง\n\"น็ได้รับความระคายเคือง เป็นเหตุให้คนไร้ความผิดจํานวนมากต้อง\nสงเวยชีวิต จึงขมวดคิวเล็กน้อย ปรายตาบอกใบ้ต่อไทจือซึ่งอยู่ด้านหลัง\nต่กงเต้แวบหนึ่ง\nไทจืองงงันวูบ จากนั้นทราบว่าฟ่านเสียนคิดอะไร จึงน้อมคํานับ\nท่กงเต้ กล่าวว่า “ท่านพ่อ สาเหตุเพลิงไหม้ไม่กระจ่าง ขอให้ล่าถอยไป','2026-04-17 09:49:10'),(91,10,88,'มิคาดฮ่องเต้ไม่สนพระทัยคําทูลเชิญของไทจือวังตะวันออก หาเน\nพระวรกายมาตรัสถามฟ่านเสียนว่า “ไฟดับแล้วหรือไม่?”\nฟ่านเสียนงงงันวูบจึงผงกศีรษะกล่าวว่า “ดับลงแล้ว”\nฮ่องเต้รับสั่งว่า “อย่างนั้นไยต้องไป ในชีวิตของข้า น้อยครั้ง\nล่าถอยมาก่อน”\nฟ่านเสียนมีสีหน้าสงบนิ่ง แต่ในใจลอบรําร้องด่าทอ ครุ่นคิดว่าท่ก\nชมชอบความเร้าใจ เราหามีอารมณ์เช่นนี้ไม่ จึงกล่าว “ถึงแม้ไม่มีควาง\nผิดปรกติใด แต่ที่นี้อยู่ที่สูง ยากระวังป้องกันได้ ขอฝ่าบาทนึกถึงแผ่นตัน\nเสด็จกลับวังไป”\nการยกอ้างแผ่นดินทัดทานฮ่องเต้ เป็นวิธีการทีละครอิงประวัติศาส๓\nที่เคยชมเมื่อชาติปางก่อนใช้ได้ผลที่สุด แต่แสดงว่าไม่อาจใช้ต่อฮ่องเต้ง:\nซิง พระองค์ตรัสเสียงเย็นชาว่า “ฟ่านเสียน เจ้ารังตําแหน่งถีซือสำนักตรวง\nสอบ หากมีคนกล้าปลงพระชนม์ข้า ถือเป็นความบกพร่องต่อหน้าทีของ\nข้า หรือเจ้าต้องการให้ข้าลงโทษเจ้าบกพร่องต่อหน้าที จนไม่สามารถชง!\nเบญจมาศต่อไป”\nฟ่านเสียนลอบขุ่นข้องใจ ครุ่นคิดว่าตนเองเพียงรังตําแหน่งถีซือ\nสำนักตรวจสอบ ถึงแม้ว่าตึกทีหกของสำนักตรวจสอบรับภารกิจส่วนนี้ แต่\nเทศกาลชมเบญจมาศในวันนี่ ไม่มีส่วนของสำนักตรวจสอบ ตนเองไหน\nเลยหยังรู้ศัตรูล่วงหน้าได้?\nจากนั้นครุ่นคิด สำนักตรวจสอบกระจายเครือข่ายสอดแนมไปทัว\nแผ่นดิน ระหว่างนี้ไม่ทราบระแคะระคายอันใด ขุมกำลังทีกล้าแตะต้องราช\n- เซ ะ ซ่\nสำนักชิง มีเพียงสองสามตระกูล ระหว่างนี้สองสามตระกูลนั้นสงบนิงเฉย\nนครตงอิทียากหยังคาดทีสุดก็สงบนิง กระบีสีทัศนาทีถูกสำนักตรวจสอบ\nจับตาดูยังอยู่ในนครตงอี','2026-04-17 09:49:10'),(92,10,89,'ฟ่ แล่ยนมองดูพระพักตร์ที่สงบนิงของฮ่องเต้ อดครุ่นคิดมิได้ หรือ\nสู่เติตคีคางน มิใช่การโหมโรงก่อนเหตุการณ์ปลงพระชนม์ เป็นตนเอง\nสี่แต้1เต๋าเกยดไป?\nเห็นเฟ่านเสียนนิงเงียบงัน องค์ชายทั้งสามทีมีคุณสมบัติกล่าววาจา\nไจว่ามันถูกฮ่องเต้รับสังตําหนิ รู้สึกเสือมเสียหน้าอยู่บ้าง ไทจือจึง\nสู่งเสียหะแอม คิดแก้ต่างให้กับฟ่านเสียน แต่แล้วฉุกคิดว่าระหว่างนี่\nฟ่าหแส่พยแจ้ดการกับองค์ชายรองสถานหนัก สร้างความ “ปลาบปลืม\nปกไแวไจ” แก่ตนเอง แต่ขุมกำลังของขุนนางผู้นี่คล้ายบรรลุถึงขอบเขต\nสู่แฟ่ไม่๓ เงควบคุมบังคับ ยามนี้พระบิดาสะกดอีกฝ่ายไว้ ไม่แน่ว่ามีพระ\nยปจาค์อันลึกลํา จึงปิดปากลง เพียงกวาดมองฟ่านเสียนเป็นเชิงปลอบโยน\nแ เบหแง\nๆงคัชายใหญ่กลับไม่ใคร่ครวญถึงเพียงนี่ จึงกล่าว “ท่านพ่อ ฟ่าน\nศีไหล่าวมีเหตุผล ถึงแม้ว่าทัวทั้งแผ่นดินไม่มีโจรร้ายกล้าประทูษร้าย\nป แพ่ก แต่เพื่อความปลอดภัย และเพื่อปลอบใจเหล่าใต้เท้าทีเบื่องล่าง\nพาะคงค์ยังคงลงจากชันบนเถอะ”\nต่องเต้คล้ายทรงชีนชมต่อท่าทีขององค์ชายใหญ่นี่ แต่ไม่ได้ไว้หน้า\nฝ่าแล่ยน หากตรัสเสียงเย็นชาว่า “ฟ่านเสียน เจ้ารังตําแหน่งถีซือสำนัก\nตาวงสอบ พอประสบเหตุกลับลนลานถึงเพียงนี้ เป็นที่ผิดหวังของข้านัก\nฟ่านเสียนลอบด่าทอในใจอีกครา เปลือกนอกกลับเคารพนบนอบ\nเล่างว่า “ฝ่าบาทสังสอนถูกต้อง”\nฮ่องเต้คล้ายมีพระทัยทดสอบมัน พลันตรัสว่า “ในใจเจ้าใช่ไม่ยอมรับ\nฟ่านเสียนพลันฉุกใจคิด กล่าวเสียงหนักๆ ว่า “ถูกแล้ว เฉินเห็นว่า\nฝี เททผูกพันถึงแผ่นดิน ควรถนอมตัวจึงถูกต้อง ต่อให้ระมัดระวังกว่านี้ก็\nไม่เกินเลย ทิวทัศน์เบญจมาศมีอยู่ทุกปี แต่ฮ่องเต้รัฐชิงมีเพียงพระองค์','2026-04-17 09:49:10'),(93,10,90,'เดียว ต่อให้ถูกผู้คนหัวร่อเยาะว่าเฉินแตกตื่นลนลานขวัญอ่อนราวมุูสเ\nเฉินก็จะทูลเชิญฝ่าบาทลงจากชันบนกลับเข้าวัง”\nชันบนของวิหารตกอยู่ในความนิงเงียบงัน ไม่ว่าผู้ใดก็นึกไม่ถึงว1!\nฟ่านเสียนกล้าโต้แย้งฮ่องเต้ กล้าเอ่ยถึงความปลอดภัยของเจ้าชีวิต\nล้างกับพระราชกระแสทีพระองค์รับสังไว้\nไม่ทราบเพราะเหตุใด ฮ่องเต้พอสดับวาจาเหล่านี่ พระพักตร์กลัง\nผ่อนคลาย ตรัสว่า “เจ้าขวัญกล้าบังอาจจริงๆ หากบอกว่าเจ้าขวัญอ่อนรา.\nข้าไม่ทราบว่าในโลกจะหามุสิกขนาดใหญ่เช่นนี้จากทีใด\nนี้ย่อมเป็นคําหยอกล้อ แต่นอกจากฮ่องเต้แล้ว ทุกคนทีชันบนล้วน\nตกอยู่ในห้วงความตึงเครียด ไม่มีผู้ใดกล้าหัวร่อออกมา มีแต่ฟ่านเสียนที่\nยิมเล็กน้อย แต่รอยยิมขมขืนอยู่บ้าง\nยามนั้นพระสุรเสียงของฮ่องเต้แผ่วทหุ้มลง แม้แต่พระเนตรยังหลับ\nตรัสว่า “ในชีวิตข้าไม่ทราบเผชิญกับการลอบสังหารกิครั้ง พวกเจ้า\nเหล่าผู้เยาว์ไหนเลยล่วงรู้สถานการณ์อันบันป่วนวุ่นวายในตอนนั้นได้?\nพระองค์ทรงพระสรวลเบาๆ ตรัสว่า “แผนการที่เต็มไปด้วยช่องโหว่ การ\nวางเพลิงทีกระทําไม่สำเร็จเช่นนี้ คิดบีบบังคับให้ข้าจากไป ไหนเลยง่ายดาย\nฟ่านเสียนเงียหูสดับฟัง จิตใจกลับแบ่งแยกสมาธิไปยังสิงแวดล้อม\nรอบข้าง กงเตียนกับหงกงกงล้วนไม่อยู่ พยัคฆ์พิทักษ์ไม่อยู่ มีแต่ราช\nองครักษ์และองค์ชายสามท่าน หรืออาจบอกว่าสีท่าน ขันทีทีใกล้ชิดกับ\nฮ่องเต้แม้จงรักภักดี แต่คิดอาศัยคนเหล่านี้อารักขาฮ่องเต้ยังไม่พอ โดย\nเฉพาะหงกงกงตามเสด็จฮองไทเฮาไป สร้างความหวันวิตกแก่ฟ่านเสียน\nทันใดนั้นมันใจสันสะท้าน นึกถึงเรื่องละเอียดอ่อนประการหนึ่ง\nพ เทว่าตอนนี้ฮ่องเต้ถูกประทูษร้าย เจาหนาทอถซอสานกตรวจสอบเช','2026-04-17 09:49:10'),(94,10,91,'ตเแกงไยมิใช่ต้องรับผิดชอบ ตอนอยู่ทีชันล่าง เหตุใดบิดาไม่ได้นึกถึง\nได้กงกงร้องดังๆ ว่า “ในชีวิตฝ่าบาทเผชิญเหตุการณ์ลอบสังหาร\nสี่ศําเสามครั้ง ไม่เคยล่าถอยแม้สักก้าวเดียว”\nฟ่านเสียนงงงันวูบ จากนั้นนึกถึงหวังฉีเหนี้ยนซึ่งอยู่ที่แคว้นเปยฉี\nที่แท้เบื่องหลังของบูคคลที่ประสบความสำเร็จ ต้องมี\nตําประกอบอยู่หลายคน\nฮ่องเต้ลืมพระเนตรขืนอย่างช้าๆ สายพระเนตรที่สงบนิงทอแววเชือ\nมแกก่างแรงกล้า รับสังว่า “ไม่ว่าเปยฉี หนั้นเวีย ยังมีตัวหนอน\nที่นาสมเพชที่ล่มสลายในเงื่อมมือข้า ผู้ใดไม่คิดสังหารข้าในกระบีเดียว แต่\nแนไปยีสิบปี ยังมีผู้ใดกระทําได้?” พระองค์ทรงพระสรวลเบาๆ ตรัสว่า\n\"แารเผชิญเหตุการณ์ลอบสังหารกลายเป็นความเคยชินอย่างหนึ่ง ฟ่าน\nเล่พ เจ้าคงเข้าใจว่าเหตุใดข้าไม่จดจําใส่ใจ”\nท่านเป็นเมล็ดพันธุ์แรงงานชนิดหนึ่ง วันนี้ฟ่านเสียนด่าทอในใจ\nมทกว่าวันใด แต่คนอยู่ในตําแหน่งต้องมีกุศโลบาย ตนเองเมื่อรังตําแหน่ง\nททสำนักตรวจสอบ ก็ต้องรับผิดชอบความปลอดภัยของฮ่องเต้ ประเด็น\nพ เค้ญคือมันไม่ต้องการแบกหม้อก้นดําใบใหญ่ทีสุดของแผ่นดินไว้ ดังนั้น\nคงคงหน้าด้านทูลเชิญฮ่องเด้ลงจากชันบนเสด็จกลับวัง\nในที่สุดฮ่องเต้กริวขึ้นมา รับสังด้วยพระสุรเสียงอันดังว่า “ฟ่านเจียน\nไหนฝักอบรมสวะเช่นนี้ เฉินผิงผิงไฉนหมายตาเจ้า?\nฟ่านเสียนบันรอยยิมทัวใบหน้า ในใจด่าทอสืบต่อ หากมีความ\nสามารถท่านก็อบรมสังสอนเอง นี้ความจริงเป็นภาระหน้าที่ของท่าน\nยามนั้นสถานการณ์กลับคืนสู่ความสงบ คาดว่าคนร้ายต่อให้ร้ายกาจ\nเก่านี้ ได้แต่ฉวยโอกาสหลบหนี้ ไม่เช่นนั้นหากจับเจ่าอยู่ต่อ ถูกร่างแหของ\nทหารรักษาพระองค์หาพบ คงไม่มีจุดจบทีดี ดังนั้นคนในบริเวณค่อย','2026-04-17 09:49:10'),(95,10,92,'ผ่อนคลาย มองดูฮ่องเต้ซึ่งทรงเก็บซ่อนความรู้สึกไว้ตลอดมากลับตูง่า\nฟ่านเสียน รู้สึกน่าหัวร่ออยู่บ้าง ไทจือยังคงใช้สายตาที่อ่อนโยนมองดูฟ่า\nเสียน ส่วนองค์ชายใหญ่ไม่อาจหักใจทนดูต้องเบือนหน้าไป กลับเป็นองค\nชายสามที่อายุเยาว์ที่สุดยิมอย่างเบิกบาน ชมดูเหตุการณ์ด้วยความสงสัย\nไม่ทราบว่าวันนี้ไฉนฮ่องเต้โกรธกริวถึงเพียงนี้ กลับดุว่าฟ่านเสียน\nไม่มีชินดี ราวกับดุด่าลูกหลานตนเองก็มิปาน ถึงอย่างไรฟ่านเสียนเป็น\nขุนนางใหญ่ผู้หนึ่ง ในรัฐชิงซึ่งปกครองเชิงบุ้น ออกจะไม่ไว้หน้าขุนนางไม\nฟ่านเสียนเปลือกนอกฝืนยิม แต่ฟังความหมายออก เกรงว่าฮ่องเต้\nทรงระแวงสงสัยเรื่องเดียวกับตนเอง จึงโกรธกริวเป็นพิเศษ หากบอกว่า\nละครบทนี้เป็นเฒ่าขาเป๋หรือบิดากําหนดขึ้น ตนเองได้แต่ชมว่าพวกมันช่าง\nขวัญกล้าบังอาจ กลับกล้าเล่นละครฉากนี้ต่อฮ่องเต้ แต่ว่าด้วยจือซัง ของ\nฮ่องเต้ ไหนเลยทอดพระเนตรไม่ออก แต่ว่าดูเหมือนฮ่องเต้เข้าพระทัยว่า\nฟ่านเสียนไม่ล่วงรู้ความจริง\nฟ่านเสียนลอบทอดถอนใจ ครุ่นคิดว่าคงไม่ปรากฏคนร้ายอันใดแล้ว\nนี้เพียงเป็นละครเรื่องหนึ่ง\nแต่ปัญหาอยู่ทีเฉินผิงผิงมิใช่นักเรียนอนุบาล พระกํากับดูแลทักษิณ\nก็มิใช่เด็กหญิงทีเข้าเรียนวันแรกเกาะประตูร้องไห้ ฮ่องเต้ยิงไม่เชือว่าคน\nใกล้ชิดที่สุดทั้งสองจะกระทําเรื่องเหลวไหลเช่นนี้ สาเหตุที่ฮ่องเต้โกรธกริว\nแท้จริงแล้วไม่เกี่ยวข้องกับฟ่านเสียนเท่าใด\n” ไอคิว','2026-04-17 09:49:10'),(96,10,93,'ตแผ หนัง จึงบุ้ยปากต่อได้กงกงทีด้านข้าง บอกใบ้ว่าเจ้าชีวิตคอแห้งแล้ว\nได้กงกงเพิงย้ายเข้าท้องพระโรงไม่นาน จึงเฝ้าสังเกตตลอดเวลา\nพอได้จําเการกระตุ้นเตือนจากฟ่านถีซือ ก็รีบไปจัดเตรียมน้ำชา\n“เปลี่ยนเป็นสูรา”\nท่องเต้ไม่หันพระวรกายมา แต่ทรงทราบว่าฟ่านเสียนทําอะไร ยัง\nตงทกตพระเนตรทิวทัศน์นอกราวลูกกรง สายพระเนตรทอแววเย้ยหยัน\nวับสังว่า “สีสันชิวเทียนกวีพันบท รินสุราราดรดพื้นหนึ่งจอก\nเมเหหมเบญจมาศแต่ไกล ไม่ดีมสุราไหนเลยสอดรับกับบรรยากาศได้?\nเทศกาลชมเบญจมาศทุกสามปีครังล้วนจัดเตรียมสุราเบญจมาศอยู่\nตี่ต กแเข้าง แต่วิหารฮุ่ยคงเกิดเพลิงไหม้โดยไวร้สาเหตุ สร้างความไม่สบายใจ\nแก่ผุคน จึงลืมยกออกมา ยามนี้พอฟังฮ่องเต้รับสัง ขันทีน้อยที่ดูแลรับผิด\nทกาเก็ยกโต๊ะสุรามาถึงข้างราวลูกกรง\nฟ่านเสียนพอได้ยินกวีบทนี้ กลับใจสันสะท้าน นี้เป็นบทกวีเบญจมาศ\nเจียเป่าลี้ เอื้อนเอ่ยในบันทึ ย - ซั,\nทเจียเป่าอี เอื่อนเอ่ยในบันทึกของก้อนหินบทที่สามสิบแปด ยามนี่ฮ่องเต้\nทางเก่กนออกมา ย่อมสือความหมายว่าพระองค์ทรงทราบเรื่องทั้งหมด\nแฟ่ฟ่าแเสียนก็เตรียมใจแต่แรกว่าเรื่องนี้ไม่อาจตบตาชนชาวโลกตลอดไป\nฮ่องเต้รับสังอีกว่า “หนังสือบันทึกของก้อนหินเอ่ยถึงแต่เรื่องรักๆ\nไพวง่ๆ แต่ความเรียงยังพอใช้ได้ เพียงแต่กวีบทนี้ไม่นับเป็นอย่างไร?”\nองค์ชายทั้งสามกับผู้ติดตามที่ชันบนไม่เข้าใจว่า ยามนี้ฮ่องเต้ไฉน\nแสงถึงแวดวงวรรณกรรม ล้วนงงงันวูบ ฟ่านเสียนทราบว่าไม่อาจปิดบัง\nคแต่กไป จึงน้อมกายกล่าวว่า “เฉินแต่งด้วยอารมณ์สนุก นึกไม่ถึงว่าจะ\nฝ \"แข้าสู่คลองจักษุฝ่าบาท นับเป็นเกียรติอย่างสูง”\nฮ่องเต้รับสังดังอืมม์ ตรัสว่า “ข้าความจริงเข้าใจว่า เจ้ากลัวผู้คน\n“ 1งจง าหนังสือเล่มนี้เป็นเจ้าปลอมชือแต่งขึ้น จึงไม่พิถีพิ นดานบทกว\nดแขลงเรื่องความฝันในหอแดง','2026-04-17 09:49:10'),(97,10,94,'เป็นเหตุให้อ่อนด้อยกว่าเดิม\nฟ่านเสียนทอดถอนใจคําหนึ่ง ไม่ทราบตอบอย่างไรดี ยามนี้คเป\nบริเวณทราบว่าหนังสือบันทึกของก้อนหินที่แพร่หลายไปทัวทุกแห่งหแ\nซ่ สช่ ๓\nทีแท้เป็นผลงานของใต้เท้าเสียวฟ่าน หลังความตื่นตระหนก ค่อยเห็น !\nชอบด้วยเหตุผล หนังสือเล่มนี้เป็นร้านหนังสือมิแสวงหาจัดพิมพ์ออเน.\nมีความเรียงสละสลวย หากมิใชใต้เท้าเสียวฟ่านแต่งขึ้น ไม่ทราบว่าในไน\nมีผู้ใดมีความสามารถถึงเพียงนี้\nฮ่องเต้ทรงรับจอกนำจัณฑ์มา ทรงสูดกลินหอมจางๆ ที่ระเหยอก\nมา จิบเล็กน้อยคําหนึ่ง ไม่สนพระทัยฟ่านเสียนทีกระอักกระอ่วน และเหม\nราชโอรสที่แตกตื่นตระหนกอีก\nบนถาดจัดวางนำจัณฑ์สองจอก ความจริงจัดเตรียมไว้สำหรับฮ่องเฉ\nกัาแฮองไทเสา ยามนี่ฮ่องเต้ทรงหยิบจอกหนึ่งดื่มลงไป คงเหลืออยู่จอกหนึ่ง\nยามนี้ฮองไทเฮาเสด็จลงไปแล้ว ไม่ทราบสมควรจัดสรรอย่างไร\nพระองค์ทอดพระเนตรไทจือ แล้วทอดพระเนตรองค์ชายใหญ่\nตพระขนงแล้วคลายออก ความจริงชีพระดรรชนี้ไปทีฟ่านเสียน แต่\nแล้วพบว่าไม่เหมาะสม จึงหันเหพระดรรชนี้ชีไปที่องค์ชายสามซึ่งหลบซ่อน\nอยู่ตางมูมห้อง\nองค์ชายสามหน้านิวคิวขมวดกล่าวว่า “ฟู้หวง (พระบิดา) ผู้บุตรไม่\nซงเซอาเดต็มสุรา” คําพูดเช่นนี้มีแต่เด็กน้อยเช่นมันจึงสามารถกล่าวออกมา\nโดยไม่ถือว่าขัดราชโองการ\nท่องเต้พระพักตร์เคร่งเครียดลง ตรัสเสียงเย็นชาว่า “เรื่องที่รูนแรง\nกว่าสหา เจ้ายังกล้ากระทํา ยังกลัวสุราจอกหนึ่ง?”\nคองค์ชายสามถูกกดดันจนแทบร้องไห้ออกมา รีบกล่าวขอบพระทัย\nเต๋เน่กงข้างราวลูกกรง ยินมอน้อยๆ หยิบฉวยจอกสุรา คิดส่งเข้าปากไป','2026-04-17 09:49:10'),(98,10,95,'เพ่กงเพล้งดังสดใส จอกสุราในมีอองค์ชายสามร่วงหล่นลงสู่พืน\nเน มันเหม่อมองดูประกายเย็นเยียบที่แทงปราดมา ไม่ว่าอย่างไรก็\nผูแติดไม่เข้าใจว่า ตนเองเพียงเข้ามาดีมสุรา ราชองครักษ์ผู้นี้ไฉนคิดฆ่า\n1ะอผ่างไรมันเป็นองค์ชาย ซึ่งเติบโตขึิ้นมาจากสภาพแวดล้อมที่\nสูกเกเกนเดราย ในที่สุดค่อยได้คิดว่ามีคนลอบสังหารตนเอง\nทีตํานหลังมันเป็นฮ่องเต้ หากว่ามันกุมศีรษะวิงหลบหนี้ ประกาย\nตต่าหิงะสายนิจะฟันใส่ฮ่องเต้ แน่นอน องค์ชายสามไม่มีท่าร่างที่เหยียบ\nคจ:ไก4คงรอยเช่นราชครูขู่เหอ และไม่มีวิชาหัตถ์กําจายเช่นเยียหลิวหวิน\nตคไห่งเย็นหยัดขวางอยู่หน้าพระพักตร์ คาดว่าดาบสะท้านดินฟ้านี้ ยังจะ\nฝ วก่าห้นออกเป็นสองเสียง ทั้งตัดพระเศียรของฮ่องเต้ลงมา\nไม่ว่าหลบหลีกหรือไม่ล้วนเป็นเช่นเดียวกัน ดังนั้นองค์ชายสามเลือก\nากีท่เบเต้อง ยืนหยัดกับทีเดิม จับจ้องมองใบหน้าอันพร่ามัวของคนร้ายซึ่ง\nหฝู่หลังแประกายดาบ สองเท้าสันระริก เป้ากางเกงเปียกชุ่มโชก พลางร้อง\nเสียงแหลมเล็กออกมา\nเสียงร้องอันแหลมเล็กดังสะท้อนสะท้าน คนในบริเวณล้วนพบเห็น\nเหตุการณ์ลอบสังหาร ไม่ว่าผู้ใดก็นึกไม่ถึงว่าในราชองครักษ์พกพาดาบของ\n\"19หลวงมีคนร้ายปะปนอยู่ ดังนั้นขณะทีดาบเล่มนั้นฟาดพฟันไส่ฮ่องเต้ซึ่ง\nทรงถือจอกนำจัณฑ์อยู่ จึงไม่มีผู้ใดปรับตัวได้ ปล่อยให้ดาบเล่มนั้นฝ่าแนว\nไ ไหงกันของราชองครักษ์พกพาดาบเข้ามา\nมีแต่ฟ่านเสียนทีมีข้อยกเว้น มันระบายลมจากปาก บิดหมุนข้อมือ\nต่กยหมัดออกไป คนร้ายผู้นี้ซ่อนตัวอย่างมิดชิด ลงมืออย่างกะทันหัน\n1จะกายดาบเจิดจ้าถึงที่สุด ทําให้ฟ่านเสียนไม่กล้าออมกำลัง พลังลมปราณ\nแล่นจากด่านเซวียซานทีชายโครงด้านหลังมายังแขนขวาส่งมาถึงตัวหมัด','2026-04-17 09:49:10'),(99,10,96,'ข้ามระยะห่างหลายก้าวต่อยใส่ประกายดาบนั้น\nหมัดนี้ไม่รวบรัดธรรมดา กระแสลมหมัดแหวกฝ่าอากาศ\nเสียงดังอึงอล คล้ายอสนี้บาตฟาดฟ้า ตกลงในประกายดาบ ทําลายประกก\nดาบดังหิมะเป็นผุยผง\nเรื่องราวย่อมไม่รวบรัดเพียงนี้\nฟ่านเสียนรู้สึกทรวงอกอืดอัดขัดข้อง พบเห็นด้วยความตระหนกกง่\nคนใช้ดาบกลับเป็นผู้เข้มแข็งชันทีเก้า แต่เช่นนี่จึงถูกต้อง คนร้ายทึกล้าม\nปลงพระชนม์เจ้าชีวิตทีทรงอํานาจที่สุดในแผ่นดิน หากไม่มีฝีมือชันที่เก้\nไหนเลยกล้าจู่โจมลงมือ\nเมื่อกระแสลมหมัดดังขึ้น ฟ่านเสียนก็โถมถึงข้างกายองค์ชายสาง!\nพลิกมือซ้ายวูบ ชักมีดสันสีดําออกจากซอกรองเท้า ปักใส่ท้องน้อยของ\nคนร้าย\nดาบในมือคนร้ายหักเหลือครึ่งหนึ่ง แต่สภาวะดาบยิงเกรียวกราด\nระดับความเร็วยิงรุนแรง คล้ายคิดเสียงชีวิตก็มิปาน ยามนั้นเหล่าราช\nองครักษ์ค่อยรู้สึกตัว ส่งเสียงร้องพลางหนุนเนื่องมายังหน้าหลังของฟ่าน\nเสียน\nแต่แล้วยามนั้น ก้อนเมฆที่อยู่เหนือฟ้าของวิหารฮุ่ยคงลอยเลื่อน\nเคลื่อนที่ เผยเห็นดวงอาทิตย์ที่แผดแสงแรงกล้า\nประกายเจิดจ้าวูบขึ้น ชันบนของวิหารบังเกิดประกายสีขาวเย็นเยือก\nผืนหนึ่ง ต่อจากนั้นปรากฏคนร้ายในชุดขาว มือถือกระบีโบราณผู้หนึ่งขึ้น\nไม่มีผู้ใดทราบว่าคนร้ายผู้นี้ปรากฏตัวได้อย่างไร และไม่มีผู้ใดพบว่ามัน\nอาศัยแสงอาทิตย์เป็นเครื่องกําบัง สะอึกถึงเบืองหน้าฮ่องเต้ได้อย่างไร\nเสียงซีซีดังขึ้น ราซองครักษ์ที่ข้างพระวรกายฮ่องเต้สองคนฉูดดึง\nฮ่องเต้ไปยังด้านหลัง ค่าตอบแทนที่จ่ายออกคือ คนทั้งสองถูกกระบี่แทง\nะลุลําคอ โลหิตฉีดพุ่งออกมา กระทั้งดาบไม่ทันชักออก ก็ล้มฟาดลง','2026-04-17 09:49:10'),(100,10,97,'กับพน\nคนชุดขาวผู้หนึ่งถือกระบีโบราณเล่มหนึ่งแทงปราดใส่พระพักตร์\nฮ่องเต้ซึ่งก่อนหน้านี้ประกาศว่าในชีวิตไม่ล่าถอย พอเผชิญกระบีที\nตผ้ายเห็นบินจากเหนือฟ้าเล่มนี้ กลับถูกราชองครักษ์ที่ไม่กลัวตายฉุดลาก\nแทพไหปหลายก้าว\nยามนี้ปลายกระบีทีคร่าขวัญกระชากวิญญาณยังอยู่ห่างพระองค์หนึ่ง\nแต่ทุกผู้คนเข้าใจว่าปลายกระบีท่อนหนึ่งแทงใส่พระศอของฮ่องเต้\nแลผ่ง\nทุกผู้คนทราบว่าฮ่องเต้รัฐชิงไม่รู้จักวิทยายุทธ์ จึงปรากฏราช\nกงครักษ์หลายคนขู่คํารามพลางขวางอยู่หน้าพระพักตร์ เหตุการณ์เกิดขึ้น\nแผ่างกะทันหัน ทั้งหมดเป็นห่วงความปลอดภัยของฮ่องเต้ ตดังนั้นราช\nกาคจักษ์เหล่านี้เลือกวิธีใช้เรือนร่างเลือดเนื้อต้านทานสภาวะกระบีของฝ่าย\nพวงข้าม\nหยาดโลหิตกระเด็นเซ็นซ่าน พระเนตรของอ่องเต้ยังสงบนิง จ้องจับ\nท่คแนร้ายชุดขาว ซึ่งคนกระบีหลอมรวมเป็นหนึ่ง\nเหล่าราชองครักษ์มีกำลังกล้าแข็ง เพียงแต่ต้องมีเวลาปรับตัว ทีชัน\nล่างของวิหารฮุ่ยคงยังมีหงกงกง ยังมีฉินเหิงกับเยียหลิงเอ๋อ ซึ่งเป็นผู้เข้ม\nแข้งชันทีเก้า ยามนี้ขอเพียงสกัดยับยังคนร้ายชุดขาวไว้ชั่วขณะ ก็สามารถ\nวัทษาชีวิตของฮ่องเต้ไว้\nแต่จะให้ผู้ใดสกัดยับยัง เหล่าราชองครักษ์ล้วนทุ่มเทอย่างเต็มที\nพวุกมันทราบว่าในพวกเดียวกันปรากฏคนร้ายขึ่น ตนเองคงยากจะมีชีวิต\nสํ1ไป เพื่อความอยู่รอดของคนในครอบครัว พวกมันตัดใจเสียงชีวิตแล้ว','2026-04-17 09:49:10'),(101,10,98,'เรื่องต้านทานรับกระบีให้กับฮ่องเต้ สมควรเป็นหน้าที่ของเหล่าราชโย\nการจู่โจมลงมืออย่างต่อเนื่อง ล้วนเกิดขึ้นในเวลาอันกระชันสัน\nตอนนั้นจอกสุราทีหลุดจากมือองค์ชายสามยังกลิงไปตามพื้นต\nองค์ชายใหญ่ก็มีสีหน้าตื่นตระหนก เตรียมโถมเข้ามาต้านทานกระบีโบรายเ\nทีแฝงสํานึกการฆ่าฟันอย่างเปียมล้น แต่ก็เพียงสืบเท้าออกมาสองก้าว\nเท้าหลังยังไม่แตะสัมผัสพื้น\nขณะทีฟ่านเสียนจ้วงแทงมีดสันสีดําออก ยังห่างจากห้องน้อยของ\nคนร้ายทีปลอมเป็นราชองครักษ์อีกหลายนิว แต่ก็รู้สึกถึงสภาวะกระบีอัน\nกราดเกรียวทีตด้านหลัง\nหยาดโลหิตกระจายเต็มฟ้า คล้ายเบญจมาศบานทัวภูเขา ซากศพ\nของราซองครักษ์ปลิวเวียนว่อนอยู่กลางอากาศ พวกมันจวบจนตายยัง\nขบคิดไม่เข้าใจว่า คนร้ายชุดขาวนั้นซ่อนตัวอยู่บนวิหารฮุ่ยคงได้อย่างไ.\nก่อนหน้านี้พวกมันตรวจค้นอย่างละเอียดแล้วชัดๆ\nทุกประการคล้ายภาพม่านตงจัว ปรากฏขึ้นทีเบืองหน้าฟ่านเสียน\nอย่างชัดแจ้ง\nฟ่านเสียนยังใช้หางตาเหลือบพบเห็นไทจือเร่งรุดเข้าหาฮ่องเต้\nความจงรักภักดีและองอาจหาญกล้าเป็นทีน่าตื่นตันใจนัก น่าเสียดายที\nไทจือบังเอิญเหยียบถูกจอกสุราที่องค์ชายสามพลังมือทําตกหล่น จนลื่น\nไถลเสียหลัก เห็นแน่ชัดว่าต้องร่วงฟาดกับพื้นในสภาพที่น่าตลกขบขัน\nเหตุการณ์ประจวบเหมาะ คล้ายลิขิตของสวรรค์ ยามนี่มีแต่ฟ่าน\nเสียนที่อยู่ใกล้กับฮ่องเต้ที่สุด และมีปฏิกิริยารวดเร็วทีสุดทําหน้าที่ขุนนาง\nจงวักและบูตรกตัญญู\nขนคอของฟ่านเสียนตั้งชัน สํานึกฆ่าฟันของกระบีทีด้านหลังยัง\nเกาพสใไลว์โมขัน','2026-04-17 09:49:10'),(102,10,99,'าคนร้ายชั้นที่เก้าที่เบื้องหน้า สะกิดความตื้อรั้นดึงดันที่อยู่ส่วนลึก\nขผงงตไจมันขึ้นมา มั่นใจว่าสามารถช่วยเหลือฮ่องเต้กับองค์ชายสามที่\nดู(1เยพร้อมกัน แต่ว่า ตนเองคงถูกมือกระบี่ชุดขาวทางด้านหลังทําร้าย\nยเตเจ็บสาหัส\nภันพอตัดสินใจเสียงชีวิต ฟ่านเสียนก็ไม่ยอมพลาดโอกาสเซชนนี้ นี้\nเป็นศตะเก้นเข้มแข็ง ฟ่านเสียนต้องไม่ยอมพลาดเด็ดขาด\nแต่แล้วทีสร้างความประหวันพรันใจแก่ฟ่านเสียนคือ กลุ่มคนร้ายใช้\nป ไม้ตายออกแล้ว\nคราครังนี่ฝ่ายตรงข้ามใช้ราชองครักษ์ที่ฝังตัวอยู่ในวังนับสิบปี\nไม่ทว หเจ่ายค่าตอบแทนมากน้อยเท่าใด ค่อยเชิญตัวมือกระบีชุดขาวมา\nแน้นการล่อลวงหงกงกงออกไป เลือกจังหวะเวลาทีเหมาะสมที่สุด\nแต่ว่าคนร้ายชันทีเก้ามิใช่ท่าไม้ตาย แม้แต่มือกระบีทีใช้กระบือย่าง\nแหพ เกราดรุนแรงก็มิใช่ท่าไม้ตาย\nท่าไม้ตายที่แท้จริงมาจากด้านหลังของฮ่องเต้รัฐซชิง\nขณะทีฮ่องเต้ถูกกระบีของมือกระบีชุดขาวคุกคามถอยไปหลายก้าว\nพแต่มาถึงเบื่องหน้าขันทีน้อยหน้าตาหมดจดที่ยกสุราเบญจมาศมา เห็น\nภ์แพลกโต๊ะสุราล้มลง ยืนมือไปที่เสาระเบียง ก็เนรมิตมีดสันสีเทาทะมีน\nแล่งแหนึ่งราวกับนักแสดงมายากล จ้วงแทงใส่พระขนองของอ่องเต้อย่าง\nมีดสันซ่อนอยู่ในเสาไม้ที่คํายันวิหารฮุ่ยคง ด้ามมีดทาสีเดียวกับเสา\nงหน้าซําผ่านเวลาแรมปี ไม่มีผู้ใดพบว่าทีนั้นซ่อนอาวุธร้ายเล่มหนึ่ง\nไม่งไผ้ใดทราบว่าฝ่ายตรงข้ามวางแผนปลงพระชนม์ฮ่องเต้รัฐชิงมานาน\nเท่ ไตแล้ว\nเพียงดูจากความอดทนและแผนการอันรอบคอบถึงเพียงนี้ ก็ทราบ\nซ ศา ข่\nเพ าพตรงข้ามหมายมันลงมือสำเร็จ คิดปลงพระชนม์ฮ่องเต้แห่งวัฐ มิใช่','2026-04-17 09:49:10'),(103,10,100,'พงพาขุมกาลง หากเป็นความตั้งใจและความกล้าหาญ\nยามนี้ทีเบืองหน้าฮ่องเต้รัฐชิงเป็นกระบีโบราณ แต่ใช้ออกต ๒\nสภาวะกระบีสะท้านดินฟ้า ทีด้านหลังของพระองค์เป็นมีดสันทีเก่าย\nโบราณ แต่พลิกแพลงชั่วร้ายถึงขีดสุด\nฟ่านเสียนเผชิญการทดสอบที่คับขันอันตรายที่สุดนับตั้งแต่กลับฑ\nมาเกิดใหม่ เปรียบกับการต่อสู้กับไห่ถังในพงหญ้ายังน่าสะพรึงกลัวกว่า แม\nว่ามันไม่ทันทอดถอนใจรําพึงอันใด หากตัดสินใจเลือกวิธีการทีคิด1\nถูกต้อง ซัดมีดสันสีดําหลุดจากมือ ปักใส่ดวงตาของฝ่ายตรงข้าม\nฟ่านเสียนทราบว่าตนเองมิใช่เซียนวิเศษ ต่อให้เป็นท่านอาอู่จิ้หก\nสีปรมาจารย์อยู่ในตําแหน่งของตนเอง ก็ไม่สามารถคุกคามคนร้ายที่เบีกง\nหน้าล่าถอย ช่วยชีวิตขององค์ชายสามไว้ แล้วค่อยปะทะกับมือกระบีชุด\nขาว หลังจากนั้นยังมีเวลาและเรียวแรงรับมือขันทีน้อยทีด้านหลังฮ่องเต้\nขันทีน้อยในวังไม่มีวิชาฝีมืออันใด แต่มีดสันเก่าแก่โบราณในมือมัน\nกลับเป็นอาวุธคร่าชีวิตคน\nดังนั้นฟ่านเสียนเลือกช่วยเหลือองค์ชายสามก่อน แล้วค่อยช่วย\nง ซาง เง :\nเหลือฮ่องเต้ ถึงแม้ว่าการเลือกเช่นนี้ดูเหมือนทรยศเนรคุณ แต่ในสายตา\nของฟ่านเสียน องค์ชายน้อยมีอายุเพียงแปดขวบ ยังเป็นเด็กชายผู้หนึ่ง\nช่วยคนย่อมต้องช่วยตัวเล็กก่อน\nมีดสันสีดําคล้ายงูดําพุ่งฉกจู่โจม มุ่งใส่หว่างคิวของคนร้ายคนแรก\nทปลอมตัวเป็นราชองครักษ\nในแผนการที่ฝ่ายตรงข้ามวางไว้ ย่อมทราบว่าฝีมือทีร้ายกาจที่สุด\nของฟ่านเสียนคือมีดสันสีดําเรียวยาวเล่มนี้ ตามคําเล่าลือ นี้เป็นอาวุธอัน\nอัปมงคลทีผ่านพิธีกรรมจากเพยเจีย ดังนั้นคนร้ายชันทีเก้านั้นไม่กล้าชะล่า\nไจ ใช้ดาบหักครึ่งเล่มปัดกระแทกมีดสันสีดําปลิวกระเด็นลงจากชันบนของ','2026-04-17 09:49:10'),(104,10,101,'ภันกลับคิดใคร่ชมดูว่า ฟ่านถีซือซึ่งได้รับการกล่าวขานว่าเปรื่อง\nฝาเตทงบปุ่นและบู๊หลังจากสูญเสียอาวุธ จะรับดาบของตนเองอย่างไร\nขณะทีมีดสันสีดําลอยพันจากราวลูกกรง ฟ่านเสียนก็หมุนตัวขวับ\nเป็ตเกยแผ่นหลังตนเองให้กับคนร้าย ในขันตอนที่หมุนตัว ก็ใช้ระดับ\nตเหเจ้วที่ไม่ว่าผู้ใดไม่อาจเห็นชัดตา ยกมือมาทีผมเผ้าของตนเอง แล้ว\nก็ดไง ดต้านหลังตามสภาวะ\nเข้มปักดอกไม้ทีเล็กละเอียดเล่มนี้ พอดีแทงใส่นิวก้อยของคนร้าย\nแพ่เก้านั้น เพียงแทงเข้าไปเล็กน้อย กระทั้งโลหิตก็ไม่ไหลออกมาแม้สัก\nหยตดเตียว\nแต่คนร้ายชันทีเก้านั้นกลับครางหนักๆ คําหนึ่ง รู้สึกเลือดลมสะดุ\nจึงสะบัดดาบพฟันนิวก้อยของตนเองลงมา\nมันพอเงยหน้าขึ้น ก็ไม่เห็นฟ่านเสียนอีก\nฟ่านเสียนเคลื่อนไหวดุจภูตพราย มาถึงเบื่องหน้ามือกระบีชุดขาว\nผู้กิงไหญ่นั้น ขวางอยู่หว่างกลางของมันกับฮ่องเต้ พร้อมกับการมาของ\nฟ \"แสียน ยังมีธนูสันสีดําที่คร่าขวัญปลิดวิญญาณสามดอก กับควันพิษ\nหนายกลุ่มที่พอผสมเข้าด้วยกัน สามารถกัดกร่อนลําไส้ขาดไป\nควันสีเหลือง เขียว ขาวกลุ่มใหญ่แผ่กระจายอยู่ชันบนสุดของวิหาร\nเป็นเความประหลาดลีลับอย่างบอกไม่ถูก คล้ายดอกไม้ไฟในงานเทศกาล\nขากงมหานคร\nมิคาดมือกระบีชุดขาวคล้ายคุ้นกับยุทธวิธีของฟ่านเสียนยิง จึงชิง\nหล1เหลีกจากธนูลับทั้งสามดอก ทั้งปิดกลันลมหายใจ ยังคงเสือกแทงกระบี\nแหวกฝ่าควันพิษ เข่นฆ่าถึงเบื่องหน้าฟ่านเสียน\nยามนี้ฟ่านเสียนใช้ออกด้วยวิธีการทั้งมวล ค่อยขวางอยู่เบืองหน้า\nทตองเต ต่อให้กระบีนี้โถมแทงมา เพียงแทงถูกร่างฟ่านเสียน ถอวามนยอม','2026-04-17 09:49:10'),(105,10,102,'ขายชีวิตให้กับเจ้าชีวิต ส่วนขันทีน้อยทีลอบปลงพระชนม์ฮ่องเต้จากพห\nด้านหลัง ก็แล้วแต่บุญวาสนาของฮ่องเต้เถอะ\nกระบีมาถึงเบืองหน้าแล้ว\nลมปราณอันกราดเกรียวภายในกายฟ่านเสียนอาละวาดอย่างตุก\nไม่ทราบว่าใช้จิตสมาธิควบคุมลมปราณ หรือว่าลมปราณควบคุมจิตสง1\nไว้ ได้ยินมันกู่ร้องเสียงแหลมเล็ก ผลักดันสองมือออก พลังลมปราณภายไแ\nกายคล้ายถูกอัดเป็นหินผาสองท่อนชําแรกผ่านท่อนแขนออกไป เข้าห\nกระบีโบราณเล่มนั้น\nมือกระบีชุดขาวขมวดคิวเล็กน้อย ทราบว่าหากตนเองยังคงใช้กาะท\nแทงตรง ต่อให้แทงทะลูอกของฟ่านเสียน เกรงว่าต้องถูกฝ่ามืออันน่ากผ้\nทั้งสองข้างฟาดกระดูกหน้าอกหักหมดสิน\nเสียงซีคราหนึ่ง กระบีโบราณเล่มนั้นคล้ายเซียนวิเศษขยับกิงไม่\nเข่ยวขจี แทงใส่หัวไหล่ของฟ่านเสียน\nขณะเดียวกันมอกระบิชุดขาวละทิ่งกระบ ประฝามอกับฟ่านเสียน\nเสียงโครมดังกึกก้อง พลังลมสะท้านพืนทีรอบข้าง เกิดผงคลีคล:\nควันพิษกระจายหายสิน มือกระบีชุดขาวต่อให้มีพรสวรรค์เพียงไหน\nก์ไม่อาจเทียบเท่ากับฟ่านเสียน ซึ่งปรับพืนฐานพลังลมปราณตั้งแต่วัย\nแบเบาะ ดังนั้นมือซ้ายเชืองช้ากว่าเล็กน้อย เสียงกร้อบเมื่อกระดูกข้อมือ\nแต่ที่สร้างความตื่นตระหนกแก่ฟ่านเสียนคือ ขณะที่มือกระบีชุดขาว\nเทดนเองกระแทกล่าถอย กลับสามารถถอนดึงกระบีโบราณซึ่งปักอยู่บน\nทวไหล่ตนเองกลับไป นับเป็นระดับความเรว็วปานใด ฝีมืออันแยบคายถึง\nเมื่อจู่โจมล้มเหลว ก็ล่าถอยในบัดดลถือเป็นแบบฉบับของนักฆ่าชัน\nแนแวหนา มือกระบีชุดขาวใช้ป ลายเหทา สะกดราวลูกกรง กระทงเหลอบแล','2026-04-17 09:49:10'),(106,10,103,'ฝั้งไปเหลือบแลฟ่านเสียน ชิงกระโดดลงจากชันบนของวิหาร เสือผ้าที่สวม\nไต่ยูเลงแทูเขาพัดกระพือปีก คล้ายกระเรียนขาวกางปีกโบยบินตัวหนึ่ง\nขเนะที่มือกระบีชุดขาวกับฟ่านเสียนประมือกัน ในบริเวณก็บังเกิด\nเสียงตั้งเบาๆ สองครา\nคนร้ายชันทีเก้าทีสร้างความบันป่วนวุ่นวายแก่ฟ่านเสียนพลันหลัง\nไตทิตเนืองนองหน้า กระดูกหัวไหล่ทั้งสองแหลกหมดสิน ดวงตาทอแววไม่\nฝ็นกกมและสินหวังล้มตัวลง\nขณะทีมันล้มลง มูมปากปรากฏโลหิตสีดําไหลซึมออกมา รอจนร่าง\n(ทะหแผกพนของวหาร กตายอยางสนท ฑทีด้านหลังคนร้ายนั้นกลับยืนไว้\nตด้ เหหงางกง\nหงกงกงที่ร่างงอรุ้มยืนสงบนิง สองมือซูกอยู่ในแขนเสือ คล้ายกับ\n1ไม่ได้ลงมือมาก่อน\nฟ่านเสียนยังนึกถึงท่าไม้ตายสุดท้ายของกลุ่มคนร้าย ต้องหมุนตัว\nไปตวยความสินหวัง กลับพบภาพอันน่าตื่นตระหนก จวบกระทั้งหลายปีให้\nหลงฝังจดจําติดตาตรึงใจไว้\nขันทีน้อยทีถือมีดสันคิดปลงพระชนม์ล้มระทวยลงกับพื้น ทีข้าง\nตท่วพะมีเศษไม้กองหนึ่ง\nฮ่องเต้รัฐชิงทีเป็นเป้าปลงพระชนม์ของมันทรงถือถาดไม้ที่จัดวาง\nฯ\"ตกสุราครึ่งท่อน นี้เป็นอาวุธเพียงหนึ่งเดียวที่ฮ่องเต้ทรงหยิบฉวยได้\nพวะถงค์ทอดพระเนตรขันทีน้อยทีแทบพระบาท ตรัสเสียงเย็นชาว่า “ข้า\nแม้วงาไช่เยียหลิวหวิน แต่อาศัยชนชันเช่นเจ้ายังไม่อาจฆ่าได้”\nนี้เป็นความสัตย์จริง ฮ่องเต้รัฐชิงแม้ไม่ทรงฝึกวิทยายุทธ์ แต่จะ\nกผ่างไรเป็นผู้ยิงใหญ่ที่ควบม้าศึกพิชิตแผ่นดิน ยังทรงมีฝีมืออยู่ท่าสองท่\nฟ่านเสียนที่ยังไม่ระงับขวัญอันแตกตื่น มองดูถาดไม้ครึ่งใบทีฮ่องเต้','2026-04-17 09:49:10'),(107,10,104,'ทรงถือไว้ ไม่ทราบเพราะเหตุใด พลันนึกถึงภาพยนตร์เรื่องกู๊หว่าไจ่\" 6,\nเคยชมมาเมื่อชาติปางก่อน\nทีชันล่างของวิหารฮุ่ยคงบังเกิดเสียงรําร้องด่าทอดังระงม\nกระบีชุดขาวนั้นหลบหนี้ลงไปถึงเบืองล่าง เหล่าคนบุญหนักศักดิใหญ่ก\nรัฐชิงทราบว่าฝ่ายตรงข้ามเป็นคนร้ายคิดปลงพระชนม์ฮ่องเต้ กลับกล้า2 ก\nล้อมเข้าไป\nแว่วเสียงร้องอุทานและเสียงครางหนักๆ ดังขืนมายังชันบน\nตอนนี่มิใช่เวลาพิจารณาความดีความชอบ และความผิดฐานละเว็น\nปฏิบัติหน้าที่ ฟ่านเสียนชะโงกศีรษะมองข้ามราวลูกกรงออกไป เห็นแม่ทัพ\nใหญ่รักษาการณ์มหานครเยียฉงยืนอยู่บนพืน ยกมือปิดปากไว้ ด้วยสาย๓\nของมัน เห็นชัดตาว่าฝ่ายตรงข้ามกระอักโลหิตออกมา คาดว่าเมื่อค\nประมือกับมือกระบีชุดขาวคราหนึ่ง\nเยียฉงเป็นผู้เข้มแข็งชันทีเก้าของรัฐชิง ภายใต้การจู่โจมของมัน\nมันยังกระอักโลหิต อย่างนั้นมือกระบีชุดขาวย่อมรับบาดเจ็บสาหัสยิงกว่า\nจริงดังคาดหมาย ท่ามกลางเบญจมาศทัวพื้นภูเขาทีห่างไป สามารถเห็น\nเงาหลังที่เชืองช้ากว่าปรกติของมือกระบีชุดขาวเคลือนห่างออกไป\nฮ่องเต้ประทับยืนอยู่ด้านหลังมัน ตรัสเสียงเย็นชาว่า “ตามคําเล่าลือ\nกระบี่สี่ทัศนามีตี้ตี้ (น้องชาย) ผู้หนึ่ง หนืออกจากบ้านตั้งแต่เล็ก ไม่มีผู้ใด\nทราบว่ามันอยู่ที่ใด” พระองค์มีพระบัญชาว่า “ฟ่านเสียน จับตัวมันให้กับข้า\nดูว่ามันสองพีน้องใช่ปัญญาอ่อนดุจเดียวกันหรือไม่?”\nหลังจากตกอยู่ในอันตรายติดต่อกัน ในที่สุดฮ่องเต้รัฐชิงซึ่งทรงสูขุม\nเยือกเย็นโกรธกริวขึ้นมาแล้ว\nฟ่านเสียนทราบว่าตอนนี้ยังไม่ถึงรอบตนเองกล่าววาจา เมอหง\nเงื่องของกลุ่มมาเฟียฮ่องกง ตอนแรกเป็นการ์ตูน ต่อมาค่อยสร้างเป็นภาพยนตร์จอเงิน','2026-04-17 09:49:10'),(108,10,105,'ลู!เจขั่นเม เกังชั้นบนแล้ว ความปลอดภัยของฮ่องเต้หลังจากนี้มิต้องกังวล\nเว ถืาแม้ที่หัวไหล่มันยังปรากฏโลหิตหลังไหล แต่คนกระโดดข้ามราว\nเขกงวหารลงยังข้างล่างดุจวิหคดําตัวหนึ่ง\nทหานลางบงเกดเสยงรองอุทานอกครา\nฟ่านเสียนร้องบอกว่า “ล้วนตามมา” เมื่อฮ่องเต้มีรับสัง ตนเองได้\nแต่ปฏิโกัติดาม\nหลังจากที่มันพุ่งผ่านไป แม่ทัพใหญ่รักษาการณ์มหานครเยียฉงก็\nจึงพุ่งปราดไปยังทิศทางที่มือกระบีชุดขาวหลบหนี้ กง\nเตี่ยแต่ในศิษย์น้องของมัน หากวันนี้จับตัวคนร้ายไม่ได้ เกรงว่าตระกูลเยีย\nคาา บคราเคราะห์ ดังนั้นต่อให้เสียงชีวิต มันก็ต้องจับตัวคนร้ายนั้นให้\nฯ1ไต้ ทั้งยังต้องจับเป็น\nต่อจากนั้นในราชองครักษ์ทีมีวิชาตัวเบาเป็นเลิศก็กลับกลายเป็นลูก\nกนุณัาไม่ถ้วนพุ่งขวับออกไป\nที่เซิงเขาปรากฏทหารรักษาพระองค์รายล้อมเป็นซันๆ บนเขามีฟ่าน\nเส่ยนกับเยียฉงที่เป็นยอดฝีมือชันทีเก้า กับราชองครักษ์ยอดฝีมือที่ไล่กวด\nพตาม ไม่ทราบว่ามือกระบีชุดขาวนั้นหนี้รอดได้หรือไม่?','2026-04-17 09:49:10'),(109,10,106,'','2026-04-17 09:49:10'),(110,10,107,'มีตสันปราทฏ\nในวิหารฮุ่ยคง ฮ่องเต้ปราศจากเค้าความกริวโกรธ พระพักตร์สงบ\nวาบเรียบ คล้ายกับว่าเศษไม้ทีแทบพระบาท คราบโลหิตและซากศพของ\nวาซองครักษ์กับคนร้าย ตลอดจนผู้รับบาดเจ็บและคนสินสติที่อยู่ชันบนสุด\nไม่ได้ดํารงคงอยู่ ดูเหมือนพระองค์ไม่ได้เผชิญเหตุการณ์ปลงพระชนนม์ที่\nศัตรูวางแผนมาหลายปี หากกำลังดําเนินเทศกาลชมเบญจมาศซึ่งจัดขึ้น\nทุกสามปีครัง\nมีคนเริมเก็บกวาดสภาพความเสียหาย ยอดฝีมือในวังเบียดเสียดกัน\nคยู่ซันบนสุด ราวกับจะกดทับวิหารหลังนี่พังลง ราชองครักษ์ที่ถวายการ\nกาจักขาฮ่องเต้ตอนแรกหน้าซีดเผือด ขันทีทั้งหลายรวมทั้งไต้กงกงตัวสัน\nงแงก ไม่ทราบว่าเหตุการณ์ปลงพระชนม์ฮ่องเต้จะนำมาซึ่งความ\nแป ลี่ยนแปลงอันใดแก่โชคชะตาตนเอง หรืออาจเป็นการสินสุดยุติของชีวิต\nไทจือคืบคลานขืนจากพื้น หลังนำตานองหน้า คุกเข่าอยู่หน้าพระ\nพผักตร์พร้อมกับองค์ชายใหญ่ องค์ชายใหญ่ก็กล่าวขออภัยโทษว่า “เอ้อเฉิน\nไจ้ความสามารถ เป็นเหตุให้ฟู้หวง ได้รับความตระหนกแล้ว”\n\"พว็ตทตัวเองของราชโอรส\nพาวะไดา','2026-04-17 09:49:10'),(111,10,108,'มันกล่าวเสียงทุ้มหนัก ระหว่างประจําการที่ชายแดนตะวันตก ภัก\nสังหารข้าศึกนับไม่ถ้วน คิดไม่ถึงเมื่อเผชิญกับคนร้าย ตนเองกลับไม่\nปฏิกิริยาใด ขณะทีฟ่านเสียนซึ่งมันนึกดูแคลนอยู่บ้างกลับมีฝีมือถึงขัน\nวับเหตุเปลี่ยนแปลงอย่างรวดเร็วถึงเพียงนี้\nฮ่องเต้ตรัสว่า “เมื่อมีฝีมือชันทีเก้า ล้วนไม่รวบรัดธรรมดา พว\nเจ้าแม้เป็นบุตรชายของข้า พอเผชิญกับคนเดนตาย ย่อมไม่ทันมีปฏิกิริย\nพระองค์คล้ายไม่ตําหนิราชโอรส เพียงทอดพระเนตรคนร้ายชันท่\nเก้าที่ตายใต้เงื่อมมือหงกงกง กับจอกสุราทีถูกไทจือเหยียบแตกแวบหนึ่ง\nทรงขมวดพระขนงเข้าหากัน\nพระองค์ทรงโอบองค์ชายสามซึ่งยังหวาดกลัวไม่คลาย สายพระเนตร\nกลับมุ่งไปยังเบญจมาศทัวพื้นภูเขา บนเนินเขามีความเคลื่อนไหวเป็นครั้ง\nคราว ปรากฏกิงใบปลิวว่อน\nหงกงกงยืนอยู่ด้านหลังฮ่องเต้ กล่าวอย่างนอบน้อมว่า “ให้บ่าวเฒ่\nไปเถอะ ระหว่างนี้ใต้เท้าเสี่ยวฟ่านไม่สบาย บ่าวเฒ่าเป็นห่วงอยู่บ้าง”\nบนพื้นทิ่งถุงยาไว้ เป็นฟ่านเสียนทิ่งให้ก่อนไป ขณะที่ควันพิษ\nอบอวล ต้องมีคนสูดดมเข้าไป ดังนั้นฟ่านเสียนทึงยาขจัดพิษเอาไว้\nฮ่องเต้ทอดพระเนตรถุงยาบนพื้น ทรงดําริถึงความรอบคอบของ\nเด็กผู้นั่น สายพระเนตรต้องทอแววเสียพระทัยเล็กน้อย ค่อยฉุกคิดว่า\nระหว่างนี้ร่างกายของฟ่านเสียนมีปัญหา ครั้งก่อนหงกงกงไปเยียมไข้ที่ตึก\nดระกูลฟ่าน ได้ยืนยันข้อนี่\nฮ่องเต้ทรงเคาะพระดรรชนี้ลงบนราวลูกกรงของวิหารเป็นเสียงดัง\nพระกํากับดูแลทักษิณทีเบืองล่างคล้ายรู้สึกได้ จึงแหงนมองขึ้นมาแวบ\nหนึ่ง\nฮ่องเต้รับสังต่อหงกงกงว่า “ท่านไม่ต้องไป ข้าส่งคนไปแล้ว”','2026-04-17 09:49:10'),(112,10,109,'เพิ่งรับสั่งจบ ในหุบเขาเบื้องล่างของวิหารฮุ่ยคงปรากฏเงาร่างหลาย\nสายขึ้น ทุกคนสะพายดาบยาว ปืนป่ายผนั่งผาขึ้นมา โถมไปในทะเลบุปผา\nเพียงชั่วขณะก็ล้าหน้าราชองครักษ์วังหลวงที่ล่วงหน้าไปก่อน ไล่กวดตาม\nสามคนแรกไป\nเป็นพยัคฆ์พิทักษ์เอง\nในป่าเขามีศาลเจ้า หน้าศาลเจ้ามีธารภูเขา ธารภูเขาลาดชันอยู่บ้าง\nฟ่านเสียนวิงตะบึงอยู่กลางท้องทุ่งธารภูเขา สูดดมกลินหอมจางๆ\nของเบญจมาศด้ายทอง คล้ายกับสูดฝืนเข้าไป พลังลมปราณภายในกาย\nโคจรผ่านเส้นทางทั้งสองสาย ชดเชยกำลังทีใช้ออก สองเท้าคล้ายกับมี\nตวงตางอกเงย หยังเท้าลงบนโขดหินเบืองล่างอย่างแม่นยํา ร่างคล้าย\nมังกรดําตัวหนึ่ง สาดพุ่งลงจากเขาด้วยระดับความเร็วที่น่าตระหนก\nเอ่ยถึงการกระโดดหน้าผา ในโลกนี้นอกจากท่านอาอู่จู๋แล้ว ไม่มี\nผู้ใดรวดเร็วกว่ามัน อย่าว่าแต่วันนี่หลังจากประมือกับมือกระบีชุดขาว\nการฝึกปรือภายในกายถูกปลูกกระตุ้นขึ้นมา อยู่ในสภาพสมบูรณ์ขีดสุด\nกาการบาดเจ็บบนไหล่ซ้ายไม่นับเป็นอย่างไร\nที่เบืองหน้าหลายสิบวาเป็นเงาร่างสีขาวลับล่อรําไร ท่าร่างก็ลึกลํา\nพิสดาร ลอยตัวดุจปุยเมฆ รุดหน้าไปอย่างแยบคาย แต่ไม่เร็วเท่ากับฟ่าน\nเสียนซึ่งอาศัยแรงดึงดูดของศูนย์กลางของโลกเพิ่มความเร็วขึ้น\nระยะห่างของทั้งสองย่นใกล้เข้าไปทุกขณะ\nเหล่าราชองครักษ์ที่ด้านหลังยังค้นหาทางภูเขาอยู่ ไม่ทราบถูก\nทอดทิงล้าหลังเท่าใด ส่วนใต้เท้าเยียฉงมีพลังการฝึกปรือเน้นหนักทีคําฉง\n(หนักหน่วง) จึงถูกยืดห่างออกไปช่วงหนึ่ง\nในระยะเวลาที่น้ำชายังไม่เย็นชีด ทั้งสองก็แยกย้ายเป็นหนึ่งหน้า\nหนึ่งหลังโถมถึงเชิงเขา มองแต่ไกลเห็นผืนธงและม้าของทหารรักษา','2026-04-17 09:49:10'),(113,10,110,'พระองค์ ฟ่านเสียนเพิงคลายใจลง กลับพบว่ามือกระบีชุดขาวทีเบื่องหน้.\nเอียวตัวคราหนึ่ง ปรับเปลี่ยนทิศทางเฉียดผ่านราวป่าที่เชิงเขา พุ่งปรา๓\nไปทางตะวันตก\nฟ่านเสียนหยังเท้าลงบนพืนราบแล้ว จึงปรับตัวไม่ทัน แต่มือกระง\nชดขาวปะทะฝ่ามือกับเยียฉง แสดงว่าพบกับความเพลียงพลํา ไม่อาจเว่ง\nความเร็วขึ้น ถูกมันตามติดอยู่ด้านหลัง\nแต่ฟ่านเสียนพอเห็นตําแหน่งทิศทีปรับเปลี่ยนของฝ่ายตรงข้าม อต\nสะท้านใจมิได้\nการติดต่อระหว่างบนเขากับเชิงเขาไม่สะดวก ต่อให้ข่าวปลง\nพระชนม์ฮ่องเต้ถูกส่งมา เหล่าทหารรักษาพระองค์ทีเชิงเขายากจะปรับตัว\nได้ อย่าว่าแต่ตําแหน่งทิศที่มือกระบีชุดขาวปรับเปลี่ยน เป็นจุดที่ทหาร\nรักษาพระองค์ยากดูแลได้โดยทัวถึง นั้นเป็นดงไม้อันหนาทีบแถบหนึ่ง ถึง\nแม้ว่าพื้นที่ของดงไม้ไม่กว้างใหญ่เท่าใด แต่ก็เพียงพอกับการช่วยปกปิด\nร่องรอยให้กับฝ่ายตรงข้าม\nฟ่านเสียนไล่กวดตามอย่างเงียบงัน ภาวนาว่าการบกพร่องต่อหน้าที\nของกงเตียน ไม่เป็นเหตุให้ราชองครักษ์วังหลวงลืมตําแหน่งทิศนี้ไป\nทีสร้างความยินดีแก่มันคือ รอบนอกของดงไม้มีการวางกำลัง\nป้องกันไว้ มือกระบีชุดขาวจึงเปลี่ยนทิศทางอีกครา\nฟ่านเสียนตามติดโดยกระชันชิด\nมือกระบีชุดขาวเปลี่ยนทิศทางอีก\nฟ่านเสียนติดตามต่อไป\nหลังจากเปลี่ยนตําแหน่งทิศหลายครั้ง มือกระบีชุดขาวยังคงรักษา\nระยะห่างจากทหารรักษาพระองค์ที่อยู่ห่างไป ขณะทีฟ่านเสียนไม่มีเวลา\nร้องขอความช่วยเหลือจากพีน้องทั้งหลาย\nเสยงขวบคราหนง มอกระบชุดขาวเรงความเรวขน พุ่งปราดไปยัง','2026-04-17 09:49:10'),(114,10,111,'แงทเบองหน้าแห่งหนง\nรอจนฟ่านเสียนกัดฟันติดตามไป ค่อยพบเห็นความจริงที่น่ากลัว\nปวะการหนึ่ง\nตนเองติดตามมือกระบีชุดขาวฝาออกจากวงล้อมของทหารรักษา\nพาวะองค์ทีเชิงเขาแล้ว\nทีเบืองหน้าเป็นที่โล่งกว้าง ไม่มีผู้คนเฝ้ารักษา ฟ่านเสียนไม่เข้าใจ\nเพื่อกระบีชุดขาวรอดพันจากการถูกจับตามองของทหารรักษาพระองค์\nได้กย่างไร นอกจากทั้งสองมีท่าร่างทีรวดเร็วแล้ว คําอธิบายเพียงหนึ่งเดียว\nมือกระบีชุดขาวผู้นี้ทําความเข้าใจกับการวางกำลังทหารรักษาพระองค์\nตลอดจนปฏิกิริยารับเหตุเปลียนแปลงของราชสำนักชิงถึงขันที่น่ากลัว\nจากนั้นนึกโยงว่าวันนึกงเตียนไม่ได้อยู่ในวิหารฮุ่ยคง ฟ่านเสียนรู้สึก\nงความเย็นเยียบแผ่ซ่านขึ้นจากกลางหลัง แต่ตอนนี้มิใช่เวลานึกถึงแผน\nเยียฉงหนักเกินไป ราชองครักษ์ช้าเกินไป ที่ข้างกายไม่มีบุคคลอื่น\nหากปล่อยให้คนร้ายรายนี้หนี้รอดได้ ฟ่านเสียนต้องรับผิดชอบแล้ว\nดังนั้นไม่อาจหันหลังกลับ ได้แต่ติดตามไป\nฟ่านเสียนมีความเชือมันต่อความสามารถในการติดตามของตนเอง\nโดยเฉพาะที่ริมทะเลสาบเปยไห่ ตนเองนำเหล่าพยัคฆ์พิทักษ์ไล่กวดตาม\nแช่ยวเอินไม่ลดละ มันไม่เชือว่านอกจากสีปรมาจารย์แล้ว มีคนสามารถหนี้\nาอดจากการติดตามของตนเอง\nแต่วันนี้เกิดเรื่องไม่คาดหมายติดต่อกัน สร้างความประหวันพรันใจ\nแก่มัน ก่อนอืนฝ่ายตรงข้ามฝ่าออกจากการปิดล้อมของทหารรักษา\nพระองค์ ต่อจากนั้นฝ่ายตรงข้ามแสดงความสามารถในการสลัดหลุดพัน\nจากเชิงเขาถึงริมบึง จากนั้นพุ่งผ่านบึงนำไป ผ่านกระท่อมชาวนากับทห้อง\nทุ่งกว้าง มือยู่หลายครั้งทีมือกระบีชุดขาวหายลับจากคลองจักษุของมัน','2026-04-17 09:49:10'),(115,10,112,'หากมิใช่ฟ่านเสียนมีสายตาคมกล้า ทั้งมีโชคดี คงถูกฝ่ายตรงข้ามสลัดหลญู๓\nไปแต่แรกแล้ว\nมิหน้าซําตลอดรายทางทีผ่านมา มือกระบีชุดขาวแสดงออกถึงควาง!\nสูขุมหนักแน่น ถึงกับเป็นการหลบซ่อนตามสัญชาตญาณ สร้างความเลือง!\nใสแก่ฟ่านเสียนยิง มันสัมผัสกับสำนักตรวจสอบตั้งแต่เล็ก ย่อมทราบว่าน\nต้องผ่านการฝึกอบรมมานานปี\nโดยเฉพาะฝ่ายตรงข้ามลงมือลบร่องรอยด้วยความชํานาญ ทั้งเยือ\nเย็นอย่างยิง ให้ความรู้สึกที่คุ้นชินแก่ฟ่านเสียน เป็นความคุ้นชินต่อควาง!\nขัดกับอาภรณ์ชุดขาวของมือกระบีผู้นื่อย่างยิง\nนี้คงเป็นด้านที่แท้จริงของมือกระบีชุดขาว ทั้งเยือกเย็น ชั่วร้าย :\nเด็ดเดียว\nากระบีทีใช้บนวิหารฮุ่ยคงแม้โอ่อ่าอาจหาญ แต่ในสายตาของฟ่าน\nสียน ไ น่าตระหนกเท่ากับกลินอายดํามิดทีแผ่ซ่านจากร่างฝ่ายตรงข้าม\nขุมกำลังทีแท้จริงของคนผู้นี้ เกรงว่าเหนือกว่าเซียวเอินที่ชราภาพลง ยัง\nเหนือลํากว่าตนเองอีก\nฟ่านเสียนยิงมายิงอกสันขวัญแขวน ตอนอยู่บนวิหารฮุ่ยคง ตนเอง\nออกจะหุนหันเกินไป เลือดร้อนเกินไป ยามนี้พอสงบเยือกเย็นลง ค่อย\nประเมินอานุภาพของท่ากระบีของฝ่ายตรงข้ามใหม่ หากมิใช่เยียฉงทําร้าย\nฝ่ายตรงข้ามบาดเจ็บบอบชํา อาจบางทีสิงทีฟ่านเสียนพึงกระทําในตอนนี้\nคือหยุดเท้าลง อยู่ห่างจากมือกระบีชุดขาวให้มากไว้\nทีเบืองหน้าทั้งสองเป็นมหานคร กําแพงเมืองที่สูงตระหง่านคุกคาม\nจิตใจผู้คน\nเสียงพืบคราหนึ่ง มือกระบีชุดขาวไม่หยุดยังท่าร่าง ใช้มือข้างเดียว\nถอดเสอยาวสขาวออก เผยเห็นเสือผ้าอันสมถะสวมทับอยู่ข้างใน เป็น','2026-04-17 09:49:10'),(116,10,113,'เครื่องแต่งกายดุจเดียวกับชาวเมืองทัวไป\nเสือยาวสีขาวถูกทึงบนดินโคลน พริบตาต่อมาปลายเท้าข้างหนึ่งก็\nแะกิดใส่เสือผ้า เงาร่างสายหนึ่งพุ่งผ่านไปอย่างรวดเร็ว\nฟ่านเสียนมองดูมือกระบีที่แปลงโฉมเป็นสามัญชนคนธรรมดา ใน\nไงยอมรับนับถือฝ่ายตรงข้ามจนหมดใจ ฝ่ายตรงข้ามต่างกับนักฆ่าทัวไปที\nหลบหนี้ไปยังชานเมือง กลับเข่นฆ่าเข้ามหานครราวกับพาตัวมาติดกับ ใน\nงเหานครไม่ทราบมีผู้คนกีหมื่นคน ฝ่ายตรงข้ามปะปนอยู่ในทะเลมนุษย์\nตตว่ามีศักดิฐานะทีไว้วางใจได้เป็นเครื่องกําบัง ต่อให้สำนักตรวจสอบทุ่ม\nทเล้งออกมาทั้งหมด เกรงว่ายากจะหามันพบ\nวันนี่ทางราชวงศ์ชุมนุมทีวิหารฮุ่ยคง การรักษาการณ์ในมหานครจึง\nหลวมคลาย ไพร่พลทีเฝ้าประตูเมืองรู้สึกละลานตาวูบ จึงยกมือขยีตา แต่\nไม่ทราบว่าเกิดเรื่องอันใด\nฟ่านเสียนเห็นชัดตาว่าฝ่ายตรงข้ามปะปนอยู่ในฝูงชนของมหานคร\nจึงไม่คํานึงถึงการสร้างความแตกตื่นแก่ผู้คน พุ่งโถมไปยังประตูเมือง\nขณะท เข้าเมืองไม่ถูกขัดขวาง ฟ่านเสียนยังสะกดรอยตามนักฆ่านั้น\nได้ เมื่ออยู่ในพืนภูมิประเทศอันซับซ้อนเช่นมหานคร คอยแสดงออกถงขด\nความสามารถของนักฆ่าทีซ่อนเร้น ฟ่านเสียนต้องทุ่มเทอย่างสุดฝีมือ จึง\nไม่ปล่อยให้บุคคลทีคล้ายเงาร่างนั้นหลุดพ้นไป ดีที่วันนี้มีสมาธิแจ่มใส\nาะดับความเร็วก็ไม่ลดลง\nการไล่ล่าและย้อนสะกดรอยดําเนินในบ้านเรือนราษฎรและตรอก\n\"ฯอยในมหานคร ระดับความคับขันอันตรายหาต้อยกว่าตอนอยู่ที่ริมทะเล\nสาบเปียไห่ไม่ ถึงกับยังตื่นเต้นตึงเครียดยิงกว่า\nเงาร่างพลิวผ่านมูมหอ สะกิดเท้าใส่รองเท้าผ้าใต้ลําไม้ไผ่ ตัดผ่าน\nกนนเก่าอันครึกครื่น ชนพ่อค้าหาบเร่ทีขายนำเต้านำตาลผู้หนึ่งล้มลง การ\n1 & 4 ๐ ๆข! รง ข เว ๑ ๕\nพุ่งชนครั้งนี้ทําให้ฟ่านเสียนลงความเห็นว่า คนรายนนรบบาดเจบสาหส จง','2026-04-17 09:49:10'),(117,10,114,'ควบคุมร่างกายตัวเองไม่ได้\nตรอกตันสายหนึ่งปรากฏขึ้นที่เบืองหน้า หลังเสียงฝีเท้าอันเร่งร้อน\nในที่สุดฟ่านเสียนอุดปากตรอกไว้ได้สำเร็จ\nหลังจากลําบากตรากตรําใช้ความคิดใช้กำลัง สีหน้าของมันขาวซีด\nอย่างไม่เป็นธรรมชาติอยู่บ้าง สองแก้มกลับแดงซ่านด้วยความลิงโลด\nดวงตาเป็นประกาย เป็นลักษณะของพลังลมปราณภายในกายสมบูรณ์\nขีดสุด\nซั ฝไไๆ ลี\nคนร้ายที่ถูกอุดอยู่ในตรอกยังยําแย่ยิงกว่า เสือขาวหลุดจากร่าง ใต้\nเสือผ้าที่พืนเพธรรมดาเผยเห็นนำเลือดไหลซึมออกมา\nคนร้ายนั้นหมุนตัวมา เป็นใบหน้าทีฟ่านเสียนไม่คุ้นเคย ทั้งขาวซีด\nดุจเดียวกัน คาดว่าปรกติน้อยครั้งจะรับแสงแดด ทั้งไม่ทราบว่าผ่านการ\nปลอมแปลงโฉมมาหรือไม่ มันกล่าวเสียงแหบพร่าต่อฟ่านเสียนซึ่งอยู่\nห่างจากตนเองเพียงสิบก้าวว่า “ใต้เท้าเสียวฟ่าน ท่านไม่เหน็ดเหนือย\nฟ่านเสียนงงงันวูบ จึงกล่าวเบาๆ ว่า “เราผู้เป็นขุนนางนึกไม่ถึงว่า\nท่านจะวิงไกลถึงเพียงนี้”\nคนร้ายนั้นยิมเล็กน้อย ยืนมือไปในเสือผ้า ล้วงกระบีโบราณเล่มนั้น\nออกมา คนพอถือกระบิมัน บุคลิกภาพก็แปรเปลี่ยนกลับกลาย จากนักฆ่า\nที่หลบหนึกลายเป็นมือกระบีทีทระนงตน เต็มไปด้วยความเชือมันและถือดี\n\'ปปากกล่าวว่า “เราความจริงไม่คิดฆ่าท่าน”\nฟ่านเสียนนิงเงียบงัน ทราบว่าหากฝ่ายตรงข้ามไม่ได้รับบาดเจ็บ\nมีกำลังเพียงพอทีจะกล่าววาจาทีดูเหมือนอวดโอ่โอหังเช่นนี้ มันรู้สึกถึงพลัง\nเพะบี่ที่แผ่พุ่งมาปะทะหน้า ต้องเลือนมือกดปุ่มของธนูลับ คิดล้วงมีดสัน\nสตําที่ซอกรองเท้า ซัดขว้างควันพิษออกไป สุดท้ายไม่พบมีดสัน ควันพิษ\nกใช้ออกหมดสิน ธนูลับไม่คงอยู่อีก','2026-04-17 09:49:10'),(118,10,115,'เต ม้ ฆ\nคนร้ายนั้นกล่าวอย่างเฉือยชาว่า “ท่านมีธนูลับสามดอก มีดสันเล่ม\nหนังง ระเบิดควันสิบสีลูก แต่ตอนนี้ ท่านอยู่ในสภาพเปลือยเปล่า\nฟ่านเสียนก้มศีรษะลง ทราบว่าตนเองวิงเข้าสู่มหานครในสภาพ\nเหเลือยเปล่า ของวิเศษทีมีส่วนช่วยตนเองทั้งสามชนิดล้วนไม่อยู่ข้างกาย\nขเนะที่ถือครองของวิเศษทั้งสามชนิด มันกล้าต่อยตีกับไห่ถัง แต่ตอนนี้\nเผชิญกับสุดยอดฝีมือทีมีขุมกำลังไม่เป็นรองไห่ถัง ฟ่านเสียนสามารถทํา\nกผ่างไร มันได้แต่ภาวนาให้อาการบาดเจ็บของฝ่ายตรงข้ามกําเริบเร็ว\nเท่านี้ ภาวนาให้ท่านอาอู่จู้มาเร็วกว่านี้\nตอนนี้พลังลมปราณภายในกายอยู่ในขันสูงสุดยอด เพิ่มความ\nเชื่อมันแก่มัน พลังปราณที่หมุนเวียนอยู่ในเส้นลมปราณอย่างรวดเร็ว\nคล้ายเด็กที่ซูกซนปลุกกระตุ้นมัน ให้ต่อสู้กับฝ่ายตรงข้ามสักครา\nที่เหนือความคาดหมายคือ ฟ่านเสียนเพียงสูดลมหายใจลึกๆ คํา\nหนึ่ง สะกดความคิดต่อสู้ของตนเองเอาไว้ ใช้สายตาทีปราศจากความรู้สึก\nเงื่อปนจับจ้องมองฝ่ายตรงข้าม ยิมพลางกล่าวว่า “ลองบอกศักดิฐานะที\nสรว้างความพึงพอใจแก่ข้าพเจ้าออกมา ข้าพเจ้าจะไม่ไล่ตามท่าน\nนี้เป็นการแลกเปลี่ยน เป็นการแลกเปลี่ยนกับสุดยอดนักฆ่าทีตนเอง\nไล่กวดตามมาถึงมหานคร เหตุการณ์ปลงพระชนม์ทีวิหารฮุ่ยคงแปลก\nประหลาดเกินไป การผละจากหน้าทีของกงเตียน ช่วงเวลาของการปลง\nพระชนม์ที่แยบคาย การปรากฏตัวและจากไปของคนร้ายผู้นี้ ความคุ้นเคย\nกับกิจการภายในของรัฐชิง ล้วนเปิดเผยความจริงที่น่ากลัวประการหนึ่งว่า\nแผนปลงพระชนม์ครังนี้ไม่ได้มีเพียงขุมกำลังกลุ่มหนึ่งเข้าร่วม หากเป็น\nทุกฝ่ายในราชสำนักชิงเข้าร่วมด้วย\nฟ่านเสียนเพียงต้องการทราบบ่อเกิดของเรื่องนี้ ไม่ได้ประพฤติเช่น\nผู้หาญกล้าทีคิดล้างอัปยศให้กับฮ่องเต้ มันมิใช่ขุนนางที่จงรักภักดี หาก\nไส่ใจว่าแผนปลงพระชนม์ครังนี่มีส่วนเกียวข้องกับตนเอง กับบิดา และกับ','2026-04-17 09:49:10'),(119,10,116,'สำนักตรวจสอบอย่างไร\nฟ่านเสียนยิมพลางกล่าวว่า “อย่าได้ยกอ้างศักดิศรีอันใด เราท่า๒\nเป็นคนประเภทเดียวกัน ทราบว่าการรับปากไม่มีความหมายอันใด\nเพียงให้ข่าวสารทีข้าพเจ้าต้องการ ข้าพเจ้าจะปล่อยให้ท่านจากไป\nคนร้ายนั้นเห็นด้วยกับคําพูดของมัน แต่ขณะที่ฟ่านเสียนเห็นว่าฝ่า\nตรงข้ามยอมรับว่านี้เป็นการแลกเปลียนทียุติธรรมแก่ทั้งสองฝ่าย\nชนะทั้งสองฝ่าย คนร้ายนั้นพลันกล่าวว่า “ปัญหาเฉพาะหน้าคือ หากว่าเน1\nญฆ่าท่าน เรามิใช่สามารถจากไปหรอกหรือ?”\nโลกนี้ช่างวิเศษแท้ ฟ่านเสียนปฏิเสธขอเสนออยู่ร่วมกันโดยสันติ ๓\nเหมือนเป็นผลดิต่อทุกฝ่ายขององค์ชายรองด้วยความติอดิง ยามนี้ก็มีคน\nตอบปฏิเสธมันอย่างดิอดึง\nทีพึ่งพาคืออะไร ย่อมเป็นขุมกำลัง\nประกายกระบีพลันปกคลุมตรอกทั้งเส้นในชั่วพริบตา ใบไม้ร่วงของ\nปลายชิวเทียนก็ถูกกระแสลมกระบีที่พัดกระโชกขึ้นมา ปลิวว่อนอยู่ระหว่าง\nคนทั้งสอง กระบีที่แฝงสํานึกโบราณเล่มนั้นก็บรรลุถึงเบื่องหน้าฟ่านเสียน\nอย่างฉับพลัน\nเช่นเดียวกับตอนอยู่บนวิหารฮุ่ยคง ฟ่านเสียนแผ่พุ่งพลังลมปราณ\nภายในกายมายังฝ่ามือทั้งสอง ใช้ลมฝ่ามือประหนึ่งเบิกฟ้าแหวกพสุธา\nกราดฟาดใส่ใบหน้าฝ่ายตรงข้าม คล้ายกับไม่เห็นกระบีที่แทงปราดมาถึง\nเบืองหน้าก็มิปาน\nลมฝ่ามืออันรุนแรงกระโชกผมเผ้าของคนร้ายนั้นพัดพลิวไปด้านหลัง\nราวกับเป็นเส้นลวดอันแข็งแกร่ง\n( 4 ขน ย ๕ ทๆข เจ่\nเอ่ยถึงวิชาการต่อสู้ ฟ่านเสียนสู้ฝ่ายตรงข้ามไม่ได้ จึงได้แต่เสียง\nมิหน้าซํามันทราบดีว่า ยิงเป็นสุดยอดนักฆ่าทีฆ่าคนนับไม่ถ้วน ยิง','2026-04-17 09:49:10'),(120,10,117,'ริกแนคมชีวิตตนเอง ยิงทระนงถือดี ไม่ยอมแลกชีวิตด้วย\nจริงดังคาดหมาย ฝ่ายตรงข้ามขวางกระบีพฟันใส่ฝ่ามือของมัน ฟ่าน\nเสียแกรังมือกลับอย่างว่องไว กลายเป็นเงาดําสองกลุ่ม ต่อยหมัดทั้งสอง\nไผ่ขงเของฝ่ายตรงข้าม ลงมือด้วยความรวบรัดจํากัด แต่ดุร้ายผิดธรรมดา\nแต่แล้วยามนั้น มือกระบีทีประมือกับมันกลับกระทําเรื่องที่ฟ่าน\nเสี่ยนคาดคิดไม่ถึงมาก่อน\nมือกระบีนั้นไม่สะบัดกระบีราวจิตรกรระบือนาม ไม่ใช้กระบีด้วยความ\nแผบคาย หากแต่ละทิงกระบี\nมันซัดกระบีจากมือ มุ่งใส่คอหอยฟ่านเสียน ร่างก็หดตัวอย่าง\nประหลาด หลบรอดจากกระแสลมหมัดอันกราดเกรียว พลางเลื่อนมือมายัง\nเกงเท้าซ้ายของตนเอง\nมันชักมีดสันทีมีดหม่นไร้ประกายออกมาเล่มหนึ่ง!\nฟ่านเสียนร้องเสียงพิกล รังหมัดกลับมา ไขว้สลับสองมือ อาศัยพลัง\nผมปราณอันกราดเกรียวกระแทกกระบีคร่าชีวิตปลิวกระเด็น กระบีโบราณ\nแหวกพุ่งเป็นเส้นตรง ปักฉีกใส่ผนั่งของตรอก สันระริกไม่หยุดยัง\nทีสร้างความตินตระหนกแก่ฟ่านเสียนยิงกว่าคือ ฝ่ายตรงข้ามกลับ\nตั้งมีดสันจากซอกรองเท้าเล่มหนึ่ง จ้วงแทงใส่ตนเอง\nกระบวนท่านี้เป็นที่คุ้นเคยของฟ่านเสียนไปแล้ว มือกระบีทีสง่า\nผ่าเผย ใช้กระบือย่างโอ่อ่าอาจหาญ ดังนั้นฟ่านเสียนใช้พลังลมปราณอัน\nร เว เซ\nกจราดเกรียวเข้าปะทะ แต่มือกระบีผู้นี้พอละทึงกระบีก็กลับกลายเป็นมืด\nหม่นไวร้ประกาย กลายเป็นเงาภูตกลางสายลมชิวเทียน มือถือมีดสันที่คม\nกล้า จ้วงแทงออกอย่างกะทันหัน\nการปรับเปลี่ยนบุคลิกภาพอย่างกะทันหันเกิดขึ้นอย่างฉับพลันทัน\nต่วน ฟ่านเสียนแทบไม่ทันรับมือได้ แขนซ้ายถูกกรีดเป็นบาดแผลโลหิต','2026-04-17 09:49:10'),(121,10,118,'เส้นหนึ่ง\nพริบตานั้นเงาร่างสีเทาดําสองสายสู้พัวพันกันในตรอกแคบเป็น\nพัลวัน นี้เป็นการต่อสู้ระยะประชิด ดําเนินไปด้วยความพลิกแพลง พันตูกัน\nโดยไร้เสียง เคลือนไหวในพื้นทีอันจํากัด หวุดหวิดหวาดเสียวถึงที่สุด ควาง!\nเคลื่อนไหวของทั้งสองยิงมายิงรวดเร็ว ทั้งหักศอกงอเข่า กดท้องน้อย\nกระทึบเท้า เริมจากมุมกําแพงขึ้นถึงบนกําแพงแล้วร่วงฟาดลงกับพื้น เสียง\nเรือนร่างเลือดเนื้อกระทบกัน ดังขึ้นอย่างชวนอกสันขวัญแขวน\nหากว่าฟ่านเสียนไม่ได้รับการชุบสร้างจากอู่จู้ตั้งแต่เล็ก และไม่ผ่าน\nการฝึกจากสำนักตรวจสอบในเชิงลึก เดินในแนวทางสายนี่อยู่ก่อน เกรงว่า\nคงถูกมีดสันทิมแทงเป็นรูโลหิตนับไม่ถ้วน แต่ถึงแม้มันหลบหลีกอย่าง\nรวดเร็ว ยังคงถูกมีดสันคร่าวิญญาณกรีดเป็นบาดแผลโลหิตหลายสาย\nฝ่ายตรงข้ามแสดงว่าล่วงรู้ลักษณะของเครื่องแบบสำนักตรวจสอบ\nเป็นอย่างดี ตําแหน่งทีปลายมีดกรีดใส่ ล้วนเป็นส่วนทีคุ้มครองไม่ทัวถึง\nทีสันขวัญสะท้านวิญญาณฟ่านเสียนคือ ฝ่ายตรงข้ามกลับศึกษา\nตนเองมาจนทะลุปรุโปร่ง คํานวณเส้นทางลงมือของตนเองได้ ท่าฝีมือย่อย\nที่ตนเองใช้รักษาชีวิต ล้วนถูกฝ่ายตรงข้ามหลบรอดได้ก่อน ไม่ว่าท่าหักนิว\nควักลูกตา บีบอัณฑะ หรือกระทุ้งศอก ทีเป็นกระบวนท่าอันตําช้าล้วนใช้\nไม่ได้ผล\nประกายสีเทาจางๆ สายหนึ่งผ่านเข้าสู่คลองจักษุของฟ่านเสียน\nส์นเล่มนั้นปักตรึงลงมา ทําให้ฟ่านเสียนนึกถึงไม้พลองของท่านอายอู่จู๋\nนึกถึงคําสอนของท่านอาอู่จู๋ทีเน็นเส้นตรง ดุดัน และแม่นยํา\nฟ่านเสียนที่ตกอยู่ในสภาพไฟลนกันเช่นนี้ ยังมีเวลารําลึกนึกถึง\nความหลัง เนื่องเพราะมันยังมีท่าผ่าโลงใหญ่ ยังซ่อนใบมีดอยู่ที่ปลายแหลม\nของรองเท้าเซวียจือ','2026-04-17 09:49:10'),(122,10,119,'ฟ่านเสียนสะบัดมอ แผ่พุ่งพลังลมปราณอันกราดเกรียวภายในกาย\nคอก ช่วงแขนของเครื่องแบบสำนักตรวจสอบขาดหลุดลุ่ย มือขวาก็สันเทิม\nขนมา กลับคล้ายท่วงท่าของหัตถ์กําจายของเยียหลิวหวิน ซึ่งเคยใช้ออก\nที่หน้าผาอ่าวต้านโจว\nคนว้ายนั้นความจริงแฝงตัวกับแขนซ้ายมันราวกับวิญญาณร้าย รู้สึก\nมีพลังอันกล้าแข็งขุมหนึ่งแผ่พุ่งมา เห็นนิวมือของฝ่ายตรงข้ามคลีขยาย\nกอก สันไหวราวกับกิงไม้อันแห้งเทียวคราหนึ่ง\nคนร้ายนั้นรู้สึกแน่นหน้าอก ถูกกระแทกกระเด็นออกไป แต่ยังจิก\nปลายเท้าลง พอดีเหยียบใส่ปลายมีดทีหัวรองเท้าเซวียจือที่เตะกราดออก\nของฟ่านเสียน หยิบยืมพลังพลิวถอยไปสามเชียะ\nฟ่านเสียนครางหนักๆ คราหนึ่ง กุมแขนซ้ายซึ่งถูกมีดสันกรีดทําร้าย\nมองดูศัตรูอันนากลัวทีเบืองหน้า พบว่าฝ่ายตรงข้ามยกมือปิดปากทิปรากฏ\nโลหิตไหลซึมออกมา ค่อยคลายใจลง\nแต่ว่าท่านอาอู่จู๋ยังไม่มา\nคนร้ายนั้นขวางศอก ยกชูมีดสันสีเทาหม่นเล่มนั้นขิน กล่าวเสียง\nแหบพร่าว่า “ท่านี้เล่าเรียนจากเจ้า\nฟ่านเสียนรู้สึกว่าพลังชีวิตของตนเองรัวไหลออกไปพร้อมกับโลหิต\nทีทะลักจากปากแผล จึงขบกรามกล่าวว่า “ไม่ต้องเกรงใจ”\nมันไม่มีเวลาโคจรพลังรักษาบาดเจ็บ ขณะที่ฝ่ายตรงข้ามมีความ\nกดทนกลํากลืนอาการบาดเจ็บเหนือกว่าตนเอง ดังนั้นฟ่านเสียนไม่ได้กล่าว\nมากความ ใช้ปลายเท้าสะกิดใส่ผนั่งกําแพงของตรอก จนอิฐสีเทาร่วงลง\nมา ตลอดทั้งร่างโถมออกไปดุจพยัคฆ์ร้าย\nคนร้ายนั้นถอยกายไปหนึ่งก้าว กระโดดปราดขึ้น มีดสันแทงย้อนใส่\nขมับของมัน','2026-04-17 09:49:10'),(123,10,120,'ฟ่านเสียนหยุดร่างไว้ พลังสภาวะเปลี่ยนจากกราดเกรียวเป็นหย\nร่างหมูนวนรอบมีดสันเล่มนั้นอย่างหวาดเสียวครึ่งรอบ ซอกนิวข์!\nขวาปรากฏประกายเย็นเยียบวูบขึ้น กลับชักดึงมือออกจากต้นคอตน๒\nนิวทั้งสองคืบจับเข็มพิษ ปักใส่ง่ามมือของมือข้างทีถือมีดสันข้างนั้น\nคิดไม่ถึงท่าจ้วงแทงมีดของคนร้ายเป็นภาพลวง เมื่อมันยืนเข็มพิห\nออกไป ฝ่ายตรงข้ามก็รังดึงมีดสันกลับมาสามนิว ปล่อยให้เข็มพิษแทงไม่\nด้านขวางของมีดสัน ไม่เกิดผลอันใด\nต่อจากนั้นคนร้ายกระทุ้งเข่าใส่ชายโครงด้านหลังของฟ่านเสียน\nสร้างความเจ็บปวดแก่มันจนหันข้างไป จึง เหนมดสนอนนากลวเลมนนย\nห่างจากหน้าอกตัวเองไม่กีนิว\nฟ่านเสียนมองดูมีดสันเล่มนั้น บังเกิดความสินหวัง ฝ่ายตรงข้าง!\nกลับเตรียมการพร้อมพรัก ล่วงรู้ว่าตนเองซ่อนเข็มรักษาชีวิตเอาไว้\nขณะที่ท่านอาคู่จู้ยังไม่มา\nทีชายโครงถูกกระทุ้งอย่างหนักหน่วง ฟ่านเสียนครางหนักๆ คําหนึ่ง\nกลับกลายเป็นเสียงแผดร้องอันเกรียวกราดออกมา\nยามคับขันเป็นตาย ฟ่านเสียนกระตุ้นพลังซ่อนเว็นภายในกายขึ้นมา\nให้พลังทําลายล้างของฝ่ายตรงข้ามแล่นเข้าสู่ด่านเซวียซานทีชายโครง\nด้านหลัง เร่งพลังลมปราณอันกราดเกรียวมายังสองแขน หนี้บประกบมีด\nสันไว้\nฝ่ามือทั้งสองกับมีดสันพอเผชิญพบกันบังเกิดเป็นเสียงดังระคายหู\nคล้ายเหล็กเผาไฟแดงจี้ใส่สันเท้าอันหยาบกร้านก็มิปาน\nทั้งสองประชิดใกล้ถึงเพียงนั้น ใกล้ชิดจนฟ่านเสียนเห็นรอยยิมใน\nดวงตาของฝ่ายตรงข้าม','2026-04-17 09:49:10'),(124,10,121,'ความโชคร้ายมักประดังติดต่อกัน ฟ่านเสียนในยามนี้ตกอยู่ในห้วง\nคําเข้าเก็นตราย ภัยซ่อนเร้นภายในกายมันกลับปะทุขึ้นมาซ้้าเติมใส่มัน\nพลังลมปราณอันกราดเกรี้ยวคล้ายเด็กดื้อที่ไม่เชื่อฟังวาจา และ\nตล เสตว์ร้ายที่ยากกําราบให้เชื่องได้ ออกอาละวาดในเส้นลมปราณอย่าง\nงาย ขณะที่ด่านเซวียซานที่เป็นจุดสะสมรวมกำลังพลันแตกระเบิด\nชั่วระยะเวลาอันกระชั้นสั้น ฟ่านเสียนบังเกิดความเจ็บปวดรวดร้าว\nกก่างที่ไม่เคยประสบมาก่อน เส้นประสาทความรู้สึกทั่วร่างคล้ายกับฉีกขาด\nง แหแท้น พลังลมปราณภายในกายก็ทะลวงผ่านเส้นลมปราณ เช่นฆ่าเข้าสู่\nากเงทายของมัน มลายหายไปในอวัยวะภายใน ไม่สามารถใช้ออกอีก\nเมื่อปราศจากพลังลมปราณ ฝ่ามือทั้งสองย่อมไร้เรี่ยวแรง\nเสียงซี่เบาๆ มีดสั้นสีเทาที่ไม่สามารถแทงถูกฟ่านเสียน กลับแทง\nไผ่หน้าอกของมันอย่างเหลือเชื่อ\nฟ่านเสียนคลายมือทั้งสอง มองดูหน้าอกตนเองพลันเพิ่มมีดสั้นเล่ม\nหนึ่งง มิหน้าซ้้าเพียงเห็นท่อนที่อยู่ทางข้างหลัง\nแม้กระทั่งฝ่ายตรงข้ามซึ่งเป็นสุดยอดนักฆ่าก็คล้ายตะลึงพรึงเพริด\nเหม่อมองดูมีดสั้นที่หน้าอกฟ่านเสียน ไม่ได้มีความเคลื่อนไหวสืบต่อ\nไม่ทราบผ่านไปนานเท่าใด อาการเจ็บปวดค่อยแล่นเข้าสู่สมองของ\nฟ่านเสียน ค่อยทราบว่าตนเองถูกแทงลึกยิ่ง เกรงว่าชีวิตน้อยๆ ต้องจบสิ้น\nใแตดรอกเล็กๆ ของโลกใบนี้อย่างเลอะเลือนงมงาย\nนี่ช่างไม่ยินยอมพร้อมใจนัก ยังมีเรื่องมากมายไม่ได้กระทํา ยัง\nไม่ได้ให้กําเนิดบุตรธิดา ความฝันในหอแดงยังคัดลอกไม่จบ ยังไม่ได้ดูแล\nท้องพระคลังซึ่งเป็นของเยี่ยชิงเหมย ยังไม่ได้เข้าสู่วิหารศักดิ์สิทธิ์ และยัง\nไม่ได้ยืนอยู่ในท้องพระโรงรัฐชิง เปิดเผยชาติกําเนิดของตนเองต่อผู้คน','2026-04-17 09:49:10'),(125,10,122,'ทั้งแผ่นดิน\nที่ไม่ยินยอมพร้อมใจที่สุดคือ คนตาบอด ท่านไฉนยังไม่มา?\n“เป็นอุบัติเหตุ”\nผูทกลาวคานออกมา นอกจากฟ่านเสียนที่ก่อนตายยังไม่ลืมเลีอกา\nโจวชิงฉือเมื่อชาติปางก่อนแล้ว ยังมีมือกระบีทีด้านตรงข้าม เพียงแต่ฟา\nเสียนกล่าวอย่างไม่ยินยอมพร้อมใจ ส่วนฝ่ายตรงข้ามกล่าวด้วยความ\nผิดหวัง\nในที่สุดมือกระบีนั้นคลายมือจากมีดสัน ฟ่านเสียนก็ล้มระทวยแง\nกับพืน\nเมื่อพยัคฆ์พิทักษ์ซึ่งเป็นทัพแกร่งของฮ่องเต้รัฐชิงรุดถึงตรอกตัน\nไม่ทันเข้าร่วมการต่อสู้ เพียงเห็นคนแต่งกายเช่นราษฎรทัวไปคนหนึ่งคลาก\nมือจากมีดสันทีปักอยู่ทีหน้าอกฟ่านเสียน จากนั้นกลายร่างเป็นเงาสีดําสาย\nหนึ่งพุ่งปราดไปยังผนั่งกําแพงทีท้ายตรอก\nส่วนใต้เท้าเสียวฟ่านที่ได้รับการกล่าวขานจากปากต่อปากว่าเป็นผู้\nเข้มแข็งอันยิงใหญ่ กลับล้มติงลงกับพืนราวกับปิศาจเมามายตนหนึ่ง\nในขบวนพยัคฆ์พิทักษ์มีคนขู่คํารามว่า “รีบตาม”\n“แบ่งกำลังออกไป ช่วยคนก่อน”\nผูนาขบวนพยคฒฆพทกษคอเกาตา มนมสหนาเครงเครยดถงทสุด\nนั่งยองๆ อยู่ข้างกายฟ่านเสียน มองดูขุนนางหนุ่มซึ่งนำตนเองเดินทางไป\nเชื่อมสัมพันธ์กับแคว้นเปียฉี บังเกิดความวิตกกังวลถึงขีดสุด\nไม่ทราบผ่านไปนานเท่าใด ภายในตรอกค่อยบังเกิดสุ้มเสียงหนึ่งดัง\nว่า “ยังไม่ตายหรอก”\nฟ่านเสียนแอบอิงกับอ้อมอกเกาตํา มองดูคราบสีแดงฉานที่หน้าอก\nกล่าวว่า “มีดแทงไม่ลึกพอ แต่ว่ารีบตามตัวหมอหลวง ไปทีบ้านขอยา','2026-04-17 09:49:10'),(126,10,123,'ขจัตพิษจากเม่ยเม่ยเรา ทั้งกราบทูลขอให้ฝ่าบาทเรียกตัวเฟยเจียกลับ\nแ ช่วยชีวิตน้อยๆ นี้\nกล่าวจบมันหลับตาลงสินสติไป แต่ว่าก่อนสลบไสล ยังใช้หางตา\nเหลือบมองกําแพงดินทีมือกระบีนั้นใช้หลบหนี้จากไป หลังจากทีมันรับ\nยุกติเหตุบาดเจ็บสาหัส ทําให้มันคาดเดาความเป็นมาของนักฆ่าที่น่ากลัว\nผู้กทอก แต่ว่าเรื่องนี้ซับซ้อนเกินไป น่ากลัวเกินไป น่ากลัวจนมันยินยอม\nปล่อยให้ตนเองสลบไสลไม่ได้สติ ไม่ต้องการครุ่นคิดถึงเรื่องนี้สืบไป','2026-04-17 09:49:10'),(127,10,124,'','2026-04-17 09:49:10'),(128,10,125,'หน้าต่างรถถูกลมโชยพัดพลิวขีน เผยเห็นสีสันของขุนเขาที่นอกรถ\nเว ๑ เว «๑.\nและทางศิลายาวเหยียดที่ถดถอยไปด้านหลัง คล้ายกับภาพที่ถอยกลับไป\nไม่หยุดยัง\nมุมหนึ่งของภาพเป็นแถบผ้าสีดําโชยพัดปลิว กลายเป็นประกาย\nสีตําเลือมพราย จนยืดครองพื้นที่ทั้งหมดไป\nต่อจากนั้นรูปภาพสว่างจ้า แสงสว่างพร่าพรายกลับกลายเป็น\nตลกไม้เล็กๆ ที่คุ้นตา เบ่งบานบนหน้าผาอ่าวต้านโจว ปรากฏมืออันหยาบ\nเจ้าน แต่ว่าอ่อนโยนข้างหนึ่งยืนมาปลิดไปช่อหนึ่ง\nดอกไม้ตากแดดตากลมบนดาดฟ้าของบ้านเรือนราษฎรจนแห้งสนิท\nกสมลงในน้ำชา เมื่อเทนำร้อนลงไป ก็กลายเป็นนำสีอําพัน ปรากฏมืออีก\nข้างหนึ่งยืนมา ยกถ้วยชาขีนวางลงตรงหน้า\nตงเอ๋อเจียเจีย (พีสาว) ซึ่งไม่พบหน้ามานานกล่าวว่า “เส้าแหย\n(นายน้อย) ดีมชาทีซือซือชงให้ลงไปเถอะ วันนี้เป็นวันแรกที่นางแต่งเข้า\nมันสันศีรษะ รับถ้วยชามาส่งไปยังอีกด้านหนึ่ง มองดูหลินว่านเอ้อ\nฑึงนั่งแทะน่องไก่ไม่หยุด กลาวตาหนวา \"ของมนเลยนยง ทานดมนาชา','2026-04-17 09:49:10'),(129,10,126,'กลัวคอ”\nหลินว่านเอฮ้อไม่ตอบคํา กลับเป็นเม่ยเม่ยซึ่งนั่งอยู่ทางขวามือขก\nตนเองหัวรอออกมา ที่หว่างคิวของนางปราศจากเค้าความวิตกกังวลยก\nสร้างความปลาบปลื้มประโลมใจแก่ตนเองยิง\nเ ณซ่ๆ ย ๕5๐ ข่ \'\nท่านอาอู่จู้ที่ใช้แถบผ้าสีดําปิดตาไว้กล่าวเสียงเย็นชาว่า “สมควรไ\n“ไปหาคุณหนู”\nตนเองรับคํา ผุดลุกขืนเดินไปหยิบฉวยสัมภาระที่ข้างเตียง ยังมีหี1\nสีดําใบหนึ่ง แต่ไม่ทราบเพราะเหตุใด หีบในวันนี่หนักอิ่งเป็นพิเศษ ไม่ว่า\nอย่างไรก็ยกไม่ขึ้น เป็นเหตุให้ตนเองหลังเหงือโซมหน้า\nหยาดเหงือเม็ดหนึ่งไหลลงจากหน้าผากของฟ่านเสียนที่สลบไสล\nหยดลงบนหมอนหนุน มันเปิดเปลือกตาอย่างงุนงง มองดูชายคาข้างบน\nทีหลากสีสัน ทราบว่าตนเองอยู่ในห้องหับทีไม่คุ้นเคยห้องหนึ่ง ต้องสะท้าน\nขืนคราหนึ่ง ครุ่นคิดขึ้น ย้อนเวลาอีกหรือ?\nหากว่าตายหนึ่งครั้งต้องย้อนเวลาหนึ่งครา ฟ่านเสียนยินยอมให้\nครั้งก่อนตนเองตายสนิท ไม่ต้องเกิดใหม่อีก จนพบกับผู้คนบางคน ประสบ\nเรื่องบางประการ บังเกิดเป็นความผูกพัน ทั้งไม่อาจหักใจ แต่ก็ต้องจากมา\nในที่สุดสายตาทีแตกซ่านของฟ่านเสียนค่อยปรับเข้ากับแสงสว่าง\nในห้อง ค้นพบจุดจู่เจียว ดุจเดียวกับเด็กทารก และเห็นชัดตาว่าหลินว่าน\nเอืออยู่ข้างกายตนเอง รําไห้จนสองตาบวมแดง ยืดจับมุมผ้าปูทีนอนไว้\nขบริมฝีปากล่าง ไม่ยอมส่งเสียงออกมา\nดูทาตนเองยงมชวตอยู่ ยังอยู่ในโลกของรัฐชิง เพียงไม่ทราบว่า\nณี่ จคไฟกัส','2026-04-17 09:49:10'),(130,10,127,'ต1แกงนอนอยู่ที่ใด\nฟ่านเสียนก้มศีรษะยากลําบากอยู่บ้าง จากอาการเจ็บปวดที่หน้าอก\nทฯ \"เว่าอาการบาดเจ็บของตนเองยังไม่หายดี ยามนิภายในห้องมีแต่ขันที\nณ ๕ สซ่ ม๓\nทีหลุบคิวกัมสายตา แสร้งเป็นสาละวนและเศร้าโศกศัลย์ ที่หน้าประตู\nปวากฎชซายชราสวมชุดหมอหลวงกลุ่มหนึ่งกล่าวกับบุรุษกลางคนผู้หนึ่งว่า\n\"ฝาบาท เฉินทั้งหลายอับจนปัญญาจริงๆ”\nบุรุษกลางคนนั้นตรัสด้วยความกวรีวว่า “หากมันไม่รอด พวกเจ้าต้อง\nาว่วมแกลบฝผัง”\nฟ่านเสียนที่ยังอยู่ในภาวะสลบไสลพอเห็นฉากนี้ อดแค่นหัวร่อมิได้\nแต่ง่ามูมปากมันไม่เชือฟังคําสังของสมองใหญ่ เพียงเชิดขึ้นเล็กน้อย\nฟ่านเสียนครุ่นคิด นิเป็นถ้อยคําทีได้ยินจนคุ้นหู แต่ว่าฮ่องเต้ท่าน\nวกจงนเราใกล้ตายค่อยอาละวาดออกมา ดูเหมือนไม่ได้มีเมตตากรุณา หาก\nเฟ่รียบกับฉากเบื่องหน้า ฟ่านเสียนยังต้องการเห็นพระกํากับดูแลทักษิณ\nทเป็นบิดาขู่คํารามใส่คณะหมอหลวงมากกว่า\n๑ สฆ่ ส \' . เท เซฆ ข่\nมันคิดยืนมือตบหลังมือของว่านเอ้อ แต่ไม่มีเรียวแรงขยับเขยือน\nว่างกายไม่มีส่วนใดไม่เจ็บปวด ไม่มีส่วนใดไม่เวิงว่างเปล่า ขณะจะสงบจิต\nสงบใจ สมองพลันลันอึงอล สินสติไปอีกครา\nขณะทีฟ่านเสียนวิพากษ์วิจารณ์ฮ่องเต้ คิดปลอบโยนบิดา มหานคร\nเล้บปันป่วนแทบถล่มทลาย\nฮ่องเต้ถูกประทูษร้าย\nเรื่องราวไม่สามารถตบตาผู้คนทั้งแผ่นดิน ยามสนธยามีคนจํานวน\nมากล่วงรู้เรื่องนี่ แต่ทีสร้างความยินดีแก่ราษฎรคือ ฮ่องเต้ไม่ได้รับบาดเจ็บ\nแต่อย่างไร\nแต่หลังจากนั้นไม่นาน มีข่าวว่าใต้เท้าเสียวฟ่านอารักขาเจ้าชีวิต','2026-04-17 09:49:10'),(131,10,128,'ลงมืออย่างอาจหาญ ขจัดบัดเป่าเภทภัยครั้งนี้ หลังจากนั้นไม่คํานา\nซีต ษาพ ง ย .\nสภาพหลังฟื้นไข้ ไล่กวดตามคนร้ายจากวิหารฮุ่ยคงถึงมหานคร\nล้มลงสินสติสมประดี ได้รับบาดเจ็บสาหัส ไม่ทราบสามารถมีชีวิตรอดผ่า\nหรือไม่\nฟ่านเสียนมีชือเสียงอันดีในรัฐชิง ชาวมหานครพอทราบข่าว\nจํานวนมากถือชามข้าวแสดงความวิตกกังวล ทั้งนึกอํานวยพร พเพบ!\nกลางคืนก็ถือโคมไปยังวัดวาอาราม บนบานศาลกล่าวขอให้ปลอดภัย\nแ เว ฉ่ ซ\nตึกตระกูลฟ่านที่ตัวเมืองด้านใต้จุดโคมริบหรื บรรยากาศเค !\nหม่นหมอง บรรดาบ่าวไพร่รอฟังข่าวคราวอย่างร้อนรุ่ม หลังจากที่ฟ่า\nเสียนรับบาดเจ็บ เหล่าพยัคฆฒ์พิทักษ์ก็ส่งตัวเข้าวัง ฮ่องเต้พอเสด็จกลง\nมหานครก็ทรงรังตัวฟ่านเสียนอยู่ในวัง รับสังให้คณะหมอหลวงเฝ้าดูอายา,\nอย่างใกล้ชิด\nผู้คนเบื่องสูงเบืองตําของตึกตระกูลฟ่านเห็นว่า การแสดงออกข๓\nฮ่องเต้ชอบด้วยเหตุผล ตอนนี้เส้าไหน่ไหน กับคุณหนูเดินทางเข้าวังแฉล้.\nยังไม่ได้ส่งข่าวมา แต่ฟังว่าต้าเส้าแหยถูกแทงใส่มีดหนึ่ง อาการหนักหน\nสาหัส คณะหมอหลวงยังไม่มีวิธีรักษา\nทีเหนือความคาดหมายผู้คนคือ พระกํากับดูแลทักษิณฟ่านเจียน\nไม่ได้เดินทางเข้าวัง หากนั่งจับเจ่าอยู่ในห้องหนังสือด้วยสีหน้าหมองคลํ\'\nไม่ทราบครุ่นคิดอันใด\nเมื่อเกิดเรื่องใหญ่เช่นนี้ เฉินผิงผิงย่อมไม่อาจชมการระบํารําฟ้อนท\nสวนอุทยานเฉินทีชานเมืองอีกต่อไป มันนั่งเก้าอิล้อเลือนกลับสำนักตรวจ\nสอบ เริมไต่สวนเหตุการณ์ปลงพระชนม์ ทั้งรับมอบตัวขันทีน้อยทีถูกจับ\nเป็น และรับศพของคนร้ายชันทีเก้ามา\nจงอองเดนทางเขาวงแลว โหยวเจียจวินจู่ขังตัวเองอยู่ในห้องเอาแต่\nคําเรียกภรรยาของเส้าแหย','2026-04-17 09:49:10'),(132,10,129,'ไนมหานครไม่ทราบมีหญิงสาวเศร้าเสียใจมากน้อยเท่าใด\nองค์ชายรองปิดประตูวัง สังห้ามมิให้ผู้ใดออกสืบข่าว หรือแสดง\nปฏิกิจยาใด มันทราบว่าตอนนี้ตนเองตกอยู่ในสถานการณ์ล่อแหลม ในช่วง\nเเผาที่เกิดเรื่องเกิดราวเซ่นนี้ ความเคลื่อนไหวทีไม่เหมาะสม จะนำมาซึ่ง\nพิกิตภัยแก่ตนเอง\nองค์ชายใหญ่เฝ้าอยู่ที่หน้าตําหนักกว่างซินที่ฟ่านเสียนพักรักษาตัว\nเต๋แพล่านไปมาไม่หยุดยัง\nอกุ้ยผิงก็นำองค์ชายสามยืนอยู่หน้าตําหนักกว่างซิน ชีวิตน้อยๆ ของ\nกงค์ชายสามเป็นฟ่านเสียนช่วยเหลือไว้ อย่าเพิงบอกว่าอีกุ้ยผิงเกี่ยวดอง\nกบตระกูลฟ่าน นางในฐานะสตรีในวังทราบว่าฮ่องเต้ที่กริวจะแสดงออก\nแพ่างไร ตัวเองสมควรแสดงท่าทีอย่างไร\nฮองเฮาไม่ได้เสด็จมา ไทจือแห่งวังตะวันออกเพียงแสดงความ\nกล่าวปลอบโยนว่านเอ้อกับเย่อเย่อ ทั้งกราบทูลขอให้ฮ่องเต้ถนอม\nพฯะวรกาย จากนั้นกลับวังตะวันออก\nมีข่าวว่าฮองไทเฮาเพียงส่งหงกงกงมาดูอาการ แต่พระนางสวดมนต์\nขคพรในห้องพระหลังตําหนักหานกวง\nข่าวฟ่านเสียนรับบาดเจ็บสาหัสใกล้ตาย ทําให้ขุมกำลังกลุ่มต่างๆ\nไนราชสำนักชิงแสดงปฏิกิริยาที่สอดคล้องกับความเป็นจริง ดูเหมือนเหลว\nไหลแต่น่ารักอยู่บ้าง\nที่ผ่านมาตําหนักกว่างซินเป็นที่อยู่ของจ่างกงจู่ และเป็นที่ซึ่งฟ่าน\nเสียนเคยลอบเข้ามา แต่ว่ามันไม่ได้หยุดยังอยู่ในตําหนักบรรทม ดังนั้น\n\'พวิบตาทีฟันคืนสติมา จึงจดจําไม่ออกว่าตนเองนอนอยู่ในวัง','2026-04-17 09:49:10'),(133,10,130,'งแม้ว่าเพราะฮ่องเต๋้ ฟ่านเสียนจึงรับบาดเจ็บสาหัส แตขาเ\nผู้หนึ่งถูกรังตัวรักษาบาดเจ็บในวัง ถึงอย่างไรขัดกับประเพณีปฏิบัติ\nยังมีศักดิฐานะอีกประการหนึ่ง เป็นราชบุตรเขยของจ่าง กงจู่\nเสียงแอ๊ดคราหนึ่ง ประตูตําหนักกว่างซินถูกผลักเปิดออก ฮีเห\nสาวพระบาทเข้ามาด้วยพระพักตร์เคร่งเครียด ทอดพระเนตรฟ่านเย่แก่\nทีนำตาคลอเบ้าแวบหนึ่ง หว่างกลางพระขนงทอแววอิดโรยอยู่บ้าง\nเหยากงกงกล่าวเสียงสันสะท้านว่า “ฝ่าบาท พระองค์ไปพักผ่อนกอน\nเถอะ ใต้เท้าเสียวฟ่านทีนี้มีหมอหลวงดูแลรักษา สมควรไม่เป็นไร\nพระเนตรฮ่องเต้ทอประกายเย็นเยียบวูบหนึ่ง ตรัสว่า “ล้วนเป็นค\nใช้การไม่ได้ ”\nฟ่านเย่อเย่อสงบสติอารมณ์ ถวายบังคมฮ่องเต้กล่าวว่า “ฝ่าบาท\nข้าพเจ้าคิดเข้าไปชมดู แต่ว่า หมอหลวงไม่อนุญาตข้าพเจ้าเข้าไป”\nฮ่องเต้ขมวดพระขนง ตรัสว่า “เพราะเหตุใด?” พระองค์สังเกตพ1!\nว่า ที่แทบเท้าคุณหนูฟ่านวางกล่องธรรมดาใบหนึ่ง\nฟ่านเย่อเย่อขบริมฝีปากกล่าวว่า “เกอเกอ (พีชาย)\nมา แต่พยัคฆ์พิทักษ์บอกให้ข้าพเจ้านำยาขจัดพิษทีมันใช้เป็นประจํามา\nคาดว่าเป็นคํากล่าวก่อนสินสติ แต่ว่าหมอหลวงไม่ เชือคําพูดข้าพเจ้า”\nฮ่องเต้ประทับยืนบนบันได การรักษาของหมอหลวงย่อมมีขันตอน\nของตนเอง ทีปฏิเสธตัวยาของฟ่านเย่อเย่อเป็นเรื่องปรกติ แต่ฮ่องเต้ใน\nยามนี้ต่างกับทีผ่านมา นี้เป็นครั้งแรกทีพระองค์ทรงพบว่า ในราชโอรส\nม ! ซ่ เข ! ซ่ เข \'\nทั้งหลาย มีแต่คนทีอยู่ข้างในจึงใช้การได้ และมีแต่คนที่อยู่ข้างในจึงไม่\nนึกถึงตําแหน่งของพระองค์\nบนวิหารฮุ่ยคง ในห้วงคับขันจวนเจียน หากว่าทางเลือกของฟ่าน\nเสียนคือช่วยเหลือฮ่องเต้อย่างไม่คิดชีวิต เกรงว่าฮ่องเต้จะทรงนึกระแวง\nสงสัยฟ่านเสียน เนื่องเพราะความเคลื่อนไหวของมันเป็นการแสดงความ','2026-04-17 09:49:10'),(134,10,131,'สูงจก่เเต่ต่อเจ้าชีวิต สำหรับกับฮ่องเต้ที่ครองบัลลังก์ จะไม่ทรงเชือความ\nลูจใบเด่ที่เห็นจากภายนอก\nแต่ปัญหาอยู่ที่ฟ่านเสียนเลือกช่วยเหลือองค์ชายสามก่อน\nหากสืบสาวราวเรื่อง ตึกตูฉาเอียนอาจอาศัยข้อปลีกย่อยนึกล่าวโทษ\nฝ่ แผียนทรยศเนรคุณ แต่ว่าฮ่องเต้มิใช่บุคคลทัวไป พระองค์อาศัยข้อ\nปฝี(เท่ายนี้ เห็นซึ่งถึงจิตใจอันดีงามเมตตา คล้ายกับสตรีเมื่อครั้งกระโน้น\nวพี ข่ ณ์ ง! 2 เ 1 ๕43\nที่น่าหัวร่อคือ ตอนนั้นฟ่านเสียนไม่ได้นึกเช่นนี้ ปัญหาอยู่ที่ฮ่องเต้\nไม่ทวงทราบ\nดังนั้นฮ่องเต้ปลื่มพระทัยยิง\nหลังจากที่ทรงทราบว่าฟ่านเสียนรับบาดเจ็บสาหัสปางตาย พระทัย\nของพระองค์ค่อยเกิดความหวันไหวขึ้นมา ถึงกับทรงนึกสงสัยว่าพระองค์\nไข่บําค้นฟ่านเสียนไปจนสุดโต่งหรือไม่ พระองค์ยังทรงอิจฉาพระกํากับ\nตุแลทักษิณอย่างไว้เหตุผล ทรงดําริว่าคนหนุ่มทีโดดเด่นเช่นนี้ไฉนถูกยืดถือ\nเป็นบุตรชายของท่าน?\nพระองค์มีราชโอรสกีองค์ เหล่าต้า (อันดับหนึ่ง) เทียงตรงเกินไป\nเหล่าเอ้อ (อันดับสอง) จอมปลอมเกินไป เหล่าซัน (อันดับสาม อายุเยาว์\nเกินไป สำหรับไทจือ ฮ่องเต้ทรงดําริในพระทัย เจ้าเข้าใจว่าข้าไม่เห็นเจ้า\nงงใจเหยียบถูกจอกสุราใบนั้นหรือ?\nดังนั้นพระองค์รังฟ่านเสียนอยู่ในวัง ทางหนึ่งเพื่อเร่งช่วยชีวิตฟ่าน\nเสียน อีกทางหนึ่งเกิดจากความรู้สึกด้านลับของบูรุษกลางคนผู้หนึ่ง พระ\nกํากับดูแลทักษิณทีเติบโตขึ้นมาพร้อมกับพระองค์ อาจล่วงรู้พระทัยของ\n\' ฆ เว3ณ «ป ซ ๓« เทย\nฮ่องเต้เป็นอย่างดี ดังนั้นในเวลาทีบุตรชายรับบาดเจ็บสาหัส มันไม่ได้เข้า\nเพียงขังตัวเองอยู่ในห้องหนังสือตึกตระกูลฟ่าน','2026-04-17 09:49:10'),(135,10,132,'ฮ่องเต้มีพระราชกระแส หมอหลวงจึงเดินออกจากประตูตําหาน\nกราบทูลว่า “ฝ่าบาท ห้ามเลือดได้แล้ว แต่ว่ามีดเล่มนั้นทําร้ายถึงอาก )\nภายในของใต้เท้าฟ่าน”\nฮ่องเต้ทรงบุ้ยพระโอษฐ์ไปที่ฟ่านเย่อเย่อตรัสถามว่า “ไฉนไม่ไห้\nคุณหนูฟ่านเข้าตําหนัก?”\nถึงแม้ว่ายามนิหมอหลวงยังไม่ลืมปกป้องความเป็นมืออาทฑา1\nของตนเอง กล่าวว่า “ยาเม็ดเหล่านั้นไม่ทราบมีส่วนผสมอันใด มีดขา\nคนร้ายฉาบพิษไว้ แต่ยังจําแนกพิษไม่ออก ดังนั้นไม่กล้าให้รับประทา\nกลัวว่า ”\nจึงอ้องซึ่งนั่งอยู่บนเก้าอิเชิงบันไดพลันกระโดดปราดขีนมา ขูคาราย\nว่า “กลัวอุบาทว์อันใด?” พลางตบหน้าหมอหลวงนั้นฉาดใหญ่ด่าทอว่า\n“บิดาให้เวลาเจ้าสองชั่วยาม อย่าว่าแต่ช่วยชีวิตคน อย่างน้อยต้องแก้ไข\nฟ่านเสียนฟินคืนสติมา ขอเพียงมันฟืนคืนสติ ด้วยวิชาแพทย์ของมัน ยัง\nน่าเชือถือกว่าเฒ่าโสโครกท่านอีก\nหมอหลวงถูกตบหน้าจนหัวหมุนงุนงง ต้องบันดาลโทสะจนไม่อาจ\nกล่าววาจาใดได้\nฮ่องเต้ขณะจะรับสังตําหนิจิงอ้องลงไม้ลงมือ แต่พอสดับวาจาเหล่า\nนั้น ทรงดําริว่ามีเหตุผล หากว่าเพยเจียไม่อยู่ในวัง เอ่ยถึงการขจัดพิษรักษา\nบาดเจ็บ เกรงว่าไม่มีผู้ใดเหนือกว่าฟ่านเสียน จึงรับสังว่า “ไม่ว่าอย่างไร\nให้หาทางแก้ไขฟ่านเสียนฟื้นคืนสติมา”\nหลังจากรับสังออกไป ค่อยพบว่าฟ่านเสียนรอบรู้สารพัน หากมิใช่\nเป็นห่วงพระองค์กับราชโอรสทั้งหลายถูกควันพิษมอมทําร้าย ทึ่งถุงยาเอา\nไว้ ต่อให้มันถูกมีดสันอาบยาพิษของคนร้ายทําร้าย คงไม่มีสภาพเช่นนี้\nเมื่อทรงดําริถึงข้อดีของฟ่านเสียน พระองค์ต้องลอบทอดถอนพระทัย ทรง\nดําริในพระทัย หากว่ามารดาของเด็กผู้นี่ มิใช่นาง ไม่ทราบประเสริฐ','2026-04-17 09:49:10'),(136,10,133,'เผียงไหน\nท่องเต้สันพระเศียร เสด็จกลับห้องทรงพระอักษร โดยมีขันทีทั้ง\nเน เทตามเสด็จ\nจิ้งอ้องได้รับพระราชกระแส จึงเดินนำฟ่านเย่อเย่อ ยกมือผลักราช\n\" พรักษ์ที่เฝ้าอยู่หน้าประตูวัวหนัก ไม่สนใจคําทัดทานของคณะหมอหลวง\nนุทจุน็งข้างเตียง\nหลินว่านเอ้อสองตาบวมแดง เพียงกุมมือทีเย็นเฉียบของฟ่าน\nเฟ่ยน เหม่อมองใบหน้าที่ขาวซีดของมัน คล้ายไม่รู้สึกตัวว่ามีคนมาถึงด้าน\nหลงตัวเอง\nฟ่านเย่อเย่อเห็นเช่นนั้นบังเกิดความเศร้าโศก จากนั้นแปลงเป็น\nพงามเข้มแข็ง นางเชือว่าเกอเกอทีเก่งกล้าสามารถของตัวเองต้องไม่ตาย\nไหล้กษณะนี้\nจึงอ้องในวันนี้ไม่คล้ายเป็นคนสวนเพาะต้นกล้า หากคล้ายแม่ทัพ\nไหญ่กลางสมรภูมิ กล่าวว่า “แก้ไขมันฟื้นคืนสติมา หากว่ารับประทานยา\nไม่ม์ประโยชน์ เราจะฟันนิวมือของมันออกมานิวหนึ่ง”\nฟ่านเย่อเย่อคล้ายไม่ได้ยินคําพูดนี้ หากเปิดกล่องหยิบตลับไม้ใหญ่\nน้กยออกมาหลายใบ\nจึงอ้องกล่าวว่า “เจ้าทราบว่า สมควรรับประทานชนิดใด?”\nมันมิอาจไม่รอบคอบ จะอย่างไรหมอหลวงกล่าวมีเหตุผลอยู่บ้าง\nหาเกว่ารับประทานยาผิด แม้แต่ภูตผียังทราบว่าจะเกิดผลอย่างไร ไม่แน่ว่า\nฟ่านเสียนที่หลงเหลือลมหายใจร่อแร่รวยรินจะจบสินอวสานในลักษณะนี้\nฟ่านเย่อเย่อผงกศีรษะรับ ล้วงหยิบยาเม็ดสีเหลืองอ่อนจากในตลับ\nไม้เม็ดหนึ่ง ยาเม็ดส่งกลินเผ็ดร้อนชนิดหนึ่ง\nนางยืนส่งยาเม็ดถึงมือเส้าจือ (พีสะใภ้) หญิงสาวทั้งสองล้วนเป็นคน\nเฉลี่ยวฉลาด หลินว่านเอ้อมือสันสะท้าน จากนั้นไม่ถามแม้สักคําเดียว','2026-04-17 09:49:10'),(137,10,134,'ยาเม็ดส่งเข้าปากขบเคี่ยวจนแหลก จากนั้นรับนำอุ่นที่ขันทียืนส่งมาต่า\nหนึ่ง ช่วยให้ตัวยาในปากละลาย\nคณะหมอหลวงทีห้อมล้อมมุงดูอยู่ด้านข้างทราบว่าหญิงสาวทั้งเย\nตระเตรียมใช้วิธีกรอกยา จะอย่างไรตนเองไม่สามารถขัดขวางได้\nหลวงผู้หนึ่งจึงสะอีกเข้ามา ใช้เครื่องมือที่ทําจากไม้งจ้างปากของฟเแ\nเสียนออก\nหลินว่านเอ้อก้มศีรษะลง ป้อนตัวยาเข้าปากฟ่านเสียน\nจึงอ๋องทีชมดูอยู่ด้านข้างพลันยืนฝ่ามือข้างหนึ่งออกตบหน้าแบ!\nฟ่านเสียน จากนั้นเลือนตําลง\nต่อจากนั้นทั้งหมดเฝ้ารอด้วยความตื่นเต้นตึงเครียด\nไม่ทราบผ่านไปนานเท่าใด ขนตาทึ่งอนยาวของฟ่านเสียนเต้นระ1\nคราหนึ่ง แล้วลืมตาขึีนมา เพียงแต่ประกายตาแตกซ่านอยู่บ้าง\nใต้เท้าฟ่านฟื้นแล้ว\nขันทีผู้หนึ่งส่งเสียงรําร้อง วิงออกจากตําหนักไปกราบทูลฮ่องเต้ ทั้ง\nภายในและภายนอกตําหนักคึกคักขึ้นมา\nฟ่านเสียนพอพื้นคืนสติมา ความคิดประการแรกคือ คงมีคน\nจํานวนมากเกิดความผิดหวังกระมฆัง?\nต่อจากนั้นมองดูใบหน้าอันคุ้นเคยทีข้างกายหลายหน้า ซึ่งทั้ง\nตื่นเต้น ยินดี แฝงความเศร้าโศก กล่าวเบาๆ ว่า “หมอนหนุน”\nหลินว่านเอ้อกําหมัดทั้งสอง เม้มริมฝีปาก คล้ายตื่นเต้นจนพูดไม่\nออก ได้แต่หยิบหมอนใบหนึ่งหนุนทีต้นคอของมัน ทราบว่าเซียงกงต้องการ\nตูอาการบาดเจ็บที่หน้าอกตนเอง จึงหนุนหมอนอีกใบหนึ่ง ให้ศีรษะของมัน\nหนุนสูงกว่านี้\nฟ่านเย่อเย่อเคลือนย้ายเชิงเทียนที่สว่างไสวมาอันหนึ่ง ส่องเห็น','2026-04-17 09:49:10'),(138,10,135,'หย้ แหาทีน่ากลัวของมัน\nฟ่านเสียนหลับตาลง ให้ฤทธิยาทีเผ็ดร้อนค่อยๆ แผ่ซ่านภายในกาย\nเผ็ยพลังชีวิตทีห่อเหียวของตนเอง แล้วค่อยๆ ลืมตาขึ้นช้าๆ มองไปที\nหน้หาดตนเอง\nปากแผลไม่ลึกนัก ทั้งอยู่ในตําแหน่งเยื่องเฉียงตําลง ดูเหมือนเป็น\nหนแหา แท้จริงแล้วสมควรอยู่เหนือกระเพาะ คณะหมอหลวงดูแลบาดแผล\nย เพแอกเป็นอย่างดี ไม่อาจค่อนแคะตําหนิได้\nแต่ฟ่านเสียนทราบว่ากระเพาะสมควรถูกทิมแทงเป็นบาดแผล ยัง\nฝีเม็กตไหลออกมา พลังลมปราณของตนเองแตกซ่านสลายสิน ไม่อาจโคจร\nพยงจักษาตัวเอง หากว่ายังเลือดออกต่อไป คาดว่าตนเองไม่อาจผ่านพัน\nด้วยเกณฑ์มาตรฐานทางการแพทย์ของโลกใบนี่ ไม่มีปัญญารักษา\nก กรบาดเจ็บของอวัยวะภายใน จึงไม่อาจโทษว่าหมอหลวงได้\nด้วยกำลังวังชาของฟ่านเสียน ได้แต่ออกคําสังสันๆ ว่า “เช็ดทิง”\nฟ่านเย่อเย่อไม่ขบคิดใคร่ครวญ หยิบผ้าหยาบที่ผ่านการต้มมาเช็ด\nย ผงที่หน้าอกฟ่านเสียนจนหมดสิ่น เป็นเหตุให้คณะหมอหลวงที่ชมดูอยู่\nต้านข้างร้องอุทานออกมา\nจริงดังคาดหมาย ปากแผลที่ทรวงอกมีโลหิตไหลซึมออกมาอีก\nฟ่านเสียนเปล่งคําพูดอีกคําหนึ่งว่า “เข็ม” พลางฝืนใจยืนมือที\nเคลื่อนไหวได้เกาะกุมมือที่เย็นเฉียบและสันระริกของภรรยาไว้\nฟ่านเย่อเย่อหยิบเข็มยาวมาหลายเล่ม ฟ่านเสียนกลอกตาไปยัง\nจงอองทดานขาง กลาววา จุดเทยนถู ฉเหมน อวิผู่ กวนหยวน แทงเขม\nเข้าไปสองหุน”\nการผังเข็มต้องใช้พลังลมปราณ ทขางกายมนตอนนคลายมแต\nจงอ้องมีความสามารถเชนนี้ ฟ่านเสียนหลังจากฟืนคืนสติมา ทราบว่า\nฝ่ามือทีหนุนส่งฤทธิยาผ่านทรวงอกถึงท้องน้อย แฝงพลังลมปราณอัน','2026-04-17 09:49:10'),(139,10,136,'แกรงกร้าวทีผ่านการฝึกปรอมานานนิี\nจึงอ้องงงงันวูบ คล้ายนึกไม่ถึงว่าตนเองกลับกลายเป็นหมอวบนก\nจึงรับเข็มยาวทีเล็กละเอียดมา ปักใส่จุดเส้นตามที่ฟ่านเสียนบ่งชี\nเข็มยาวพอแทงใส่ร่าง โลหิตก็หยุดไหล คณะหมอหลวงรอบข้างค1\nปากอ้าตาค้าง แทบไม่เชือสายตาตนเอง\nฟ่านเสียนกล่าวเสียงอ่อนล้าต่อจิงอ้องว่า “ตึกที่สาม”\nจึงอ้องเข้าใจในบัดดล ตึกทีสามสำนักตรวจสอบค้นคว้าพิษสะกดพิน\nตนเองกับฮ่องเต้ยามว้าวุ่นจิตใจสับสน กลับลืมเบิกตัวพวกมันเข้าวังมาขา๓\nพิษให้กับฟ่านเสียน จึงรีบออกจากตําหนัก ให้ผู้คนตามตัวหัวหน้าตึกทีสาง!\nกับเจ้าหน้าทีทีเกียวข้องเข้าวังมาขจัดพิษรักษาคน\nมิคาดคนของตึกทีสามมารอที่หน้าวังหลวงตั้งแต่แรก หัวหน้าตึกพ่\nสามยังกราบทูลขอเข้าวังไปช่วยเหลือฟ่านเสียน แต่ว่าคืนนี้ในวังชุลมูแ\nหัวหน้าราชองครักษ์หลายนายถูกสำนักตรวจสอบเชิญตัวไป\nสอบสวน กลับไม่มีผู้ใดกล้ากราบทูลฮ่องเต้ ย่อมไม่มีคนปล่อยให้พวกมัน\nเขาวง\nยามนี้จิงอ้องออกคําสังแทนฮ่องเต้ คนของสำนักตรวจสอบค่อย\nระบายลมหายใจโล่งอก เดินทางเข้าวัง รุดถึงตําหนักกว่างซิน คนของตึก\nที่สามยังหอบสิงของมาด้วย บังเกิดเสียงดังตึงตั้ง คล้ายเป็นวัตถุโลหะ ฟ่าน\nเสียนบนเตียงพอฟัง ดูเหมือนได้สดับดุริยทิพย์ก็มิปาน\nหัวหน้าตึกที่สามเป็นศิษย์ของเพยเจีย จึงมีศักดิเป็นศิษย์พีของฟ่าน\nเสียน สนิทสนมกับฟ่านเสียนเป็นอย่างดี ยามนี้เห็นศิษย์น้องนอนแน่นิง\nบนเตียง ต้องหน้าหมองคลําลง เดินถึงข้างกายฟ่านเสียน ใช้นิวมือนิวหนึ่ง\nแตะตรวจข้อมือของมัน\nทุกผู้คนรวมทั้งหมอหลวง ต่างจับจ้องมองมันเป็นจุดเดียว','2026-04-17 09:49:10'),(140,10,137,'หัวหน้าตึกที่สามค่อยผงกศีรษะ กล่าวกับฟ่านเสียนว่า\n\"แ แว่เตของซือตี (ศิษย์น้อง) ใช้ได้ผลดี แต่ว่าพิษชนิดนี้มาจากสายนคร\nตาก ลคงใช้ตัวยาที่ทางสำนักจัดเตรียมไว้\nฟ่านเสียนฉุกใจคิด รับประทานยาตามคําแนะนำของมัน ไม่ทราบ\nเป็นพลทางจิตวิทยาหรือไม่ รู้สึกคึกคักแจ่มใสขืน\nไนโลกมีปรมาจารย์ใช้พิษสามท่าน หนึ่งคือเฟยเจีย สองคือเซียว\nเก๊น จ่วนอีกท่านหนึ่งเป็นตัวประหลาดนครตงอื ในปรมาจารย์ทั้งสาม เฟย\nเจพศกษาอย่างกว้างขวาง จึงมีฝีมือสูงเยียมที่สุด แต่ปรมาจารย์ใช้พิษเลือก\nหุและวิธีการผสมพิษผิดแผกแตกต่าง ยกตัวอย่างเซียวเอินเน้นที่ไขมัน\nแผะต่อมในตัวสัตว์ เฟยเจียเน็นทีต้นพืชยางไม้ พลอยส่งผลต่อฟ่านเสียน\nฯเไจทีพิษทีฉาบบนมีดสันของคนร้าย กลับเป็นแร่พิษดินประสิว สำนักทั้ง\nสทงมีรูปแบบที่แตกต่าง คิดขจัดพิษจึงยุ่งยากอยู่บ้าง ในสำนักไหนเลย\nเตรียมยาขจัดพิษไว้ล่วงหน้า?\nดังนั้นฟ่านเสียนทราบว่ายาเม็ดนิมคนแอบอ้างช้อของศิษย์พี ส่งเข้\nงงมาขจัดพิษให้กับตนเอง แต่ว่าศิษย์พีที่หมกมุ่นกับการค้นคว้าพิษ จน\nขาตสมองความคิดไปบ้าง แสดงว่าไม่ได้นึกถึงข้อนี้\nพิษร้ายค่อยสลายไปทีละน้อย ทีเหลือคืออาการบาดเจ็บของอวัยวะ\nภายใน คณะหมอหลวงเห็นฝีมือขจัดพิษของสำนักตรวจสอบ บังเกิดความ\nเลื่อมใสอยู่บ้าง แต่ยังเกิดความสงสัยอยากรู้ว่า ฟ่านถีซือกับตึกที่สาม\nเตรียมจัดการกับปากแผลบนร่างอย่างไร\nหัวหน้าตึกทีสามกล่าวว่า “ซือติ ก่อนนี้ท่านให้ทางตึกจัดเตรียม\nเครื่องมือชุดนั้น เรายังนำมาแล้ว ไม่ทราบใช้อย่างไร?” ฟังจากนำเสียงมัน\nตัวมันคล้ายไม่ล่วงรู้ประสิทธิผลของวัตถุเหล่านั้น\nฟ่านเสียนมองดูปากแผลโลหิตที่หน้าอกด้านล่างของตนเอง หอบ\nหายใจกล่าวว่า “ข้าพเจ้าต้องการคนทีขวัญกล้าเป็นพิเศษ และต้องการ','2026-04-17 09:49:10'),(141,10,138,'คนทมมอทิมันคงเป็นพิเศษ\nหัวหน้าตึกที่สามคลูกคลีอยู่กับวัตถุพิษและคนตาย ไม่ทราบเห้เ\nเหตุการณ์แหวะอกผ่าท้องมากีปี ย่อมมีขวัญกล้าแข็งพอ ส่วนคนทีมีมือท่\nมันคง คนของตึกที่สามสมควรรับหน้าทีนี้ได้\nแต่ว่าฟ่านเย่อเย่อยืนอยู่หน้าเตียงกล่าวอย่างเด็ดเดียวว่า “','2026-04-17 09:49:10'),(142,10,139,'ผ่าทัตไต๊กสนโหม\nฟ่านเสียนนอนอยู่บนเดียง ความคิดประการแรกคือคัดค้าน หนึ่งนั้น\nมันเองไม่มีความเชือมันต่อการเย็บแผลเท่าใด สองมันไม่อาจหักใจให้เม่ย\nง ฆ ซ่ ซู ร\nเม่ยที่มีนิสัยรักความสะอาดเฝ้ามองหน้าอกที่กลายเป็นเลือดเนื่อเลอะเลือน\nอย่าว่าแต่อีกสักครู่ยังต้องยืนมือสัมผัส\nฟ่านเสียนกล่าวเสียงแหบพวร่าว่า “ว่านเอ้๋อ ท่านออกไป นำเม่ย\nเม่ยออกไปด้วย”\nหลินว่านเอ้อไม่เอ่ยปาก เพียงสันศีรษะคราหนึ่ง ฟ่านเย่อเย่อก็กล่าว\n‘ น ฆ ขุณฒ สม\nกย่างยืนกรานว่า “ข้าพเจ้ามีมือทีมันคง\nทั้งหมดรวมทั้งหัวหน้าตึกที่สามพอฟังคุณหนูฟ่านกล่าวอย่างเชือ\nมันถึงเพียงนี้ ล้วนรู้สึกเหนือความคาดหมาย\nฟ่านเสียนกวาดมองนางแวบหนึ่ง เห็นในดวงตาที่ราบเรียบธรรมดา\nของฟ่านเย่อเย่อทอแววเชือมัน ต้องฉุกใจคิด ไม่ทราบนึกได้อันใด ใบหน้า\nทีขาวซีดปรากฏรอยยิมน้อยๆ ขึ้น กล่าวว่า “อีกสักครู่จะเกิดการพะอืด\nมิหน้าซําท่านเป็นญาติสนิทของข้าพเจ้า ตามเหตุผลข้าพเจ้าไม่\nสมควรเลือกท่าน ท่านเมื่อยืนกรานเช่นนี่ ก็รังอยู่เถอะ\nหลังจากกล่าววาจาอย่างยืดยาว อาการของมันก็เสือมทรุดลง หลิน','2026-04-17 09:49:10'),(143,10,140,'ว่านเอ้อทีข้างกายจึงสันศีรษะ ยังคงไม่กล่าววาจา\nหลังความนิงเงียบงัน เปลวเทียนส่องต้องใบหน้าของฟ่านเสียแลเ\nบัดเดียวมีดบัดเดียวสว่าง มันฝืนยิมพลางกล่าวว่า “อย่างนั้นพวกท่าแย1\nรออันใด เพียงผ่าตัดเล็กเท่านั้น”\nหีบทีตึกที่สามพกนำมาหลายใบจัดสร้างตามข้อเสนอของฟ่า\nเสียน แต่ว่าผู้ริเริมคือเฟยเจีย ส่วนเฟยเจียเล่าเรียนวิชานี้จากที่ใด\nจากฟ่านเสียนแล้ว สมควรไม่มีผู้ใดทราบ แต่ตอนนี้มันต้องเป็นผู้อําน\nการผ่าตัดตนเองแล้ว พร้อมกับคํากล่าวที่ขาดๆ หายๆ ของมัน ทุกคนไ\nตําหนักกว่างซินล้วนสาละวนวุ่นวายขึ้นมา\nวังหลวงเป็นสถานที่อันฟุ่มเฟือย มีเชิงเทียนมากพอ ทั้งนึกหาวิธีไห\nเปลวเทียนเหล่านี่รวมตัวอยู่บนเตียง ส่องต้องบริเวณหน้าอกท้องน้อยขยง\nฟ่านเสียน\nเหล่าขันทีน้อยวุ่นวายกับการต้มนำ ต้มเครื่องมือ ให้คนในตําหน้ง\nล้างมือให้สะอาด ฟ่านเย่อเย่อก็ยืนหันข้าง ตั้งใจฟังเกอเกอบอกเล่าหัวข้อ\nทีพึงระวังและวิธีการทํางาน ส่วนหัวหน้าตึกทีสามกลายเป็นหม่าจุ้ยซือ\nจําเป็น ขันทีน้อยทั้งหลายกลายเป็นผู้ช่วยพยาบาล\nคณะหมอหลวงเห็นทั้งหมดวุ่นวายเป็นการใหญ่ แต่ไม่ทราบว่าคิด\nทําอะไร ได้แต่ยืนตะลึงลานอยู่ด้านข้าง คล้ายกลับกลายเป็นนักศึกษาแพทย์\nปิทีสามทียินดูการผ่าตัด\nฟ่านเสียนครุ่นคิดจะอย่างไรมิใช่ตรวจภายใน ดังนั้นเลิกล้มความคิด\nไล่คณะหมอหลวงออกไป ส่วนขันตอนฆ่าเชือได้แต่ข้ามไป ในวังหามี\nเงื่อนไขข้อนี้ไม่\nเสียงติงของโลหะกระทบกัน ดังสะท้อนอยู่ในตําหนักกว่างซินทีเงียบ\nสงบ ฟ่านเยอเยอผงกศีรษะด้วยความตินเต็นอยู่บ้าง บอกใบ้ต่อเกอเกอว่า\nวิสัพญีแพทย์','2026-04-17 09:49:10'),(144,10,141,'ต๋๋)เกงพร้อมแล้ว\nหลนวานเออเห ลยวดูเสยวกู (อาหญง) ด้วยความเป็นห่วงแวบหนึ่ง\nจเหนไช้ผ้าเช็ดหน้าเนื่อแพรสีขาวซับเหงือที่หน้าผากฟ่านเสียน\nฟ่านเสียนยิมอย่างยากลําบากกล่าวว่า “ฮูหยิน (คําเรียกภรรยา)\nฟ \"แสมควรเช็ดเหงือให้กับหมอรักษา”\nหัวหน้าตึกที่สามดึงดันป้อนยาให้ แต่ฟ่านเสียนพอสูดได้กลินยา ก็\nเม้งเวิมฝีปากไม่ยอมรับประทาน กล่าวว่า “เมล็ดหม่าเฉียนจื่อรุนแรงไป\nเป็นเหตุให้สลบไสล”\nหัวหน้าตึกที่สามกล่าวอย่างอัดอันตันใจว่า “ท่านไม่สลบไสลจะทํา\nหค่างไร อีกสักครู่เจ็บปวดจนทะลึงตัวขึ้นมาจะทําอย่างไร?\nฟ่านเสียนแม้ไม่มีความกล้าหาญเช่นกวนอูปล่อยให้ขูดกระดูกขจัด\nพัษของลูกธนู แต่ยามนี้มีแต่มันทีเชียวชาญชํานาญวิชานี้ ย่อมไม่อาจ\n1ล่อยให้ตนเองสลบไสล มอบชีวิตให้กับยาโถวเช่นเม่ยเม่ย จึงกล่าว “ใช้\nเครื่องหอมเกอหลอฟางในปริมาณน้อยเถอะ”\nหัวหน้าตึกที่สามค่อยนึกออกว่าตนเองลืมเลือนยาตัวนี้ เมื่อฤดูใบไม้\nแล๊ปีนี้ตนเองเป็นคนแนะนำตัวยานี้ให้กับฟ่านเสียน ต่อมาฟ่านเสียนขึ้น\nเหนือลงใต้นำไปใช้ออก ตึกทีสามเองกลับน้อยครั้งจะใช้ออก จึงเดินไปที\nมุมห้อง รือค้นหีบห่อดู ในที่สุดค้นพบขวดเล็กๆ สีนำตาลใบหนึ่ง จึงเดิน\nกลับมา ยืนขวดถึงริมจมูกฟ่านเสียน\nปรากฏกลินหอมเล็กน้อยชําแรกเข้าจมูกฟ่านเสียน ชั่วครู่ให้หลัง\nตัวยาก็ออกฤทธิ์\nถึงแม้ม่านสายตาไม่ได้พร่ามัว แต่ภาพทีเบืองหน้าฟ่านเสียนแปลก\nประหลาดอยู่บ้าง คล้ายมองเห็นภาพพร้อมกันสองภาพ ภาพหนึ่งเป็นเม่ย\nเม่ยถือเครื่องมือคล้ายคืมมองดูตนเอง อีกภาพหนึ่ง เป็นเมื่อนานปีมา\nแลว ในสถานที่ทีเรียกว่าโรงพยาบาล มนางพยาบาลทคุนตานางหนงกาลง','2026-04-17 09:49:10'),(145,10,142,'สนทนากับตนเอง\nฟ่านเสียนมีสมาธิจิตใจเข้มแข็งกว่าชนชาวโลกมากนัก\nตนเองเริมเกิดภาพลวงตาช่วงสันๆ ภาพจริงกับภาพลวงทับซ้อนกัน )\nไม่มีเวลามากความ\nฟ่านเสียนหยีตาลงกล่าวว่า “เริมได้ เร็วกว่านี้ หากเย่อเย่อไม่ถา1\nประคองตน (ศิษย์พี่) ก็เข้าแทนที”\nมันขวัญกล้าแข็งยิง คล้ายกับใช้ชีวิตตนเองสนับสนุนความเชือง\nของฟ่านเย่อเย่อ เพียงแต่ภายใต้ฤทธิยาเกอหลอฟาง จิตสํานึกของมันล่๓1\nลอยออกจากห้องผ่าตัดในวัง ลืมเลือนว่าคนไข้ที่รับการผ่าตัดเป็นตนเอง\nฟ่านเสียนเคยใช้เครื่องหอมเกอหลอฟางจัดการกับเซียวเอิน จัดกา.\nกับเอียนปิงหวิน และจัดการกับองค์ชายรอง วันนี้นับว่ารับกรรมสนอถง\nฟ่านเสียนเหลียวดูใบหน้าอันขาวผ่อง ดวงตาทีบวมแดงจนโศกซึ่ง\nเป็นพิเศษของหลินว่านเอ้อ มองดูเม่ยเม่ยที่สาละวนอยู่กับหน้าอกของ\nตนเอง พลันยิมอย่างโง่งม ครุ่นคิดว่าหากวันหน้าให้ภรรยากับเม่ยเม่ยอยู่\nบ้านแต่งเครื่องแบบนางพยาบาล สมควรเป็นภาพอันงดงามกระมฆัง?\nคนใกล้สลบไสล สันดานเดิมจะปรากฏขึ้น\nผู้คนที่หน้าตําหนักกว่างซินรออย่างร้อนรุ่ม พวกมันทราบว่าฟ่าน\nเสียนฟืนคืนสติแล้ว กำลังเตรียมการรักษาบาดเจ็บให้กับตนเองตามวิธีการ\nของตนเอง\nชาวชิงแม้คุ้นชินกับฟ่านเสียนทีนำความตื่นตะลึงมาให้ ยกตัวอย่าง\nเช่น ร่ายกวีร้อยบท หยอกเย้าไห่ถัง เปิดโปงทุจริตการสอบแข่งขันฤดู\nซุนเทียน รับตําแหน่งในตึกที่หนึ่ง แต่ทั้งหมดยังครุ่นคิด มันรับบาดเจ็บ\nสาหัส ยังคิดรักษาตนเอง ใช่สามารถกระชากตนเองพันจากห้วงความเป็น','2026-04-17 09:49:10'),(146,10,143,'ตวเมตายหรือไม่?\nฮ่องเต้หลังจากพักผ่อนพระอิริยาบถทีห้องทรงพระอักษร คล้ายกับ\nทวงห่วงใยขุนนางหนุ่มผู้นี้เป็นพิเศษ จึงประทับนั่งราชรถกลับมาทีหน้า\nต๋เหนักกว่างซินอีก\nพระองค์ทอดพระเนตรกลุ่มคนที่ชุมนุมอยู่หน้าตําหนัก ทรงสดับ\nเสียงคนและเสียงโลหะกระทบกันดังลอดออกมา อดขมวดพระขนงมิได้\nทวงดําริถึงเมื่อหลายปีก่อน บนสมรภูมิอันกันดารทางเหนือ พระองค์คล้าย\n1ระสบเหตุเช่นนี้เช่นกัน\nจิงอ้องเข้ามาถวายบังคม ฮ่องเต้รีบรับสังถามว่า “เป็นอย่างไรแล้ว?\nจิงอ้องกล่าวด้วยความเป็นห่วงว่า “คณะหมอหลวงไม่อาจช่วยเหลือ\nไต้ คนของตึกทีสาม สมควรขจัดพิษได้ แต่ว่าบาดแผลจากคมมีด ลึก\nเกินไป”\nฮ่องเต้แย้มพระโอษฐ์พลางตรัสว่า “นางทึ่งของวิเศษเหล่านั้นไว้\nสมควรไม่มีปัญหาอันใด”\nจึงอ้องงงงันวูบ นิงเงียบงันไม่ตอบคํา ล่าถอยไปหยุดยืนที่ด้านหลัง\nท่องเต้ สายตาที่ก้มตําทอแววโกรธแค้นและโศกศัลย์วูบหนึ่ง จากนั้นกลับ\nคืนสู่ความสงบนิง\nไม่ทราบผ่านไปนานเท่าใด ประตูตําหนักกว่างซินถูกผลักเปิดออก\nอิกุ้ยผิงไม่คํานึงถึงศักดิฐานะจู่จือ (นาย) รีบฉุดดึงองค์ชายสามชะโงกศีรษะ\nมองเข้าไป ถามอย่างร้อนรุ่มว่า “เป็นอย่างไร?”\n๐ ซ่ทๆ ข๑๓ \'\nคําตอบทีได้รับคือเสียงโอ้กอย่างไร้มารยาท\nผู้ที่ออกมาเป็นขันทีน้อยผู้หนึ่ง ก่อนหน้านี้อยู่ในตําหนัก ทําหน้าที\nส่งเครื่องไม้เครืองมือ จึงออกมาเป็นคนแรก ย่อมตกเป็นเป้าสายตาของ\nทงหมด พอได้ยินคําถามของอีกุ้ยผิง ก็ไม่ตอบคําอันใด หากเกาะเสา','2026-04-17 09:49:10'),(147,10,144,'ระเบียง ส่งเสียงอาเจียนออกมา\nเหยากงกงด่าว่า “เดียรัจฉานน้อยอาเจียน ”\nไม่ทันขาดคํา ปรากฏหมอหลวงหนุ่มคนหนึ่งเดินออกจากประ๓\nตําหนัก กลับประพฤติเช่นเดียวกับขันทีน้อย นั่งยองๆ อาเจียนออกมา\nโลกนี้ความจริงสงบสันติ ขันทีน้อยเติบใหญ่ในวัง เคยเห็นการลงโท\nฟาดโบย แต่ไม่เคยเห็นภาพอันสยดสยองเช่นในตําหนักยามนี้ วัตถุสีแดง\nสีเขียวสีขาวเหล่านั้นเป็นอะไร หรือในท้องของมนุษย์ประกอบด้วยก้อนเนี้็ก\nแปดเปือนคราบเลือดเหล่านั้น คุณหนูฟ่านกล้าหาญจริงๆ กลับยืนมือออก\nลูบคลํา\nหมอหลวงหนุ่มนั้นรําเรียนวิชาแพทย์ อย่างมากเพียงมองดู รับฟัง\nถามไถ่ สัมผัส ทีสร้างความพะอืดพะอมที่สุดคือฝ้าที่ลินกับโรคฮัวหลิว\nคําคืนนี้เป็นครั้งแรกที่เห็นมีคนใช้เข็มเย็บผิวหนัง ใช้กรรไกรตัดเนื่อ นั้น\nเป็นเนื่อหนังมนุษย์ชัดๆ\nหลังจากนั้นคณะหมอหลวงทยอยออกจากตําหนักกว่างซินอย่าง\nเงียบงัน แต่ว่าสีหน้าทุกคนไม่น่าดูอยู่บ้าง ถึงแม้ว่าผู้คนส่วนใหญ่รักษา\nความเยือกเย็นไว้ แต่ส่วนลึกของจิตใจได้รับความสะท้านสะเทือนไม่น้อย\nฮ่องเต้ทอดพระเนตรสีหน้าพวกมัน ทรงทราบว่าฟ่านเสียนไม่เป็นไร\nแล้ว แต่ยังตรัสถามว่า “เป็นอย่างไร?”\n2 97 รส่ เบซี่ ส รห\nหมอหลวงที่ถูกจึงอ้องตบหน้าฉาดหนึ่งก่อนนือดเมียงมองมิได้\nยามนี้พอฟังฮ่องเต้รับสังถาม จึงกล่าวด้วยใบหน้าเขียวคลําอมแดงว่า\n“ฝ่าบาท ช่างลึกลําพิสดารจริงๆ”\nจิงอ้องพอฟังนำเสียงนี่ อดด่าทอมิได้ว่า “ถามถึงฟ่านเสียน มิใช่\nให้ท่านทอดถอนรําพัน”\nหมอหลวงนั้นยังทอดถอนรําพัน เคราใต้คางสันสะท้าน กล่าวว่า\nกามโรค','2026-04-17 09:49:10'),(148,10,145,'\" อฮ้องแหย เฉินผู้น้อยเป็นหมอมาหลายสิบป เคยได้ยินวิชามีดเข็ม\nทีผีกลําพิสดารเช่นนี้มาบ้าง มิคาดวันนี้ได้เห็นกับตา ขอฝ่าบาทวางใจ\nผวายวะภายในใต้เท้าเสียวฟ่านสมานตัวแล้ว สมควรไม่เป็นไร เพียงแต่เสีย\nในหิตมากไป ยังไม่ฟืนคืนสติมา”\nมันไม่กล้าบอกว่า หลังการผ่าตัดเสร็จสิน ฟ่านเสียนไม่อาจต้านฤทธิ\nกาเกอหลอฟาง นอนบน “เตียงผ่าตัด” กล่าวเพ้อเจ้อเหลวไหล เรื่องราว\nเกียวพันถึงพฤติการณ์ของเชือพระวงศ์สูงศักดิ ดังนั้นไม่กล้ากราบทูล\nต่อฮ่องเต้เด็ดขาด ดีทีข้างเตียงผ่าตัดนอกจากนักศึกษาแพทย์เช่น\nตนเอง คงมีแต่หญิงสาวทิใกล้ชิดกับใต้เท้าเสียวฟ่านที่สุดสองนาง สมควร\nไม่เป็นไร\nยามนั้นผู้คนทีรังอยู่หน้าตําหนักกว่างซินล้วนภาวนาให้ฟ่านเสียน\nงชีวิตรอด พอได้ยินหมอหลวงรับประกันเช่นนี้ ต่างระบายลมหายใจ\nโล่งอก\nองค์ชายใหญ่ยิมออกมา ถวายบังคมฮ่องเต้แล้วเดินทางกลับวัง\nมันไม่ต้องการให้ผู้คนเข้าใจว่าตนเองแสดงมิตรไมตรีต่อฟ่านเสียน และ\nไม่ต้องการให้ผู้คนเข้าใจว่าตนเองกำลังประจบประแจงพระบิดา เพียงไม่\nต้องการเห็นฟ่านเสียนตกตาย ยามนี้ฟังว่าอีกฝ่ายปลอดภัย ก็จากไปอย่าง\nผ่าเผย\nฮ่องเต้โบกพระหัตถ์ เป็นความหมายให้อิ๊กุ้ยผิงนำองค์ชายสาม\nสึ่งง่วงเหงาสุดทนทานกลับวังไปก่อน จากนั้นสาวพระบาทเตรียมเข้าไปยัง\nตําหนักกว่างซิน จิงอ้องย่อมตามเสด็จอยู่ด้านหลัง\nมิคาดหมอหลวงนั้นทัดทานคนบุญหนักศักดิใหญ่ทั้งสองไว้ ฝืนยิม\nพลางกล่าวว่า “ใต้เท้าเสียวฟ่านก่อนสินสติบอกว่า ทางทีดีอย่าให้ผู้คน\nเข้าไป มิให้ ”\nมันขมวดคิวครุ่นคิดอยู่ครึ่งค่อนวัน ค่อยนึกคําศัพท์ใหม่นั้นได้ว่า “','2026-04-17 09:49:10'),(149,10,146,'เกิดการติดเชือ”\nฟ่านเสียนสังไว้เช่นนี้ ความจริงแล้วเพียงต้องการความสงบ ฮ่องเมฉ่\nกับจึงอ้องงงงันวูบ แล้วอนุญาตตามที่ร้องขอ หมอหลวงกลับกล่าวอีก.่\n“ฝ่าบาท เฉินเห็นว่าใต้เท้าเสียวฟ่านมีวิชาแพทย์เป็นเลิศ สมควรวํา!\nตําแหน่งในตึกไท่อี (ตึกหมอหลวง หนึ่งนั้นจะได้รักษาโรคของคนบูแย\nหนักศักดิใหญ่ในวัง สองให้ถ่ายทอดวิชาความรู้แก่ศิษย์ นำความผาสุกม\nสู่ชาวชิง ”\nนี้เป็นกุศลเจตนาอันใหญ่หลวง ทั้งปราศจากความคิดเห็นแก่ตัว แต่\nยามนี้สถานการณ์ตึงเครียด ฮ่องเต้จึงตรัสด้วยความกริวว่า “คนยังไม่ฟีน\nคืนสติ เจ้าแย่งชิงตัวอันใด ฟ่านเสียนมีขีดความสามารถเพียงไหน ไหนแ\nเลยยอมจมปลักอยู่กับหน้าทีนี้\nจิงอ้องทีเจ้าอารมณ์กลับไม่มีโทสะ หัวร่อเฮอะฮะกล่าวว่า “เป็นหมก\nรักษาย่อมดีกว่าเป็นคนป่วย\nยามนั้นคนของตึกทีสามล้วนล่าถอยออกมา แสดงความเคารพต่อ\nฮ่องเต้ ฮ่องเต้ก็รับสังชมเชยอยู่หลายคํา จากนั้นทั้งหมดพกความอิดโรย\nล่าถอยออกจากตําหนัก\nภายในตําหนักกว่างซินนอกจากขันทีนางกํานัลทีอยู่รับใช้แล้ว คง\nเหลือแต่ฟ่านเสียนกับหลินว่านเอ้อและฟ่านเย่อเย่อสามคน\nหลินว่านเอ้อมองดูฟ่านเสียนด้วยความเจ็บปวดใจ จากนั้นเหลียวดู\nเสียวกู (อาหญิง) ทีหน้าซีดขาว พลางซับหยาดเหงือบนหน้าผากนาง นี้\nเป็นคําพูดที่ฟ่านเสียนบอกกล่าวเอาไว้\nฟ่านเย่อเย่อมีมือทีมันคงตลอดมา ยามนี้ค่อยสันระริกขึ้นมา นาง\nทราบว่าภายใต้คําสังการของเกอเกอ ตัวเองค่อยทําการใหญ่สำเร็จ\nของเกอเกอนับว่ารักษาไว้ได้แล้ว สมาธิจิตใจของนางอยู่ดีๆ ก็ผ่อนคลาย\nพลันเข่าอ่อนระทวยแทบล้มลงกับพืน','2026-04-17 09:49:10'),(150,10,147,'หลินว่านเอ้อประคองนางไว้ ยมเยาะตวเองอยูบาง ยังคงไม่เอ่ยปาก\nวกยยิมนี้สือความหมายอย่างชัดแจ้ง นางเห็นว่าคนที่ข้างกายจะมากจะน้อย\nมีส่วนช่วยเหลือฟ่านเสียน มีแต่ตัวเองทีได้แต่ยืนดู ไม่เกิดผลอันใด\nฟ่านเย่อเย่อค่อยพบเห็นความเงียบขรืมที่ผิดปรกติของหลินว่าน\nต้องสอบถามว่า “เส้าจือไม่เป็นไรกระมัง?”\nหลินว่านเอ้อถูกจ้องมองจนยิมเล็กน้อย ตอบว่า “ไม่เป็นไร\nคําไม่เป็นไรนี้ไม่ชัดเจนอยู่บ้าง ฟ่านเย่อเย่อเพ่งตามอง ค่อยพบว่า\nมุมปากเส้าจือมีคราบเลือดเล็กน้อย สร้างความตื่นตระหนกจนคิดออกไป\nตามตัวหมอหลวงมาตรวจดู\nหลินว่านเอ๋อรีบปิดปากนางไว้ เกรงว่าจะปลุกฟ่านเสียนทีตกอยู่ใต้\nยุทธิยาเกอหลอฟางตื่นขืนมา อธิบายเสียงอู้อิว่า “ไม่ เป็นไร เพียงกัดลิน\nตัวเอง”\nฟ่านเย่อเย่องงงันวูบ จากนั้นเข้าใจว่าเป็นเรื่องราวใด ต้องบังเกิด\nความอบอุ่นใจ ทั้งเพิ่มความเคารพรักต่อเส้าจืออายุเยาว์อีกหนึ่งส่วน\nเมื่อครู่ตอนป้อนยาให้กับฟ่านเสียน หลินว่านเอ้อร้อนรุ่มใจดุจมีไฟ\nสุมทรวง เอาแต่กัดยาเม็ดจนแตก กลับกัดลินของตัวเอง แต่จิตใจห่วงใย\nความปลอดภัยของเซียงกง จึงสะกดอดกลันถึงเพียงนี้\nผ้าแพรสีขาวที่ขึงอยู่ในตําหนักกว่างซินถูกถอดออกตั้งแต่แรก ยาม\nนจันทราโผล่พันก้อนเมฆ สาดแสงอําไพลูบไล้พสุธา ผู้คนทีหน้าตําหนัก\nคอยๆ สลายตัวไป คงเหลือแต่ราชองครักษ์รักษาการณ์กับขันทีทีมีหน้าที\nส่งข่าว ส่วนขันทีนางกํานัลในตําหนักกว่างซินนั่งหลับพักผ่อนกับเก้าอี\n1องกันว่าอาการบาดเจ็บของใต้เท้าเสียวฟ่านเกิดความเปลี่ยนแปลง นาง\nกํานัลทีเข้าเวรยังขนย้ายเชิงเทียนที่มากเกินออกไป\nหญิงสาวทั้งสองนั่งสงบบนเก้าอิ๋ มองดูฟ่านเสียนทีหลับใหลใต้แสง\nเทียน ใบหน้าล้วนปรากฏรอยยิมอันปลาบปลืมประโลมใจขึ้น','2026-04-17 09:49:10'),(151,10,148,'ทีนอกกําแพงวังหลวง คู่จู้ในเสื้อผ้าเนื้อหยาบ\nหนึ่งในวัง จวบจนแน่ใจว่าบุคคลบางคนพันขีดอันตราย ค่อยเร้นหางย\nดงไม้ใต้ม่านวิกาล\nผ่านไปหลายวันยังคงอยู่ในวัง ส่วนลึกของอุทยานเหมยซึ่งปรก\nเงียบสงบ วันนี้กลับวางกำลังรักษาการณ์อย่างแน่นหนา คนไข้ที่มีชื่อเนิย,\nลือที่สุดในมหานครนอนอยู่บนเตียง แสดงความขุ่นเคืองออกมา\n“เมื่อใดจึงกลับบ้านได้?”\nฟ่านเสียนห่มผ้าห่มเบาบาง นอนอยู่บนเตียง มองดูผลเหมยซึ่งออ\nผลก่อนกําหนดในอุทยานเหมย กล่าวด้วยความขุ่นข้องใจอยู่บ้าง\nในวังย่อมมีทรัพยากรอุดมสมบูรณ์ ตัวยาอันล้าค่าผ่านการปรุงจ นา\nตึกหมอหลวง กรอกเข้าปากมันไม่หยุดหย่อน ไม่คิดทุเลาหายดียังยากเกน\nยังมีความสามารถในการปรนนิบัติของขันทีนางกํานัลในวัง ย่อง!\nเหนือกว่าบ่าวไพร่หญิงรับใช้ตึกตระกูลฟ่าน แม้กระทั่งทิวทัศน์ของอุทยาแ\nเหมยก็งดงามกว่าสวนหลังตระกูลฟ่าน บวกกับภรรยาและเม่ยเม่ยได้วั1\nอนุญาตพิเศษจากฮ่องเต้ สามารถอยู่เป็นเพื่อนมัน ดูเหมือนไม่ต่างกับชีวิต\nในบ้าน นอกจากที่นี้ไม่มีชิงช้าเท่านั้น\nแต่ว่าฟ่านเสียนยังคิดกลับตึกตระกูลฟ่าน เนื่องเพราะมันมีความ\nสึกว่าทีนั้นจึงเป็นบ้านที่แท้จริงในมหานครของตนเอง\nหลังจากทําการผ่าตัดเป็นครั้งแรกของราชสำนักชิง อาศัยร่างกายที\n& ฒ ลยมก รซ -\nปรับพื้นฐานมาเกือบยีสิบปี ช่วยให้ฟ่านเสียนมีสุขภาพฟืนฟูโดยเร็ว ถึงแม้\nบาดแผลยังไม่สมานตัว แต่ก็สามารถนอนชมทิวทัศน์ เพียงแต่สภาพ\nลมปราณภายในกายแตกซ่านยังไม่ดีขึ้น สร้างความประหวันพรันใจแก่มัน','2026-04-17 09:49:10'),(152,10,149,'ฟ่านเย่อเย่อใช้ปากเป่าข้าวต้มในชาม ใช้ช้อนตักขึ้นมา ป้อนให้กับ\nฝันคําหนึ่ง หลินว่านเอ๋อที่ด้านข้างยืนมือเข้ามาในชุดยาวอันหลวมกว้าง\nของมัน ปรับตําแหน่งของถุงธัญพืชทีกดทับอยู่เหนือผ้าพันแผล นี้เป็นการ\nช้คงขอของฟ่านเสียน เมื่อใช้ผ้าพันแผลพันปากแผล ใช้ถุงบรรจุภัณฑ์กด\nทํา ไว้ จะมีส่วนช่วยให้ปากแผลสมานตัว\nฟ่านเสียนกลืนข้าวต้มลงไปอย่างยากเย็น ตัดพ้อว่า “รับประทาน\nข้างต้มทุกวัน ปากจืดชีดจนเกิดนก ออกมานแล้ว ข้าพเจ้าคิดกลับบ้าน\nตท่าว่าแต่รับประทานอาหารของหอโอบจันทร์ เพียงนำผลไม้ทีหลิวอิเหนี้ยง\n(น้าสาว) ปรุงขึ้นมา ก็เหนือกว่ามากมาย\nหลินว่านเอ้อกล่าวอย่างขุ่นเคืองแง่งอนว่า “ตื่นขึ้นมาเพียงสองวัน\nแล้บช่างพูดช่างจา ฝ่าบาทเมื่ออนุญาตท่านพักรักษาตัวในวัง ท่านยัง\nเล้วคําครหานินทาอันใด แต่ว่า ปากจืดชีดจนเกิดนกหมายความว่า\nฟ่านเย่อเย่อก็ซักถามว่า “นกอะไร?”\nฟ่านเสียนไม่อธิบายอันใด หากหันเหหัวเรื่องว่า “ข้าพเจ้าไม่กลัวคํา\nครหานินทา เพียงแต่คิดถึงบ้าน\nตอนนี้มันอยู่ในวัง ไม่สามารถติดต่อกับกลุ่มย่อยที่หวังฉีเหนี้ยนฝึก\nกบรมขึ่น ฮ่องเต้ก็มีพระราชกระแส ให้มันมิต้องวุ่นวายใจ ว่านเอ้อกับเย่อ\nเย่อพานไม่ออกจากวัง ขันทีนางกํานัลในตําหนักยิงไม่บอกกล่าว คดีปลง\nพระชนมัที่วิหารฮุ่ยคงผ่านไปหลายวันแล้ว มันกลับไม่ได้รับข่าวสารอันใด\nยิงไม่สามารถไปคาดค้ันถามถึงอิงจือ (เงา) จากเฒ่าขาเป๋ สร้างความ\nคับข้องใจยิง\nนกในที่นี้เป็นคําสแลง หมายถึงอวัยวะเพศชาย','2026-04-17 09:49:10'),(153,10,150,'','2026-04-17 09:49:10'),(154,10,151,'ฑพนปายไนธุทยาน\nอุทยานเหมยอยู่หลังตําหนักกว่างซิ่น สภาพแวดล้อมร่มรื่น หลังจาก\nตัดผ่านแท่นเทียนซินจะเป็นหออื่นฟง และเป็นสถานพักฟื้นของฟ่านเสียน\nถึงแม้ว่าฮ่องเต้ทรงอนุญาตให้มันพักรักษาตัวอยู่ในวัง มิหน้าซ้้า\nคนบุญหนักศักดิ์ใหญ่ล้วนทราบว่าคราครั้งนี้ฟ่านเสียนกระทําความดีความ\nซอบต่อเชื้อพระวงศ์ แต่ขุนนางบุรุษผู้หนึ่งพํานักในวัง จะอย่างไรไม่เหมาะ\nสมอยู่บ้าง ฟ่านเสียนก็รู้สึกถึงข้อนี้ จึงรั้งอยู่ในอุทยานเหมยอย่างเรียบๆ\nข้อยๆ ปฏิเสธการมาเยือนของคนบุญหนักศักดิ์ใหญ่ในวัง อ้างว่าร่างกาย\nไม่สบาย\nยามนี้ปรากฏสตรีสูงศักดิ์นางหนึ่งสืบเสาะมาถึงหออิ่นฟง ในมือยัง\nงงเด็กชายผู้หนึ่ง ที่ต้านหลังตามติดด้วยนางกํานัลหลายนาง\nฟ่านเสียนงงงันวูบ พบว่าเป็นอี้กุ้ยผิง จึงไม่กล่าวกระไร นับตั้งแต่\nตนเองพื้นคืนสติมา อี้กุ๊ยผิงจะนำองค์ชายสามมานึ้งที่นี้ทุกวัน หนึ่งนั้น\nทั้งสองฝ่ายเกี่ยวดองเป็นญาติ สอง ตอนอยู่บนวิหารฮุ่ยคง ตนเองช่วยชีวิต\nขององค์ชายสาม อีกฝ่ายยกอ้างบุญคุณ ตนเองย่อมไม่สะดวกกับการ\nทัดทาน\nนยมพลางกลาววา “ (14779) มิใช่บอกว่าไม่ต้องมาแล้วหรือ','2026-04-17 09:49:10'),(155,10,152,'วันนี้ไฉนยังนำสิงของมาอีก?\nตามพิธีริตอง ฟ่านเสียนต้องเรียกอิกฝายเป็นเหนี้ยงเหนี้ยง ( 7961)\nพระชายา) แต่เมื่อปีก่อนครั้งแรกที่มันเข้าวัง อิกุ้ยผิงก็ชมชอบฟ่านเสีย\nเรียกตัวเองเป็นอิ เห็นว่าคําเรียกหานี้สะท้อนความใกล้ชิดสนิทสนม\nเสียนจึงไม่ยืนกรานอีกต่อไป เห็นนางกํานัลที่ด้านหลังยังถือกล่องอาหา»\nใบหนึ่ง ไม่ทราบภายในบรรจุสิงของใด\nอิกุ๊ยผิงทักทายหญิงสาวที่ข้างกายมันทั้งสอง จากนั้นขนย้ายม้าน\nแพรตัวหนึ่งมา นั่งลงที่ข้างกายฟ่านเสียน กล่าวว่า “นี้เป็นนำแกงถังเชซ่า\"\nแต่มิใช่ของในวัง เป็นทางบ้านของท่านตุ๋นเสร็จแล้วให้เราส่งมา”\nฟ่านเสียนส่งเสียงดังอ้อ มองดูเหล่านางกํานัลเทนำแกงออกมา\nว่าหนึ่งในจํานวนนั้นคุ้นตายิง จึงทักทายว่า “สิงเอ้อก็มาแล้ว\nสิงเอ้อเป็นนางกํานัลน้อยที่นำมันไปกราบคารวะพระชายาต่างๆ\nครั้งแรกที่มันเข้าวัง นางนึกไม่ถึงว่าใต้เท้าเสียวฟ่านยังจําตัวเองได้\nหน้าแดงวูบ รับคําดังอืมม์อย่างแผ่วเบาราวกับยุง\nทั้งหมดชมดูจนหัวร่อออกมา อิกุ้ยผิงด่าอย่างยิมแย้มว่า “บาดเจ\nถึงเพียงนี้ ยังไม่ลืม\nพลันพบว่าคําพูดนี้ไม่อาจกล่าวต่อ จึงแย้มยิมอย่างอ่อนหวานพลา1!\nปิดปากลง นางมีอายุไม่มาก บวกกับปล่อยตัวตามธรรมชาติ ชวนให้ผู้ค\nเกิดความใกล้ชิดสนิทสนม ยามนั้นหันไปกล่าวกับหลินว่านเอ๋ออยู่หลายก่า\nทั้งสนทนาถึงเรื่องทางบ้านกับฟ่านเย่อเย่อ ให้พวกนางพํานักในวังอย่า!\nวางใจ ตึกตระกูลฟ่านไม่มีปัญหาอันใด\nองค์ชายสามนั่งอยู่ข้างกายนาง วันนี้แสดงว่าเรียบๆ ร้อยๆ กว่าเต๋ง\nยิงปราศจากเค้าความดุร้ายเช่นตอนอยู่ในหอโอบจันทร์ หากก้มศีรษะ๓๒!\nนิงเงียบงันไม่พูดจา เพียงแต่บางครั้งเงยหน้าขึ้น แอบมองคนไข้บนเต่ยเ','2026-04-17 09:49:10'),(156,10,153,'แวบหนึ่ง\nเหตุการณ์บนวิหารฮุ่ยคง ได้สลายความโกรธแค้นที่มันมีต่อฟ่าน\nเสียนด้วยเรื่องของหอโอบจันทร์ ตอนนั้นนอกจาก ต้าเปียวเกอ (\nผูกน้องคนโต) ท่านนี้แล้ว กลับไม่มีผู้ใดสนใจความเป็นความตายของมัน\nวงมทั้งพีชายร่วมสายเลือดทั้งสอง รู้จักแต่รุดไปช่วยเหลือพระบิดา\nตกแน้นหากมิใช่ฟ่านเสียนอยู่ในทีเกิดเหตุ เกรงว่าชีวิตน้อยๆ ของตนเอง\nคงจบสินในเงือมมือคนร้ายชันที่เก้านั้นแล้ว\nเด็กชายอายุแปดขวบผู้หนึ่งต่อให้เป็นผู้ใหญ่กว่านี้ ก็รู้จักแต่อาศัย\nทวามรักความชังจําแนกความใกล้ชิดห่างเห็น ยามนืองค์ชายสามมองดู\nไบหน้าทีขาวซีดของฟ่านเสียน นึกถึงท่วงท่าอันองอาจของฟ่านเสียนที่\nเณซี ก วู ย\nขาางอยู่เบืองหน้าตนเอง ในใจต้องเกิดความเคารพยกย่องอย่างบอก\nไม่ถูก\nหลินว่านเอ้๋อกวาดมององค์ชายสามแวบหนึ่ง กล่าวอย่างสงสัยใจว่า\n\'เหลาซน (อนดับสาม) วันนี้ไฉนกลับกลายเป็นเรียบร้อยถึงเพียงนี้?\nองค์ชายสามหัวร่อฮิฮะกล่าวว่า “เฉินเจียเจีย (พีสาว) ไม่มีใด\nหลินว่านเอ้ออัดอันตันใจกว่าเดิมกล่าวว่า “คล้ายกลับกลายเป็น\nฑาเละคนก็มีปาน”\nอีกุ้ยผิงมองดูบุตรชายตัวเองด้วยความเจ็บปวดใจ กล่าวว่า “หาก\nมไขซ่ฟ่านเสียน เด็กน้อยนี้คงจบชีวิตไปแล้ว หลังจากรับความตื่นตระหนก\nสงเควรเรียบร้อยกว่าเดิม\nฟ่านเสียนนอนอยู่บนเตียง ไม่สะดวกกับการเหลียวหน้าไป เพียงใช้\nหางดาชําเลืองมองสตรีและเด็กสนทนากัน ภายใต้การปรนนิบัติจากสิง\nเก่ก มันดีมนำแกงถังเช่าลงไปชามหนึ่ง เมื่อสิงเอฮ้อรับชามกลับไป\nไจหลางฝ่ามือของมันคราหนึ่ง ปลายนิวของนางนุ่มนิมยิง\nฟ้านเสียนงงงันวูบ ทราบว่านางกํานัลน้อยต้องไม่ยัวเย้าตนเอง','2026-04-17 09:49:10'),(157,10,154,'คาดว่าอี๋กุ้ยผิงคงมีคําพูดอันใดคิดกล่าวกับตนเองเป็นการส่วนตัว จึงกล่า,\nว่านเอ้อ ท่านนำซันเดียนเซีย (องค์ชายสาม) ไปเดินเล่นในสวนเถอะ\nเม่ยเม่ย ท่านก็ไปด้วย”\nหญิงสาวทั้งสองสบตากันวูบ ทราบว่ามันกับอีกุ้ยผิงมีเรื่องสนทน\nจึงผุดลูกขืน ฉุดลากองค์ชายสามซึ่งไม่ยินยอมจากไปออกจากหอ !\nขันทีนางกํานัลทีปรนนิบัติอยู่ด้านข้างไปด้วย\nยามนี้ภายในหออินฟงคงเหลือฟ่านเสียนกับอีกุ้ยผิงสองคน เพียง\nแต่ขุนนางหนุ่มไม่สะดวกกับการอยู่ร่วมกับเหนี้ยงเหนี้ยงเยาว์วัยสองต่๓\nสอง ดังนั้นสิงเอ้อจึงรังอยู่\nฟ่านเสียนเหลียวหน้าด้วยความยากลําบาก มองดูสิงเอ้อแวบหนึ่ง\nอีกุ๊ยผิงเข้าใจความหมายของมัน จึงยืมพลางกล่าวว่า “เป็นยาโถ\nที่หอบหิวมาจากบ้าน ไม่ต้องกลัวอันใด\nฟ่านเสียนฝืนยิมพลางกล่าวว่า “อีเอย มีเรื่องใดต้องระมัดระวังถึง\nเพียงนี้ ผู้หลานรับบาดเจ็บสาหัส เพิงฟินคินมาเพียงสองวัน\nอีกัยผิงโบกผ้าเช็ดหน้าในมือ ยิมพลางกล่าวว่า “เราไม่มาหาท่าน\nหรือท่านไม่คิดไปหาเรา?”\nคําพูดนิปราศจากความหมายฉันชู้สาว เพียงแต่นางคํานวณแน่ว่า\nตอนนี้ฟ่านเสียนต้องการทราบข่าวทีนอกวัง เหตุการณ์ปลงพระชนม์บน\nวิหารฮุ่ยคงลิลับอยู่บ้าง ไม่เพียงแต่ผู้นำในวังนึกหวันวิตก ขุนนางในราช\nสำนักไม่สบายใจ แม้แต่ชาวมหานครก็วิพากษ์วิจารณ์กันที่ข้างโต๊ะอาหาร\nในเหลาสุราต่างด่าทอคนร้าย ทั้งกระซิบถามความเป็นมาของคนร้าย จน\nมีคําตอบหลายร้อยข้อ อีกุ๊ยผิงทราบว่าฮ่องเต้มีพระประสงค์ให้ฟ่านเสียน\nสงบจิตใจพักรักษาตัว จึงตัดทีมาของแหล่งข่าวของมันทั้งหมดไป\nล่วงรู้ว่าตัวเองสามารถช่วยเหลือมันข้อนี่\nฟ่านเสียนกล่าวเป็นเชิงยิมไม่เชิงยิมว่า “ไม่กลัวฝ่าบาทตําหนิเหนี้ยง','2026-04-17 09:49:10'),(158,10,155,'เพนแยงหรอว”\nอีกุ้ยผิงกล่าวตรงๆ ว่า “ในสถานการณ์เช่นนี่ นอกจากท่านแล้ว เรา\nไม่สามารถคาดหวังผู้ใด”\nฟ่านเสียนเข้าใจความหมายของนาง ในวังมีเหนี้ยงเหนี้ยงสีนาง\nก์ แนิดบุตรชาย อย่าเพิงเอ่ยถึงฮองเฮา ราชโอรสของหนิงไฉเหยินกับสู\nกุ๊ย\"เฟยล้วนเติบโตเป็นผู้ใหญ่ ต่างก็เพาะกำลังของตนเอง แม้แต่อี๋กุ้ยผิงที\nเบืองหน้าก็มีชาติตระกูลสูงส่ง ทั้งมีกำลังหนุนจากตระกูลฟ่านที่เบืองนอก\nแต่ว่าองค์ชายสามอายุเยาว์เกินไป\nหลังจากนิงเงียบงันชั่วขณะ ฟ่านเสียนก็บอกเล่าเหตุการณ์ทีวิหาร\nทุบคงออกไป\nถึงแม้ทราบจากปากคําบุตรชายแล้ว แต่อีกุ้ยผิงยังรับฟังด้วยความ\nตสั้นขวัญแขวน สองมือกําผ้าเช็ดหน้าไว้ คล้ายหวันวิตกว่าคนร้ายที่ปะปน\nแย่ในกลุ่มราชองครักษ์จะฟันบุตรชายตัวเองเสียชีวิตในดาบเดียว\nหลังจากฟังจบ นางค่อยกล่าวอย่างแค้นเคืองว่า “คนร้ายปะปนอยู่\nไนกลุ่มราชองครักษ์ได้อย่างไร ราชองครักษ์วังหลวงทําการสืบประวัติย้อน\nทวนขึ้นไปถึงสามรุ่น”\nฟ่านเสียนกล่าวว่า “สมควรไม่ได้มุ่งเป้าไปที่เหล่า ” มันยิมพลาง\nเล่าวถามว่า “ข้าพเจ้าสามารถเรียกเป็นเหล่าซัน (อันดับสาม) หรือไม่?”\n“ท่านมีศักดิเป็นเกอเกอ (พีชาย) เรียกอย่างไรก็ได้\nฟ่านเสียนอธิบายว่า “คนร้ายนั้นอาจถือโอกาสฆ่าเหล่าซัน แต่เป้า\nหมายที่แท้จริงของมันยังเป็นฝ่าบาท อิท่านวางใจ ถึงแม้ตอนนี้ไทจือเกิด\nความตื่นเต้นตึงเครียด ความสัมพันธ์ระหว่างข้าพเจ้ากับเหล่าเอ้อ (อันดับ\n) ก็ไม่ดีนัก แต่เหล่าซันยังเยาว์วัย สมควรมิใช่เป้าหมายอันดับแรกของ\nพวกมัน”\nคําพูดนี้บอกกล่าวในวัง ออกจะขวัญกล้าบังอาจไป ถงแมวารอบหอ','2026-04-17 09:49:10'),(159,10,156,'อินฟงไม่มีคนแอบฟัง แต่อี๋กุ้ยผิงยังหน้าแปรเปลี่ยนไป ยิมอย่างไม่ แ\nธรรมชาติอยู่บ้าง\nทีนางหวันวิตกคือ ไม่ทราบว่าในวังมีคนคิดร้ายต่อบูตรชายตั๒\nหรือไม่ ยามนี้ได้ยินฟ่านเสียนแยกแยะเช่นนี้ ค่อยคลายใจลง\nบอกเล่าผลการสืบเสาะต่อฟ่านเสียน เนื่องจากนางมีการติดต่อกับทางป\nวางหูตาอยู่นอกวังไม่น้อย จึงทราบความคืบหน้าของเหตุการณ์เป็นอย่า!\nก่อนอืนอี๋กุ้ยผิงแจ้งว่า “กงเตียนถูกจับตัวแล้ว\nฟ่านเสียนส่งเสียงดังอืมม์ ไม่สะท้านสะเทือนเท่าใด อีกุ้ยผิงใช้คํา0\nจับตัว หมายความว่าราชสำนักมีข้อสรุปแล้ว แต่ก็ไม่ประหลาดใจ ในฐาน:\nผู้บัญชซาการทหารรักษาพระองค์ควบตําแหน่งหัวหน้าราชองครักษ์ ขณะท่\nเกิดเหตุการณ์ปลงพระชนม์บนวิหารฮุ่ยคง กลับไม่อยู่ข้างพระวรกายฮ่องเต้\nคาศัยเหตุผลข้อนี้ ก็เพียงพอให้กงเตียนถูกกระชากลงจากตําแหน่ง\nที่ฟ่านเสียนให้ความสนใจคือ ตอนนั้นหัวหน้าราชองครักษ์ที่เลอ:\nเลื่อนงมงายผู้นี้ทําอะไร?\nอีกุ้ยผิงกล่าวว่า “มันอยู่ที่เขตลัวโจวทางใต้ของมหานครสีสิบลี มัน\nกลิบายว่าได้รับราชโองการให้ไปทํางาน”\nนางทางหนึ่งกล่าวทางหนึ่งแสดงความเคลือบแคลงสงสัย ต่อให้\nกงเตียนคิดแก้ข้อกล่าวหา ก็ไม่อาจบอกว่าได้รับราชโองการ คําแก้ตัวนิพอ\nพาถงหน้าพระพักตร์ ก็ถูกกล่าวเปิดโปง\nนางกล่าวเสริมว่า “แต่ว่าไปทําอะไร สำนักตรวจสอบไต่สวนอยู่สอง\nน สุดท้ายไม่ได้บอกกล่าวอย่างชัดแจ้ง”\nฟ่านเสียนสูดลมหายใจเข้าไปคําหนึ่ง ทอดถอนใจกล่าวว่า “ข้าพเจ้า\nความจริงทราบว่ากงเตียนเป็นคนเทียงตรง แต่นึกไม่ถึงว่ามันจะโง่เขลา\nอด์วี้ว\nเงเพยงน','2026-04-17 09:49:10'),(160,10,157,'ฟ่านเสียนสั้นศีรษะทอดถอนใจกล่าวว่า “เมื่อมิใช่ฝ่าบาทมี\nราฑโองการให้มันไปทํางานที่เขตลั้วโจว อย่างนั้นคงเป็นท่านนั้น ปัญหา\nแผู่ที่เมื่อเกิดเหตุการณ์ปลงพระชนม์ มันไฉนขนข้ายท่านนั้นออกมา ต่อให้\nฝ๋แขนย้ายออกมา ฝ่าบาทต้องไม่ยอมรับ รังแต่เป็นเหตุให้มันตายเร็วกว่า\nอี้กุ้ยผิงไม่อาจปรับตัวเข้ากับการใช้ถ้อยคําที่เปิดเผยอุกอาจของฟ่าน\nเสียน ต้องฝืนยิ้มพลางกล่าวว่า “พวกเรา อย่าได้ยุ่งเกี่ยวกับเรื่องเหล่านี้\nฟ่านเสียนทอดถอนใจกล่าวว่า “ถูกแล้ว พวกเราไม่มีคุณสมบัติยุ่ง\nคราครงนตระกูลเยยเคราะหรายแลว ไม่ทราบสืบประวัติของคนร้าย\nคคกหรือไม่?”\nอกุ้ยผิงกล่าวว่า “คนร้ายที่ลงมือคนแรกซึ่งเป็นยอดฝีมือชันที่เก้า\nทเสียชีวิต ฟังว่ามาจากวังจัวเสียนอ้องแห่งซีหู แฝงตัวอยู่ในรัฐชิงมาสิบสี\nปแล้ว”\nฟ่านเสียนกล่าวอย่างสงสัยใจว่า “ไฉนเกียวข้องกับซีหู ชาวหู ไฉน\nกยู่ในวังเป็นเวลานานโดยไม่ถูกพบเห็น?”\nอิกุ้ยผิงกล่าวว่า “คนผู้นิมีความเป็นมาอยู่บ้าง” นางลําดับความคิด\nแล้วค่อยอธิบายบอกกล่าวให้ทราบ\nฟ่านเสียนค่อยทราบว่า คนร้ายชนชาติหูตะวันตกที่ตายใต้เงื่อมมือ\nหงกงกงผู้นี้ เป็นทายาทรุ่นหลังของชนชาติหูตะวันตกเมื่อตอนรัฐชิงแรก\nตั้งประเทศ ตอนนั้นชนชาติหูตะวันตกถูกรัฐชิงโจมตือย่างหนัก ฝ่ายตรง\nข้ามเคยคิดยอมอ่อนน้อม ถึงกับจัดส่งคณะทูตเชือมสัมพันธ์ผ่านทางสมรส\nขนชาติหูตะวันตก\nฑาวจีนเรียกคนต่างชาติเป็นชาวหู','2026-04-17 09:49:10'),(161,10,158,'มาถึงมหานคร แต่ถูกรัฐชิงปฏิเสธ จึงเดินทางกลับไปยังพื้นที่ตะวันเย .\nไม่ถึงจะทิงยอดฝีมือผู้หนึ่งอยู่ในมหานคร จากนั้นเลือกเวลานี้ก่อเหตณ่เ\nฟ่านเสียนถามว่า “ฝ่ายตรงข้ามไฉนปะปนเข้าวังมาอยู่ในตําแหน\nราชองครักษ์ เป็นผู้ใดดําเนินการจัดการ?”\n“ผู้ดําเนินการเสียชีวิตตั้งแต่แรก จึงกลายเก้ไนนก\nปริศนา”\nฟ่านเสียนลอบชูนิวหัวแม่มือในใจ ในที่สุดนับว่าคลําพบเบาะแสง\nหนึ่ง ปากกล่าวว่า “ขันทีน้อยยังมีชีวิตอยู่ ด้วยฝีมือของสำนักตรวจสก\nสมควรสืบเสาะทราบได้”\nอิกัยผิงผงกศรษะกล่าวว่า “ขันทีน้อยเป็นทายาทของเชอพระวงศา\nเสียชีวิตในเหตุการณ์นองเลือดเมื่อสิบห้าปีก่อน ตอนนั้นในมหานครมีคแ\nตายมากมาย ดังนั้นบ่าวไพร่ทีรับใช้เชือพระวงศ์จึงอุ้มมันหลบหนี้\nมันเพิงถือกําเนิดไม่นาน จึงไม่ได้ขึ้นทะเบียนสํามะโนครัว บ่าวไพร่แน\nสมควรฆ่าตัวตาย ต่อมาทารกนั้นถูกชาวนาทีชานเมืองผู้หนึ่งอุ้มไปเลียง๓\nหลังจากนั้นตอนตัวเองเข้าวัง”\nฟ่านเสียนกล่าวถามว่า “มีดสันเล่มนั้นถูกซ่อนไว้ได้อย่างไร?” มัน\nเห็นว่านี้เป็นปัญหาที่แท้จริง ขันทีน้อยนั้นสมควรวางแผนเชนนี้ไม่ได้\nคําพูดหลังจากนี้ของอิกุ้ยผิงได้หักล้างความคิดของมันว่า “เมื่อสาง!\nก่อนขันทีน้อยรับมอบหมายให้ปัดกวาดชันบนของวิหารฮุ่ยคง จึงซ่อนมี๓\nสันไว้ตั้งแต่ตอนนั้น สำนักตรวจสอบสืบค้นถึงตัวคนจัดทํามีดสัน ยืนยัน\nกําหนดเวลาได้”\nฟ่านเสียนขมวดคิว ที่แท้ขันทีน้อยเป็นคนทีรอดชีวิตจากเหตุการณ์\nนองเลือดเมื่อสิบห้าปีก่อน มันทราบว่าคําคืนนองเลือดนั้นเป็นฮ่องเต้ เฉิน\nผิงผิงและบิดาลงมือล้างแค้นให้กับมารดา เชือพระวงศ์หลายฝ่ายถูกขุดราก\nถอนโคน ในมหานครไม่ทราบมีคนตายมากน้อยเท่าใด แม้แต่ตระกูลของ','2026-04-17 09:49:10'),(162,10,159,'ตกงเสาก็ถูกฆ่าทึ่ง คงเหลือพระนางอยู่ในวังแต่ผู้เดียว ไม่ทราบว่าเบือง\nหผังของขันทีน้อยผู้นี้หมายถึงอันใด?\nชนชาติหูตะวันตก เชือพระวงศ์ที่ถูกขุดรากถอนโคน คนเหล่านี่มี\nใตหูประสงค์และความกล้าหาญปลงพระชนม์ฮ่องเต้จริง แต่ว่าเหตุใดรวม\nตํงกันอย่างประจวบเหมาะถึงเพียงนี้?\nฟ่านเสียนกล่าวถามว่า “ทางตระถูลเยียมีปฏิกิริยาใด?”\nอิกุ้ยผิงยืมพลางกล่าวว่า “เยียฉงทําหนังสือขออภัยโทษรวมแปด\nยิงไม่กล้ากลับเขตติงโจว หากรังอยู่ในตึก กระทั้งทหารคนสนิทในตึก\nก็ส่งมอบให้สำนักว่าการมหานครดูแลแทน ระมัดระวังถึงที่สุด ดูว่าฝ่าบาท\nจงะจัดการอย่างไร”\nฟ่านเสียนก็ยิมออกมากล่าวว่า “นี้ขึ้นอยู่กับว่าเยียหลิวหวินจะกลับ\nงเหานครหรือไม่”\nทั้งสองยังคิดกล่าวกระไร พลันได้ยินเสียงคนดังแว่วมา จึงเปลี่ยน\nเป็นสนทนาถึงเรื่องอืน ก่อนอื่นฟ่านเสียนขออภัยทีเหตุการณ์ของหอ\nโถบจันทร์กระทบถึงตึกกว้อกง อิกุ้ยผิงก็เป็นตัวแทนของตึกกว้อกง กล่าว\nขอบคุณฟ่านเสียนอบรมสังสอนลูกหลานกว๊อกง มิให้ถลําลึกกว่านี้\nทั้งผู้เหย้ากับผู้เยือนสนทนาอย่างยิมแย้ม ค่อยแยกจากกัน\n“สนทนาว่ากระไร?”\nหลินว่านเอ้อมองดูอิ๊กุ้ยผิงจูงมือองค์ชายสามออกจากอุทยานเหมย\nกล่าวด้วยความประหลาดใจว่า “เหนี้ยงเหนี้ยงท่านนี้พอใจอยู่แต่ในวัง\nวันนี่ใฉนตื่นเต้นอยู่บ้าง?\nฟ่านเสียนยิมพลางกล่าวว่า “เด็กน้อยเติบใหญ่แล้ว ผู้เป็นมารดา\nไหนเลยนิงนอนใจได้ รอจนภายหน้าพวกเราให้กําเนิดทารก ท่านจะเข้าใจ','2026-04-17 09:49:10'),(163,10,160,'หลินว่านเอือมีสีหน้ากระอักกระอ่วน จากนั้นครุ่นคิดว่าท้องข๓เ\nตัวเองไม่มีอาการผิดปรกติใด แต่ตอนนี้เซียงกงรับบาดเจ็บ ไม่สะดวกป็\nการกล่าวอันใด ได้แต่ฝืนแย้มยิม หันเหหัวเรื่องว่า “ทีเบืองนอกเป็นอย่างไ ,\nใช่ปันป่วนจนแทบถล่มทลายหรือไม่?”\nฟ่านเสียนลดสุ้มเสียงแผ่วเบาลง บอกข่าวสารที่ทราบจากอี๋กุ้ยก\nต่อนาง พลางกวาดมองขันทีนางกํานัลทีอยู่ห่างไปแวบหนึ่ง กล่าวว่า “ลง\nเย็นกว่าเดิมแล้ว พวกเรากลับห้องกันเถอะ”\nหลินว่านเอ้อกับฟ่านเย่อเย่อทราบว่ามีเรื่องบางประการไม่อาจบแ!\nกล่าวต่อคนรับใช้ในวัง จึงผงกศีรษะรับ บอกให้ขันทีมายกตั้งเตียงไป\nเมื่อกลับเข้าห้อง ฟ่านเสียนนอนบนเตียงใหญ่ ลืมตามองดูเพดาแ\nมุ้ง ชั่วครู่จึงกล่าว “ท่านคาดว่าตระกูลเยียจะมีสภาพอย่างไร?”\nยามนิภายในห้องไม่มีบูคคลอืน จึงไม่มีข้อห้ามใด กล่าวตรงๆ ว่า\n“กงเตียนคงได้รับราชโองการใด ค่อยไปยังเขตลัวโจว แต่ต้องมิให\nราชโองการฮ่องเต้ ไม่เช่นนั้นกงเตียนโอดครวญออกมา แม้แต่ฝ่าบาทก็ไม่\nสามารถโต้แย้งได้”\nมันรู้สึกมีความหนาวเย็นแผ่ซ่านจากใจกล่าวว่า “หมากตานี้แม้เหลว\nไหลอยูบ้าง แต่ก็ได้ผล ไทเฮามีบัญชาลับให้กงเตียนไปทํางานที่เขตลัวโจว\nมันเป็นผู้บัญชาการทหารรักษาพระองค์ ย่อมต้องรุดไป แต่แล้วกลับเกิด\nเหตุการณ์ปลงพระชนมับนวิหารฮุ่ยคง หากทําการไต่สวน กงเตี่ยนให้การ\nว่าได้รับบัญชาลับไทเฮาออกจากมหานคร ไยมิใช่ป่าวประกาศว่าเป็น\nไทเฮาคิดฆ่าฮ่องเต้ หากกงเตี่ยนไม่คิดถูกประหารเก้าชั่วโคตร คําพูดนี้\nได้แต่กล้ากลืนไว้ในท้อง”\nหลินว่านเอ๋อกับฟ่านเย่อเย่อล้วนฉลาดหลักแหลม ย่อมไม่เห็นว่า\nฮองไทเฮามีส่วนเกี่ยวข้องกับการปลงพระชนม์บนวิหารฮุ่ยคง หลินว่าน\nเอ้อกล่าวด้วยความกลัดกลุ้มว่า “ท่านหมายความว่ากงเตียนไปยังเขต','2026-04-17 09:49:10'),(164,10,161,'ผงใจว เป็นแผนการร่วมของไหว้จู่มู่ (พระอัยกี) กับฝ่าบาท?”\nฟ่านเสียนส่งเสียงดังอืมม์\nฟ่านเย่อเย่อขมวดคิวกล่าวว่า “ไยต้องทําเช่นนี้?”\nฟ่านเสียนแค่นหัวร่อกล่าวว่า “กงเตียนเป็นผู้บัญชาการทหารรักษา\nพระองค์ ทั้งเป็นศิษย์น้องของเยียฉง คราครังนี้มันเคราะห์ร้าย ตระกูลเยีย\nท่อมต้องรับเคราะห์ด้วย\nหลินว่านเอ๋อเป็นห่วงเป็นใยในเยียหลิงเอ้อทีเป็นเพื่อนหญิง\nทอดถอนใจกล่าวว่า “ตระกูลเยียจงรักภักดีตลอดมา เหตุใดฝ่าบาทจึง ”\nนางไม่ได้กล่าวจบ แต่ทั้งหมดล้วนฟังออก ฟ่านเสียนก็ทอดถอนใจ\nเล่าวว่า “หากฝ่าบาทไม่ระแวงในความจงรักภักดีของตระกูลเยีย คงไม่\nเลือกกระทําเช่นนี้ ตอนนี้เมื่อระแวงสงสัย ได้แต่ให้ตระกูลเยียไปยืนอยู่\nต้านข้าง อย่างน้อยไม่อาจให้มันสองศิษย์พืศิษย์น้องเฝ้ารักษามหานครอีก\nต่อไป ประเด็นสำคัญคือตระกูลเยียมีปรมาจารย์ท่านหนึ่ง ตราบใดทีเยีย\nหลิวหวินยังไม่ตาย ต้องไม่อาจโยกคลอนตระกูลเยียได้”\nมันทอดถอนใจแล้วกล่าว “ดังนั้นได้แต่ดําเนินแผนเช่นนี้ นี้ไม่กลัว\nสร้างความผิดหวังแก่ขุนนางทั้งหลายหรือ?”\nหลินว่านเอ้อกล่าวถามว่า “เหตุใด ฝ่าบาทจึงระแวงสงสัยตระกูล\nฟ่านเสียนบอกกล่าวว่า “ฝ่าบาทพระราชทานสมรสแก่องค์ชาย\nรองกับเยียหลิงเอฮ้อ หากว่าเยียฉงวิเคราะห์ออก ตอนนั้นสมควรตอบ\nปฏิเสธ ต่อให้มันเห็นด้วยกับพิธีสยุมพร ก็สมควรลาออกจากตําแหน่ง\nแม่ทัพใหญ่รักษาการณ์มหานคร แม้ไม่ถึงกับปลดเกษียณ ก็สมควรย้าย\nตัวเองไปยังแนวหน้า เพื่อให้ฝ่าบาทคลายพระทัย แต่มันไม่ทําอะไรทั้งสิน\nดังนั้น ”\nหลินว่านเอ๋อกับฟ่านเย่อเย่อผงกศีรษะด้วยความสะท้อนใจ ฟ่าน','2026-04-17 09:49:10'),(165,10,162,'เย่อเย่ออดกล่าวมิได้ว่า “เรื่องราวช่างสลับซับซ้อนยิง”\nฟ่านเสียนกล่าวว่า “ตอนอยู่ที่แคว้นเปยฉี ข้าพเจ้าก็คาดเดา2\nมีวันนี้ แต่นึกไม่ถึงว่าฝ่าบาทจะใจแคบ เลือกวิธีเช่นนี้\nหลินว่านเอ้อพลันกล่าวว่า “เช่นนี้เป็นว่าเหตุการณ์ปลงพระชนงา๒\nวิหารฮุ่ยคงเป็นเรื่องที่อยู่ในความคาดหมายของฝ่าบาท?\nฟ่านเสียนมองดูนาง กล่าวว่า “เพียงไม่ทราบว่าเรื่องทั้งหมดล้1แก,\nในความคาดหมาย หรือว่าฝ่าบาทเพียงวางแผนบางส่วน”\nหลินว่านเอ้อจับจ้องมองตามัน กล่าวช้าๆ ว่า “ในชีวิตฝ่าบาทไ\nนิยมเสียงอันตราย ดังนั้น อย่างมากเพียงแค่วางเพลิง”\nสองสามีภรรยาจับจ้องมองกันนิงนาน คล้ายบังเกิดความกลัวอยู่ป์!\nหากว่าฮ่องเต้วางเพลิงทีชันล่างของวิหารฮุ่ยคง อย่างนั้นปฏิบัติการหล\nจากนั้นเป็นแผนของผู้ใด?\nฟ่านเสียนหลับตาลงช้าๆ กล่าวเบาๆ ว่า “การจัดการของคนร้าย\"\nแยบคายไปแล้ว แยบคายจนข้าพเจ้าไม่เชือว่า นี้เป็นแผนการที่หน่วยงาแ\nหนึ่ง หรืออีกหลายหน่วยสามารถกําหนดขึ้น”\nมันกล่าวเสริมว่า “นี้เพียงเป็นความบังเอิญ เพียงเพราะคนร้ายพ่\nซ่อนตัวอยู่ในวังพบว่า สถานการณ์บนวิหารฮุ่ยคงเหมาะกับการก่อหวอต\nของพวกมัน ดังนั้นไม่ได้นัดแนะ และไม่ได้วางแผน การปลงพระชนม์อย่าง\nต่อเนืองจึงปะทุขิน\nสุดท้ายมันบอกต่อตนเองว่า “แสดงแน่ชัด นี้เป็นสภาวะเซียนวิเศษ\nเป็นสภาวะเซียนวิเศษที่ฝ่าบาทคาดไม่ถึง\nในสิงปลูกสร้างอันเย็นเยือกซึ่งอยู่ห่างจากวังหลวงเม่ไกลเท่าใด เฉิน\nผิงผิงนั่งบนเก้าอิล้อเลือน ไม่ปริปากกล่าววาจา หัวหน้าตึกทั้งเจ็ดก็นิง\nเงียบงัน ไม่ทราบสมควรกล่าวอันใด ฮ่องเต้ประสบเหตุปลงพระชนม์','2026-04-17 09:49:10'),(166,10,163,'แยจงากทหารรักษาพระองค์ต้องรับผิดชอบโดยตรงแล้ว สำนักตรวจสอบ\nต็ต้แงแบกรับผลเช่นกัน\nหากมิใช่ใต้เท้าถีซือซึ่งตอนนี้นอนรักษาตัวอยู่ในวังกอบกู้สถาน\nแกรเนไว้ อาจบางทีสำนักตรวจสอบคงมีสภาพเช่นเดียวกับตระกูลเยีย รอ\nให้ไแว้งยืนมือมาบีบเค้นคอหอยตนเอง\nเอียนปิงหวินซึ่งเข้ารับตําแหน่งหัวหน้าตึกทีสือย่างเป็นทางการ\n(เพ่าวทําลายความเงียบสงัดของห้องลับว่า “คนร้ายชนชาติหูตะวันตกที่ฝัง\n1กยู่ในกลุ่มราชองครักษ์ ขนทนอยทรอดชวตจากเหตุการณนองเลอด\nเมกสบห้าปก่อน และผู้ที่เล่าลือว่าเป็นตีตี (นองชาย) ของกระบสท์ศนา\nเ1 !แไปไม่ได้ที่บุคคลเห ลานจะรวมตวกนกอหวอดเชนน ยงมอคคทชนลาง\nเป็นผู้ใดจุดขึ้น จนบัดนี้ยังสืบไม่ออก ตามขาวทุกสายแจงมาวา องครกษ\nเท ๐ เซ ซ่\nเส่อแพรแคว้นเปยฉียังอยู่ในสภาพระสําระสาย ไม่มีเวลาเตรียมการเรื่องนี่\nแคตรตงอีก็ไม่มีวีแววว่าคิดอ่านวางแผนอันใด\nผู้รักษาการแทนหัวหน้าตึกที่หกก็กล่าวเสียงเย็นชาว่า “มิหน้าซํา\nเรื่องที่กระบีสีทัศนามีติตีคนหนึ่งเป็นเพียงข่าวลือ ไม่ว่าผู้ใดก็ไม่ทราบว่า\nคนผู้นี้ดํารงคงอยู่จริงหรือไม่”\nตึกที่สองสำนักตรวจสอบมีหน้าที่รวบรวม และแยกแยะข้อมูล\nหัวหน้าตึกที่สองจึงกล่าวด้วยสีหน้าละอายว่า “นี้ไม่มีข้อมูลอันใด ถึงแม้\nเป็นความบกพร่องของผู้น้อย แต่ผู้น้อยเห็นว่าคิดวางแผนสังหารเช่นนี่ ต้อง\nมีการติดต่อสือสารกัน พวกเราสมควรเกาะกุมเบาะแสบางส่วนได้ แต่ก็ไม่มี\nเบาะแสแม้แต่น้อย เราเห็นว่าฝ่ายตรงข้ามไม่ได้พบปะหารือกัน ถึงกับ\nกล้าลงความเห็นว่า คนร้ายเหล่านั้นไม่รู้จักกันมาก่อน”\nเฉนผงผงทนงบนเกาอลอเลอนลมตาขนชาๆ ใช้สายตาทีชุ่นมัว\nมองดูเหล่าผู้ใต้บังคับบัญชาพลางครุ่นคิด ฝ่าบาทสังคนวางเพลิง ย่อมไม่\nปล่อยให้พวกท่านจับตัวได้ คนร้ายชนชาติหตะวันตกกับขันทีน้อยทีอกอาจ','2026-04-17 09:49:10'),(167,10,164,'มีแต่ภูตผีจึงทราบว่าผุดโผล่จากที่ใด ฝ่าบาทกับเราหาใช่เซียนวิเศษง1\nท่านผู้เฒ่าอ้าปากหาวคําหนึ่ง กล่าวว่า “นี้เป็นสภาวะเซขียนวิเศษ )\nต้องขบคิดมากความแล้ว”','2026-04-17 09:49:11'),(168,10,165,'ผู้ทียผู่เบี๊ชนหลับ\nสำนักตรวจสอบจัดทําหนังสืออ่านประกอบสำหรับบุคคลภายในไว้\nยกตัวอย่างเล่มที่ห้าจะรวบรวมบันทึกคดีต่างๆ ทําการคัดเลือกคดีที่เป็นเชิง\nสัญลักษณ์ อรรถาธิบายตั้งแต่เริมต้นเตรียมการ ขันตอนทีดําเนินการ ความ\nเปลี่ยนแปลงกลางคัน จนถึงผลท์เกิดขึ้น\nเลมทหานมบนทกคดมากมาย จากนนอาศยระบบขอมูลของสานก\nบวกกับหลักฐานที่ค้นได้จากในเรื่อง ทําความเข้าใจกับสิงทีเรียกว่าแผน\nอุบาย ค้นหาสาเหตุทีแท้จริง\n\' บญูขบ\nแต่ก็มีบางคดีทีผู้คนได้แต่ขุดคุ้ยด้านหนึ่งด้านใดของเรื่องราว ไม่\nสามารถอธิบายสิงทีเกิดขึ้นทั้งหมด เพราะเหตุนี้หน้าสุดท้ายของหนังสือ\nเล่มทีห้าจะเขียนข้อความหนึ่ง ซีงเป็นข้อความทีฟ่านเสียนกับเฉินผิงผิง\nคุ้นเคยเป็นอย่างดี\nเป็นคําสภาวะเขซียนวิเศษ\nที่ว่าสภาวะเซียนวิเศษหมายความว่าในเหตุการณ์เกิดความ\nว ต ธ ล ๕ สฒา\nเปลี่ยนแปลงที่ไม่สามารถอธิบายด้วยเหตุผลทัวไป จนเกิดสภาวะที่แม้แต่\nเซียนวิเศษก็ไม่สามารถคาดเดาได้\nยกตัวอย่างเช่นครั้งกระโน้นเฉินผิงผิงนำทัพทมิฬดําเดินทางพันลี','2026-04-17 09:49:11'),(169,10,166,'จับตัวเซียวเอินซึ่งลอบเดินทางมาร่วมงานแต่งงานของบุตรชายได้\nตรวจสอบความจริงคํานวณรายละเอียดทั้งหมด ตลอดจนค่าตอบแท\'แพ่\nต้องจ่ายออกไปเอาไว้ แต่ในพิธีวิวาห์ เซียวเอินไม่ได้ดื่มสุราทีเฟยเจียผเบ\nขึ้น หากใช้สายตาที่สงบเยือกเย็นจนถึงขันเลือดเย็นอํามหิต\nรส ๑ ๕ ะ\nเหตุการณ์ทีเกิดขึ้นทั้งหมด\nขณะทีชาวชิงเข้าใจว่าแผนการครั้งนี่ไม่สามารถดําเนินตามขันตกน\nทีวางไว้ ก็เกิดความเปลี่ยนแปลงอย่างคาดไม่ถึง เซียวเอินได้ยินในห้1\nส่งตัวบังเกิดเสียงทะเลาะวิวาทดังลอดออกมา สร้างความอัดอันตันใจจ\nคิดดีมสุรา ที่ประจวบเหมาะคือหัวหน้าทหารคนสนิททีดูแลถุงสุราให้กับเก\nไม่อาจสะกดความอยากสูรา แอบดีมสุราไปจนหมดสิน เมื่อเซียวเอินร้อง\nขอสุรา หัวหน้าทหารคนสนิทนั้นจึงตวงสุราในงานเลียงส่งให้\nดังนั้นเซียวเอินถูกพิษ ดังนั้นเฉินผิงผิงกับเฟยเจียปฏิบัติการสําเวง\nจวบกระทั้งหลายปีต่อมา เฉินผิงผิงกับพวกค่อยทราบว่า เซียวเอินทีอัดอัแ\nตันใจ เพราะว่า บุตรชายมันสูญเสียสมรรถภาพทางเพศ\nความเปลี่ยนแปลงนี้ไม่ได้อยู่ในแผนการ แต่ส่งผลกระทบต่๓๒\nสถานการณ์โดยรวม\nยกตัวอย่างเมื่อยีสิบปีก่อน พ่อค้าเกลือทางใต้คนหนึ่งเสียชีวิตกลาง\nงานเลียงวันเกิด กรมราชทัณฑ์คลีคลายคดีไม่ได้ จึงโอนมาให้ตึกทีสีสำนัก\nตรวจสอบสะสาง มิคาดสืบไปสืบมา พบว่ามีผู้ต้องหาสิบสีคน รวมทั้งเหล่า\nอิไท่ไท่ (คําเรียกอนุภรรยา) ทั้งหลาย แต่ละคนคล้ายต้องการให้คหบดีผู้น่\nตกตาย\nแต่ว่าฆาตกรทีแท้จริงเป็นใคร\nผ่านไปอีกสามปี มีชายชรายากจนผู้หนึ่งขโมยเซาปิง ถูกจับกุมตัว\nส่งให้กับทางการ มันคงไม่ต้องการมีชีวิตสืบไป จึงยอมรับว่าพ่อค้าเกลือ\nขนมเปียะที่โรยหน้าด้วยงา','2026-04-17 09:49:11'),(170,10,167,'เมื่อสามปีก่อนตายใต้เงื่อมมือมัน คนของตึกที่สีสำนักตรวจสอบพอทราบ\nฆ่าวถึงกับทั้งอับอายทั้งขุ่นเคือง ครุ่นคิดว่ามืออาชีพเช่นตนเองไฉนปล่อย\nไห้ฆาตกรตัวจริงอยู่ลอยนวล พอเดินทางไปไต่สวนค่อยทราบกระจ่าง\nเมื่อวัยเยาว์ชายชรานั้นกับพ่อค้าเกลือบ้านอยู่ติดกัน เติบโตขึ้นมา\nด้วยกัน ต่อมาชายชรานั้นย้ายไปทีเขตอู่โจว พอกลับบ้านเกิดเห็นพ่อค้า\nเทลือจัดงานวันเกิด ไม่ทราบถูกผีร้ายใดเข้าสิง กลับปืนกําแพงเข้าลานตึก\nใช้ก้อนหินทุบพ่อค้าเกลือทีดีมจนเมามายตายคามือ\nสำนักตรวจสอบเคยตรวจพบร่องรอยปืนกําแพงตึก แต่นึกไม่ถึงว่า\nขายชราที่เพิงกลับบ้านเกิดมาผู้หนึ่งจะเสียงอันตรายปืนกําแพงเข้าไป\nก่คการร้าย โดยไม่ถูกบ่าวไพร่และนักบู๊เฝ้าดูแลตึกพบเห็น\nตอนนั้นเอี่ยนเย่อไห่ซึ่งยังไม่ได้รับตําแหน่งหัวหน้าตึกที่สีซักถามว่\n\"ตอนทีเรารับมอบคดี เป่าเจ็ง เคยสอบปากคําเจ้า เหตุใดเจ้าไม่ตื่นเต้น\nตดงเครยดแม่แตน้อย?\nชายชรานั้นตอบว่า “มีอันใดต้องตื่นเต้นตึงเครียด อย่างมากชดใช้\nซ่วตให้กับมัน\nเอียนเย่อไห่เพิงพบเห็นคนทีดุร้ายเช่นนี้เป็นครั้งแรก จึงซักถามด้วย\nความประหลาดใจว่า “เจ้าไฉนฆ่ามัน?”\nชายชรานั้นกล่าวอย่างขึงขังว่า “เมื่อวัยเด็กมันเคยตบหน้าเราฉาด\nหนึ่ง\nเหตุการณ์ปลงพระชนม์บนวิหารฮุ่ยคงก็คล้ายเป็นสภาวะเซียน\nฮ่องเต้เริมนึ้กระแวงสงสัยตระกูลเยีย แต่ว่าในตระกูลเยียมีบูคคล\nจะดับปรมาจารย์ท่านหนึ่ง จึงเดินหมากเช่นนี้ให้ร้ายอีกฝ่าย ทางหนึ่งแอบ\nตําแหน่งเทียบเท่ากํานั้น ผู้ใหญ่บ้าน','2026-04-17 09:49:11'),(171,10,168,'อ้างพระเสาวนี้ย์วังหลวงล่อกงเตียนออกไป ทางหนึ่งวางเพลิงเล็กๆ\nล่าง คาดว่าพระกํากับดูแลทักษิณกับเฉินผิงผิงคงทราบแน่แก่ใจว่าเป็น\nราวใด\nหลังจากทีเกิดเพลิงไหม้ ชันบนของวิหารเกิดความบันป่วนเล็กใก\nคนร้ายชนชาติหูตะวันตกนั้นเห็นเป็นโอกาสเหมาะ ในที่สุดอดลงมีคง์าไป\nมันฝังตัวอยู่ในวังสิบกว่าปี บังเกิดความคับข้องทรมาน ผ่านไปสามปี๊น0,\nสามปีเล่า ไม่ทราบเมื่อใดจึงยุติ ตอนนั้นหงกงกงอารักขาฮองไทเฮาลงฯง\"\nชันบน มันยังประเมินขีดความสามารถของฟ่านเสียนตําเกินไป เห็นตนแก\nอยู่ห่างจากฮ่องเต้ไม่กีก้าว จึงตัดสินใจลงมือ\nราซองครักษ์พอลงมือ ก็เปิดโอกาสให้กับมือกระบีชุดขาวนั้น\nมือกระบีชุดขาวพอลงมือ ขันทีน้อยทีเป็นทายาทของเชือพระวง\"\nซึ่งแฝงตัวอยู่ในวังเป็นเวลานาน เห็นฮ่องเต้หันพระขนองให้ หวนนึกถึงม์ ๒\nสันที่ซ่อนอยู่ในเสาไม้ห่างจากตนเองเพียงหนึ่งก้าว นับเป็นโอกาสที่ฟี!\nประทาน ภายใต้การเย้ายวนเช่นนี่ ความคิดแก้แค้นจึงปะทุขืน\nนับตั้งแต่ฮ่องเต้วางเพลิง เหล่าผู้คนทีซ่อนตัวอยู่ในความมืดล้วนผูห\nออกว่านี้เป็นโอกาสให้ฉกฉวย ขึ้นชื่อว่าคนร้ายย่อมเป็นชนชันอันกล้าหาน\nถึงแม้ไม่มีส่วนเกียวข้องมาก่อน แต่ก็เลือกจังหวะเวลาลงมือ อันว่าช่วย\nเหลืออีกฝ่ายเพื่อตอบสนองตนเอง ขอเพียงปลงพระชนม์ฮ่องเต้รัฐชิง พวก\nมันไม่เสียดายกับการสละชีวิต แต่ต้องฉกฉวยโอกาสนิให้ดี\nพวกมันมาจากคนละทิศละทาง เพื่อเป้าหมายเดียวกัน กลับเดินมา\nบรรจบพบกัน สอดประสานกันอย่างกลมกลืน\nวิกาลคล้อยดึก ฟ่านเสียนนอนบนเตียง มองดูเพดานมุ้ง ไม่ว่า\nอย่างไรก็นอนไม่หลับ ระหว่างที่พักรักษาตัวในวัง มันนอนกลางวันมากเกิน\nไปแล้ว','2026-04-17 09:49:11'),(172,10,169,'แสงไฟในวังริบหรี มันจับจ้องมองม่านมุ้งอันเบาบาง คล้ายคิดฉีก\n(จะซากม่านมุ้ง เห็นความจริงที่ซ่อนอยู่ทางด้านหลัง\nหลินว่านเอ้อหลับใหลแล้ว นางอยู่ห่างจากตนเองช่วงใหญ่ กลัวว่า\nยามหลับขยับตัว กระทบถูกปากแผลทีหน้าอกตนเอง ฟ่านเสียนเหลียว\nมกงนางแวบหนึ่ง ใช้สายตาลูบไล้ผมดําขลับที่สยายอยู่บนหมอนหนุนด้วย\nความเวทนา ภายในวังเงียบสงบยิง ขันทีทั้งหลายเข้านอนแล้ว นางกํานัล\nผู ไว . ซู ;\nทเข้าเวรฟุบหลับกับเก้าอิ้บูแพร ฟ่านเสียนจึงช้อนตามองท้องฟ้า\nพีมพํากับตนเอง\nมันเพียงขยับเขยือนริมฝีปาก ไม่ได้ส่งเสียงออกมา ทําการตั้งคําถาม\nต่อตนเอง พร้อมกันนั้นก็สะสางต้นสายปลายเหตุของเรื่องราว\n\"คนร้ายชนชาติหูตะวันตกกับขันทีน้อยทีซ่อนตัว เป็นพยานที่ตาย\nแล้วและมีชีวิตอยู่ ดังนั้นข้อวินิจฉัยของสำนักตรวจสอบสมควรไม่มีปัญหา\n\'แต่ว่าอิงจือ (เงา) เล่า นอกจากตนเองแล้ว คงไม่มีผู้ใดทราบว่า\nกระบีชุดขาวนั้นเป็นหัวหน้าตึกที่หกทีมีชีวิตอยู่ในความมีด ไม่เคยมีคนเห็น\nหน้าค่าตามาก่อน เป็นมือสังหารเงาทีร้ายกาจที่สุดของรัฐชิง\nนี้เป็นสภาวะเซียนวิเศษหรือ เป็นสภาวะทีฮ่องเต้กําหนดขึ้น เพื่อ\nผิดรอนขุมกำลังในมหานครของตระกูลเยีย มิให้จับมือกับจ่างกงลู่ได้\n\'คาดว่าแม้แต่ฮ่องเต้ก็เห็นว่าเราบีบคันเหล่าเอฮ้อเกินไป มิหน้าซํา\nพระองค์คงทราบว่าปีหน้าเราจะลงมือต่อทางแดนซินหยาง\nนึกถึงตอนนี้ ฟ่านเสียนต้องสูดลมหายใจเข้าไปอย่างหนาวเหน็บ ไม่\n๑ เซซี ๑\nทราบปากแผลปวดแปลบขึ้นมา หรือบังเกิดความตินตระหนกต่อฝีมืออัน\nตําช้าของฮ่องเต้รัฐชิง\n\' , เร ซ่ เ ๑ ๑ .ข\nต่อจากนั้นฟ่านเสียนนึกถึงคนขาเป้นั้น มันเชือว่าเฉินผิงผิงต้องดู\nออกว่าผู้ทีสร้างสภาวะเป็นฮ่องเต้เอง','2026-04-17 09:49:11'),(173,10,170,'\'อย่างนั้นท่านคิดทําอะไร หากว่าเราถามท่าน ท่านคงนั่งบนเก\nล้อเลือน บอกว่าตอนอยู่ที่สวนอุทยานเฉิน เราบอกแล้วว่าเรื่องทีเกี่ยวซัเก.\nกับฮ่องเต้ เราจะจัดการเอง\n\'หลังจากทีเกิดเหตุเปลี่ยนแปลง ท่านยังมีกะใจส่งตัวอิงจือ (เงา) !\nปลงพระชนม์ เพื่อให้ตนเองรับบทวีรบุรุษหรือ?\n“เรื่องราวรวบรัดเพียงนี่หรือ\nในฐานะนักฆ่าอันดับหนึ่งของรัฐชิง อิงจือ (เงา) สามารถตบตาห\nส \" น รวซี\nกงกงได้ นี้เป็นเรื่องที่อยู่ในความคาดหมาย แต่ฟ่านเสียนไม่เชือว่าถา\nลงมือของอิงจือ เพียงเพื่อสร้างสภาวะให้ตนเองช่วยชีวิตฮ่องเต้จนรับบ\nเจ็บ เพื่อเป็นที่โปรดปรานของฝ่าบาท\nความเคลือนไหวนี้ใหญ่เกินไป ผลรับไม่มากพอ ไม่สอดรับกับนิสก\nใจคอของเฉินผิงผิง ดังนั้นฟ่านเสียนมีความรู้สึกว่าเฉินผิงผิงมีเรื่องใดปิด1\nตนเองไว้\n\'หากบอกว่าท่านคิดปลงพระชนม์ฮ่องเต้ นี้ไม่สามารถกล้อมแกล้ง\n1 ่ 1 ๕ เจซ่ ซ เซ่ «๑ ๕\nไปได้ อย่าเพิงบอกว่าสูนัขที่ซื่อสัตย์เปลี่ยนเป็นไม่ซือสัตย์ขึ้นมา แต่ด้ก\nขุมกำลังของท่าน หากคิดปลงพระชนม์ ต้องสร้างสภาพแวดล้อมทีสมบูรย\nพร้อมกว่านี้ ท่านคิดทดสอบราชโอรสทั้งหลายให้กับฮ่องเต้หรือ เราถล่ะ!\nมารดาท่าน สูนัขเฒ่าเช่นท่านยุ่งเกียวมากความไปแล้ว มิหน้าซําฮ่องเต\nไม่ต้องการรับความตระหนกเช่นนี้\'\nมันนึกไปนึกมา ตนเองถูกกักอยู่ในสภาวะไม่สามารถหลุดพันออก\nมา ได้แต่ทอดถอนใจ หลับตาลงอย่างช้าๆ แต่แม้กระทั้งยามหลับผัน มัน\nผังเชือว่าพันธมิตรเก่าแก่ของมารดาต้องซ่อนความคิดอยู่ส่วนลึกของจิตใจ\nไม่เปิดโอกาสให้ผู้ใดดูออกได้\n“โลกนี้ไม่มีสภาวะเซียนวิเศษ”','2026-04-17 09:49:11'),(174,10,171,'มูซับ 4 2 ููื ซ่\nเฉินผิงผิงนั่งบนเก้าอิล้อเลือน กล่าวกับคนใช้แถบผ้าสีดําปิดตา ซึ่ง\nกยู่ในดงไม้ของสวนอุทยานเฉินว่า “ท่านเองก็ทราบว่า ในบันทึกเล่มที่ห้า\nเอ่ยถึงการตายของพ่อค้าเกลือนั้นว่า ชายชราทีแย่งชิงเซาปิงสามารถฆ่า\nพ่อค้าเกลือโดยง่ายดาย เพราะว่าบ่าวไพร่และนักบู๊พิทักษ์ตึกทั้งหลายถูก\nบรรดาอิเหนี้ยง (คําเรียกอนุภรรยา) ซื้อตัวไปแต่แรก พวกนางยินดีทีมีคน\nช่วยกระทําเรื่องนี้ให้กับพวกนาง\n“ชายชรานั้นที่ลงมือต่อพ่อค้าเกลือ มิใช่เพราะพ่อค้าเกลือตบหน้า\nมันเมื่อหลายปีก่อน\n“สาเหตุที่แท้จริงคือ ครั้งกระโน้นพ่อค้าเกลือนั้นแย่งชิงภรรยาของ\nชายชรานั้น ความแค้นของการแย่งชิงภรรยาใหญ่หลวงกว่า\n“มิหน้าซําอย่าได้เชือว่าเอียนเย่อไห่สืบความจริงไม่ออก ความจริง\nแล้วเราท่านล้วนทราบว่า ครั้งกระโน้นบรรดาอนุภรรยาของพ่อค้าเกลือมอบ\nตัวเงินห้าหมืนตําลึงแก่มัน”\nเฉินผิงผิงกล่าวสรุปว่า “ดังนั้นไม่มีสภาวะเซียนวิเศษอันใด เรื่อง\nทั้งหมดเกิดจากการจัดฉากของผู้คน ต่อให้ระหว่างนั้นเกิดเหตุเปลี่ยนแปลง\nแทรกซ้อน ก็อยู่ในการคํานวณของเรา หากไม่สามารถคํานวณได้ ตอนนี้\nฝ่าบาทคงเสียชีวิตแล้ว”\nอู่จู๋กล่าวอย่างเฉือยชาว่า “ในโลกไม่มีเหตุการณ์ที่ควบคุมได้โดย\nเด็ดขาด\nเฉินผิงผิงกล่าวว่า “เรายอมรับว่าการปรากฏตัวของคนร้ายชนชาติ\nหูตะวันตกกับขันทีน้อยนั้น สร้างความปันป่วนแก่แผนการของเรา แต่ยัง\nดีที่ไม่ส่งผลกระทบต่อความปลอดภัยของฝ่าบาท\nอู่จู้กล่าวว่ “ฟังจากปากคําท่าน เราไม่สามารถตรวจสอบออกว่า\nท่านมีความจงรักภักดิต่อฮ่องเต้อย่างเติมเปียม”\nเฉินผิงผิงยิมพลางกล่าวว่า “เราจงรักภักดีต่อฝ่าบาท แต่ก็เพื่อผล','2026-04-17 09:49:11'),(175,10,172,'ประโยชน์ของฝ่าบาท เราไม่ถือสาทีฝ่าบาทได้รับความตื่นตระหนกยป )\nอู่จูกล่าวว่า “ ฉลประโยชน์อันใด เป็นคนรับช่วงทีเป็นผู้ใหญ่เตง๒,\nหรือ?” อาจบางทีมีแต่อยู่ต่อหน้าคนรู้จักมักคุ้นเช่นเฉินผิงผิง อู่จู้จึงพูตง1\nเป็นพิเศษ\nเฉินผิงผิงกล่าวอย่างจริงจังว่า “นี้เป็นการวางแผน การเมืองเป\nขันตอนของการวางแผน ฝ่าบาทคิดไล่ตระกูลเยียออกไป เพียงแค่วางเพน\nยังไม่พอ”\nอู่จู้กล่าวอย่างเฉือยชาว่า “ท่านเห็นว่าหากฮ่องเต้องค์นี้ล่วงรู้คา 1)\nจริงทั้งหมด จะเชือคําอธิบายของท่านหรือ?”\nเฉินผิงผิงสันศีรษะกล่าวว่า “ขอเพียงเอือประโยชน์แก่ฝ่าบาท\nได้รับความเชือถือหรือไม่ หาใช่เรื่องสลักสำคัญไม่”\nอู่จู้เชือว่ามันกับเฟยเจียล้วนเป็นเฒ่าวิปริต จึงกล่าวเบาๆ ว่า “ฮ่องเต\nของท่านแทบตกตายแล้ว”\nเฉนผงผงคุนกบคาเรยกหาทหมนพระบรมเดชานุภาพน นบตงแต\n๕ 1 เจ ท เซ๑ ๆข ๐ ! 4 1 ซ\nหลายปีก่อนก็เป็นเช่นนี้ อู่จู้ไม่มีวันใช้คําว่าฝ่าบาทเช่นเดียวกับผู้คนทัวไป\nเฉินผิงผิงกล่าวอย่างหนักแน่นว่า “ฝ่าบาทไม่มีวันตาย นี้เป็นความ\nเชือของเรา อย่าลืมว่าฝ่าบาทจะไม่ให้ผู้คนล่วงรู้ไพ่ใบสุดท้ายที่พระองค์ถือ\nลู่จู๋เอียงศีรษะกล่าวว่า “มันตายหรือไม่ เราไม่กังวลสนใจ ที่เรากังวล\nสนใจคือ มันเกือบตายแล้ว”\nคํามันทั้งสองคํา แสดงออกถึงท่าทีที่แตกต่างของถู่จู๋\nเฉินผิงผิงฝืนยิมออกมา มันย่อมทราบว่าฟ่านเสียนรับบาดเจ็บสาหัส\nจะเป็นเหตุให้อู่จู้กลายเป็นเครื่องจักรสังหารที่น่ากลัวเพียงไหน ต่อให้มัน\nลกซึ่งชั่วร้ายกว่านี้ ยามเผชิญหน้ากับอู่จู้ที่กระด้างเย็นชา ส่วนลึกของจิตใจ\nยังเกิดความเย็นเยียบแผ่ซ่านออกมา ดังนั้นมันทดลองอธิบายว่า “ฟ่าน','2026-04-17 09:49:11'),(176,10,173,'เสียนหวันวิตกว่า การผูดขึ้นมาอย่างรวดเร็วของมัน จะสร้างความระแวง\nสงพัยแก่ฝ่าบาทหรือไม่ ดังนั้นเราเตรียมการครั้งนี้ เพื่อขจัดความเคลือบ\nแคลงสงสัยของมัน แน่นอน ขณะที่เราเริมดําเนินการ ไม่สามารถคาด\nเตาตอนจบของเรื่องได้”\nมนยมออกมา คล้ายภาคภูมิใจที่ตนเองยังจําคําพูดที่ติดปากคุณหนู\nก 1 ๒ ง ณา บสรบบโว น\nเมื่อครั้งกระโน้น จากนั้นกล่าวสืบต่อ “ถึงแม้ว่านี้มีส่วนเกี่ยวข้องกับอิงจือ\n(เงา) มันคิดต่อยตีกับท่าน แต่ท่านไม่เปิดโอกาสแก่มัน ดังนั้นยากนักทีมี\nโถกาสประมือกับศิษย์ของท่าน มันความจริงไม่อาจหักใจลงมือ แน่นอน\nหากฟ่านเสียนไม่ไล่ตามมา จนรับบาดเจ็บสาหัส อย่างนั้นเรื่องนี้ก็ไม่มี\nคุณค่าความหมายถึงเพียงนี้\nอู่จู๋พลันกล่าวว่า “ท่านเรียกตัวอิงจือ (เงา) มา เราจะให้โอกาสมัน\nต่อยตีกับเรา”\nคําหยอกล้ออันเย็นชานี้ เป็นเหตุให้เฉินผิงผิงส่งเสียงไอออกมา\nชั่วครู่ค่อยแบมือทั้งสอง อธิบายว่า “นี้เพียงเป็นอุบัติเหตุเท่านั้น”\nลูจูกลาวตรงๆ วา “หากว่าเพียงเป็นอุบัติเหตุ เหตใดก่อนที่เราจะไป\nถึง มันชิงหลบหนี้จากไป?”\nใบหน้ายับย่นของเฉินผิงผิงเต็มไปด้วยรอยฝืนยิม ไอเป็นเวลานาน\nค่อยสงบลง กล่าวว่า “นี้เป็น เราสังการไว้ เพราะว่าเราหวันวิตกว่าท่าน\nไม่ยินดี ทําให้มันได้รับอุบัติเหตุใด ควรทราบว่าที่ข้างกายเรามีคนใช้สอย\nเช่นนี้อยู่คนหนึ่ง หากว่าท่านฆ่ามันทึง เราเฒ่ากระดูกผูกร่อนจะมีชีวิต\nสืบไปได้อย่างไร?”\nอู่จูไม่กล่าวกระไร ลมราตรีโชยพัดแถบผ้าสีดําของมันกระพือพลิว\nแสดงออกถึงความไม่พอใจของมัน\nเฉินผิงผิงตอบแทนด้วยการกล่าวอย่างจริงจังว่า “หลังจากทีเราตาย\nแล้ว อิงจือจะติดตามรับใช้มัน”','2026-04-17 09:49:11'),(177,10,174,'อูจูเอยงศรษะ คล้ายใคร่ครวญว่าฟ่านเสียนจะยอมรับการขะ เ\nหรือไม่ จากการวิเคราะห์ของมัน ฟ่านเสียนหาเป็นคนนิยมความงายยแย\n๐ (เซ ซ่ขุขยรจั \'\nอํานาจไม่ ต้องเกิดความสนใจต่อนักฆ่าทีอยู่เหนือชันทีเก้าผู้นื้อย่างแน่เนอ\nอู่จู๋เงี่ยบจันชั่วขณะจึงกล่าว “ท่านลงใต้ไปหาเราจนพบ บอก1\nมหานครมีเรื่องน่าเล่นให้เราชมดู หรือว่าเป็นละครฉากนี้?\nเฉินผิงผิงกล่าวว่า “ฟ่านเสียนบอกว่าท่านไปเล่นที่ทางใต้\nจริงเข้าใจว่ามันหลอกเรา คิดไม่ถึงท่านอยู่ทางใต้จริงๆ ถือเป็นคง1\nประจวบเหมาะ”\nมันโน้มตัวไปข้างหน้ากล่าวว่า “เราตระเตรียมให้ท่านชมดูละคร 11\nเสียดายที่เราประเมินขีดความสามารถของฟ่านเสียนตําเกินไป แผ:\nประเมินความไร้ยางอายของฟ่านเจียนตําเกินไป เฒ่าทารกนี้ทราบแล้ว1\nฝ่าบาทเป็นคนวางเพลิง ยังบอกให้ฟ่านเสียนรีบขึ้นไปอารักขา ” มันหัว4ก\n๕ ณะ เทย ๕ . เซ ,\nเสียงแหลมเล็กกล่าวอีกว่า “ท่านไม่ได้เห็นฉากนี้ ช่างน่าเสียดายนัก\nอู่จู๋เงยหน้าขีนช้าๆ กล่าวว่า “ท่านคิดฆ่าไทเฮา\nเฉินผิงผิงส่ายหน้ากล่าวว่า “ไทเฮาจะอย่างไรเป็นไหน่ไหน ( :\nอัยกี) ของฟ่านเสียน ถึงแม้ว่าในเหตุการณ์ที่เกิดขึ้นกับคุณหนู พระนางนิง\nเฉยดูดาย ไม่ให้ความช่วยเหลือต่อนิเวศน์สันติสุข แต่ถึงอย่างไรไม่ได้มี\nส่วนร่วม จนบัดนี้ที่เราสีบออกได้ ยังไม่สามารถยืนยันอันใด\nส่ายหน้ากล่าวอย่างเฉือยชาว่า “หากว่าภายหน้าท่านสืบทราบ\nหรือว่าเราพบเห็นอันใด ไม่ว่าฟ่านเสียนทําอย่างไร เราจะทําเช่น\nยันใด\nเฉินผิงผิงกล่าวว่า “เราก็จะกระทํา\" คําพูดนี้แสดงออกถึงการ\nตัดสินใจ แต่ยังสันศีรษะกล่าวว่า “เหล่าอู่ (อันดับห้า) ถึงแม้ท่านเป็นบุคคล\nที่น่ากลัวที่สุดในโลก แต่ยังอย่าได้ประเมิน ขุมกำลังของประเทศหนึ่ง และ\nาังหลวงหลังหนึ่งตําเกินไป มิหน้าซําเราเมื่อเป็นหัวหน้าสำนักตรวจสอบ','2026-04-17 09:49:11'),(178,10,175,'ตด้แงพิจารณาถึงการสืบทอดต่อไปของรัฐชิง”\nมันยิมพลางกล่าวว่า “อย่าลืมว่านี้เป็นปณิธานของคุณหนู ส่วนเรื่อง\nไห้สาระเหล่านี้ปล่อยให้เรากระทําเถอะ”\nอู่จู๋กล่าวถามว่า “อย่างนั้นท่านตระเตรียมให้เราชมดูอะไร?”\nเฉินผิงผิงทอดถอนใจคําหนึ่ง กล่าวด้วยความอ้างว้างอยู่บ้างว่า \'ใน\nเม็กละครฉากนี้ไม่ได้ร่วมแสดง อย่างนั้นก็ไม่ต้องกล่าวอีกแล้ว\nปฏิกิริยาของอู่จู้ต่างกับผู้คนทัวไป กลับไม่มีความสนใจซักไซ้ไล่เลียง\nพลันหมุนตัวไป ตระเตรียมกลืนหายกับความมืด\nเฉินผิงผิงทอดถอนใจทีด้านหลังมัน กล่าวว่า “หลังจากทีท่านนำ\nเส้าแหย (นายน้อย) ไปยังอ่าวต้านโจว พวกเราก็ไม่ได้พบหน้ากันอีก” มัน\nเหล่าวยําว่า “ไม่พบกันสิบเจ็ดปี ตอนนี้รีบร้อนคิดจากไปแล้ว?”\nคู่จู้ชะจักงันเล็กน้อย จากนั้นกล่าววาจาที่แห้งแล้งว่า “ถนอมตัว”\nกล่าวจบกลืนหายกับความมีด แต่ด้วยนิสัยใจคอของอู่จู๋ สามารถให้\nมันกล่าวคําถนอมตัว นับเป็นเรื่องที่หายากยิง อย่างน้อยเฉินผิงผิงเกิด\nความอบอุ่นใจวูบหนึ่ง\nบ่าวชราประจําสวนอุทยานเฉินเดินเข้ามาเข็นเก้าอิล้อเลือนกลับ\nห้อง เฉินผิงผิงไม่ทราบครุ่นคิดอันใด ต้องทอดถอนใจด้วยความพึงพอใจ\nกล่าวว่า “ท่านลองบอกมา สามารถหลอกล่อให้ราชองครักษ์กับขันทีน้อย\nทีมีความอดทนเป็นเลิศลงมือ เราถือเป็นคนที่ร้ายกาจหรือไม่ แต่ว่านี้ต้อง\nขอบคุณคนร้ายชาวซีหูนั้น หากว่ามันเห็นฟ่านเสียนขึ้นวิหารมา ตัดใจแฝง\nตัวต่อไป เรื่องนี่ก็ไม่น่าสนุกสนานแล้ว”\nบ่าวชรานั้นฝืนยิมพลางกล่าวว่า “ใต้เท้าเอียนจ่าง (หัวหน้าสำนัก)\nไม่เคยคํานวณผิดพลาดมาก่อน”\nเฉินผิงผิงรําพึงรําพันว่า “ช่างลําบากตรากตรํานัก ต้องคอยถอนดึง\nตะปูให้กับฝาบาทตลอดเวลา”','2026-04-17 09:49:11'),(179,10,176,'หลังจากพักรักษาตัวในวังอีกระยะหนึ่ง จวบกระทั้งนำค้างแข็งห\nหนก มีวีแววว่าหิมะจะตกลงจากฟ้า ภายใต้คําร้องขอของฟ่านเสียน\nรัฐชิงค่อยทรงอนุญาตให้มันกลับบ้าน\nภายหลังเหตุการณ์ถวายการอารักขาบนวิหารฮุ่ยคง\nทีมีลูกตา สามารถดูจากเหตุการณ์ที่ฟ่านเสียนพักรักษาตัวในวัง พบว่าฟ่าแ\nเสียนไม่เพียงเป็นที่โปรดปรานดังเดิม ทั้งยังเหนือกว่ากาลก่อน แต่กาไข้\nร่างกายตนเองต้านทานกระบีคร่าชีวิตไว้ ค่อยแลกมาซึ่งการโปรดปราน 1\nได้สร้างความอิจฉาตาร้อนแก่ผู้คนมากเกินไป เพียงแค่ขอบตาร้อนผ่าเ\nเท่านั้น\nวันทีฟ่านเสียนออกจากวัง ตําหนักต่างๆ ล้วนจัดส่งของขวัญลําค่\nมา แม้แต่ฮองเฮาก็ไม่มีข้อยกเว็น โดยเฉพาะของขวัญจากสูกุ้ยเฟย ผู้เป๊น\nมารดาบังเกิดเกล้าขององค์ชายรองหนาหนักเป็นพิเศษ\nแม้แต่ฮองไทเฮายังพระราชทานไข่มุกป้องกันคุณไสยซึ่งทรงใช้ม\nเป็นเวลาสิบกว่าปี เหนี้ยงเหนี้ยง (พระชายา) ทั้งหลายไหนเลยกล้าเพิก\nเฉยได้\nฟ่านเสียนครึ่งนั่งครึ่งนอนในรถม้า ถึงแม้ว่าบาดแผลทีหน้าอกยัง\nไม่หายดี แต่อย่างน้อยสามารถพลิกตัวได้ มันเลิกม่านหน้าต่างรถ อาศัย\nแสงสว่างจากภายนอก มองดูไข่มูกอันกลมเกลียงในมือ หยีตาลงครุ่นคิด\nหรือว่าไหน่ไหน (พระอัยกี) ขนานแท้ยอมรับการคงอยู่ของตนเองแล้ว?\nตลอดรายทางหลินว่านเอ๋อกับฟ่านเย่อเย่อยินดีทีสุด หลังจากจับเจ่า\nอยู่ในวังนานวัน นับว่าน่าเบืออยู่บ้าง มิหน้าซําอาการบาดเจ็บของฟ่าน\nเสียนดีวันดีคืน ช่วยให้หญิงสาวทั้งสองคลายใจลง\nรถม้าแล่นถึงประตูใหญ่ของตึกตระกูลฟ่าน มีคนปู่แผ่นไม้อยู่บน\nบันไดตั้งแต่แรก ตึกตระกูลฟ่านเปิดประตูใหญ่ราวกับรับราชโองการ ให้รถ','2026-04-17 09:49:11'),(180,10,177,'ฝีแล่นเข้าไป\nโดยทัวไปแล้วรถม้าไม่สามารถเข้าทางประตูใหญ่ แต่ว่าต้าเส้าแหย\nจ1กทเาดเจ็บถึงเพียงนี่ ย่อมต้องจัดการเช่นนี้\nรถม้าแล่นตรงถึงข้างตึกหลัง เถิงจือจิงกับพวกช่วยกันแบกยกฟ่าน\nเสียนลงมา ซือซือดูความเรียบร้อยอยู่ด้านข้าง นางไม่มีคุณสมบัติเข้าวัง\nหลายวันนี้อยู่บ้าน สร้างความร้อนรุ่มใจอย่างมาก\nฟ่านเสียนเห็นนางหน้าแดงเรือ จึงกล่าวสัพยอกอยู่หลายคํา พอ\nเหลี่ยวหน้าไป ก็เห็นบิดากับนางหลิวซือ\nฟ่านเสียนพบว่าเปลือกนอกของบิดาแสรังเป็นสงบนิง แต่ดวงตา\nทอแววห่วงใย สร้างความอบอุ่นใจจนกล่าวเบาๆ ว่า “ท่านพ่อ ข้าพเจ้า\nกลับมาแล้ว”','2026-04-17 09:49:11'),(181,10,178,'','2026-04-17 09:49:11'),(182,10,179,'ยนท์หายไหญ่มาเยียน\nเรื่องราวเป็นไปตามที่ฟ่านเสียนคาดคิดไว้ ปรมาจารย์แห่งรัฐิ่งที่\nออกท่องเที่ยวไม่ได้กลับมหานคร ตระกูลเยี่ยจึงยอมรับการจัดการ ถอน\nตัวออกจากระบบรักษาการณ์มหานคร แน่นอน พวกมันทิ้งกำลังส่วนหนึ่ง\nอยู่ในระดับกลางถึงล่าง แต่ก็ไม่เพียงพอกับการกําหนดสถานการณ์ได้\nหากว่าหลังจากเกิดเรื่องนี้ เยี่ยหลิวหวินเดินทางกลับมหานคร\nช่องเต้ที่เปลือกนอกเมตตากรุณาอาจแสดงด้านที่ดุดันอํามหิตออกมา โดย\nยอมสูญเสียกำลังของประเทศ แต่ต้องขจัดตระกูลเยี่ยออกไป ไม่เช่นนั้น\nหากปล่อยให้ชาติตระกูลหนึ่งคุมมหานครเอาไว้ หลังจากนี้ยังจะเป็นทอง\nแผ่นเดียวกับองค์ชายสูงศักดิ์ อย่างนั้นก็ต้องสะกดเอาไว้\nสุดท้ายเยี่ยหลิวหวินไม่ได้กลับมหานคร หมายความว่าตระกูลเยี่ย\nยอมรับสถานการณ์เฉพาะหน้า ฮ่องเต้ทรงเห็นแก่หน้าเยี่ยหลิวหวิน และ\nทรงเห็นว่าตระกูลเยี่ยยังจงรักภักดี จึงไม่สร้างความลําบากแก่ตระกูลเยี่ย\nเกินไป เยี่ยฉงยังรั้งอยู่ที่เขตชังโจว ทั้งไม่ลดบรรดาศักดิ์ทางทหารแต่\nอย่างไร\nแม้แต่กงเตี่ยนที่ชื่อตรงจนน่ารัก กระทําความผิดใหญ่หลวงถึงเพียง\nนี้ ฮ่องเต้ก็ไม่ได้ทรงลงโทษอย่างเฉียบขาด เพียงปลดมันออกจากตําแหน่ง','2026-04-17 09:49:11'),(183,10,180,'ฟาดโบยมันสามสิบที ลดฐานะเป็นสามัญชนคนธรรมดา\nตระกูลเยี่ยมีความรู้สึกว่าไม่ได้รับความเป็นธรรม แต่เพื่อความเทแร\nของรัฐชิ่ง พวกมันได้แต่ยอมเสียสละ ดีที่สามารถฉวยโอกาสออกจายเน็นก่\nมหานคร ไม่แน่ว่าจะเป็นเรื่องร้าย\nความจริงแล้วผู้ที่บังเกิดความผิดหวัง สมควรเป็นจ่างกงจู่แห่งย\nซิ่นหยาง กับองค์ชายรองซึ่งถูกจํากัดบริเวณอยู่ในวัง\n“ช่างเหลวไหลจริงๆ”\nฟ่านเสียนอ่านดูรายงานที่มู่เถี่ยส่งมา ต้องสันศีรษะคราหนึ่ง ตวะ0\nเยี่ยถอนตัวออกจากการรักษาการณ์มหานคร เป็นเรื่องที่คนในราชส์เน่น\nต่างจับตามอง ปรากฏว่าตําแหน่งรักษาการณ์มหานครตกเป็นของฉินเพ\nส่วนตําแหน่งผู้บัญชาการทหารรักษาพระองค์กับหัวหน้าราชองควัก\nความจริงเป็นบุคคลคนเดียวควบสองตําแหน่ง กลับถูกฮ่องเต้ผ่าเป็นส๓\nตําแหน่งหัวหน้าราชองครักษ์ว่างลงชั่วคราว ตามรายงานข่าวจ\nในวัง สมควรให้ขันทีเฒ่าหงกงกงรักษาการแทน\nสวนผู้ ญชาการทหารรกษาพระองคกลบ เป็นองค์ชายใหญ่\nฟ่านเสียนทีบอกว่าเหลวไหล หมายถึงพระบัญชาข้อนี้ ตามบันทึก\nประวัติศาสตร์ น้อยครั้งจะมืองค์ชายใดรับตําแหน่งผู้บัญชาการทหารรักษา\nพระองค์ เหตุผลคือกลัวว่าองค์ชายผู้นี้จะนำกำลังในมือลูกฮือก่อกบฏ แต่\nฮ่องเต้พานแต่งตั้งองค์ชายใหญ่เป็นผู้บัญชาการทหารรักษาพระองค์ ขณะ\nที่วังตะวันออกยังมีไทจืออยู่ ฮ่องเต้พระองค์นี้ที่แท้ทรงดําริอย่างไร มารดา\nขององค์ชายใหญ่หนิงไฉ่เหยินเป็นชาวตงอี ไม่ว่าอย่างไรตําแหน่งนี่ไม่ควร\nตกเป็นของมัน\nมู่เถียไม่กล้าแสดงความเห็น เพยงรายงานงานการของตกทหนง','2026-04-17 09:49:11'),(184,10,181,'ตู่กฟ่านเสียน เห็นสีหน้าของใต้เท้าถึซืออิดโรยอยู่บ้าง จึงอําลาจากไป\nซือฉ่างลีก็กล่าวว่า “เหล่าซือ (ท่านอาจารย์) ยังคงพักผ่อนเถอะ\nเป็ททยู่ร่วมกันเป็นส่วนตัว มันยังคุ้นกับการเรียกหาฟ่านเสียนเป็นเหล่าซื้อ\nแทนที่จะใช้คําใต้เท้า เห็นสีหน้าของฟ่านเสียนขาดเลือด จึงกล่าวด้วยความ\nเจ็บปวดใจว่า “ฝ่าบาทมีพระราชกระแส ท่านมิต้องถามไถ่กิจการในสำนัก\nสามเดือน แสดงว่าให้ท่านพักผ่อนให้ดี ท่านพานไม่ฟัง\nเหล่าซื่อเป็นทีโปรดปรานถึงเพียงนี้ มันที่เป็นลูกศิษย์พลอยภาค\nบมิใจอยู่บ้าง\nฟ่านเสียนสันศีรษะด่าอย่างยิมแย้มว่า “ท่านไม่อยู่ที่หอโอบจันทร์\nทุกจันวิงมาทีห้องหนังสือข้าพเจ้าทําอะไร?\nซือฉ่างลสีฝืนยิมพลางกล่าวว่า “รังอยู่ทีนั้น มีความรู้สึกว่าไม่ถูก\nฟ่านเสียนยิมพลางไล่มันออกไป พร้อมกับบอกให้มันตามตัวเติง\nงจ่อเวียเข้ามา\nเติงจือเวียพอมาถึง ฟ่านเสียนก็หน้าเคร่งขรืมลง กล่าวว่า “ทาง\nสำนักมีบทสรุปต่อมือกระบีชุดขาวนั้นอย่างไร?\nถึงแม้มันทราบว่าตอนนี้ตนเองไม่สามารถขุดคุ้ยความลับในใจเฉิน\nผิงผิงออกมา แต่ตนเองมีข้อมูลทีใกล้เคียงกับเฒ่าขาเป่นั้น กลับไม่ใช้\nคลีคลายปริศนา นับเป็นทีน่าเสียดายนัก\nเติงจือเวียสันศีรษะกล่าวว่า “ถึงแม้ว่าฝ่าบาทตอนอยู่บนวิหารฮุ่ยคง\nเปิดโปงศักดิฐานะของฝ่ายตรงข้าม แต่ว่า ” มันฝืนยิมพลางกล่าวว่า\nใต้เท้าท่านก็ทราบว่าฝ่าบาทมิใช่ชาวยุทธจักร คํารับสังไม่อาจถือเป็น\nบรรทัดฐาน กระบีสีทัศนามีติตี (น้องชาย) ผู้หนึ่งจริง แต่หายสาบสูญไป\nนานปี ผู้คนทั้งแผ่นดินคาดเดาว่าอาจเสียชีวิตเมื่อตอนกระบีสีทัศนายืด\nครองนครตงอี ดังนั้นทางสำนักระมัดระวังต่อการแสดงความเห็น”','2026-04-17 09:49:11'),(185,10,182,'ฟ่านเสียนรู้สึกเหนือความคาดหมายอยู่บ้าง สำนักตรวจสอ1แน\nไม่ลบส่วนหางที่โผล่ออกมาทิงไป หรือเฉินผิงผิงเชือมันว่าไม่มีคนฝ่า\nโฉมหน้าแท้จริงของอิงจือ (เงา) ดังนั้นพานไม่กลบเกลื่อนอันใด\nเติงจือเวียกล่าวอีกว่า “แต่ว่า ฝ่าบาทเมื่อบอกว่านี้เป็นตีติของ\nสีทัศนา พวกเราเหล่าขุนนางก็ไม่สะดวกกับการคัดค้าน โดยเฉพาะไม่ท 11\nว่าฝ่าบาทพอรับสังออกมา ใช่จะส่งผลถึงสถานการณ์ภายภาคหน้าหรือไม\nฟ่านเสียนยิมออกมา รัฐซชิงนิยมการต่อสู้ เมื่อปีก่อนตนเองถูกล\nสังหารทีถนนหนิวหลาง ฮ่องเต้ฉวยโอกาสกรีธาทัพขึ้นเหนือยึดครองพี1เท่\nของแคว้นเปยฉีแถบใหญ่ ขุนนางทั้งหลายล่วงรู้ว่าฮ่องเต้นิยมยัดเยียดข๒ )\nหาข้ออ้างทําสงคราม ย่อมไม่สะดวกกับการอวดฉลาดไป\nหลังเหตุการณ์บนวิหารฮุ่ยคง ตามเหตุผลฟ่านเสียนสมควรไ1 ท่\nสำนักตรวจสอบไต่สวนขันทีน้อยนั้น หรือตรวจดูซากศพของคนร้ายชนชา\nหูตะวันตก แต่ก็ทราบว่านำในทีนี้ขุ่นมัว ตนเองไม่สมควรดําลึกเกินไป\nมีเหตุผลอีกประการหนึ่งคือ ในสภาพร่างกายตอนนี่ ญาติสนิททุกคนรวงเ\nทั้งบิดาไม่อนุญาตมันออกจากบ้าน\nมันเองก็ไม่กล้าออกไป ใต้เท้าเสียวฟ่านรักถนอมชีวิต ตอนนี้พลัง\nลมปราณภายในกายแตกซ่านหมดสิน ไม่ทราบเมื่อใดค่อยเก็บกุ๊กลับม1\nในความท้อแท้ผิดหวัง ยิงระมัดระวังความปลอดภัยส่วนตัวเป็นพิเศษ\nแน่นอน ฟ่านเสียนไม่เปิดเผยสภาพที่แท้จริงของตนเองต่อผู้ใด\nประตูห้องหนังสือถูกผลักเปิดออกดังแอ๊ด องครักษ์ทีเฝ้าประตูกลับ\nไม่มีปฏิกิริยาใด ฟ่านเสียนนอนอยู่บนเตียงเหลียวหน้ามอง เห็นเป็นว่าน\nเอ้อกับเม่ยเม่ยเอง\nเตงจอเวยเหนสูหยนกบเมยเมยม สีหน้าโกรธเคือง ทราบว่าตนเอง\nสมควรไปแล้ว จึงน้อมคํานับแล้วล่าถอยออกไป เป็นเหตุให้ฟ่านเสียนไม่มี','2026-04-17 09:49:11'),(186,10,183,'โอกาสให้มันถ่ายทอดวาจาให้เอี่ยนปิงหวินรุดมาสักครา\nหญิงสาวทั้งสองเปลี่ยนยา ป้อนตัวยาให้กับมัน ทางหนึ่งกล่าวว่า\n\"บอกแล้วว่าจะพักรักษาตัว พานไม่ยอมอยู่นิง”\nฟ่านเสียนฝืนยืมพลางกล่าวว่า “คาดว่าตั้งชือไม่ดี ดังนั้นไม่ยอมอยู่\nชื่อเสียนแปลว่าอยู่ว่าง แต่นับแต่ฟ่านเสียนออกจากวังกลับถึงบ้าน\nตึกตระกูลฟ่านก็กลายเป็นตัวตึกที่คึกคักที่สูดของมหานคร ตลอดทั้งวัน\nปรากฏขุนนางสามสำนักหกกรมมาเยียมไข้ใต้เท้าถีซื้อไม่ขาดสาย ยังมีคน\nบุญหนักศักดิใหญ่มาเยือน ถนนทิศใต้หน้าตึกตระกูลฟ่าน ปรากฏรถม้า\nแน่นขนัด กล่องของขวัญสุมซ้อนนับไม่ถ้วน\nผู้ทีมายังตึกตระกูลฟ่านจัดส่งตัวยาอันลําค่า และอาหารบํารุงมา\nฟ่านเสียนคนเดียวไหนเลยรับประทานหมดสิน นอกจากตัวยาทีลําค่าแล้ว\nทีเหลือล้วนส่งไปยังหอโอบจันทร์\nเหตุการณ์ปลงพระชนม์ทีวิหารฮุยคง หนุนส่งให้ฟ่านเสียนขึ้นเป็น\nขุนนางใหญ่อีกครั้ง บวกกับมันรังตําแหน่งถีซือสำนักตรวจสอบ ยิงเสริม\nความมันคงแก่มัน สร้างความครันคร้ามแก่เหล่าขุนนางรัฐชิง\nขุนนางทั้งหลายไม่ได้หูหนวกตาบอด ฟ่านเสียนหลังจากรับบาดเจ็บ\nก็ถูกรังตัวอยู่ในวังนานวัน มิหนำซํามีข่าวจากในวัง คําคืนที่ฟ่านเสียนรักษา\nบาดเจ็บ ฮ่องเต้คล้ายไม่ได้บรรทมแม้สักงีบเดียว พระมหากรุณาเช่นนี้\nคล้ายมีแต่เฉินผิงผิงเทียบเปรียบได้\nขณะที่ผู้คนจํานวนมากประจบสอพลอตึกตระกูลฟ่าน แท้จริงแล้วใน\nใจไม่ยอมรับนับถือ โดยเฉพาะคนหนุ่มทีอาจหาญต่างนึกอิจฉาฟ่านเสียน\nโชคดีเกินไป ขณะที่เกิดเหตุการณ์ปลงพระชนม์ฮ่องเต้ เหตุใดตนเองไม่อยู่\nฟ่านเสียนกล่าวว่า “ครั้งนี้ทางบ้านรับเงินทองไม่น้อย” นี้มิใช่เรื่อง','2026-04-17 09:49:11'),(187,10,184,'ล้อเล่น เมื่อชาติปางก่อนฟังว่านายอําเภอท่านหนึ่งล้มป่วย ได้รับเงน\nจํานวนหลายหมืน อย่าว่าแต่ตนเองเป็นขุนนางใหญ่ ทั้งอยู่ในรัฐชิงซึ่งก\nติดสินบนกลายเป็นเรื่องธรรมดา\nหลินว่านเอฮ้อยิมพลางกล่าวว่า “แต่ว่าสร้างความลําบากแก่เหล่าแหย\n(นายผู้เฒ่า) แล้ว” นางมีศักดิฐานะสูงส่ง ย่อมไม่ใส่ใจกับการประจบสอพล\nของขุนนางทั้งหลาย\nฟ่านเสียนอยู่ระหว่างการพักรักษาตัว ไหนเลยมีอารมณ์ออกไ1!\nต้อนรับขุนนางทีมาเยียมไข้ แท้จริงแล้วคิดแสดงมิตรไมตรี แต่ว่าขุนนาง\nบางคนมีความเป็นมาใหญ่หลวง จึงสร้างความลําบากแก่ฟ่านสังซู (ขุนนาง\nสังซูแซ่ฟ่าน) ทุกวันนอกจากดูแลงานประจําแล้ว เวลาส่วนใหญ่หมดไปกัา\nการต้อนรับแขกเหรือ\nฟ่านเย่อเย่อกล่าวตัดพ้อว่า “คนเหล่านี้มาครั้งเดียวยังพอทําเนา\nกลับหมุนเวียนกันมาอีก ช่างน่าขุ่นข้องรําคาญนัก”\nหลินว่านเอฮ้อคล้ายนึกได้อันใด จึงกล่าวอย่างยิมแย้มว่า “ขุนนางกรง!\nต่างๆ ยังดีอยู่ ที่น่ากลัวคือหมอหลวงนั้น ท่านผู้เฒ่ามีความอดทนเป็นเลิศ\nมาทั้งสินสีครัง ท่านไม่ยอมพบกับมัน สุดท้ายถ่ายทอดวาจาถึงมันว่า ท่าน\nจะไม่เข้าสังกัดตึกไท่อี (ตกหมอหลวง) มันยังไม่เลิกล้มความตั้งใจ เมอค1\nได้ยินเถิงจือจิงบอกว่าวันนี้หมอหลวงมาอีกแล้ว นั่งแช่อยู่ในห้องข้างไม่\nยอมจากไป น้ำชาถ้วยหนึ่งกลายเป็นจืดชีด เหล่าแหยปรายตาบอกใชบ้ มัน\nกลับแสร้งเป็นมองไม่เห็น\nนางทอดถอนใจกล่าวว่า “ช่างเป็นบุคคลอันร้ายกาจจริงๆ”\nฟ่านเสียนฝืนยิมออกมา แม้ไม่กล่าวกระไร แต่ในใจนับถือเลือมใส\nหมอหลวงหน้าด้านอันดับหนึ่งของรัฐชิงผู้นั้นจนหมดใจ\nคําคืนที่อยู่ในวัง ตอนแรกหมอหลวงไม่มีความเชือมันต่อวิชาแพทย์\nของตนเอง แต่ตอนอยู่ในตําหนักกว่างซิน กลับแอบดูแอบฟัง ต่อมาพบเห็น','2026-04-17 09:49:11'),(188,10,185,'วิชาแพทย์พิสดารของฟ่านเสียน ก็คิดฉุดลากฟ่านเสียนเข้าตึกไท่อี อย่าง\nน้อยให้ฟ่านเสียนถ่ายทอดวิชาแพทย์ประหลาดให้ กลับแวะเวียนมาหา ยืน\nกรานไม่ยอมกลับไป\nในสายตาของหมอหลรรงรัฐชิง วิชาผ่าตัดย่อมลึกลําพิสดาร แต่ฟ่าน\nเสียนทราบดีว่าตอนนั้นตนเองเพียงมีชะตากล้าแข็ง นอกจากนี้ยังมีประเด็น\nสำคัญ ทําให้วิชาความรู้แขนงนี้ยากจะแพร่หลายออกไป\nฟ่านเสียนเหลียวมองเม่ยเม่ยที่พันผ้าพันแผลให้กับตนเองอย่าง\nระมัดระวังแวบหนึ่ง พลันนึกถึงความเป็นไปได้บางประการ จากนั้นสัน\nศีรษะคราหนึ่ง\nคนในห้องหนังสือทั้งสามสงบปากคํา บรรยากาศกลมเกลียวยิง มิ\nคาดมีคนเคาะประตูเบาๆ ฟ่านเสียนต้องขมวดคิวเข้าหากัน\nทีหน้าประตูบังเกิดเสียงบ่าวไพร่ในบ้านดังว่า “มีแขกมาเยือน”\"\nคราครังนี้แม้แต่หลินว่านเอ้อก็ขมวดคิวกล่าวว่า “มิใช่บอกว่าไม่พบ\nผู้ใดหรอกหรือ?”\nแขกผู้นี้ไม่พบไม่ได้ ฟ่านเสียนฝืนยิมพลางมองดูองค์ชายใหญ่ทีมา\nโดยไม่เชือเชิญ กล่าวว่า “ตอนอยู่ในวังสะดวกยิง ต้าเตียนเซีย (องค์ชาย\nใหญ่) ไม่ไปเยียมข้าพเจ้าที่อุทยานเหมย วันนี้ไฉนมาแล้ว?”\nหลินว่านเอ้อก็เชิดปากขึ้น ตําหนิว่า “พีใหญ่ ตอนนิมีคนมามากมาย\nท่านก็มาร่วมวงด้วย?\nองค์ชายใหญ่มองดูนางอย่างอับจนบัญญา เม่ยเม่ยผู้นี้เป็นตนเอง\nเฝ้าดูจนเติบใหญ่ เพิงแต่งออกไปหนึ่งปี ก็ทุ่มเทชีวิตจิตใจให้กับบ้านของ\n” สญี เวไ\nจึงกล่าว “ไหนเลยมีเรื่องเชซ่นนั้น?”\nสองซงเม่ย (พี่ชายน้องสาว) ประคารมกันหลายคํา องค์ชายใหญ่\nพบกับความพ่ายแพ้ ได้แต่ใช้เคล็ดวิชาตัดต่อทาบกิง เปลี่ยนเป็นกล่าวว่า','2026-04-17 09:49:11'),(189,10,186,'“องค์หญิงใหญ่ก็ตามเรามา กำลังสนทนากับฟ่านฮูหยิน เฉินเม่ยเมีย (6!\nสาว) ท่านไปพบปะสักครา”\nองค์หญิงใหญ่ทีมันเอ่ยถึง ย่อมเป็นหญิงสาวที่ดันต้นมาจากแก\nเปยฉี เพื่อสยุมพรกับองค์ชายรัฐชิง ฟ่านเสียนรับฟังจนงงงันวูบ\nร ! ฆ «๑ ๕ ๕๕ &\nถึงว่าบุรุษสตรีคู่นี้ยังไม่เข้าพิธีวิวาห์ ก็เพาะสร้างความสัมพันธ์ถึงขันน 1\nส ทง ๑ขี่ \' เวิ -\nหน้าซําในวังก็ปล่อยให้พวกมันเคลื่อนไหวเป็นคู่ จากนั้นหวนนึกถึงเม่เ\nตนเองเดินทางกลับประเทศ เคยสนทนากับองค์หญิงใหญ่ผู้นี้หลายครั้ง !\nงงงันวูบหนึ่ง\n1ไสรไธฑฑฑเฑ 7้็ืจฒ6น0ง090้ั ,\nหลินว่านเอ๋อกับฟ่านเย่อเย่อเพียงได้ยินแต่ชื่อ ยังไม่เคยพบหน\nองค์หญิงจากต่างแดนผู้นี้ จึงเกิดความสงสัยอยากรู้ บวกกับทราบ.\nองค์ชายใหญ่คงมีเรื่องคิดสนทนากับฟ่านเสียน จึงลูกขึ้นจากไป\nภายในห้องหนังสือเงียบสงบลง ฟ่านเสียนผายมือเป็นความหม\nให้อีกฝ่ายดีมน้ำชา ปากกล่าวว่า “ขอแสดงความยินดีต่อต้าเตียนเซีย\nทีมันแสดงความยินดีคืออีกฝ่ายรับตําแหน่งผู้บัญชาการทหา\nวรักษาพระองค์ องค์ชายใหญ่พอฟังต้องเลิกคิวขึ้น จากนั้นคลายออก\nว่า “มีอันใดน่ายินดี เราผู้เป็นอ้องความจริงเป็นแม่ทัพใหญ่พิชิตตะวันตก\nแล้วาว”\nอย่แล้ว\nฟ่านเสียนยิมออกมากล่าวว่า “ถึงแม้ลดตําแหน่งลงมาสองขัน แต่\nทหารรักษาพระองค์อยู่ศูนย์กลางการปกครอง ไหนเลยเปรียบกับพื้นที่\nองค์ชายใหญ่กวาดมองมันแวบหนึ่ง ไม่ทราบว่าคําพูดของมันนี่\nแฝงความหมายอย่างอื่นหรือไม่ จึงกล่าว “เราผู้เป็นอ้อง ไม่ต้องการ\nตําแหน่งผู้บัญชาการทหารรักษาพระองค์ ยินยอมขึื้นเหนือไปชายแดน\nเปลี่ยนตัวกับเอียนเสียวอิ\nฟ่านเสียนสันศีรษะครุ่นคิดว่า ฮ่องเต้ย้ายเยอียนเสียวอิไปไกล','2026-04-17 09:49:11'),(190,10,187,'ทั้งคับตระกูลเยียพันจากหน้าที่รักษาการณ์มหานคร เพราะไม่ไว้วางพระทัย\nสตรีเสียสติทีแดนซินหยาง ท่านอาสาขึ้นเหนือไปชายแดน\nท่อมยินดี แต่ฮ่องเต้ต้องไม่พอพระทัย\nฟ่านเสียนหัวร่อเบาๆ กล่าวว่า “อย่าได้บอกต่อข้าพเจ้าว่าวันนี้ต้า\nเตียนเซียมาเยียมไข้คนป่วย แท้จริงแล้วไม่สมมาดปรารถนาต่อตําแหน่ง\nข้าพเจ้าเพียงแต่เป็นผู้ฟังทีเหมาะสมกับตําแหน่งผู้หนึ่ง\nองค์ชายใหญ่แม้ไม่เข้าใจว่าคําเหมาะสมกับตําแหน่งหมายความ\nอย่างไร แต่ยังกล่าวว่า “ไม่เพียงเป็นผู้ฟัง เราคิดขอความช่วยเหลือจาก\nมันไม่เรียกตัวเองเป็นเราผู้เป็นอ้อง หากใช้คําว่าเราแทน\nฟ่านเสียนสังเกตเห็นความเปลี่ยนแปลงนี้ ต้องใจเขม็งตึงเครียด\nอยู่บ้าง ดูท่าองค์ชายใหญ่ทีมีสายเลือดชาวตงอิผู้นี้คิดขอความช่วยเหลือ\nจากตนเองจริงๆ\nสวรรค์เป็นพยาน\nฟ่านเสียนลอบทอดถอนใจ ปากกล่าวว่า “เตียนเซีย ตําแหน่งผู้\nบัญชาการทหารรักษาพระองค์สำคัญเพียงไหน ฝ่าบาทเชือในความจงรัก\nภักดีของท่าน จึงจัดการเช่นนี่ ฟ่านเสียนเป็นขุนนาง ไหนเลยกล้าวิพากษ์\nองค์ชายใหญ่สันศีรษะกล่าวว่า “ฟ่านเสียน ขอบอกตามตรง ตอน\nแรกทีกลับมหานคร เราไม่ลงรอยกับท่าน ตอนอยู่ที่ชายแดนตะวันตก\nได้ยินว่ามหานครปรากฏเซียนกวีผู้หนึ่ง แต่ว่าเราเป็นแม่ทัพบู้ ไม่เชือว่า\nเรื่องประโลมโลกเหล่านี้จะเกิดประโยชน์แก่ชาติบ้านเมือง ตลอดจน\nประชาราษฎร์อย่างไร ”\nจากนั้นเปลี่ยนเป็นกล่าวว่า “แต่หลังจากกลับถึงมหานคร ดูจาก\nพฤติการณ์ของท่าน ในความดูต้นแฝงความจริงใจ ภายใต้ไหวพริบปฏิภาณ','2026-04-17 09:49:11'),(191,10,188,'แสดงออกถึงความรู้ความสามารถ อย่าเพิ่งเอ่ยถึงเรื่องที่ท่านจัดการกั1\nเหล่าเอ้ออย่างสาหัส เพียงเหตุการณ์บนวิหารฮุ่ยคง ทําให้เราเปลี่ยนแปลง\nมุมมองต่อท่าน”\nองค์ชายใหญ่กล่าวอย่างจริงจังว่า “ตอนที่อยู่ในวัง ท่านยังรักษา\nอาการบาดเจ็บของตัวเองจนรอดชีวิตจากความตาย เรานึกไม่ออกว่า ใน\nโลกนี้มีเรื่องใดที่สร้างความลําบากแก่ท่าน ดังนั้นท่านต้องช่วยเหลือเรา\nฟ่านเสียนได้รับการเยินยอไม่หยุดหย่อน ต้องนิ่งเงียบงันไป เฉิน\nผิงผิงเคยบอกว่า องค์ชายใหญ่ผู้นี้ไม่เหมือนใคร พาตัวเองออกจากวัง\nตั้งแต่เล็ก อยู่ห่างไกลจากบัลลังก์มังกร ตอนนี้ฮ่องเต้ฉุดลากมันมายัง\nปลักนำนี้ มันจึงคิดต่อสู้ขัดขืน\nแต่ว่าองค์ชายใหญ่เพียงคุมกำลังทหาร ไม่มีนักวางแผนดําเนิน\nอุบายให้ แต่ว่าอีกฝ่ายมาเสาะหาตนเอง นับว่าเหนือความคาดหมายอยู่\nถึงแม้ว่าฟ่านเสียนยินดีที่พบเห็นในบรรดา “ ” เหล่านี้ มีคน\nผู้หนึ่งรักษาจิตใจที่กว้างขวางเปิดเผย ทั้งนึกเห็นใจต่อสภาพการณ์ของ\nอีกฝ่าย แต่ยังสันศีรษะกล่าวว่า “เตียนเซีย มิใช่ไม่กล้า มิใช่ไม่กระทํา หาก\nแต่ไม่สามารถ ฟ่านเสียนจะอย่างไรเป็นขุนนางผู้หนึ่ง สำนักตรวจสอบ\nไม่อาจก้าวก่ายการบริหารราชการแผ่นดิน”\nองค์ชายใหญ่ทอดถอนใจคําหนึ่ง การมาของมันในวันนี้เสียง\nอนตรายอยูบาง แต่เหลียวดในมหานคร นอกจากฟ่านเสียนแล้ว มันยังไป\nหาผู้ใดได้ หรือว่าสุดท้ายตนเองต้องไปยังสวนอุทยานเฉินอีกครั้ง?\nฟ่านเสียนคล้ายล่วงรู้ความในใจมัน จึงกล่าว “ฝ่าบาทพอตัดสิน\nพระทัยก็ไม่มีผู้ใดเปลี่ยนแปลงได้ เตียนเซียไม่ต้องไปยังสวนอุทยานเฉิน\nแล้ว แต่ว่าข้าพเจ้านึกประหลาดใจ วันนี้เตียนเซีย ไฉนตัดสินใจเช่นนี้ ใน','2026-04-17 09:49:11'),(192,10,189,'สายตาของท่าน ข้าพเจ้ามิใช่ขุนนางดีงามอันใด”\nองค์ชายใหญ่จิบชาในถ้วย กล่าวว่า “ฟ่านเสียน ท่านสามารถตบตา\nผู้อื่น แต่ไม่สามารถตบตาเรา อย่าลืมว่าตอนนั้นเราก็อยู่ในวิหารฮุ่ยคง ดู\nจากการที่ท่านช่วยเหลือเสียวตี (น้องเล็ก) ก่อน ค่อยช่วยเหลือฟู่หวง (พระ\nบิดา) เราก็ทราบว่าท่านเป็นคนที่ควรแก่การไว้วางใจ\nฟ่านเสียนนิงเงียบงันไป คิดไม่ถึงว่าค่านิยมทางโลกใบนี่ จะเป็นเหตุ\nให้ฮ่องเต้กับองค์ชายใหญ่เกิดความไว้วางใจต่อตนเอง\nการมาขององค์ชายใหญ่ในวันนี้ ก็คิดแสดงท่าที่ของตนเองต่อสำนัก\nตรวจสอบ พร้อมกันนั้นหวังว่าจะได้รับการชีแนะทีเป็นประโยชน์จากฟ่าน\nเสียน แต่อีกฝ่ายเมื่อนิงเฉยไว้ ตนเองก็ไม่สะดวกกับการรุกลําเกินไป\n“ฟังว่าหมอหลวงแวะเวียนมาทีตึกท่านหลายครั้ง”\nองค์ชายใหญ่หันเหหัวเรื่องด้วยความกระบิดกระบวนอยู่บ้าง ชีวิต\nบนหลังม้าทําให้มันไม่อาจปรับตัวเข้ากับความคดเคี่ยวในแวดวงขุนนางได้\nโดยสนิทใจ\nฟ่านเสียนลอบหัวร่อในใจ อธิบายว่า “มันต้องการให้ข้าพเจ้ารับ\nตําแหน่งที่ตึกไท่อี แต่ถูกฝ่าบาทติกลับมา จึงเปลี่ยนเป็นขอให้ข้าพเจ้าไป\nสอนนักศึกษาแพทย์ทีตึกไท่อี\nนี้ความจริงเป็นการสนทนาด้วยเรื่องสัพเพเหระ องค์ชายใหญ่กลับ\nจริงจังขึ้นมา กล่าวว่า “ฟ่านเสียน เราก็เห็นว่าท่านสมควรไปที่ตึกไท่อี คืน\nนั้นเราก็อยู่ที่ตําหนักกว่างซิน ดูจากสีหน้าท่าทีของคณะหมอหลวง ก็ทราบ\nว่าท่านมีวิชาแพทย์สูงเยียมยิง”\nมันกล่าวด้วยความสงสัยอยากรู๊ว่า “ความจริงแล้วผู้คนในมหานคร\nล้วนประหลาดใจ ท่านไฉนกล้าให้คุณหนูฟ่านจัดการกับหน้าอกตัวเอง หมอ\nหลวงเหล่านั้นต่างประโคมโอ่ท่านราวกับเป็นเซียนวิเศษองค์หนึ่ง”\nฟ่านเสียนฝืนยิมพลางกล่าวว่า “อย่าได้เชือพวกมัน ทั้งหมดล้วน','2026-04-17 09:49:11'),(193,10,190,'ทราบว่าเฟยเจียเป็นเหล่าซือข้าพเจ้า หากให้พวกมันออกไปขุดหลุงวแ\nศพ แหวะอกผ่าท้องซากศพตั้งแต่อายุสีขวบ พวกมันก็จะมีความสามา1.\nเช่นเดียวกับข้าพเจ้า”\nองค์ชายใหญ่ทอดถอนใจกล่าวว่า “ที่แท้เป็นเช่นนี่ ดูท่าไม่ว่าเว็ก1\nราวใดไม่อาจใช้คําพรสวรรค์อธิบายได้” จากนั้นเกลียกล่อมว่า “ตึกไท่ยีแล่า\nไม่ทรงอํานาจเท่ากับสำนักตรวจสอบ แต่ก็มีจุดเด่นที่สันติสุข ความคิดอ่าก\nของหมอหลวงก็รวบรัด หากว่าวิชาแพทย์ของท่านได้รับการแพร่หลายอกเ\nไป ไม่ทราบช่วยชีวิตผู้คนมากน้อยเท่าใด”\nมันจับจ้องมองตาฟ่านเสียนกล่าวว่า “เรื่องการช่วยคนย่อมดีกว่าซา\nคน มิหน้าซําเราอยู่ในกองทัพ ทราบว่าการมีหมอดีท่านหนึ่ง หมายถึงกา-\nช่วยชีวิตไพร่พลทีรับบาดเจ็บ\nฟ่านเสียนกล่าวถามว่า “เหตุใดต้องเผยแพร่วิชาแพทย์ออกไป?”\n“เพื่อความผาสูกของแผ่นดิน”\n“นี่เป็นความคิดของหมอหลวงกระมฆัง?”\n“ถูกต้อง”\nฟ่านเสียนหัวร่อฮาฮากล่าวว่า “ที่แท้วันนี้เตียนเซียยังพ่วงตําแหน่ง\nทูตเจรจาให้กับหมอหลวง มิน่าเล่าหัวข้อสนทนาในตอนแรกจึงประหลาด\nพิกลยิง”\nองค์ชายใหญ่เห็นมันหัวร่อด้วยความเบิกบานใจ ต้องหน้าเคร่งเครียด\nลงกล่าวว่า “หรือท่านเข้าใจว่าพวกเรากำลังกล่าววาจาเหลวไหล?”\nความจริงแล้วนี้แทบเป็นวาจาเหลวไหล กลับให้ฟ่านเสียนวางมือ\nจากตําแหน่งถีซือสำนักตรวจสอบ หันไปสอนนักศึกษาแพทย์ ไม่ว่าผู้ใดก็\nไม่สามารถเอ่ยปากได้ หมอหลวงกับองค์ชายใหญ่กลับบอกออกมา\nฟ่านเสียนชะงักเสียงหัวร่อ พบว่าปากแผลที่หน้าอกปวดแปลบเล็ก\nน้อย ต้องใจหายวาบ รีบกล่าวว่า “มิใช่หัวร่อเยาะ ในทางกลับกัน ข้าพเจ้า','2026-04-17 09:49:11'),(194,10,191,'ให้ความเคารพต่อหมอหลวงหนึ่งส่วน”\nหากคิดทําการผ่าตัด มีปัญหามากมายไม่อาจคลีคลายได้ หนึ่งคือ\nตมยา สองคือฆ่าเชื่อ สามคือเครื่องมือทางการแพทย์ ด้วยเกณฑ์มาตรฐาน\nในโลกปัจจุบัน ยังไม่สามารถแก้ปัญหาเหล่านี้ ฟ่านเสียนใช้เครื่องหอม\nเกอหลอฟางมอมตัวเอง การฆ่าเชือใช้วิธีต่อต้านแข็งขืน ทั้งหมดนี้ล้วน\nตั้งอยู่บนรากฐานทีตนเองมีร่างกายแข็งแรง หากเปลียนเป็นชาวบ้านทัวไป\nหากมิใช่ถูกยาสลบมอมทําร้ายเสียชีวิต ก็เกิดอาการติดเชือถึงแก่ความตาย\nส่วนปัญหาเครื่องมือทางการแพทย์ยิงยากแก้ไข ฟ่านเสียนกับเฟยเจีย\nช่วยกันขบคิดอยู่หลายปี สุดท้ายได้แต่ให้ตึกที่สามจัดสร้างเครื่องมือออก\nมาชุดหนึ่ง\nหากเรื่องห้ามเลือดยังทําไม่ได้ ยังเอ่ยถึงการลงมีดอันใด\nฟ่านเสียนใช้ถ้อยคําเท่าที่อธิบายได้ บอกกล่าวเหตุผลเหล่านี้เทียว\nหนึ่ง องค์ชายใหญ่ค่อยเข้าใจกระจ่าง วิชาแพทย์แขนงนี้ค่อนข้างแรงกล้า\nเป็นการต่อสู้ระหว่างร่างกายของผู้บาดเจ็บกับคมมีดยาสลบ หากฟ่าน\nเสียนไม่ได้ฝึกฝนร่างกายตั้งแต่เล็ก คงไม่อาจทนทานได้\nองค์ชายใหญ่นึกถึงไพร่พลที่ถูกลูกธนูยิงทําร้าย สุดท้ายเสียชีวิต\nโดยไม่อาจรักษา ต้องทอดถอนใจกล่าวว่า “ไม่มีวิธีทีดีกว่านี้หรือ?\nไม่ทราบเพราะเหตุใด ห้วงสมองฟ่านเสียนปรากฏภาพมือที่มันคง\nของเม่ยเม่ยขึ้นจึงกล่าว “มีสิงทีเป็นพื่นฐานบางอย่าง ข้าพเจ้าจะให้เย่อเย่อ\nไปยังตึกไท่อี แลกเปลี่ยนความคิดกับหมอหลวงทั้งหลายดู”\nองค์ชายใหญ่ผงกศีรษะรับกล่าวอีกว่า “ก่อนหน้านี้ท่านดูเหมือน\nไม่เห็นด้วยกับคําว่าความผาสุกของแผ่นดิน”\nนี้เป็นความเคลือบแคลงสงสัยของมัน ดูจากเปลือกนอกฟ่านเสียน\nย่อมเป็นขุนนางกุมอํานาจ เห็นแต่ผลประโยชน์ แต่จากการสังเกตดู องค์\nชายใหญ่มีความรู้สึกว่าอีกฝ่ายไม่ได้มีความมุ่งมาดปรารถนาเพียงนี้เท่านั้น','2026-04-17 09:49:11'),(195,10,192,'ฟ่านเสียนเงียบงันชั่วขณะจึงกล่าวเบาๆ ว่า “คิดสร้างความผาเน\nแผ่นดินมีอยู่หลายวิธี ไม่เพียงช่วยชีวิตคนเท่านั้น”\nองค์ชายใหญ่รับฟังไม่เข้าใจ\nฟ่านเสียนกล่าวว่า “ยกตัวอย่างเตียนเซียท่าน ท่านอยู่ที่ชายแ\nตะวันตก สู้รบกับชนชาติหู ฆ่าศัตรูนับไม่ถ้วน แต่ก็ยับยังมิให้ชนซา๒\nตะวนตกรุกลาเขามา หรือไม่ถือเป็นการสร้างความผาสูกแก่แผ่นดิน?\nต่อให้องค์ชายใหญ่มีนิสัยหนักแน่นกว่านี้ พอฟังคําสอพลอเช่นนี้ 1\nเกิดความยินดี\nฟ่านเสียนกล่าวสืบต่อ “ลองยกตัวอย่างข้าพเจ้า ถึงแม้ชนชาวไแย\nเห็นว่าสำนักตรวจสอบเป็นองค์กรลับทีเย็นเยียบ แต่หากข้าพเจ้าสามา\nชักนำไปยังวิถีทางทีถูกต้อง สร้างความมันคงให้กับต้าชิงเรา ให้ประฯ\nราษฎร์อยู่เย็นเป็นสุข ถือเป็นการสร้างความผาสุกแก่แผ่นดินหรือไม่?\nมันกล่าวยําว่า “จุดมุ่งหมายอาจพ้องต้องกัน แต่วิธีการมีอยู่ม\nหลาย” หวนนึกถึงอาจารย์สอนภาษาเมื่อชันมัธยม บอกเล่าว่าหลู่ซิน\nละทิ่งอาชีพหมอ มู่งสู่เส้นทางวรรณกรรม จึงอ้างว่าเคยอ่านพบจากตํา !\nโบราณของจวงม่อหาน ถ่ายทอดบอกออกไป\nองค์ชายใหญ่รับฟังจนงงงันวูบ ทวนคําว่า “หากช่วยร่างกายของ\nประชาชาติ มิสู้กอบกู้จิตวิญญาณของประชาชาติหรือ? แต่ว่ารัฐชิงเราตอนแ\nนี้ไม่ได้อ่อนแอเช่นประเทศในตํานานเรื่องนี้ ไยต้องใช้ความเรียงเข้ากล่อง!\nคําพูดนี้เป็นความจริง ชาวชิงมีจิตใจสัตย์ซือบริสูทธิ เกิดความ\nมูมานะ ถือว่าต่างกับยุคสมัยปลายแมนจูต้นสาธารณรัฐของหลู่ซิน ซึ่ง\nกระทั้งหายใจยังยากลําบาก\nฟ่านเสียนยิมออกมากล่าวว่า “ดังนั้น ข้าพเจ้าไม่เพียงละทิ่งการ\nณัเหระพันธ์ผู้ยิงใหญ่ของจีน ค.ศ. 1881 : ๓ ฑ 1996 เจ้าของผลงานเรื่องบันทึกของอาคิว','2026-04-17 09:49:11'),(196,10,193,'แพทย์ กระทั้งความเรียงก็ละทิง เรียกว่าละทิงการแพทย์เข้าสู่การเมือง\nละทิงพู่กันสวมเครื่องแบบนักรบ”\nองค์ชายใหญ่ยังไม่เห็นด้วยกับมุมมองของมัน กล่าวว่า “ท่านสม\nเป็นอัจฉริยะ เหตุใดไม่ถ่ายทอดวิชาความรู้ทั้งหมดออกมา หากสามารถ\nเปลี่ยนแปลงโลกใบนี้ให้ดีกว่านี้ ”\nฟ่านเสียนโบกมือกล่าวว่า “ผู้คนส่วนใหญ่คิดเปลี่ยนแปลงโลกใบนี่\nเจ ม ข ๕ ! \'\nแต่น้อยคนที่คิดเปลี่ยนแปลงตัวเอง ข้าพเจ้าเห็นว่าเปลี่ยนแปลงตัวเองก่อน\nแล้วค่อยว่ากล่าว”\nเมื่อหลายสิบปีก่อน ปรากฏสตรีนางหนึ่งคิดเปลี่ยนแปลงโลกใบนี้\nสุดท้ายนางตายแล้ว ฟ่านเสียนไม่คิดซ่ารอยของนาง มันรักตัวกลัวตาย\nมากกว่า คิดเห็นแก่ตัวมากกว่า\nขณะสนทนา ทีนอกหน้าต่างแว่วเสียงอึกทึกวุ่นวายดังมา นำเสียง\nแฝงความปลาบปลืมยินดี\nองค์ชายใหญ่กวาดตามองมันแวบหนึ่ง ยิมพลางกล่าวว่า “ดูท่า\nราชโองการปูนบําเหน็จท่านมาถึงแล้ว”\nฟ่านเสียนยืมเยาะตัวเอง ไม่กล่าวว่ากระไร ในดวงตาสุกใสเพียง\nฉายแวววิตกกังวลต่อสภาพกายตนเอง ไม่ได้กังวลก่อนความกังวลของ\nแผ่นดิน แต่อย่างไร\nหมายถึงยอดขุนนางราชวงศ์ช้องฟ้านจงเอียน เคยกล่าววรรคทองสองประโยคว่า กังวลก่อนความกังวลของแผ่นดิน โสมนัส\nหลังความโสมนัสทุกถินแคว้น','2026-04-17 09:49:11'),(197,10,194,'','2026-04-17 09:49:11'),(198,10,195,'ยนเหปู่นบําเหน็ง\nผู้ที่เดินทางมาอ่านราชโองการคือเหยากงกง ตึกตระกูลฟ่านรีบจัด\nตั้งโต๊ะบูชา ผู้คนเบื่องสูงเบืองตําของตระกูลฟ่านน้อมรอที่ห้องโถง ส่วน\nองค์ชายใหญ่กับองค์หญิงใหญ่แคว้นเปียฉีไม่สะดวกกับการรังอยู่ในตึก จึง\nปลีกตัวไป แต่หมอหลวงนั้นยังดึงดันรังอยู่ในห้องหนังสือ\nซู ก่ ฆ\nราชโองการมาถึงตัวตึกเป็นเรื่องใหญ่โต แม้แต่ฟ่านเสียนยังถูกหาม\nออกจากห้องนอน ดีที่ในวังทราบว่ามันอยู่ระหว่างการพักฟืน ดังนั้นกําชับ\nว่ามันไม่ต้องลูกขึ้นรับราชโองการ ถือเป็นพระมหากรุณาประการหนึ่ง\nฟ่านเสียนรับฟังสุ้มเสียงแหลมเล็กของเหยากงกง พบว่าครั้งนี่\nฮ่องเต้พระราชทานสิงของไม่น้อย เหยากงกงท่องอ่านครู่หนึ่งยังท่องไม่จบ\nฟ่านเสียนย่อมไม่สนใจสิงของพระราชทาน จึงไม่ได้ตั้งใจฟัง กลับเห็นว่า\nสุ้มเสียงของขันทีผู้นี้คล้ายสะกดจิต ยามนอนบนตั้งเตียงอันนุ่มนิม กลับ\nปิดเปลือกตาลงคิดหลับใหลไป\nพระกํากับดูแลทักษิณกระแอมเบาๆ ใช้สายตากระตุ้นเตือน หลิน\nว่านเอ้อก็ใจหายวาบ บีบใจกลางฝ่ามือฟ่านเสียนคราหนึ่ง มันค่อยฝืนใจ\nลืมตาขึ้น ได้ยินคําว่าแพรพรรณห้าร้อยพับ ที่นาอีกหลายมู่ (ไร่จีน) ทอง\nแท่งจํานวนหนึ่ง เงินแท่งจํานวนหนึ่ง','2026-04-17 09:49:11'),(199,10,196,'ตระกูลฟ่านขาดแคลนหลายสิง แต่ไม่ขาดแคลนเงินทอง นี้เป็นเว็อ!\nทชาวชงลวนทราบด ดังนั้นฮ่องเต้ไม่ชดเชยสิงเหล่านี้แก่ฟ่านเสียน เพยเ\nนฟูบรรดาศักดิแก่ฟ่านเสียน ทั้งเพิมบรรดาศักดิแก่พระกํากับดูแลทักทงแ\nกขนหนง\nหลังจากอ่านราชโองการจบ ผู้คนในห้องโถงแยกย้ายจากไป เหย\nกงกงค่อยลดสุ้มเสียงเบาลง อ่านราชโองการลับของฮ่องเต้\nราชโองการลับไม่ลับ แต่ข้อดีของราชโองการนี้คือไม่ต้องเปิดเหย\nออกไป\nฟ่านเสียนคึกคักอักโข ฟังว่าฮ่องเต้จัดสรรพยัคฆ์พิทักษ์เจ็ดคนไดห้\nกับตนเอง ค่อยมีความรู้สึกว่าฮ่องเต้ไม่ได้มีพระทัยคับแคบ ยามลิงโลดยินต\nกลับมองข้ามพระกระแสรับสังอีกสองข้อไป\nตอนนี้ที่มันวิตกกังวลทีสุดคือความปลอดภัยส่วนตัว ปีหน้ามันต้อง\nเดินทางสู่แดนเจียงหนั้น ผู้ใดทราบว่าเมื่อถึงเวลานั้นตนเองสามารถฟืนฟู\nพลังลมปราณหรือไม่ ท่านอายอู่จู๋ดูเหมือนไม่สนใจชีวิตน้อยๆ ของตนเอง\nทีหน้าสวนหลัง ฟ่านเสียนพบกับพยัคฆ์ ทักษ์ที่คุ้นเคยทั้งเจ็ด ผู้นำ\nขบวนคือเกาต้าเอง\nเมื่อหลายเดือนก่อนพยัคฆ์พิทักษ์เหล่านี้เคยร่วมทางกับมันไป\nเชอมสัมพันธ์กับแควันเปยฉิ ถือเป็นคนคุ้นเคย ตอนนฮองเตมพระบญชา\nให้มาคุ้มกันฟ่านถีซือ กบงเกดความยนด เมื่ออยู่ร่วมกับใต้เท้าฟ่าน ยอม\nสุขสบายกว่าอยู่ในห้องมีดมิด อย่าว่าแต่ใต้เท้าเสียวฟ่านมีฝีมือสูงเยียม\nพวกมันมิต้องกังวลใจอันใด\nภายใต้การนำของเกาตํา เหล่าพยัคฆ์พิทักษ์ที่สะพายดาบยาวคุกเข่า\nลงข้างหนึ่ง กล่าวโดยพร้อมเพรียงว่า ผู้น้อยคํานับใต้เท้าถีซือ','2026-04-17 09:49:11'),(200,10,197,'ฟ่านเสียนส่งเสียงกระแอม กล่าวอย่างยิมแย้มว่า “ลุกขืนเถอะ ล้วน\nเป็นคนกันเอง หลังจากนี้ชีวิตน้อยๆ ของเราผู้เป็นขุนนางต้องพึงพาพวก\nท่านแล้ว\n\' ๑ ๕6 ๑7 ๕ จ เฉลข ข 1 \' \' \'\nเหล่าพยัคฆ์พิทักษ์เข้าใจว่าใต้เท้าเสียวฟ่านกล่าวล้อเล่น ไม่ทราบ\nตอบอย่างไรดี เพียงฝืนหัวร่อสองครา ไหนเลยทราบว่าทีฟ่านเสียนกล่าว\nเป็นความจริง เมื่อพยัคฆ์พิทักษ์อยู่ข้างกาย ต่อให้ไห่ถังเสียสติขึ้นมาคิดฆ่า\nตนเอง มันก็ไม่ต้องหวาดกลัว\nฟ่านเสียนกล่าวกับเกาตําว่า “จพวกท่านไปพบท่านพ่อก่อน ถึงแม้ว่า\nยามปรกติไม่ควรทําเช่นนี่ แต่พวกท่านเมื่อต้องติดตามเราผู้เป็นขุนนาง\nไม่ต้องกริงเกรงไป”\nเกาตําผงกศีรษะรับ นึกขอบคุณฟ่านถีซือชีแนะ ยามนั้นรุดไปยังตึก\nหน้า เข้าพบผู้บังคับบัญชาเก่าของตนเองก่อน\nหมอนหนุนลายบัก? สูราเลิศรส? เสือผ้าอาภรณ์ ยังมีเครื่อง\nดนตรีชุดหนึ่ง?\nฟ่านเสียนเข้าห้องของตนเอง อ่านดูรายการสิงของพระราชทาน\nโดยละเอียด จากนั้นกวาดมองภรรยาแวบหนึ่ง ฝืนยิมพลางกล่าวว่า\n“ข้าพเจ้าแม้รับตําแหน่งขุนนางแสลวีหลาง แต่ไม่เคยเล่นเครื่องดนตรีมา\nหลินว่านเอ้ออธิบายว่า “เพียงเป็นกฎในวังเท่านั้น\nเห็นฟ่านเสียนมีสีหน้าเบือหน่าย จึงไม่ได้บอกในสิงของพระราชทาน\nงมีถังอุจจาระด้วย\nยามนี่ที่ตึกหลังชุลมูนวุ่นวาย เถิงจือจิงจัดคนรับมอบสิงของ\nพระราชทานจากในวัง จากนั้นพิจารณาว่าควรเก็บรักษาในห้องใด หากเป็น\nสงของสาคญ ต้องเขาหองมาเรยนถามหลนวานเออ','2026-04-17 09:49:11'),(201,10,198,'ฟ่านเสียนเห็นภรรยาของเถิงจือจิงวุ่นวายจนหลังเหงือโซมหน้ก1 น)\nทอดถอนไจกล่าวว่า “นี่ที่แท้เป็นการปูนบําเหน็จ หรือเป็นการลงโทษผู้ห \'\nภรรยาของเถิงจือจิงยิมระรีนแจ่มใสกล่าวว่า “ต่อให้เป็นหนึ่งเว\nหนึ่งด้าย ก็ไม่รวบรัดธรรมดา ต้องมีวาสนาจึงครอบครอง ทัวทั้งมหาาย\nมีตระกูลใดได้รับสิงของพระราชทานถึงเพียงนี่ คราครั้งนี้เส้าแหยมีพา\nมีตานัก”\nหลินว่านเอ้อสอดคําขึ้น “หน้าตาทีใช้ชีวิตเข้าแลกมา มิสู้ไม่ต้องกา\nนางกลับกลัวว่าฮ่องเต้จิวจิว (พระเชษฐาของมารดา) มีพระประสงค์เคผีอห\nแฝง สิงของพระราชทานยิงมาก วันหน้าเซียงกงตัวเองยิงต้องต้านทานว็น\nมีดดาบให้กับพระองค์\nฟ่านเสียนยิมพลางกล่าวว่า “ฝ่าบาทใจแคบนัก ข้าพเจ้าฟังดูแล้.\nพบว่าพระราชทานเงินทองน้อยนิดยิง”\nหลินว่านเอ้อยิมออกมากล่าวว่า “ท่านยังนำพาสิงนี้? ความจริงแล้.\nสิงของพระราชทานยิงหยุมหยิม ยิงแสดงว่าฝ่าบาทเป็นห่วงอาการบาดเจ๊1!\nของท่าน”\nฟ่านเสียนเลิกคิวขึ้นกล่าวว่า “ไฉนไม่นำพา ตอนนี้บ้านเราพึงพา\nร้านหนังสือเลียงชีพตัวเอง หากมีค่าใช้จ่ายพิเศษ ต้องวิงไปทีตึกหน้า\nแบมือขอเงินจากท่านพ่อ”\nหลินว่านเอ้อเห็นภายในห้องไม่มีคนนอกอยู่ด้วย จึงกล่าวสัพยอกว่า\n“ท่านมิใช่ยังมีหอนางโลมหลังหนึ่งหรอกหรือ ฟังว่าหอหลังนั้นเดือนหนึ่ง\nทํากําไรหลายหมืนตําลึง”\nฟ่านเสียนหัวร่อออกมากล่าวว่า “นั้นเป็นของเสียวซือ (ซื้อน้อย)\nท่านอย่าได้ลากข้าพเจ้าเข้าไป”\nหลินว่านเอ้อแสร้งร้องเพียคําหนึ่งกล่าวว่า “ยามอยู่เบืองหน้าคน\nกันเอง ยังเสแสร้งแกล้งทํา ไม่กลัวตัวเองเหนือยยากลําบากหรือ?','2026-04-17 09:49:11'),(202,10,199,'“ไม่ว่าเมื่อใดเวลาไหนล้วนต้องเสแสร้ง ทางทีดีให้หลอกลวงตัวเอง\nหลินว่านเอ้อพลันลืมตากลมกว้าง กล่าวว่า “พีใหญ่มาหาท่านด้วย\nฟ่านเสียนขบคิดแล้วกล่าว “มันไม่ต้องการเป็นผู้บัญชาการทหาร\nรักษาพระองค์ จึงมาหาข้าพเจ้า ดูว่ามีหนทางใด\nหลินว่านเอ๋อขมวดคิวกล่าวว่า “ด้วยนิสัยใจคอของพีใหญ่ คงไม่\nต้องการรังอยู่ในมหานคร”\nฟ่านเสียนแค่นหัวร่อกล่าวว่า “ผู้ใดต้องการรังอยู่ในมหานคร แต่ว่า\nฝ่าบาทไม่ไว้วางใจที่ราชโอรสทีเชียวชาญการรบผู้หนึ่งนำทัพอยู่ข้างนอก”\nคําพูดนี้กล่าวอย่างอุกอาจไปบ้าง หลินว่านเอ้อต้องใจสันสะท้าน\nกล่าวว่า “ตอนนี่ท่านยิงมายิงไม่ระมัดระวังคําพูดแล้ว”\nฟ่านเสียนกล่าวว่า “มีแต่อยู่เบืองหน้าท่าน จึงสามารถกล่าวอย่าง\nเปิดเผย” มันทอดถอนใจกล่าวว่า “ข้าพเจ้ากลับยินดีช่วยเหลือต้าเตียนเซีย\n(องค์ชายใหญ่) แต่ข้าพเจ้าจะอย่างไรเพียงเป็นขุนนาง ไม่มีสิทธิมีเสียงใน\nการเอ่ยปาก เพียงไม่ทราบต้าเตียนเซียถูกความคิดใดครอบงํา จึงกล้ากล่าว\nตรงๆ กับข้าพเจ้าถึงเพียงนี้\nหลินว่านเอ้อฝืนยืมพลางกล่าวว่า “อาจบางทีพีใหญ่เข้าใจว่า เห็น\nแก่หน้าข้าพเจ้า ท่านคงไม่ทําร้ายมัน”\nฟ่านเสียนขมวดคิวกล่าวว่า “นำของมหานครลึกยิง ข้าพเจ้าว่ายอยู่\nครึ่งค่อนวัน ยังไม่อาจหยังถึงก้นแม่นำ” มันกล่าวเสริมว่า “ปีหน้าเดินทาง\nสู่แดนเจียงหนั้น ท่านร่วมทางกับข้าพเจ้า อยู่ที่นั้นให้นานกว่านี้\nหลินว่านเอ้อกล่าวแยกแยะว่า “เพียงไม่ทราบว่าเมื่อถึงเวลานั้นราช\nสำนักจะแต่งตั้งท่านเป็นผู้แทนพระองค์ไปตรวจสอบท้องพระคลัง หรือว่า\nให้ท่านเป็นผู้ดูแลท้องพระคลังประจําการที่แดนเจียงหนั้น หากไปในฐานะ','2026-04-17 09:49:11'),(203,10,200,'ผู้แทนพระองค์ ท่านไม่สามารถนำครอบครัวไป หากให้ประจําการที่แต\nเจียงหนั้น ข้าพเจ้าก็สามารถติดตามไป\nฟ่านเสียนสันศีรษะกล่าวว่า “สนใจไยกันว่าจะจัดการอย่าง .\nข้าพเจ้าจะนำท่านไป”\nหลินว่านเอ้อยิมพลางกล่าวว่า “คําพูดไม่อาจกล่าวเช่นนี้” ปากกล่า.\nวาจา ในใจบังเกิดความวาบหวามดีมดํา นางทราบว่าด้วยศักดิฐานะฟ่า\"เ\nเสียนกับตัวเอง ไม่ว่าละเมิดกฎอย่างไรก็ไม่มีผู้ใดกล้ากล่าวมากความ เพียง\nไม่ทราบเหนี้ยงเหนี้ยงทั้งหลายในวังยินยอมให้ตัวเองเดินทางไกลถึงแดนแ\nเจียงหนั้นหรือไม่ นางมีร่างกายอ่อนแอ สถานที่ไกลที่สุดเพียงไปพักผ่อน\nทีภูเขาชังซานเท่านั้น\n๑ \' «๑๐๑!๑ไช\nนางพลันนึกถึงเรื่องหนึ่ง จึงกล่าว “อย่าได้หลุดจากกรอบไปแล้:\nฝ่าบาทแม้มีราชโองการลับให้พยัคฆ์พิทักษ์มาคุ้มครองท่าน เพียงเพื่อให้\nคนในมหานครทราบว่าท่านรับบาดเจ็บสาหัส พยัคฆ์พิทักษ์จึงมีเหตุผลใน\nการมาอารักขาท่าน แต่ว่า พยัคฆ์พิทักษ์มีฐานะพิเศษ จะเป็นเหตุให้ท่าน\nสะดุดตาเกินไป”\nฟ่านเสียนยกมือลูบหนวดทึ่งอกเงยออกจากริมฝีปากด้านบน ยิม\nพลางกล่าวว่า “วางใจเถอะ ฝ่าบาทเป็นคนฉลาด ทีให้พยัคฆฒ์พิทักษ์มายัง\nตึกตระกูลฟ่าน อ้างว่าเพื่อคุ้มครองจวินจู่เหนี้ยงเหนี้ยงท่าน\nเสียงเคาะประตูดังขีน สร้างความขุ่นข้องใจแก่ฟ่านเสียนอยู่บ้าง แต่\nมิใช่ขุ่นเคืองที่มีคนมารบกวนตนเอง หากแต่พบว่าหลังจากที่ตนเองสูญเสีย\nพลังลมปราณ ก็ไม่มีปฏิกิริยาอันปราดเปรียวต่อสภาพแวดล้อมรอบข้าง\nอย่างน้อยไม่สามารถได้ยินเสียงฝีเท้าดังมาแต่ไกล\nฟ่านเย่อเย่อนำหมอหลวงนั้นเข้าห้องมา หมอหลวงนั้นเห็นหลิน\nว่านเอ๋อก็อยู่ในห้อง จงรบนอมคานบ จากนั้นเบือนหน้าไปอีกทางหนึ่ง','2026-04-17 09:49:11'),(204,10,201,'ฐซชิงต่างกับแควันเปยฉิ ไม่มีข้อห้ามฉันบุรุษสตรีอันใด อยาวาแต\nของหมอหลวง สามารถเป็นจู่ฟู (ท่านบู่) ของหลนวานเออ ทงหมด\nด้วยอา\nเห็นมันหัวโบราณครําครึถึงเพียงนี้ ต้องหัวร่อออกมา\nฟ่านเย่อเย่อยิมพลางกล่าวว่า “ท่านพ่อ บอกว่าเกอเกอมีสีหน้า\nแจ่มใส จึงให้สนทนากับใต้เท้าไท่อี (หมอหลวง) เอง”\nฟ่านเสียนทราบว่าบิดาไม่อาจทนรําคาญได้ จึงผลักไสหมอหลวงมา\nให้บุตรชายจัดการเอง แต่ว่ามันมีการตัดสินใจแต่แรก จึงหยีตาลงกล่าวกับ\nหมอหลวงว่า “ใต้เท้าไท่อี เราผู้เป็นขุนนางทราบเจตนาการมาของท่านเป็น\nอย่างดี\nหมอหลวงนั้นคิดกล่าวกระไร ฟ่านเสียนชิงกล่าวว่า “ด้วยสภาพ\nร่างกายของข้าพเจ้า ไม่สามารถไปสอนวิชาแพทย์ได้ แต่ข้าพเจ้าจะ\nบรรยายเนื่อหา จัดพิมพ์เป็นรูปเล่ม ส่งไปให้กับตึกท่าน”\nหมอหลวงนั้นยกมือลูบเครา เห็นว่านี้เป็นผลรับที่ไม่เลว หลังจาก\nครุ่นคิดจึงกล่าว “แต่ว่าด้วยวิชาแพทย์ต้องถ่ายทอดด้วยตนเอง ทั้งสอนกับ\nมือ เพียงดูหนังสือเกรงว่าไม่เข้าใจ”\nฟ่านเสียนกล่าวว่า “หลังจากจัดพิมพ์หนังสือออกไป หากว่ามีปัญหา\nใด ข้าพเจ้าจะให้เย่อเย่อไปอธิบายเพิมเติม”\nหมอหลวงนั้นกล่าวอย่างประหวันลนลานว่า “ไหนเลยให้คุณหนู\nฟ่านออกหน้าได้?” ตอนผ่าตัดในวัง มันชมดูอยู่ด้านข้าง ทราบว่าเป็น\nคุณหนูฟ่านเย็บแผลด้วยตัวเอง กลับไม่เคลือบแคลงสงสัยฝีมือของนาง\nฟ่านเสียนกล่าวว่า “เย่อเย่อเองไม่เข้าใจอันใด ข้าพเจ้าอยู่บ้านจะ\nสอนแก่นาง” มันทอดถอนใจแล้วกล่าว “คาดว่าต้าเตียนเซียคงถ่ายทอด\nความคิดของข้าพเจ้าไปแล้ว เรื่องนี้ยังไม่สามารถพัฒนาในเชิงลึก\nสามารถศึกษาร่วมกับใต้เท้าไท่อี หารือถึงหัวข้อทีเป็นประโยชน์อยู่บ้าง\nมันยิมพลางกล่าวว่า “มิหน้าซําเจียซือ (อาจารย์เรา) กำลังจะกลับ','2026-04-17 09:49:11'),(205,10,202,'มหานครแล้ว เมื่อถึงเวลาให้ท่านผู้เฒ่าไปบรรยายที่ตึกไท่อี ความรู้ค 1\nสามารถของท่านผู้เฒ่ายังเหนือลํากว่าเย่อเย่อมากนัก”\nหมอหลวงนั้นบังเกิดความยินดี จากนั้นกล่าวด้วยความหวันวิตก11\n“เฟยเซียนเซิง (ท่านผู้เฒ่าแซ่เฟย) หรือ เราเคยเรียนเชิญท่านผู้เฒ่าหล 11)\nครั้ง แต่ท่านผู้เฒ่าไม่ยอมไป”\nฟ่านเสียนกล่าวราวกับพูดปลอบเด็กทารกว่า “ข้าพเจ้าจะทูลขอต่ก\nฝ่าบาทเอง ขออย่าได้เป็นห่วงไป” ปากกล่าววาจา มุมปากปรากฏรอยยิง!\nอันชั่วร้ายขึ้น\nรอจนหมอหลวงนั้นจากไปด้วยความพึงพอใจ ฟ่านเย่อเย่อค่อยร้อง\nอุทานว่า “เกอเกอ ข้าพเจ้าไม่ล่วงรู้อันใด คําคืนนั้นเพียงทําตามคําบอก\nของท่าน”\nฟ่านเสียนฝืนยิมพลางกล่าวว่า “นี้เป็นเรื่องอับจนปัญญา ข้าพเจ้า\nจะเขียนความรู้เบืองต้นเกียวกับอุณหภูมิร่างกาย การฆ่าเชือ และป้องกัน\nการติดต่อ อื่นๆ รอจนเหล่าซือ (ท่านอาจารย์) กลับมาแล้วค่อยว่ากล่าว\nท่านยังสามารถรําเรียนกับท่านผู้เฒ่า”\nฟ่านเย่อเย่องงงันวูบ จากนั้นสีหน้าเปล่งประกายชนิดหนึ่ง ผงก\nศีรษะรับอย่างหนักแน่น\nฟ่านเสียนสองสามีภรรยารู้สึกเหนือความคาดหมาย คิดไม่ถึงว่า\nเม่ยเม่ยจะรับปากโดยง่ายดาย กลับไม่ทราบกล่าวกระไรดี\nฟ่านเย่อเย่อกล่าวว่า “เกอเกอ ท่านเคยบอกว่าเกิดมาชาติหนึ่ง\nสมควรค้นหาสิงทีตัวเองรักชอบ จากนั้นกระทําต่อไป” นางก้มศีรษะกล่าว\nอย่างเอียงอายว่า “คําคืนนั้นถึงแม้ผู้น้องไม่ได้ทําอะไร แต่เห็นเกอเกอรอด\nชีวิตกลับมา ข้าพเจ้าค่อยทราบว่า การช่วยชีวิตคนผู้หนึ่งมีความสุขถึง\nเพียงนี้ ดังนั้นต่อให้เกอเกอวันนี้ไม่จัดการเช่นนี้ ข้าพเจ้าก็จะขอเล่าเรียน\nวิชาแพทย์จากเกอเกอ”','2026-04-17 09:49:11'),(206,10,203,'ฟ่านเสียนอ้าปากค้าง ชั่วครู่ไม่อาจกล่าววาจาใดได้ หรือว่าตนเอง\nกระทําการวุ่นวาย กลับบ่มเพาะหมอหญิงให้กับรัฐชิงผู้หนึ่ง เพียงไม่ทราบ\nง่าหากรับการฝึกอบรมจากเพยเจีย สุดท้ายเม่ยเม่ยจะกลายเป็นเปียน\nเชวีย หรือไม่?\nไม่ ไม่อาจเป็นตัวประหลาดหญิงเปียนเชวีย สมควรเป็นพระแม่เจ้า\nซีหวงมู่ที่สูงสง่า ฟ่านเสียนมองดูใบหน้าที่งามสดใสของเม่ยเม่ย นึก\nปลอบโยนตนเองว่า อย่างน้อยก็ต้องเป็นต้าฉางจิน ฉบับรัฐชิง\nวิกาลกราย\nซือซีอปูผ้าปูทีนอน ปรับระดับของเตาไฟให้พอดี จากนั้นล่าถอย\nออกจากห้องพร้อมกับซือฉีทียกนำเข้ามา ฟ่านเสียนสองสามีภรรยานอน\nสงบบนเตียง มองดูเปลวเทียนนอกห้องสลัวลงทีละน้อย ผ่านไปเนินนาน\nยังไม่ส่งเสียงสําเนี้ยงใด\n“นอนไม่หลับหรือ?”\nกลางวันนอนมากเกินไป ท่านเล่า วันนี้ไฉนนอนไม่หลับ จํา\nได้ว่าตอนอยู่บนเขาชังซาน ท่านหลับใหลราวกับลูกแมว”\n๓๑๓ เวย ข ด ทรด\nเอ่ยถึงแมว ไม่ทราบว่าเจ้าขาวเจ้าเหลืองเจ้าดําเป็นไรแล้ว?\nฟ่านเสียนยิมพลางกล่าวว่า “เป็นท่านสังให้เถิงจือจิงอุ้มไปทีตัวตึก\nไร่นา ตอนนี้ไฉนคิดถึงพวกมันขึ้นมา?\nหลินว่านเอ้อพืมฬาว่า “เป็นท่านบอกว่า เสียงแมวไม่เป็นผลดีแก่\nทารกในครรภ์”\nฟ่านเสียนงงจงันวูบ ได้แต่ฝืนยิม ไม่สะดวกกับการบอกต่อนางว่า\n๓ ส ๑ ๕ ซั \'\nตนเองรงเกยจสตวเลยงชนดน ไม่ว่าแมวแก่หรือลูกแมว เมอเหนทวงทา\nหมอมีชื่อเสียงยุคเลียดก๊ก เป็นผู้คิดค้นการจับชีพจรรักษาโรค\nแดจังกีม จอมนางแห่งวังหลวง','2026-04-17 09:49:11'),(207,10,204,'อันเกียจคร้านของพวกมัน ก็มีโทสะขึ้นมา\nณ์ ๑ ซ่ ,\nหลินว่านเอ้อขยับหันข้าง ลมหายใจที่คล้ายกล้วยไม้พวยพ่ไจ\nใบหน้าฟ่านเสียนกล่าวว่า “เซียงกง ข้าพเจ้าใชไม่มีประโยชน์หรือไม\nฟ่านเสียนยืนหน้าต่อภรรยากล่าวว่า “รู้สึกคันอยู่บ้าง ท่านช่วก๒\nให้กับข้าพเจ้า” จากนั้นกล่าวอย่างสงสัยใจว่า “ไฉนถามคําถามนี้?\nหลินว่านเอ๋อยืนมือมาเกาทีใต้ใบหูมัน เชิดปากน้อยๆ กล่าวว่า “คน\nทีข้างกายท่านคล้ายกับต่างมีปมเด่นของตัวเอง สามารถช่วยเหลือท่าน “\nเจ้อรู้จักค้าขาย ตอนนี้เย่อเย่อคิดเล่าเรียนวิชาแพทย์ ตัวนางเป็นผู้ท\nปัญญาแห่งมหานครอยู่แล้ว คุณชายเอียนสามารถช่วยเหลือท่านตูแน\nกิจการในสำนัก แม้แต่ไห่ถังแห่งเปียฉี ”\nฟ่านเสียนส่งเสียงไออย่างรุนแรง จนแทบกระทบถึงปากแผลพ่\nทรวงอก\nหลินว่านเอ้อลูบคลําด้านบนของปากแผลมันเบาๆ กล่าวสืบต่อ “\nก็เป็นยอดหญิงนางหนึ่ง เกิดความคิดทํานุบํารุงบ้านเมือง มีแต่ข้าพเจ้า.\nสุขภาพอ่อนแอตั้งแต่เล็ก ได้รับการเลียงดูจากในวังจนเติบใหญ่ ‘\nอันใดก็ไม่รู้จัก ไม่มีความสำเร็จเชิงบุ่น และไม่มีความสำเร็จเชิงบู๊”\nฟ่านเสียนฟังความหมายในวาจาภรรยาออก หลังจากเงียบงันข์.\nขณะ จึงกล่าว “ว่านเอ้อ ความจริงแล้วข้าพเจ้ามีคําพูดหลายประโยคไม่ได้\nบอกต่อท่าน”\nฟ่านเสียนกล่าวเสียงนุ่มนวลว่า “คนถือกําเนิดเกิดมา\nประโยชน์ก็ประเสริฐ ไม่มีประโยชน์ก็ไม่ดี มีบางบทบาทมิใช่เป็นความ\nต้องการของพวกเรา ยกตัวอย่างข้าพเจ้า ข้าพเจ้าความจริงตั้งปณิธานเป็น\nคนอยู่ว่างที่สูงศักดิ ส่วนเอียนปิงหวินไม่ได้ต้องการเป็นหัวหน้าสายสืบ ท่าน\nก็เห็นสภาพระหว่างมันกับคุณหนูเสินแล้ว”','2026-04-17 09:49:11'),(208,10,205,'มุมปากมันปรากฏรอยยิมอันอ่อนโยนขึ้น กล่าวอีกว่า “สำหรับกับ\nข้าพเจ้า ตัวท่านคือความพิเศษเฉพาะ ท่านเติบโตขึ้นในวัง ซึ่งเป็นสถานที\nทีหักเล่ห์ชิงเหลียม แต่ไม่ได้เปลี่ยนแปลงนิสัยใจคอของท่าน หากงอกงาม\nวาวกับดอกบัวช่อหนึ่ง ข้าพเจ้าโชคดีทีเด็ดลงมา นิความจริงเป็นเรื่องที\nหายากยิง”\nหลินว่านเอ้อรับฟังคําพลอดรัก บังเกิดความวาบหวามใจ แต่ยัง\nกล่าวอย่างลําบากใจอยู่บ้างว่า “แต่ว่า ถึงอย่างไรยังคง ”\nฟ่านเสียนตัดบทของนางว่า “มิหน้าซําว่านเฮ้อท่านเก่งกล้าสามารถ\nเวลาเล่นไพ่นกกระจอก แม้แต่ซือเจ้อยังเอาชนะไม่ได้”\nสองสามีภรรยาหัวร่อออกมา\nฟ่านเสียนเงียบงันชั่วขณะจึงกล่าวอย่างจริงจังว่า “อีกประการ\nข้าพเจ้าทราบว่าท่านถนัดจัดเจนอันใด ท่านมีประสบการณ์ต่อทิศทางของ\nราชสำนักเหนือกว่าข้าพเจ้า ทั้งมีสายตาที่แหลมคม หลังเหตุการณ์ทุจริต\nการสอบแขงขนชุนเทยน หากมิใช่ท่านเคลื่อนไหวในวัง ข้าพเจ้าคงไม่อยู่\nรอดปลอดภัยเช่นนี้ เชือว่าหากท่านช่วยข้าพเจ้าคิดอ่านวางแผน ต้องมี\nความสามารถไม่ด้อยกว่าเอียนปิงหวิน แต่ว่า ”\nหลินว่านเอ้อลืมตาทีกระจ่างสุกใส ถามว่า “แต่ว่าอะไร?\nฟ่านเสียนเน้นเสียงว่า “แต่ว่าข้าพเจ้าไม่ต้องการ ข้าพเจ้าไม่ต้องการ\nให้ท่านถูกลากดึงเข้ามายังเรื่องเหล่านี้ เรื่องเหล่านี้โสมมเกินไป ข้าพเจ้า\nไม่ต้องการให้ท่านสัมผัสถูก ท่านเป็นภรรยาข้าพเจ้า ข้าพเจ้ามีหน้าทีให้\nท่านอยู่อย่างเบิกบานแจ่มใส มิใชให้ท่านเปลืองสมองความคิดตลอดทั้ง\nมันยิมพลางสรุปว่า “ข้าพเจ้าเป็นผู้ถือลัทธิบุรุษต้องเป็นใหญ่ อยาง\nน้อยทางดต้านนิต้องเป็นเชนนี้','2026-04-17 09:49:11'),(209,10,206,'ผ่านไปเนินนาน หลินว่านเอ้อค่อยทอดถอนใจคําหนึ่ง ในเสียงทก\nถอนใจแฝงความพึงพอใจและปลาบปลืมประโลมใจ กล่าวเบาๆ 1:\nข้าพเจ้าจะอย่างไรเป็นเชือพระวงศ์ หลังจากนี้มีเรื่องบางประการ ท่าแก!\nไม่ต้องการให้ข้าพเจ้าได้ยิน ถึงแม้ข้าพเจ้าทราบว่าท่านไว้วางใจข้าพเจา\nแต่ท่านบอกแล้วว่าเรื่องเหล่านี้สกปรกโสมม ข้าพเจ้าไม่ต้องการให้ท่ กเ\nหลังจากนี้ระแวงสงสัยข้าพเจ้า หากยินยอมให้ท่านไม่บอกต่อข้าพเจ้า”\nการแต่งงานระหว่างนางกับฟ่านเสียน เป็นพระประสงค์ของฮ่องเย่\nแฝงกลินอายทางการเมือง ดีที่สวรรค์ส่งเสริม ให้บุรุษสตรีคู่นี้ใช้น่องไก่เก็\nลอบเข้าห้องหับไปพลอดรัก เปรียบกับการสมรสทางการเมืองทัวไป 1\nความมันคงกว่ามากนัก\nแต่ยามอยู่ท่ามกลางมรสุมทางการเมือง ต่อให้สองสามีภรรยาวัก!\nมันกว่านี้จะเป็นอย่างไร ในประวัติศาสตร์เกิดโศกนาฏกรรมเช่นนี้ไม่น้อก\nอย่าว่าแต่จ่างกงจู่ถึงอย่างไรเป็นมารดาบังเกิดเกล้าของนาง ดังนั้นคําพูต\nต ล มู เร ”\nของหลินว่านเอ้อเหล่านี้ไม่ได้เสแสร้งแกล้งมารยา ยิงไม่ได้ถอยเพื่อรูกคืง\nหากแต่คิดอ่านแทนฟ่านเสียนอย่างแท้จริง\nฟ่านเสียนกล่าวเสียงราบเรียบว่า “อย่าได้คิดมากไปแล้ว หากว่าเกิต\nมาชาติหนึ่ง กระทั้งคนที่ใกล้ชิดที่สุดยังไม่ไว้วางใจ ยังดําเนินชีวิตต่อไป\nความหมายในวาจาคือ หากว่าคนมีโอกาสชุบชีวิตใหม่ แต่ต้องเฝ้า\nระวังป้องกันคนข้างหมอนตลอดเวลา อย่างนั้นมันยินยอมไม่ฟื้นคืนชีพมา\nประเสริฐกว่า\nหิมะแรกตกลงยังมหานคร เกล็ดหิมะพอตกถึงพื้นก็ละลาย ตามบ้าน\nเรือนราษฎรเพิ่มความเย็นเยือกขึ้น ดีทีรัฐชิงมีสถานะที่เข้มแข็ง สิงของ\nเครื่องใช้อุดมสมบูรณ์ แม้แต่ชาวบ้านร้านถินก็ไม่ขาดแคลนเครื่องนุ่งห่ม','2026-04-17 09:49:11'),(210,10,207,'มองแต่ไกลเห็นชายคาบ้านเรือนทีเป็นสีดําปรากฏหมอกควันลอยขึ้น คาด\nว่าภายในบ้านมีเตาไฟเพิ่มความอบอุ่น\nรถม้าธรรมดาคันหนึ่งแล่นวนอยู่ในมหานครหลายรอบ ในที่สุดมา\nถึงหน้าตึกโดดเดียวกลางบ้านเรือนราษฎรหลังหนึ่ง วันนี้อากาศหนาวเย็น\nท้องถนนไว้ผู้คน ทุกที่ทางเงียบสงบ ย่อมไม่มีผู้ใดเห็นโฉมหน้าของคนที่\nลงจากรถม้า\nเติงจือเวียอุ้มฟ่านเสียนนั่งลงบนเก้าอิ๊ล้อเลือน เข็นเข้าสู่ลานตึก\nวันนี้ฟ่านเสียนสวมเสือคลุมตัวใหญ่ ปกเสือขนสัตว์ปิดลําคอ ให้\nความอบอุ่นแก่ร่างกาย สายตายามกวาดมอง เห็นชายหนุ่มผู้หนึ่งอยู่ที่มุ\nลานตึก กำลังผ่าฟืนตามคําสังของซูเหวินเม่า ต้องงงงันวูบ\nคิวคางของชายหนุ่มคุ้นตาอยู่บ้าง ทั้งเปลือยร่างท่อนบน ภายใต้\nอากาศทีเหน็บหนาว ปราศจากความสะทกสะท้าน ผ่าฟืนโดยไม่หยุดยัง\nฟ่านเสียนหยีตาลง กล่าวว่า “นี้เป็นตีตี (น้องชาย) ของซือหลีลี?\nลณ่ ณ ๑ ๐ « \' ณฆ่ๆยข\nเติงจือเวียรับคําดังอืมม์ กล่าวว่า “หลังจากทีใต้เท้ามีคําสัง เอียน\nจ่าง (หัวหน้าสำนัก) ก็เขียนคําสังลายมือ ให้พวกเรารับตัวมาจากคุกคุมขัง\nเนื่องจากแม่นางซือเข้าวังเปยฉีแล้ว ศักดิฐานะของมันกลายเป็นอ่อนไหว\nสูขย ๆชู ,\nจึงจัดให้อยู่ทีนี้\nฟ่านเสียนผงกศีรษะรับ ตึกหลังนี้เป็นที่พักเท้าของตนเอง นอกจาก\nตนเองและกำลังกลุ่มย่อยของหวังฉีเหนี้ยนแล้ว คงมีแต่เฉินผิงผิงที่ล่วงรู้\nจึงปลอดภัยยิง วันนี้มันทีไม่คํานึงถึงอาการบาดเจ็บรุดมาทีนี้ เพราะว่า\nฮ่องเต้จัดสรรพยัคฆ์พิทักษ์แก่ตนเอง การคงอยู่ของพยัคฆ์พิทักษ์ แม้\nสามารถรับประกันความปลอดภัยของตนเอง แต่ในพวกมันคงต้องมีหูตา\nทีฮ่องเต้ส่งมาจับตาดูตนเอง\nหวนนึกถึงหลังจากนี้ยากจะมีโอกาสรุดมา วันนี่มันจึงฝ่าลมหิมะมา\nฟ่านเสียนกล่าวว่า “คุณชายซือผู้นิเป็นคนหุนหันพลันแล่น เพราะ','2026-04-17 09:49:11'),(211,10,208,'เพื่อเจียเจีย (พี่สาว) ของมัน กลับวิงจากแคว้นเปียฉีมาถึงรัฐชิง ยากรับ4ก !\nว่าหลังจากนี้จะไม่ออกจากตึกหลังนี้” มันยกมือกําเป็นหมัด ไอเบาๆ \"คา\nหนึ่งแล้วกล่าว “จับตาดูอย่างใกล้ชิด หากว่ามีความเคลือนไหวผิดปวเห\nให้ฆ่ามันทึง”\nเตงจอเวยรบคาคราหนง ผลักดันมันเข้าไปข้างใน เกาอลอเลอน\nบดผ่านนำหิมะบนพื้นไป\nฆ ซ่๐ ๑- ๑ ๑2 ร,ๆชูซ่\nเจ้าหน้าที่สำนักตรวจสอบในห้องออกมาต้อนรับ เห็นใต้เท้าถีซื้อทง\nสฆจับย ,\nบนเก้าอิล้อเลือน ต้องใจสันสะท้าน คลายเกดความรูสกหลอน เข้าใจ2\nรัฐชซึ่งปรากฏเฉินผิงผึงคนทีสองขึ้น','2026-04-17 09:49:11'),(212,10,209,'ฝ่บบทหมาย5ัก\nตัวตึกบนถนนเซ็ินเจิงใช้ถ่ายทอดคําสังของฟ่านเสียน และรับ\nข่าวสารทีหวังฉีเหนี้ยนส่งมาจากทางเหนือ ตี๋ตีของซือหลีลีกับผู้อื่นล้วน\nฆ ดคดขเ ๑ ๐ \'\nอยู่ที่ห้องข้าง เก็บรักษาห้องหับให้ฟ่านเสียนนั่งทํางาน ยามปรกติย่อมไม่\nก่อไฟทิงไว้\nถึงแม้ว่าวันนี้ทราบว่าใต้เท้าถีซือจะมา มีคนก่อเตาเพิ่มความอบอุ่น\nล่วงหน้า แต่ภายในห้องสะสมความเย็นมากเกินไป ในเวลาอันสันจึงขับ\nไม่ออก ฟ่านเสียนนั่งบนเก้าอิล้อเลือน รู้สึกถึงความหนาวเย็นในห้อง\nเป่าลมหายใจใส่ฝ่ามือ ฝืนยิมพลางกล่าวว่า “กระทั้งเตาไฟยังไม่ก่อทิงไว้\nทางสำนักยากจนถึงเพียงนี้หรือ?\nเติงจือเวียกำลังปิงจานฝนหมึกอยู่เหนือเตา ทั้งสังคนจัดหานำร้อน\nซ่ นู 1 เเสซัๆปย ป\nแชพูกนทผนกแขงตว พอฟังต้องฝืนยิมพลางกล่าวว่า “ระหว่างนี้ใต้เท้ามี\nเรื่องวุ่นวาย ทั้งยังรับบาดเจ็บ ระดับล่างไม่ได้ตระเตรียมว่าท่านจะมาใน\nอย่างยากเย็นค่อยตระเตรียมใกล้แล้วเสร็จ ฟ่านเสียนมองดูเติงจือ\nเวียออกแรงใช้แท่งหมึกฝนจาน ทั้งเติมนำอุ่นลงไป ลงทุนลงแรงราวกับ\nกาลงลบมด ในที่สุดค่อยฝนนำหมึกออกมา','2026-04-17 09:49:11'),(213,10,210,'ฟ่านเสียนผงกศีรษะด้วยความพึงพอใจ ยืนพู่กันที่อ่อนนุ่มไปในจก\nฝนหมึก จุ่มนำหมึกขีดเขียนตัวหนังสือลงบนกระดาษขาวสะอาด เขียนไม\nไม่กีตัว หมึกก็ผนึกแข็งตัวแล้ว\nฟ่านเสียนพานโยนพู่กันทีคล้ายท่อนไม้ลงบนโต๊ะ ด่าทอว่า “\nดินฟ้าอากาศผีสางอันใด อยู่บ้านไฉนไม่หนาวถึงเพียงนี่?\nเติงจือเวียรู้สึกมีลมหนาวโชยมาจากทุกทิศทาง จึงตอบอย่าง\nระมัดระวังว่า “ทีนี้ต้องใช้เตาเป็นจํานวนมาก ตอนที่ซื้อตึกหลังนี้ไม่1\nอุปกรณ์เหล่านี้ แม้แต่คังที่นอนก็ไม่ได้ก่อไฟ”\nฟ่านเสียนตัดบทว่า “ข้าพเจ้าไม่คิดนอนทีนี้” จากนั้นกล่าวตัดพ้อว่\nท่านคนหนึ่ง เหล่าหวัง (คนแซ่หวัง) คนหนึ่ง ล้วนตระหนี้ถีเหนี้ยวจแ\nตาย ตอนแรกให้เงินหวังฉีเหนี้ยนหนึ่งพันตําลึง มันเพียงใช้เงินหนึ่งร้อย\nยีสิบตําลึงซือตึกทรุดโทรมหลังนี้ คิดปล่อยให้ข้าพเจ้าแข็งตัวตายหรือ?\nเติงจือเวียนึกเห็นอกเห็นใจผู้บังคับบัญชาเก่าซึ่งอยู่ไกลถึงแคว้น\nยฉี ยังถูกใต้เท้าถืีซ็อกล่าวพาดพิงทุกวัน จึงอธิบายอย่างระมัดระวังว่า\nนดทเงยบสงบ\nฟ่านเสียนกวาดมองมันแวบหนึ่ง กล่าวว่า “มิใช่เงี่ยบสงบ แต่เรียก\nว่ายากเข็ญ หากให้ขุนนางใหญ่ในมหานครพบเห็น ยังเข้าใจว่าสำนักตรวจ\nสอบเราเป็นหน่วยงานใสสะอาดเสียอีก”\nวันนี้มันคิดเขียนจดหมายสำคัญหลายฉบับ จึงไม่คํานึงมากความ\nฝืนใจใช้พู่กันทีแข็งทีอ สุดท้ายไม่ถนัดมือได้แต่ละทึง ตบโต๊ะร้องว่า “มอบ\nดินสอแท่งนั้นแก่ข้าพเจ้า”\nเติงจือเวียค่อยล้วงหยิบดินสอดําจากเสือผ้าชันในแท่งหนึ่ง ส่งมอบ\nต่อฟ่านเสียน กล่าวอย่างจริงจังว่า “สิงของนี้มีค่ายิง ฟังว่าท้องพระคลังมี\nเหลืออยู่ไม่มาก ใต้เท้าต้องใช้อย่างประหยัด”\nฟ่านเสียนยืนมือแย่งชิงมา กวาดมองมันอย่างเหยียดหยามแวบหนึ่ง','2026-04-17 09:49:11'),(214,10,211,'ครุ่นคิดว่ามิใช่เป็นดินสอดําแท่งหนึ่งหรอกหรือ ยังมีค่าอันใด รอจนไปถึง\nแดนเจียงหนั้น ค้นหาเหมืองตะกัวสักหลายแห่ง ท้องพระคลังจะเริมต้น\nสณุว ๐ 1 ส ๕ 2 ๑7” ๑2” ๆชง”\nผลิตดินสอดําใหม่ เมื่อถึงเวลานั้นเราจะให้ท้องพระคลังจัดให้กับท่านสอง\nเข่ง เข่งหนึ่งให้ท่านเขียนจนตาย อีกเข่งหนึ่งให้ท่านขว้างปาเล่น\nดินสอดําขีดเขียนไปบนกระดาษขาวสะอาด คล้ายกับสาวงามใช้\nปลายเท้าลีลาศบนผิวนำแข็ง บางครั้งสะกิดเกล็ดหิมะปลิวกระจาย\nเติงจือเวียทราบว่าใต้เท้าถีซือคิดเขียนจดหมายลับ จึงล่าถอยออก\nไป ภายในห้องหนังสืออันเย็นเฉียบ มีแต่ฟ่านเสียนขีดๆ เขียนๆ คนเดียว\nนี่เป็นจดหมายลับของสำนักตรวจสอบ เรื่องราวในจดหมายมีความ\nสำคัญยิ่ง มิหน้าซ้้าลายเส้นของดินสอดําลบออกได้ ดังนั้นฟ่านเสียนไม่\nไว้วางใจ ใช้ถ้อยคําซ่อนเร็น หากว่าเป็นข้อความลับล้วนแต่ใช้ภาษาลับ\nจดหมายเขียนถึงหวังฉีเหนี้ยน เกี่ยวข้องกับตระกูลชุย เนื่องเพราะ\nตระกูลชุยในมหานครถูกกดดัน เพื่อระดมทุนให้กับองค์ชายรองกับทางแดน\nซิ่นหยาง จําต้องส่งของเถื่อนไปยังแดนเปยฉี แต่ช่องทางทางตด้านนั้นยัง\nไม่ปรุโปร่ง จึงเกิดสภาพสินค้าตกค้างขึ้น\nตอนนี้สินค้าที่ขนออกจากแดนซิ่นหยางอยู่ในระหว่างทาง มีจํานวน\nถึงเศษหนึ่งส่วนหกของผลผลิตทั้งปีของท้องพระคลัง\nจากอัตราส่วนนี้ แสดงว่าระหว่างที่จ่างกงจู่ดูแลท้องพระคลัง ทําการ\nยักยอกเป็นเงินมากมายเพียงไหน\nสภาพในปัจจุบันเป็นผลจากการที่ฟ่านเสียนกับเอี่ยนปิงหวินใช้เวลา\nหลายเดือนโจมตืองค์ชายรองกับบีบค้นตระกูลชุย ที่รอคอยคือยามนี้ มัน\nคิดรับประทานฝ่ายตรงข้ามลงไป กระทั่งเศษกระดูกยังไม่คายออกมา\nคําพูดสุดท้ายที่เขียนถึงหวังฉีเหนี้ยนคือยกอาหารขึ้นโต๊ะได้แล้ว','2026-04-17 09:49:11'),(215,10,212,'ฟ่านเสียนนั่งบนเก้าอิล้อเลือน ใช้นิวมือลูบด้านบนของปากแผล ที่\nนั้นพันผ้าพันแผลไว้เกิดอาการคันแทบตาย\nหลังจากเขียนจดหมายเสร็จฉบับหนึ่ง มือไม้เริมแข็งทีออยู่บ้าง ต้อง\nนึกถึงตอนอยู่ที่อ่าวต้านโจว ซือซือทําหน้าที่คัดลอกหนังสือให้กับตนเอง\nขณะทีตนเองเขียนหนังสือ ยาโถวนี้จะดึงมือของตนเองซูกกับหน้าอกนาง\nสัมผัสถูกความกลมกระเปาะ ให้ความรู้สึกทีดียิง\nฟ่านเสียนวาบหวิวใจขึ้นมา จับดินสอดําเขียนต่อ จดหมายฉบับที่\nสองเขียนถึงไห่ถังตว่อตวอ ขณะที่เขียนจดหมายฉบับนี้ มันปล่อยตัวปล่อย\nใจ ใช้ถ้อยคําที่อุกอาจ แฝงความหมายปลูกเร้า\nหลังจากกลับจากแคว้นเปียฉี มันก็เขียนจดหมายติดต่อกับไห่ถังมิได้\nขาด คุ้นชินกับการมีมิตรสหายทางเหนือคนหนึ่ง จะอย่างไรทั้งสองเป็น\nบุคคลสำคัญของสองประเทศ มีความจําเป็นต้องสร้างช่องทางสือสาร เป็น\nประโยชน์ในภายหน้า\nในจดหมายยังเอ่ยถึงเรื่องป่ากัว ทีเกิดขึ้นในมหานคร รวมถึง\nเหตุการณ์บนวิหารฮุ่ยคง ถึงแม้ว่าข่าวฮ่องเต้รัฐชิงถูกปลงพระชนม์สะท้าน\nทัวแผ่นดิน ทางแดนเปยฉีได้รับรายงานแต่แรก แต่มันเป็นผู้อยู่ใน\nเหตุการณ์ ยามบ่งบอกบรรยายย่อมตื่นเต้นเว้าใจเป็นพิเศษ\nหลังจากนี้ยังเอ่ยถึงเรื่องอื่น ทั้งซ่อนภาษาลับอยู่ในถ้อยคําว่า ตนเอง\nตระเตรียมลงมือต่อตระกูลชุยแล้ว ให้นางกับฮ่องเต้เปียฉีสอดประสานกับ\nตนเอง ที่ท้ายจดหมายยังคัดลอกบทกวี พิสูจน์ว่าตนเองยังทรงภูมิปัญญา\nดุจเดิมว่า\n“ตัวเราคิดตอบแทนพระคุณ มิมุ่งหวังลาภสักการะ ยินยอมตายเพื่อ\nผู้รู้ใจกัน คงต้องฝังกระดูกที่ชายแดน มวลมิตรสหายล้วนเห็นห่าง สวมชุด\nหนาหนักพู่หมวกปลิว ทราบว่าทางเหนือหิมะพัดพลิว ไม่ทราบดํารงชีพ\nกือสซิป','2026-04-17 09:49:11'),(216,10,213,'ได้อย่างไร”\nนี้เป็นข้อความตอนท้ายที่ซือหม่ากวง ประพันธ์ขึ้นตอนแร้นแค้น\nฟ่านเสียนมีความรู้สึกว่าตนเองคัดลอกบทกวีนี้สอดคล้องกับสถานที่ มิ\nหน้าซําระหว่างบรรทัดแฝงความหมายเห็นอกเห็นใจผู้คน สมควรสร้าง\nความหวันไหวใจแก่ให่ถัง การหลอกลวงหญิงสาวจนตายไม่ต้องชดใช้ชีวิต\nเป็นเรองทมันนิยมชมชอบ\nหลังจากตรวจทานจนแน่ใจว่าไม่มีที่ใดตกหล่น ฟ่านเสียนค่อยปิด\nผนึกซอง ประทับตราครังลงไป แต่แล้วฉุกใจคิด เห็นว่าตนเองยังพลอด\nพรํารําพันไม่พอ ดังนั้นคลีกระดาษอีกแผ่นหนึ่ง ขบคิดแล้วจรดดินสอดํา\nเขียนว่า\n“ตว่อตวอ ท่านสบายดี จดหมายฉบับก่อนเป็นเรื่องส่วนรวม ฉบับ\nนี้จะชวนสนทนาพาทีกัน วันนี่มหานครเกิดหิมะแรกแห่งปี เปรียบกับที่ผ่าน\nมาถือว่ามาเร็วกว่า คาดว่าหิมะทีเมืองสังจิงยิงหนาหนัก อากาศยิงเหน็บ\nหนาว วันที่อยู่ในแปลงผักของท่าน เห็นมุมรัวมีต้นเหมย ไม่ทราบผลิดอก\nเหมยแดง แต่งแต้มพื่นหิมะขาวหรือไม่\n“เป็ดที่ท่านเลี้ยงไว้เป็นอย่างไร ขอให้เพิ่มความระวัง อย่าปล่อยให้\nหนาวตาย ข้าพเจ้าทางด้านนี้เป็นปรกติ เจ้าเหลืองเจ้าดําเจ้าขาวถูกเลียง\nในตัวตึกไร่นานอกเมือง ฟังว่าผู้คนในตึกขุนจนเป็นแมวอ้วนสามตัว อาจ\nบางทีการเลี้ยงดูมีปัญหา\n็ข้าพเจ้าสบายดี กินได้นอนหลับ ทางบ้านเงียบสงบ สองวันนี้เม่ย\nเม่ยขลุกอยู่ที่ตึกไท่อี กลายเป็นปรากฏการณ์แปลกใหม่ในมหานคร วันนี่\nว่านเอ๋อกลับตึกตระกูลหลิน ต้าจิว (พีชายภรรยา) ที่น่ารักของข้าพเจ้า\nระหว่างนี้ถูกละเลย อารมณ์ไม่สู้ดีนัก ไม่ทราบว่าตอนนี้ท่านกำลังทําอะไร”\nฟ่านเสียนเขียนตามสบาย คล้ายกำลังโอภาปราศรัย นึกได้อะไรก็\nขุนนางสมัยราชวงศ์ซ้อง เคยดํารงตําแหน่งมหาเสนาบคดี ทั้งจัดทําหนังสือประวัติศาสตร์ จือจือทงเจียน','2026-04-17 09:49:11'),(217,10,214,'เขียนอย่างนั้น\n“ยังมี ลูกศิษย์แซ่ซื้อของเราเปิดหอนางโลมหลังหนึ่ง กิจการค้าไม่\nเลว โดยเฉพาะอาหารโอชะ วันใดท่านท่องเทียวถึงรัฐชิง ข้าพเจ้าจะเป็น\nเพื่อนท่านไปลิมลองดู ใช่แล้ว ข้าพเจ้าลืมชื่อเหลาสุราทีเมืองสังจิงนั้นไป\nแต่ยังจําได้ว่าสุราในวันนั้นไม่เลว ทั้งกล่าววาจาเหลวไหลต่อท่านไม่น้อย\nไม่ทราบท่านจําได้มากน้อยเท่าใด\n“จดหมายที่ท่านส่งมา ข้าพเจ้าอ่านดูอยู่หลายเที่ยว รู้สึกเปรี่ยวฝาต\nยิง ท่านเป็นยอดหญิงสูงส่ง อย่าได้เลียนเยียงกุลสตรีในหอห้อง สอดแทรก\nบทกวีในจดหมาย ถึงแม้ว่าข้าพเจ้าได้ชือว่าเซียนกวี แต่ไม่มีอารมณ์ตรวจ\nแก้ความเรียง\nัครั้งก่อนท่านบอกว่าซือหลีลีมีความเป็นอยู่ไม่เลว เรื่องนือย่าได้\nเอ่ยถึงอีกแล้ว ข้าพเจ้านึกคุมแค้นต่อเรื่องนี้ตลอดมา มิหน้าซําไม่ทราบ\nเพราะเหตุใด พอได้ยินข่าวคราวของนางจากปากท่าน ก็ปวดเศียรเวียน\nเกล้าขึ้นมา\n“ตว่อตวอ มาท่องเทียวรัฐชิงเถอะ ภรรยาข้าพเจ้าเกิดความสงสัย\nอยากรู้ต่อท่าน ทั้งขอถามสักคํา เคล็ดวิชาสํานึกฟ้าเอกะของพวกท่าน\nสามารถถ่ายทอดต่อคนนอกหรือไม่ ระหว่างนี้ข้าพเจ้าเกิดความสนใจต่อ\nเคล็ดวิชาฝีมือของพวกท่านขึ้นมา\nนี้คล้ายเป็นการถามดู แท้จริงแล้วกลับแสดงออกถึงความเจ้าเล่ห์\nเพทุบายของฟ่านเสียน\nหิมะทีนอกหน้าต่างคล้ายหนาหนักกว่าเดิม ชายหนุ่มทีเบื่องนอก\nยังคงผ่าฟื้น คนหนุ่มมักเลือดลมร้อนระอุ ถึงแม้ข้าพเจ้ายังเยาว์วัย แต่ไม่\nทราบเพราะเหตุใด จิตใจกลับชราร่วงโรย มองดูผู้คนเรื่องราวรอบข้าง ยาก\nจะปลูกปลอบความสนใจขึ้น ทงเบอหนายทั้งเหนอยล้า\nลมหิมะที่เบืองนอกโชยพัด เร่งรัดให้ข้าพเจ้าจรดพู่กันลง เป็นอันว่า','2026-04-17 09:49:11'),(218,10,215,'ยุติแต่เพียงนี่ เตาในห้องชํารุดเกินไป ไม่สามารถเร่งอุณหภูมิสูงขืน ถึงแม้\nยังคิดสนทนากับท่าน แต่เห็นว่าไม่จําเป็นต้องต่อสู้กับสวรรค์อันโหดร้าย\nยังมี ช่วยดูแลมันให้กับข้าพเจ้า ขอขอบคุณอย่างสูง ขออวยพรให้สมมาด\nปรารถนา”\nจดหมายแม้ธรรมดา แต่ภายในเจือปนข่าวสารที่เป็นประโยชน์มาก\nหลาย มันอ่านจดหมายอีกเทียวหนึ่ง จากนั้นลงท้ายว่า “หวังฉีเหนี้ยน หาก\nท่านกล้าแอบอ่าน ข้าพเจ้าจะให้หลานชายของมู่เถี่ยแอบดูบุตรีท่านอาบ\n“ไฉนเพิ่มจดหมายอีกฉบับหนึ่ง?”\nเติงจือเวียนับจํานวนจดหมายในมือ จากนั้นลืมตากลมโตถามว่า\n“ส่งถึงแม่นางไห่ถังสองฉบับหรือ?\nฟ่านเสียนตัดบทว่า “ถามไถ่มากความทําอะไร?” จากนั้นสังการว่า\nใช้วิธีการเดิมส่งถึงเมืองสังจิง\nเติงจือเวียผงกศีรษะรับ เดินออกจากห้อง ส่งจดหมายที่ปิดผนึก\nเรียบร้อยหลายฉบับนั้นแก่กำลังกลุ่มย่อยของหวังฉีเหนี้ยนที่น้อมรออยู่\nเจ้าหน้าที่นั้นนับจํานวนจดหมายในมือ ตั้งคําถามดุจเดียวกันว่า\n“ไฉน เพิ่มจดหมายอีกฉบับหนึ่ง?”\nเติงจือเวียสูดลมหายใจเข้าไปคําหนึ่ง กล่าวเสียงเย็นชาว่า “ถามไถ่\nมากความทําอะไร?”\nทั้งสองพากันปิดปากลง คิดอ่านในใจ ใต้เท้าถีซื้อใช้ช่องทางลับ\nสุดยอดของสำนักตรวจสอบส่งจดหมายรักออกไป ออกจะฟุ่มเฟือยเกินเหตุ\nฟ่านเสียนนั่งเก้าอิล้อเลือนออกจากตัวตึกบนถนนเซ็นเจิง ขึ้นรถม้า','2026-04-17 09:49:11'),(219,10,216,'ไปยังตึกตระกูลหลิน เตรียมรับตัวว่านเอ๋อกับต้าเปากลับบ้าน\nหลังจากขืนรถ ฟ่านเสียนค่อยนึกถึงคําสังแต่งตั้งในราชโองการล1!\nนถามว่า “ตําแหน่งไท่เสวียซือเยียมีหน้าทีอันใด ยังมี ข้าพเจ้าไม่ไม\nตึกไท่ฉังซือมานาน ครั้งนี้ไฉนเลือนตําแหน่งข้าพเจ้าเป็นขุนนางเม้ 1\nเติงจือเวียอธิบายตําแหน่งหลังก่อนว่า “ขุนนางเส้าชิงตึกไท่ฉังอ\nมีสองท่าน เยินเส้าอันเป็นหัวหน้า ใต้เท้าเป็นผู้ช่วย แต่ว่านิเป็นตําแหน่ง\nลอย ไม่ต้องไปทุกวัน ส่วนตําแหน่งไท่เสวียซือเยียดูแลหน่วยงานเจ็ดแพ่ง\nตําแหน่งทั้งสองล้วนจัดเป็นขุนนางชันทีสี”\nมันกล่าวเตือนสติว่า “ใต้เท้า ท่านแม้รับตําแหน่งถีซื้อสำนักตร9\nสอบ ไม่อาจดํารงตําแหน่งในราชสำนัก แต่ถึงอย่างไรฮ่องเต้ไม่ได้ยกเลผิ!\nตําแหน่งในตึกไท่ฉังซือกับสถานศึกษาไท่เสวีย ครั้งนี้ฝ่าบาทแต่งตั้งท่าเ\nรับตําแหน่งลอยทั้งสองตําแหน่ง คาดว่าเพียงเป็นพระมหากรุณา ‘\nเจตนาอย่างอืน”\nฟ่านเสียนสันศีรษะ ตําแหน่งขุนนางทั้งสองตําแหน่งนั้นอยู่ใน\nราชโองการลับ ตอนแรกฟ่านเสียนไม่ได้ใส่ใจ ต่อมายิงครุ่นคิดยิงไม่ถูกต้อง\nฮ่องเต้มีพระทัยลึกลํา ต้องไม่ทรงแต่งตั้งตําแหน่งอย่างเลือนลอยแน่นอน\nฟ่านเสียนขมวดคิว เรียบเรียงคําพูดว่า “ตําแหน่งทั้งสองนี้ มีควาง!\nพิเศษเฉพาะอันใด?”\nเติงจือเวียขบคิดแล้วกล่าวอย่างไม่แน่ใจว่า “ตําแหน่งเส้าชิงค่อนข้าง\nดาษดีน ไม่มีความพิเศษอันใด ขุนนางเส้าชิงตึกไท่ฉังซือดูแลกิจการของ\nศาลเจ้าหลวง สามารถเข้าวังได้โดยสะดวก ส่วนตําแหน่งขุนนางไท่เสวีก\nซื้อเยียไม่ปรากฏมานานปี หลังจากปรับปรุงข้อบริหารราชการแผ่นดิน\nตําแหน่งต่างๆ กลายเป็นสับสนอยู่บ้าง ”\nมันพลันตบต้นขาฉาดหนึ่ง กล่าวด้วยความยินดีว่า “นึกออกแล้ว','2026-04-17 09:49:11'),(220,10,217,'ผ่านมาขุนนางไท่เสวียซือเยียต้องเข้าวังไปสอนหนังสือให้กับราชโอรส เป็น\nผู้ช่วยของขุนนางไท่ผู่\nฟ่านเสียนอ้าปากค้าง ชั่วครู่ไม่อาจกล่าววาจาใดได้ ในที่สุดมันค่อย\nเข้าใจว่าฮ่องเต้ทรงแต่งตั้งตําแหน่งทั้งสองนี้ให้ตนเองทําอะไร ตําแหน่ง\nขุนนางเส้าชิงตึกไท่ฉังซือควบตําแหน่งขุนนางไท่เสวียซือเยีย ไยมิใช่ให้\nตนเองกลายเป็นครูบาอาจารย์ขององค์ชายทั้งสาม?\nกล่าวให้แน่ชัดคือ ให้อบรมสังสอนเหล่าซัน (อันดับสาม)\nฟ่านเสียนนึกถึงตอนนี้ ต้องร้องโพล่งว่า “บิดาไม่มีเวลาเข้าวังไป\nทุกวัน มิใช่ต้องเดินทางสู่แดนเจียงหนั้นหรอกหรือ ไฉนยังมอบหมาย\nงานเช่นนี้ให้อีก?”\nเสียงเอียดคราหนึ่ง รถม้าคล้ายถูกมันรําร้องด่าทอจนหยุดก็กลง\nฟ่านเสียนเลิกม่านหน้าต่างรถมองออกไป เห็นที่หน้ารถปรากฏขันทีผู้หนี้\nนำราชองครักษ์ในวังหลายนายขวางทางไว้\nเหยากงกงมองดูฟ่านเสียนในรถ หนาวสันจนขนคิวเต้นกระตุก\nกล่าวเสียงสันสะท้านว่า “ใต้เท้า บ่าวค้นหาอย่างยากเย็น รีบตามเราไป\nเถอะ ฝ่าบาทเบิกตัวท่านเข้าวัง”','2026-04-17 09:49:11'),(221,10,218,'','2026-04-17 09:49:11'),(222,10,219,'ท่ขนสุทยานหสาบน (1)\nวันนี้เหยากงกงไปที่ดึกตระกูลฟ่าน แต่หาคนไม่พบ ไม่ทราบว่า\nใต้เท้าถีซือทีกำลังพักรักษาตัวไปที่ใด แม้แต่ฟ่านสังซูก็ไม่ทราบ ฮูหยิน\nเสียวฟ่านผู้สูงศักดิก็ไม่อยู่ในตึก ไม่ทราบจะสอบถามร่องรอยของฟ่าน\nเสียนจากผู้ใด\nแต่ว่าฮ่องเต้ทรงรออยู่ในวัง สร้างความร้อนรุ่มใจแก่เหยากงกงยิง\nสอบถามดูค่อยทราบว่าสูหยินเสียวฟ่านกลับไปยังตึกตระกูลหลิน จึงนำราช\nองครักษ์ริบรุดมา ประจวบพบเห็นรถม้าคันนี่ทีปากถนน หากมิใช่ราช\nองครักษ์ตาแหลมคม จดจําผู้ติดตามคนหนึ่งของฟ่านเสียนออก คงต้อง\nคลาดจากกันแล้ว\nฟ่านเสียนมองดูเหยากงกงทีหอบหายใจ ทอดถอนใจกล่าวว่า\nข้าพเจ้ายังต้องกลับตึกตระกูลหลินไปรับคน ไฉนบอกให้ข้าพเจ้าเข้าวังใน\nเหยากงกงร้อนรุ่มใจแทบตาย มันไหนเลยเคยเห็นขุนนางทีไม่ให้\nความสนใจกับพระราชกระแสในวัง มันกับตระกูลฟ่านมีการคบหาด้วยดี ไม่\nสะดวกกับการกล่าวกระไร ได้แต่เร่งรัดว่า “ฝาบาทมีพระราชกระแสมานาน\nแล้ว หากใต้เท้าเสียวฟ่านไปสาย เกรงว่าฝ่าบาทไม่ยินดี”','2026-04-17 09:49:11'),(223,10,220,'ฟ่านเสียนกล่าวเสียงละห้อยว่า “ย่อมต้องไปอยู่แล้ว” มันไม่๓า1\nหักใจทนดูเหยากงกงยืนอยู่บนพื้นหิมะ จึงเรียกหาขันทีผู้เฒ่าขึ้นรถ\nผู้คนเดินทางเข้าวัง ทั้งจัดคนไปยังตึกตระกูลหลินแจ้งต่อหลินว่านเอ้อ\n“เหล่าเหยา (คนแซ่เหยา) ลองบอกว่าเกิดเรื่องอันใด?”\nฟ่านเสียนพิงผนั่งรถ หลับตาพักผ่อน กล่าวโดยไม่เหลือบแลอีกฝ่าย\nตึกตระกูลฟ่านป้อนขันทีเหล่านี้จนอิมหมีพีมัน ดังนั้นมันคร้านที่จะหยิบย\nตัวเงินให้อีก\nซึ่งความจริงเหยากงกงตอนนี้ไม่กล้ารับตัวเงินจากตระกูลฟ่านถ่ง\nเพียงยิมประจบกล่าวว่า “นี้ บ่าวไหนเลยทราบได้ ท่านไปแล้วจะทรา\nฟ่านเสียนสันศีรษะแสร้งกล่าวอย่างขุ่นเคืองว่า “ท่านผู้นี้ทํางานไม่\nจริงจัง” หยุดเล็กน้อยจึงกล่าวอีกว่า “ขอสอบถามเรื่องหนึ่ง”\nเหยากงกงเงียใบหูมองดูรอบตัวรถ ไม่พบเห็นคนนอก จึงลดสุ้มเสียง\nเบาลง กล่าวว่า “ใต้เท้า เรื่องอันใด หากว่าบอกได้เราจะบอกกล่าวให้ทราบ“\nฟ่านเสียนขมวดคิวกล่าวว่า “เหล่าขันที ทีวิหารฮุ่ยคงนั้นจัดกา\nเหยากงกงงงจงันวูบ จึงยกมือขึ้นปาดใส่ลําคอตนเองคราหนึ่ง\nฟ่านเสียนมีสีหน้าเป็นปรกติดุจเดิม มันทราบว่านี้เป็นผลที่ต้องเกิด\nขึ้น ในขบวนขันทีปรากฏคนร้าย คนในบริเวณย่อมยากรอดพันจากชะตา\nกรรม เกรงว่าในวังต้องชําระสะสางขนานใหญ่ จึงกล่าว “เหล่าไต้ (คนแซ่\nเหยากงกงบอกกล่าวว่า “ไม่ มันเป็นคนชรา ฝ่าบาทยังไว้วางใจ แต่\nไม่อาจประจําอยู่ที่ท้องพระโรงอีก เมื่อสองเดือนก่อน เพราะหลานชายที\nไม่รักดีของมัน ถูกตึกตูฉาเอี่ยนฟ้องร้องเทียวหนึ่ง ต้องทนลําบากอยู่ในวัง\nอยางลาบากยากเยน ฝ่าบาทเห็นแก่หน้าสูกุ้ยเฟย ค่อยชุบเลียงมันใหม่','2026-04-17 09:49:11'),(224,10,221,'พลางชําเลืองมองฟ่านเสียนแวบหนึ่ง ฟ่านเสียนไม่แสดงออกอันใด\nเหยากงกงไม่ทราบว่าระหว่างฟ่านเสียนกับไต้กงกงมีความสัมพันธ์ลึกซึ่ง\nเพียงไหน จึงกล่าวต่อ “คิดไม่ถึงเกิดเหตุการณ์ปลงพระชนม์ขึ้น เหล่าได้\nช่างเคราะห์ร้ายจริงๆ ไม่ว่าตําแหน่งใดล้วนถูกถอดถอน ยังถูกฟาดโบยสิบ\nเนรเทศไปยังหน่วยซือคู อายุปูนนิยังต้องทํางานหนัก\nเหยากงกงกับไต้กงกงเข้าวังพร้อมกัน ยามปรกติแม้เคยงัดข้อกัน\nแต่ยามนี้เห็นอีกฝ่ายพังครีนลง อดเกิดความเศร้าหดหู่ต่อชะตากรรมของ\nพวกเดียวกันมิได้ ต้องยกแขนเสือขึ้นเช็ดหางตาคราหนึ่ง\nฟ่านเสียนสันศีรษะกล่าวว่า “เหล่าไต้ อดทนอีกหลายวันเถอะ รอ\nจนฝ่าบาทคลายจากกริวแล้วค่อยว่ากล่าว สามารถรักษาชีวิตไว้ถือว่าไม่\nเลวแล้ว” จากนั้นกล่าวถามว่า “ตอนนี่เป็นผู้ใดประจําท้องพระโรง?”\nเหยากงกงตอบว่า “เป็นหงจู๋” มันเห็นฟ่านเสียนมีสีหน้าเคลือบแคลง\nสงสัย จึงอธิบายว่า “เป็นเด็กน้อยผู้หนึ่ง ปีนี้เพิงวิงเต้นระหว่างท้องพระโรง\nกับสำนักจงซูเสิง ฝ่าบาทโปรดมันที่คล่องแคล่วว่องไว”\nฟ่านเสียนกล่าวด้วยความสงสัยอยากรู้ว่า “เรื่องถ่ายทอดพระราช\nกระแสก็เป็น หงจู้ผู้นั้น?”\nเหยากงกงสันศีรษะกล่าวว่า “มันไหนเลยมีคุณสมบัติเช่นนี้?”\nรถม้าแล่นถึงปากถนนซินเจีย ก็ถูกเหยากงกงร้องบอกให้หยุดลง\nเติงจือเวียไม่ใคร่พึงพอใจ จะอย่างไรลานที่ว่างหน้าประตูวังกว้างขวาง\nท่ามกลางหิมะโปรยปราย ให้ใต้เท้าถีซือที่ยังไม่ทุเลาจากอาการบาดเจ็บ\nนั่งเก้าอิล้อเลือนผ่านไป ไม่กลัวใต้เท้าตัวแข็งตายหรือ\nเหยากงกงกล่าวอย่างอับจนปัญญาว่า “กวนแหย (คําเรียกผู้ดํารง\nตําแหน่ง) ทั้งหลาย นี้เป็นเรื่องอับจนปัญญา หลังจากเกิดเรื่องครังก่อน\nทหารรักษาพระองค์ปรับปรุงขนานใหญ่ ปิงแหย (คําเรียกนายทหาร) ทั้ง','2026-04-17 09:49:11'),(225,10,222,'หลายเฝ้าจับตาดูทุกคน ถึงกับคิดขู่ขวัญผู้คนทีเข้าวังไปให้หมดสิน\nฟ่านเสียนรับฟังอยู่สองคําก็กล่าวว่า “อย่าได้สร้างความลําบากแก่\nเหยากงกงแล้ว พวกเราลงไปเถอะ\nเติงจือเวียกวาดมองประตูวังอย่างขุ่นเคืองแวบหนึ่ง จากนั้นอุ้มฟ่าน\nเสียนลงจากรถ วางลงบนเก้าอิล้อเลือน แล้วกางร่มสีดําขนาดใหญ่ บดบัง\n\' ฆ ซ่ ๐ ๕\nอย่เหนือศีรษะของใต้เท้าถีซือ เจ้าหน้าที่สำนักตรวจสอบทีด้านหลังเข็น\nเก้าอิล้อเลือนแทน หิมะพอตกลงบนร่มสีดํา บังเกิดเสียงดังเบาๆ\nเหยากงกงไม่ได้รับการปฏิบัติเช่นนี้ ต้องยกมือปิดบังศีรษะ รีบรุด\nไปยังประตูวังพร้อมกับราชองครักษ์ทั้งหลาย\nฟ่านเสียนห่อตัวอยู่ในเสือคลุมขนาดใหญ่ หลบเลียงจากลมหนาว\nซ่ ฆ เว ๑7 ๕๓๑7 ๕4 ๕ ฆ งจง», ข ๕\nทีมาปะทะหน้า ใช้ปกเสือขนสัตว์ปิดบังครึ่งซีกหน้า ยังรู้สึกมีความเย็นขุม\nหนึ่งชําแรกเข้ามาในเสือผ้า\nทหารรักษาพระองค์ทีหน้าประตูวังรับหน้าเหยากงกง ดําเนิน\nขันตอนในการเข้าวัง พลางมองดูขบวนผู้คนทีเดินผ่านลานกว้างมา ใต้\nลมหิมะเกลื่อนฟ้า เจ้าหน้าที่นอกเครื่องแบบเหล่านั้นเข็นเก้าอิล้อเลื่อน\nคันหนึ่ง เหนือเก้าอิล้อเลื่อนกางร่มสีดํา บดบังเกล็ดหิมะที่ตกลงจากฟ้าเอา\nไว้ ไม่ปรากฏคราบหิมะตกใส่ร่างคนบนเก้าอิล้อเลือนแม้แต่น้อย\nหัวหน้าขบวนทหารรักษาพระองค์กล่าวอย่างสงสัยใจว่า “วันนี้หาได้\nเบิกตัวใต้เท้าเอี่ยนจ่าง (หัวหน้าสำนัก) เข้าวังไม่\nทหารรักษาพระองค์นายหนึ่งกล่าวว่า “นิเป็นฟ่านถิซือ\nทั้งหมดใจหายวาบ หัวหน้าขบวนทหารรักษาพระองค์ตรงเข้ารับ\n\'หนา เพยงตรวจสอบคนบนเกาอลอเลอนอยางลวกๆ แล้วปล่อยให้เข้าวัง\nลมเหนือโชยพัด เกลิดหิมะปลิวว่อน เติงจือเวียเข็นเก้าอิล้อเลือนไป\nตามเส้นทางข้างตําหนักหลัก สีสันของกําแพงวังยิงมายิงลึก สุดท้ายหยุด','2026-04-17 09:49:11'),(226,10,223,'เท้าทีหน้าประตูขวามอบานหนึ่ง\nปรากฏขันทีกางร่มสีดําขนาดใหญ่ ปิดบังอยู่เหนือศีรษะฟ่านเสียน\nอย่างมิดชิด ห้อมล้อมผู้บาดเจ็บอายุเยาว์ผู้นี้เข้าสู่วังหลัง\nเดินทางอยู่ครู่หนึ่ง ฟ่านเสียนพลันขมวดคิวกล่าวถามเหยากงกงที\nข้างกายว่า “มิใช่ห้องทรงพระอักษรหรือ?”\nก่อนนี้มีข่าวว่าฮ่องเต้ทรงรอเป็นเวลานาน ฟ่านถีซือยังไม่มาถึง จึง\nกริวขึ้นมา เหล่าขันทีน้อยพอรับตัวฟ่านเสียนได้ ไหนเลยกล้าชักช้า พากัน\nวิงตะบึงเข้าสู่วังหลัง เก้าอิล้อเลือนถูกเข็นลันเอียดอ๊าด ขันทีที่กางร่มสีดํา\nขนาดใหญ่ก็โอนไปเอนมา หากมิใช่พื้นผิวภายในวังราบเรียบ การรีบรุด\nเดินทางเช่นนี้ คงสร้างความสันสะเทือนแก่ปากแผลของฟ่านเสียนจนปริ\nแตกแล้ว\nเหยากงกงวิงจนหอบหายใจ ตอบว่า “ที่ ที่ตําหนักบรรทม”\nฟ่านเสียนเกิดความประหลาดใจ สีหน้าปันยากอยู่บ้าง เหยากงกง\nสังเกตเห็นเช่นนั้น ค่อยฉุกคิดว่าหากรีบรุดเดินทางจนอาการบาดเจ็บของ\nฟ่านถีซื่อกําเริบขึ้น ตนเองคงยําแย่แล้ว จึงรําร้องด่าทอออกมา ให้ทั้งหมด\nชะลอความเร็วลง จากนั้นค่อยสอบถามฟ่านเสียนว่า “ใต้เท้าเสียวฟ่าน\nได้รับความกระทบกระเทือนกระมัง?”\nฟ่านเสียนตอบว่า “ยังไม่สูงศักดิถึงเพียงนั้น”\nไม่นานให้หลัง ทั้งหมดมาถึงมมหนึ่งของอุทยานหลวง แต่มิใช่\nตาหนกบรรทมของฮองเต หากเป็นทีอยู่ของอิกุ้ยผิง เหยากงกงเรงฝีเท้า\nเข้าไปกราบทูล หลังจากนั้นมีคนออกมารับตัวฟ่านเสียนเข้าไป\nวันนี้ฮ่องเต็ทรงฉลองพระองค์ชุดลําลอง ประทับนั่งบนตั้งเตียงอัน\nอบอุ่น ทรงมีปฏิสันถารกับอีกุ้ยผิง องค์ชายสามนั่งอยู่ด้านข้างอย่างเรียบๆ\nร้อยๆ กำลังคัดลอกอันใด\nเหล่าขันทีพอเข็นเก้าอิล้อเลื่อน นำฟ่านเสียนเข้ามา ฮ่องเต็ค่อยปิด','2026-04-17 09:49:11'),(227,10,224,'ประโอษฐ์ ทอดพระเนตรฟ่านเสียนแวบหนึ่ง ตรัสว่า “เมื่อรับบาดเจ็บ ไม่\nนอนพักรักษาตัวในบ้าน ออกไปวิงเพ่นพ่านทําอะไร?”\nฮ่องเต้พระองค์หนึ่งรับสังตําหนิขุนนางหนุ่มผู้หนึ่ง แท้จริงแล้วทาง\nแสดงความห่วงใย ผู้เป็นขุนนางสมควรสํานึกตื่นตันจึงถูกต้อง แต่ฟ่าน\nเสียนกลับแค่นหัวร่อในใจ หากว่าห่วงใยตนเองจริง ไยต้องรอถึงสิบเจ็ด1\nค่อยแสดงออก หากทรงเป็นห่วงอาการบาดเจ็บของตนเอง เหตุใดจึงรีง\nร้อนเบิกตัวตนเองเข้าวัง?\nแต่ว่าเปลือกนอกฟ่านเสียนแสรังเป็นสํานึกเต็มตื่นวูบหนึ่ง\nจากนั้นกล่าวเสียงราบเรียบว่า “ทูลฝ่าบาท อาการบาดเจ็บใกล้ทุเลา จึง\nกล้าออกไปท่องเทียว ทั้งเตรียมไปยังตึกตระกูลหลิน รับตัวว่านเอ๋อกลับ\nฮ่องเต้ตรัสว่า “ว่านเอือ กลับตึกตระกูลหลินไปหรือ ในตึกไม่มี\nนอกจากตัวโง่งมตนหนึ่ง\nพระองค์คล้ายไม่โปรดปรานที่หลานสาวไปมาหาสู่กับตึกตระกูลหลิน\nพระพักตร์ไม่พอพระทัยอยู่บ้าง\nอีกุ้ยผิงสังเกตพระพักตร์ฮ่องเต้ จึงหัวร่อพลางหันเหหัวเรื่องว่า\n“ฟ่านเสียน ท่านยังไม่ทุเลาหายดีก็ออกไปข้างนอก ไม่กลัวฟ่านสังซู\n(ขุนนางสังซูแซ่ฟ้าน) ฟาดโบยก้นหรือ?”\nฮ่องเต้ทรงพระสรวลออกมาตรัสว่า “ฟ่านเจียน ไหนเลยหักใจได้?\nนี้แม้เป็นรับสังหยอกล้อ แต่ภายในแฝงความหมายอย่างอื่น ฟ่าน\nเสียนต้องใจสันสะท้าน ใบหน้าปันรอยยิมขึ้น ไม่กล่าวว่ากระไร\nฮ่องเต้ทอดพระเนตรองค์ชายสามซึ่งคัดลอกหนังสืออยู่ด้านข้าง\nแวบหนึ่ง จากนั้นรับสังต่อฟ่านเสียนว่า “ก่อนหน้านี้เจ้าไปยังสถานศึกษา\nไท่เสวีย ตรวจชําระหนังสือหลายเล่ม ข้าให้เฉิงผิงคัดลอกออกมา ขุนนาง\nไท่ผู้เห็นว่าลึกลําเกินไป เจ้าคิดเห็นอย่างไร เฉิงผิง เข้ามาคํานับใต้เท้า','2026-04-17 09:49:11'),(228,10,225,'องค์ชายสามแซ่หลีนามเฉิงผิง ตามกฎของรัฐซชิง เหล่าองค์ชายต้อง\nแสดงความเคารพต่อขูนนางใหญ่ ฮ่องเต้รับสังเช่นนี้ ไม่น่าประหลาดอันใด\nดังนั้นองค์ชายสามรีบวางพู่กันลง เดินถึงหน้าเก้าอิล้อเลือน น้อมคํานับต่อ\nฟ่านเสียน\nฟ่านเสียนนั่งบนเก้าอีล้อเลือน ไม่สามารถหลบเลียง ได้แต่กล่าวว่า\n“นี้จะได้อย่างไร?”\nฮ่องเต้รับสังว่า “ตอนนี้ท่านรับตําแหน่งไท่เสวียซื้อเยีย สมควร\nรับการคํานับอยู่แล้ว”\nพระองค์รับสังราวกับเป็นเรื่องธรรมดา อิกุ้ยผิงฟังออกว่าฮ่องเต้มี\nพระประสงค์ให้ฟ่านเสียนเป็นครูบาอาจารย์ขององค์ชายสาม หวนนึกถึง\nฟ่านเสียนเปรืองปราดทั้งบุ่นและบู้ มีอิทธิพลอยู่ในราชสำนัก สร้างความ\nยินดีแก่อิกุ้ยผิงจนยิมแย้มแจ่มใส สายตาทีมองดูฟ่านเสียน รู้สึกสบายตา\nกว่าเดิม\nสีหน้านิพอปรากฏแก่สายพระเนตรฮ่องเต้ อดทรงพระสรวลมิได้\nตรัสว่า “ดูท่านยินดีถึงเพียงนี้”\nอิกุ้ยผิงทีเป็นทีโปรดปราน เพราะว่าเปลือกนอกของนางไม่เก็บซ่อน\nพอยินดีก็แสดงความยินดี ยามนี้ได้ยินฮ่องเต้รับสังหยอกเย้า นางก็\nบผิงเอ้อคนหนึ่ง\nฟ่านเสียนได้ยินทั้งสองปฏิสันถารกัน สร้างความขุ่นข้องใจ ครุ่นคิด\nเรื่องนี้ไฉนไม่มีคนสอบถามความเห็นของเรา?\nองค์ชายสามหอบหนังสือมา ฟ่านเสียนรับมาตรวจดูโดยคร่าวๆ จาก\nนั้นเงยหน้าขึ้นกราบทูลว่า “รูปแบบการปกครองของจวงม่อหานประเสริฐ\nเลศยง ขุนนางไท่ผู้เห็นว่าลึกลําเกินไปก็มีเหตุผล แต่หลายบทนี้เพียงเป็น','2026-04-17 09:49:11'),(229,10,226,'ซ๊ ๕ ข้ - เว \"\nวิชาเบืองต้น ซันเดียนเซีย (องค์ชายสาม) สัมผัสก่อน ก็ไม่มีปัญหาใด\nเจ้าชีวิตกับขุนนางสนทนาอีกหลายคํา ฟ่านเสียนตอบอย่าง\nระมัดระวัง ทราบว่าฮ่องเต้ต้องมีพระราชกระแสอันใด จริงดังคาดหมาย\nหลังจากเสวยนำแกงร้อนกรุ่นชามหนึ่ง ฮ่องเต้ก็รับสังว่า “หิมะข้างนอก\nหยุดตกแล้ว หิมะแรกนาถนอม ฟ่านเสียน เจ้าเป็นเพื่อนข้าออกไปเดิน\nเล่นในสวน”\n“ทราบแล้ว ฝ่าบาท”\n\' เว ๑ สูร &\nฮ่องเต้ประทับยืนขึ้น อกุยผงยมพลางหยบฉวยเสอคลุมลายนก\nกระเรยนหนง แมวป่าตัวหนึ่งคลุมลงบนพระวรกาย\nขณะทออกจากตําหนักเส้าฟางทอ\nกุ้ยผิงพักอาศัยอยู่ หิมะหยุดตก\nแล้ว พื้นดินทั้งลื่นทั้งใสสะอาด แต่ไม่ ม่สุมคลุมด้วยหิมะ เพียงแต่ต้นไม้ใน\nอุทยานแขวนไว้ด้วยเส้นหิมะ ท้องฟ้าเป็นสีขาวอมเทา กําแพงสีแดงชายคา\nขบ ๕ ธ ทๆขย ๑, \'\nสีเหลือง ก้อนอิฐเขียวกิงไม้หิมะ ขับเน็นจนงดงาม อากาศก็สดชีนแจ่มใส\nฮ่องเต้ทรงคลุมเสือคลุมขนาดใหญ่สาวพระบาทนำหน้า ขันทีน้อย\nผู้หนึ่งเข็นเก้าอิล้อเลือนของฟ่านเสียนตามเสด็จอยู่ด้านหลัง ตามรายทาง\nเหล่าขันทีนางกํานัลที่สวมชุดนวมหลบเลียงแต่ไกล หากพบกันระหว่างทาง\nก็ยืนหันข้างสงบนิงไม่พูดจา\nฮ่องเต้คล้ายทรงคาดเดาออกว่าฟ่านเสียนคิดอะไร จึงรับสังว่า “วัน\nซ เข จ่ซ เซ\nฝนหิมะตก พบเห็นข้าไม่ต้องคุกเข่า นี้เป็นกฎทีข้างตราไว้ตั้งแต่ขึ้นครอง\nวาชย์ ตลอดทั้งวันเอาแต่คุกเข่า ต่อให้พวกมันไม่รําคาญ หากว่าคุกเข่าจน\nเสือผ้าสกปรก หรือว่าขาดวิน ทางท้องพระคลังต้องควักเงินซือหา”\nฟ่านเสียนนั่งบนเก้าอิล้อเลือน ลอบปลดกระดุมปกเสือเม็ดหนึ่ง หลัง\nจากลมหิมะหยุดตก รู้สึกร้อนอยู่บ้าง พอได้ยินพระกระแสรับสัง ทราบว่า\nหัวข้อสนทนาเตรียมหันเหไปทางท้องพระคลัง มันกลับปิดปากไม่ยอม','2026-04-17 09:49:11'),(230,10,227,'พูดจา\nฮ่องเต้คล้ายกริวต่อการนิงเงียบงันของฟ่านเสียน จึงตรัสเสียง\nไจว ม ซ๊ เซ่\nเยนชาวา “เหลาเอ้อ (อันดับสอง) ของตระกูลฟ่านตอนนี้อยู่ที่ใด?\nยามนี่มาถึงสวนอุทยานทีเงียบสงบภายในวัง ทีเบื่องหน้ามีบึงนำ\nเล็กๆ เหนือบึงพาดสะพานหินทอดถึงเก๋งกลางบึง ภายในเก๋งมีคราบหิมะ\nหินสีดําอันเย็นเยือกได้\nเบาบาง แต่ไม่อาจปิดบังหินสีดําอันเย็นเยือก','2026-04-17 09:49:11'),(231,10,228,'','2026-04-17 09:49:11'),(232,10,229,'ท่ยนสุทยานหสาน (2)\nหิมะแรกหยุดตก ภายในวังยังสะสมความหนาวเย็นไว้ อานุภาพแห่ง\nธุง ข้ วัย\nฟ้านี้ยากรับไว้ได้ แต่ฟ่านเสียนนั่งบนเก้าอิล้อเลื่อน รู้สึกอบอุ่นสบาย เสือ\nคลุมปกเสื่อสูงทีสวมใส่สามารถต้านลมหิมะ ถึงกับร้อนอยู่บ้าง\nฟ่านเสียนเตรียมใจรับมือพระกระแสรับสังถามของฮ่องเต้ไว้แต่แรก\nจึงกราบทูลว่า “เมื่อวันก่อนเพิงได้รับจดหมายว่าพักอาศัยที่เมืองสังจิงแล้ว\nมันเหลียวมองขันทีน้อยที่ด้านหลังแวบหนึ่ง ยามนั้นฮ่องเต้กำลัง\nสาวพระบาทไปที่เบืองหน้า จึงไม่ทันสังเกตพบการสบสายตาของบูคคลที่\nด้านหลังทั้งสอง\nขันทีน้อยนี้คือหงจู๋ มันเห็นสายตาทียิมแย้มของฟ่านถีซือ ไม่ทราบ\nเพราะเหตุใดรู้สึกหัวใจเย็นวาบ บังเกิดความกลัวขีนมา\nหงจู้ทราบว่าใต้เท้าถีซีอกระตุ้นเดือนตนเองว่า มีคําพูดบางคําไม่อาจ\nเข้าหูบุคคลอื่น ระหว่างนี้ขันทีน้อยนี้ตามเสด็จอยู่ตลอดเวลา ล่วงรู้ท่าที\nของเจ้าชีวิตกับขุนนางคนนี้เป็นอย่างดี จึงรีบกัมศีรษะลงไม่กล้าสบ\nสายตากับฟ่านเสียน\nหงจู้เองก็คิดปืนป่ายภูผาสูงเช่นฟ่านเสียน ไหนเลยกล้าเปิดโปงเรื่อง\nทีไม่เป็นผลดีต่อตระกูลฟ่านออกไป','2026-04-17 09:49:11'),(233,10,230,'ฮ่องเต้ทางหนึ่งสาวพระบาทไปยังบึงนำ ทางหนึ่งรับสังว่า “เพียงน\nเท่านั้นหรือ ข้าเห็นว่านี้แม้เป็นเรื่องที่ผู้คนทราบแน่แก่ใจ แต่ก็สมคว\nดําเนินการบางอย่าง”\nฟ่านเสียนก้มศีรษะหมูนคอ ให้ข้างแก้มเสียดสีกับขนสัตว์บนปกเสือ\nปากกล่าวว่า “ฝ่าบาทรับสังถาม เฉิน (คําเรียกตัวเองของขุนนาง) ไม่กล้า\nกลาวเทจแมสกครงคา\nฮองเตพลนหยุดชะงกลง ขันทิน้อยริบรังดิงเก้าอิล้อเลอนของฟ่าน\nเสียน ไม่กล้าเทียบเคียงกับฮ่องเต้\nฮ่องเต้เหลียวพระพักตร์มาทอดพระเนตรฟ่านเสียน รับสังว่า “ไม่\nกล้ากล่าวเท็จต่อข้า แต่กล้าพูดปดผู้คนทั้งแผ่นดินหรือ?” รอยย่นที่หาง\nพระเนตรฮ่องเต้คล้ายฉายรอยยิมทั้งแฝงความหมายคาดค้นเค้นถาม\nฟ่านเสียนเงยหน้าขึ้น สบสายพระเนตรของฮ่องเต้อย่างอุกอาจอยู่\n“ชนชาวโลกโฉดเขลา เฉินเพียงจงรักภักดีต่อฝ่าบาท ไม่\nบ้าง กล่าวว่า\nซือสัตย์ภักดีต่อราษฎรเหล่านั้น\nสายพระเนตรฮ่องเต้ทอแววฉงนสนเท่ห์ ตรัสว่า “แต่มีคนบอกว่า\nประชาราษฎร์สำคัญที่สุด ประเทศชาติสำคัญรองลงมา ผู้ปกครองสำคัญ\nน้อยที่สุด\nฟ่านเสียนลอบขมวดคิวกล่าวว่า “ล้วนเป็นวาจาเหลวไหล ไม่ทราบ\nผู้ใดบังอาจถึงเพียงนี้?”\nมันย่อมทราบว่าเป็นผู้ใดบังอาจถึงเพียงนี้ ผู้บัญญัติคือเม่งจื่อ คน\nคัดลอกคือมารดามันเอง\nฮ่องเต้สาวพระบาทต่อไป พลางรับสังว่า “ตอนนี้กรมราชทัณฑ์ยัง\nตามล่าตีตเจ้า หรือเจ้าไม่กลัวข้าลงโทษเจ้า?\nหงจั๋เข็นเก้าอิล้อเลือนตามไป ฟ่านเสียนได้ยินเสียงเก้าอิล้อเลือน\nปราชญ์เมธียุคเลียดกิก ซึ่งสืบทอดปรัชญาความคิดของขงจื่อ','2026-04-17 09:49:11'),(234,10,231,'ฒ ข & ๑ ๕ส \' \'\nลันเอียดอ๊าด รู้สึกปวดเศียรเวียนเกล้าขึ้นมา ต้องสันศีรษะกล่าวว่า\n“ฝ่าบาททรงปรีชาสามารถ ย่อมเข้าใจความคับแค้นจําเป็นของเฉิน”\nฮ่องเต้ตรัสทวนคําว่า “ความคับแค้นจําเป็น? เกรงว่าเหล่าเอ้อ\n(อันดบสอง) จึงมีความคับแค้นจําเป็นที่ไม่อาจระบายบอกกล่าวกระมัง?\n“เฉินผิดไปแล้ว”\nมันทราบว่าตอนนี่สมควรเล่นละครดุจเดียวกับขุนนางคนสนิทของ\nฮ่องเต้ในละครโทรทัศน์ชุดกษัตริย์แมนจู แต่มันทราบว่าการกระชากองค์\nชายรองลงมา ความจริงเป็นพระประสงค์ของฮ่องเต้เอง ตนเองเพียงเป็น\nดาบเล่มหนึ่ง มิหน้าซําในพระทัยฮ่องเต้ ตนเองไม่เพียงเป็นขุนนาง หาก\nมีความสัมพันธ์อีกชันหนึ่ง\nดังนั้นฟ่านเสียนไม่กลัวเกรงแต่อย่างไร ทั้งไม่ตื่นเต้นตึงเครียด เป็น\nเหตุให้แสดงออกอย่างเกินจริง คําเฉินผิดไปแล้วลากจนยาวเหยียด คล้าย\nกำลังแสดงละคร\nฮ่องเต้ลดพระสุรเสียงลงดูว่า “ต่อให้เล่นละครก็ต้องสมจริงกว่านี้”\nฟ่านเสียนกล่าวเสียงละห้อยว่า “เฉินผิดไปแล้ว”\nกล่าวไปกล่าวมายังคงเป็นคําเฉินผิดไปแล้ว กลายเป็นวาจาไร้สาระ\nดีที่ตอนนี่ทั้งสามขืนสะพานไม้ที่ทอดข้ามบึงนำแล้ว จึงยุติการสนทนาลง\nชั่วคราว\nถึงแม้มหานครเหน็บหนาว แต่ว่าหิมะแรกตก นำในบึงยังไม่แข็งตัว\nเป็นนำแข็ง ยังเป็นสีเขียวใส แผ่ซ่านความเย็นออกมา สะพานไม้แม้สร้าง\nบ ๒๑ ฑู ! ”\nอย่างมันคง แต่เมื่อเก้าอิล้อเลือนกดทับลงไป ยังให้ความรู้สึกไม่ปลอดภัย\nฟ่านเสียนต้องยืดจับที่เท้าแขนของเก้าอ จับจ้องมองรอยร่องบนสะพาน\nครุ่นคิดว่าหากขันทีน้อยทีด้านหลังกลับกลายเป็นมือสังหาร คงยําแย่แล้ว\nเหล่าขันทีนางกํานัลทีล่วงหน้ามาจัดเตรียมสิงของภายในเก๋ง ถวาย\nบังคมแต่ไกล จากนั้นแยกย้ายจากไป ไม่กล้ารังรออยู่ด้านข้าง','2026-04-17 09:49:11'),(235,10,232,'ฮ่องเต้ประทับนั่งบนม้าหินซึ่งปูเบาะกลมไว้ ใช้สายพระเนตรบอกไกพ้\nให้ฟ่านเสียนดีมน้ำชาทีร้อนกรุ่น สวนพระองค์ทรงแกะเม็ดสนอยางซาๆ\nขันทีน้อยหงจู๋ล่าถอยไปข้างเก๋ง ทางหนึ่งดูต้นทาง ทางหนึ่งรอว่าจู่จือ\n(นาย) ในเก๋งมีคําสังอันใด\nฮ่องเต้รับสังถามว่า “เป็นอย่างไร?”\nฟ่านเสียนคล้ายถูกน้ำชาในถ้วยลวกจนขมวดคิว ปากกล่าวว่า\n“ฝ่าบาทหมายถึงอาการบาดเจ็บของเฉิน หรือว่า ”\n“หมายถึงอย่างหลัง”\nฟ่านเสียนกราบทูลว่า “ตระเตรียมลงมือแล้ว คําสังถูกส่งออกไปโดย\nไม่ผ่านทางสำนัก สมควรไม่สะกิดความสนใจผู้คน”\nฮ่องเต้ผงกพระเศียรรับ\nฟ่านเสียนแจกแจงรายละเอียดว่า “ตอนนี้สินค้าที่อยู่ในอาณาจักร\nสมควรถูกสกัดไว้ แต่ว่า ทางแคว้นเปียฉี ข่าวคราวอาจรัวไหล มีคนทํา\nกําไรเป็นกอบเป็นกํา จะอย่างไรตระกูลชุยกักตุนสินค้าอยู่ทางเหนือไม่\nน้อย ” มันซูกงําข่าวสารสำคัญไว้ ต่อให้ฟาดมันจนตายก็ไม่เปิดเผยออก\nไปว่ามันกับฮ่องเต้เปยฉีแบ่งของโจรกัน\nฟ่านเสียนกล่าวสืบต่อ “เส้นทางส่งสินค้าขึ้นเหนือมีทั้งสินสามสาย\nตอนนี้ตึกที่สีทําการควบคุมไว้ ส่วนคนของสำนักทีวางอยู่ในท้องพระคลัง\nอยู่กับฝ่ายตรงข้ามเป็นเวลานาน ไม่อาจไว้วางใจ จึงไม่ใช้สอย”\nมันบอกแผนการของเอี่ยนปิงหวินออกไป แต่ยังไม่ทันกล่าวจบ\nฮ่องเต้ก็โบกพระหัตถ์ตรัสว่า “ข้าไม่ต้องการทราบรายละเอียด เพียง\nต้องการทราบผล”\nฟ่านเสียนหยุดไปเล็กน้อยจึงกล่าว “ฝ่าบาทโปรดวางใจ อย่างช้า\nหนึ่งปี สมควรดึงรายได้ของท้องพระคลังกลับมาครึ่งหนึ่ง\nฮองเตสายพระเศยรตรสวา ท้องพระคลังคิดฟินฟูสภาพเมื่อกาล','2026-04-17 09:49:11'),(236,10,233,'ก่อน เป็นเรื่องทีเป็นไปไม่ได้ คาดว่าเจ้าก็เข้าใจเหตุผลกลใน”\nฟ่านเสียนก้มศีรษะลง\nฮ่องเต้ตรัสถามว่า “ข้าถามเจ้า เหตุใดเจ้ามันใจว่าข้าจะสนับสนุนเจ้า\nลงมือต่อเหล่าเอ้อกับจ่างกงจู่?”\n“เพราะว่า ราชสำนักต้องการเงิน”\nหลังจากเงียบงันไปครู่หนึ่ง ฮ่องเต้จึงรับสังดังอืมม์ ตรัสว่า “\nราชสำนักคิดกระทําการ คิดขยายเขตแดน ก็ต้องใช้เงิน หลายปีนี้หวิน\nรุ่ย ล้วงเงินของท้องพระคลังมากเกินไป ทําให้ข้าไม่อาจทนดูต่อไป จึงให้\nม ทูทขม\nเจารบชวงดูแลแทน เจ้าไม่ได้สร้างความผิดหวังแก่ข้า กอนอนกลาทจะรบ\nช่วง รองลงมาคือลงมืออย่างดุดัน โดยไม่กริงเกรงศักดิฐานะของอีกฝ่าย\nเป็นส่วนทีข้าเลอกเจ้า\nฟ่านเสียนได้แต่กล่าวขอบพระทัยฝ่าบาท เนื่องเพราะเรื่องราวเกี่ยว\nพันถึงจ่างกงจู่ นางจะอย่างไรเป็นจังมู่ (แม่ยาย) ของตนเอง ตนเองย่อม\nไม่อาจวิพากษ์วิจารณ์\nฮ่องเต้ทรงคืบเม็ดสนเข้าพระโอษฐ์ ขบเคียวอย่างช้าๆ ลมหิมะที่\nนอกเก๋งสงบลง ในความเงียบสงบแฝงความหนาวอยู่บ้าง\nฮ่องเต้รับสังโดยไม่ใส่พระทัยเท่าใดว่า “เยียฉงกลับเขตชังโจวไปแล้ว\nข้าให้เหอชิงอ้อง รับตําแหน่งผู้บัญชาการทหารรักษาพระองค์ ฟังว่าใน\nๆข ไวเฒ\nมหานครมีคําวิพากษ์วิจารณ์ไม่น้อย เจ้าได้ยินมาบ้างหรือไม่?\nฟ่านเสียนฝืนยิมพลางกล่าวว่า “การวิพากษ์วิจารณ์ยากหลีกเลียง\nถึงอย่างไรขัดกับแบบแผนเก่า”\n“ในความเห็นเจ้าเล่า?”\nฟ่านเสียนใจหายวูบ ครุ่นคิดว่าเรื่องเช่นนี้ไหนเลยถึงรอบให้ตนเอง\nชื่อจริงของจ่างกงจู่\nบรรดาศักดิขององค์ชายใหญ่','2026-04-17 09:49:11'),(237,10,234,'แสดงความเห็น จึงกล่าว “ฝ่าบาทคิดอ่านมองการณ์ไกล เฉินไหนเลยกล้า\nกล่าวเพ้อเจ้อเหลวไหล\nฮ่องเต้รับสังโดยทีเพ่งพระเนตรไปที่ต้นไม้ในอุทยานหลวงว่า “บอก\nมาเถอะ ข้าจะให้อภัยโทษเจ้า”\nฟ่านเสียนสงบจิตใจลง มันทราบว่าการสนทนากับฮ่องเต้เป็น\nเรื่องยากลําบาก ครั้งกระโน้นอุ้ยเสียวป้อกล่าวเก้าเท็จหนึ่งจริง สุดท้ายยัง\nถูกค่งซฮองเต๋ คว้าหางเปียไว้ ส่วนเรื่องทิตนเองกระทําการเป็นการลับ มี\nทั้งลอบเข้าวังหลวงแห่งนี้ ทําข้อตกลงกับแคว้นเปยฉี และสนทนากับ\nเซียวเอิน ทุกประการล้วนปกปิดฮ่องเต้ที่เบืองหน้า หากว่าความจริงถูก\nเปิดโปง ผู้ใดทราบว่าตนเองจะมีจุดจบอย่างไร\nฮ่องเต้ทีเบื่องหน้าพระองค์นี่ลึกลําสุดหยังคาด หากมิใช่ตนเอง\nช่วงชิงความได้เปรียบ ยังไม่กล้าล้อเล่นด้วย ความได้เปรียบทีว่าคือตนเอง\nล่วงรู้ความสัมพันธ์ที่แท้จริงระหว่างตนเองกับพระองค์ ขณะทีพระองค์ไม่\nทรงทราบว่าตนเองล่วงรู้ข้อนี้ ดังนั้นฟ่านเสียนสามารถแสดงบทของขุนนาง\nพระองค์ยิงนึกเสียพระทัยต่อตนเอง ตนเองยิงได้รับประโยชน์\nฟ่านเสียนกล่าวตรงๆ ว่า “ต้าเตียนเซียไม่ต้องการรังอยู่ในมหานคร\nมิหน้าซําการลดบรรดาศักดิชิงอ้องให้รับตําแหน่งผู้บัญชาการ ถือว่าขัดกับ\nหลกเกณฑ ประเด็นสำคัญคือวังหลวงเป็นหัวใจของรัฐชิง มิอาจไม่ระวัง\nคําพูดนี้กล่าวตรงๆ ถึงกับข้ามเส้นแบ่งไป แต่ฮ่องเต้ไม่มีปฏิกิริยา\nใด เพียงตรัสเสียงเย็นชาว่า “ไม่ต้องการ? ในโลกมีเรื่องไม่สมมาดปรารถนา\nแปดเก้าส่วน มันไม่ต้องการรังอยู่ในมหานคร หรือหักใจปล่อยให้เราผู้เป็น\nบิดาอยู่เฝ้ามหานครเพียงลําพัง ฟ่านเสียน ทูตเจรจาเช่นท่านไม่เข้าเกณฑ์\nมาตรฐานแต่อย่างไร”\nฟ่านเสียนมีสีหน้ากระอักกระอ่วน ทราบว่าเรื่องทีองค์ชายใหญ่ไปยัง\nคํานี่ออกเสียงเป็นจีนแต้จิว','2026-04-17 09:49:11'),(238,10,235,'ตึกตระกูลฟ่าน ไม่อาจรอดพันจากสายพระเนตรฮ่องเต้\nฮ่องเต้หลับพระเนตรลง ตรัสว่า “อย่าได้ทะเลาะกับเหล่าเอ้อแล้ว ให้\nมันอยู่อย่างสงบเสงี่ยมเถอะ”\nฟ่านเสียนรับพระราชกระแส ตนเองบรรลูจุดประสงค์แล้ว ยังทะเลาะ\nฮ่องเต้พลันตรัสว่า “เหตุการณ์บนวิหารสุ่ยคง เจ้ามีความดีความ\nชอบใหญ่หลวง แต่เจ้ารังตําแหน่งถีซื้อสำนักตรวจสอบ กลับปล่อยให้\nคนร้ายปะปนเข้ามหานคร ก่อนเกิดเหตุตึกที่สองไม่ทราบระแคะระคาย\nถือว่าเจ้าบกพร่องต่อหน้าที ทั้งสองประการหักกลบลบล้างกัน ข้าได้แต่ส่ง\nซ่ เซมณี ส\nมอบสิงของทีไม่มีประโยชน์แก่เจ้า เจ้าอย่าได้ขึ่งเคียดไป”\nฟ่านเสียนกล่าวว่า “เฉินมิกล้า นี้เป็นความบกพร่องของเฉิน ส่วน\nเรื่องรับบาดเจ็บ เป็นเฉินฝีมืออ่อนด้อย จึงถูกมือกระบีชุดขาวนั้นทําร้าย\nฮ่องเต้พลันรับสังด้วยความสนพระทัยว่า “มือกระบีนั้น ยังสืบไม่\nออกว่าเป็นใคร เจ้าประมือกับมัน สามารถคาดเดาอันใดได้หรือไม่?”\nชาด้าน กลับปรากฏหยาดเหงือไหลซึมออกจากซอกคอ หยดหยาดลงยัง\nเสือผ้าชันใน มันไม่ทราบว่าฮ่องเต้รับสังถามด้วยพระประสงค์ใด แต่เห็น\nว่าหากตนเองไม่ระวัง ความพยายามที่แล้วมาล้วนล้มเหลวสิน\nมือกระบีชุดขาวคืออิงจือ (เงา) ไม่ทราบเฉินผิงผิงสร้างสภาวะเช่น\nนี้ด้วยเหตุผลใด ก่อนทีจะสือสารกับตนเอง ย่อมไม่กราบทูลความจริงต่อ\nฮ่องเต้ แต่หากฮ่องเต้ทรงคาดเดาออก ตนเองสมควรตอบว่าอย่างไร หาก\nบอกว่าตนเองไม่ทราบ ใช่จะโยกคลอนศักดิฐานะของตนเองทีอยู่ในพระทัย\nฮ่องเต้หรือไม่?\nฟ่านเสียนเพียงงงงันวูบ ก็กลบเกลือนผ่านไป กลาวอยางตนเตน','2026-04-17 09:49:11'),(239,10,236,'แวท ก ร ะ\nสงสัยว่า “ฝ่าบาทมิใช่บอกว่ามือกระบีชุดขาวนั้นเป็นตีตี๋ (น้องชาย) ของ\nกระบึสีทัศนาหรอกหรือ?\nฮ่องเต้ทรงพระสรวลอย่างเย็นชา “ครั้งกระโน้นนครตงอีเกิด\nเหตุการณ์แย่งชิงเมือง กระบีสีทัศนาไม่ยังกระบีไว้ไมตรี สังหารคนในบ้าน\nไม่น้อย ฟังว่ามีเพียงพีน้องคนหนึ่งหนี้รอดได้ นี้เป็นการคาดเดาของข้า\nเมื่อวันก่อนอยู่ชันบนของวิหาร กระบีอันเจิดจ้าท้าแสงอาทิตย์นั้น หากมิใช่\nสํานึกกระบีของกระบีสีทัศนา ข้าคงตาบอดไปแล้ว\nฟ่านเสียนค่อยคลายใจลง ทราบว่าตนเองทุ่มแทงถูก จึงกล่าว “น่า\nเสียดายนัก หากว่ามีหลักฐานแน่นหนา ปีหน้าใช้เป็นข้ออ้างกรีธาทัพต่อ\nนครตงอี เฉินแม้รับบาดเจ็บก็คู่ควร\nคําพูดนี้เกาถูกทีคันของฮ่องเต้ ฮ่องเต้พระองค์นี้นิยมกระทําการ\nเช่นนี้เอง จึงรับสังว่า “กระบีสีทัศนาได้รับการรักษาจากเฟยเจีย ไม่ได้\nปัญญาอ่อนอีก ไหนเลยยอมรับหนี้บัญชีรายนี้ ก่อนอืนไม่ยอมรับว่าตีดี\nยังมีชีวิตอยู่ ต่อจากนั้นส่งสาส์นมาแสดงความเสียใจต่อเหตุการณ์ทีข้าถูก\nปลงพระชนม์ ทั้งไม่เชือว่าคนร้ายจะโหดเหียมอํามหิตถึงเพียงนี้\nรับสังถึงตอนนี้ พบว่าไม่มีคนขานรับแต่อย่างไร พอเหลียวพระ\nพักตร์ไป ทรงพบว่าฟ่านเสียนมองดูพระองค์ ขันทีน้อยทีนอกเก๋งก็งอตัว\nลง สงบปากคําไว้\nฮ่องเต้ลอบทอดถอนพระทัย ดําริว่าผ่านไปนานปี ไม่มีคนกล้าขัด\nแย้งกับพระองค์เช่นนางอีก\nฮ่องเต้หม่นหมองพระทัยอย่บ้าง รับสังช้าๆ ว่า “ฟ่านเสียน ตอน\nอยู่บนวิหาร เจ้าไฉนช่วยเหลือผิงเฮ้อก่อน?\nฟ่านเสียนนั่งบนเก้าอิล้อเลือน กราบทูลขออภัยโทษแล้วกล่าว\n“สถานการณ์ในตอนนั้น หากเฉินไปถึงข้างพระองค์ ก็ได้แต่ต้านทานกระบี\nที่ด้านหน้า ไม่อาจรับมือดาบทางด้านหลัง ส่วนซันเตียนเซีย (องคชาย','2026-04-17 09:49:11'),(240,10,237,'สาม) ต้องตายแน่นอน”\n“อืมม์ หรือว่าชีวิตของข้ามีราคาไม่เท่ากับชีวิตของผิงเอ้อ?\nฟ่านเสียนทูลขออภัยโทษอีกครั้งว่า “เฉินสมควรตายหมืนครั้ง\nตอนนั้นสถานการณ์คับขัน ไม่ทันปรับตัวได้”\n“รอจนเจ้าโถมถึงเบื้องหน้าข้า ก็ ก็สูญเสียโอกาสรุกไป หรือว่าเจ้าไม่\nฟ่านเสียนขบคิดแล้วกล่าววาจาทรยศเนรคุณออกไปว่า “ตอนนั้น\nเฉินครุ่นคิด หากว่าด้านทานกระบีนั้นได้ก็ประเสริฐ หากว่าต้านทานไม่ได้\nเฮอะเฮอะ สามารถลงไปชมทิวทัศน์ของอีกโลกหนึ่งพร้อมกับฝ่าบาท ถือ\nเป็นเกียรติอย่างสูง”\nฮ่องเต้ทรงงงงันวูบ จากนั้นทรงพระสรวลดังๆ ออกมา เสียงทรง\nพระสรวลถ่ายทอดไปไกลโข เหล่าขันทีนางกํานัลซึ่งอยู่ห่างไกลต่างพากัน\nหันไปมองหน้ากัน ไม่ทราบว่าวันนี้ฟ่านถีซือกล่าวเรื่องขบขันอันใด ฝ่าบาท\nจึงเกษมสําราญถึงเพียงนี้\nฮ่องเต้ชะงักเสียงทรงพระสรวล เพ่งพิศพบเห็นส่วนที่ละม้าย\nเหมือนจากหว่างคิวฟ่านเสียน ยิงปลาบปลื้มพระทัย รับสังเสียงอ่อนโยน\nว่า “การไปแดนเจียงหนั้นครั้งนี่ อย่าได้ถาโถมออกไปโดยวู่วาม ฟังว่า\nตอนอยู่ทางเหนือ เจ้าก็หุนหันพลันแล่น ทั้งที่เป็นขุนนางใหญ่โต กลับไม่\nรักถนอมชีวิต”\nฟ่านเสียนบังเกิดความกระอักกระอ่วน ทราบว่า ฮ่องเต้รับสังมีเหตุผล\nขุนนางใหญ่ของประเทศมีสักกีคนที่เสียงอันตรายเช่นตนเอง แต่ว่าตนเอง\nนิยมเคลือนไหวเพียงลําพัง กล่าวถึงที่สุดเป็นเพราะไม่ไว้วางใจผู้ใด แต่\nว่าการเดินทางสู่แดนเจียงหนั้นต้องรออีกหลายเดือน ฮ่องเต้รับสังเช่นนี้\nคล้ายเร็วกว่าเหตุไป\nฟ่านเสียนนึกถึงเรื่องสำคัญประการหนึ่ง ต้องกล่าวด้วยความไม่','2026-04-17 09:49:11'),(241,10,238,'สบายใจว่า “ก่อนหน้านี้ฝ่าบาทรับสังในที่พักของอีกุ้ยผิง ใช่เป็นเรื่องก\nเล่นหรือไม่?”\nฮ่องเต้ตรัสเสียงเย็นชาว่า “เจ้าชีวิตไม่ล้อเล่น”\nฟ่านเสียนกล่าวอย่างประหวันลนลานว่า “เฉินอายุยังเยาว์ ไร้ซึ่ง\nคุณวุฒิ ไหนเลยเป็นอาจารย์องค์ชายได้?”\nฮ่องเต้แย้มพระโอษฐ์พลางตรัสว่า “ฟังว่า ตอนอยู่ทีเมืองสังจึง\nแคว้นเปยฉี ฮ่องเต้หนุ่มนั้นให้การยกย่องท่าน สำหรับด้านคุณวุฒิ แม้แต่\nจวงม่อหานยังกล่าวชมเชย ไหนเลยเป็นอาจารย์ไม่ได้ หากมิใช่เห็นว่าเจ้า\nอายุยังเยาว์ ข้าคงแต่งตั้งให้ท่านเข้าวังมาสอนหนังสือ ยังมีผู้ใดกล้าโต้\nฟ่านเสียนกล่าวด้วยความกลัดกลุ้มใจว่า “แต่ว่า ฤดูใบไม้ผลิปีหน้า\nเฉินต้องเดินทางสู่แดนเจียงหนั้น ไยมิใช่คลาดเวลาศึกษาหาความรู้ของ\nซันเตียนเซีย?”\nฮ่องเต้โบกพระหัตถ์ตรัสว่า “เจ้านำผิงเอ้อร่วมทาง ข้ากราบทูลต่อ\nไทเฮาแล้ว”\nฟ่านเสียนอ้าปากค้าง ชั่วครู่ยังไม่อาจกล่าววาจาใดได้\nฮ่องเต้รับสังด้วยพระพักตร์ราบเรียบว่า “หลังจากเสร็จเรื่องแดนเจียง\nหนั้น อยู่ในมหานครอีกสองปี ข้าจะให้เจ้าเข้าสำนักจงซูเสิง\nพระองค์จ้องตาของฟ่านเสียน รับสังเสียงอ่อนโยนว่า “ข้าจะให้ความ\nสำคัญแก่เจ้า\nฟ่านเสียนเงียบงันชั่วขณะ ค่อยผงกศีรษะรับ ทราบว่าการสนทนา\nเสร็จสินแล้ว ขณะจะทูลลากลับบ้าน มิคาดฮ่องเต้โบกพระหัตถ์ตรัสว่า “วัน\nนเป็นวันลิบตั้ง เนวังมีงานเลียง เจ้าอยู่รับประทานอาหาร ข้าส่งคนไป\nคํานี้ออกเสียงเป็นจีนแต้จิว เป็นหนึ่งในยีสิบสีฤดูกาลของจีน แปลว่าย่างเข้าสู่ฤดูหนาวแล้ว','2026-04-17 09:49:11'),(242,10,239,'รับตัวว่านเอฮ้อจากบ้านเจ้าแล้ว”\nฟ่านเสียนใจสันสะท้านอีกครา ไม่ทราบว่านี้หมายความว่าอย่างไร\nฮ่องเต้รับสังว่า “ไทเฮาต้องการพบเจ้า” ทรงกระแอมกลบเกลือน\nแล้วตรัสว่า “ท่านผู้เฒ่าต้องการดูว่าสามีของว่านเอ้อมีรูปโฉมอย่างไร\nฮ่องเต้ประทับราชรถจากไปแล้ว ภายในเก๋งเงียบสงบลง คงเหลือ\nแต่ฟ่านเสียนกับขันทีน้อยทีวันนี้รับหน้าทีเข็นเก้าอิล้อเลือน\nฟ่านเสียนจับจ้องมองทิศทางทีฮ่องเต้จากไป ดวงตาทอแววเย้ยหยัน\nวบหนึ่ง วันนี้มันได้รับพระราชกระแสให้เข้าวัง แม้เป็นเรื่องกะทันหัน\nยังตั้งความหวังเล็กๆ ว่า บูรุษกลางคนนั้นจะให้ตนเองเห็นภาพวาดนั้น หรือ\nว่าบูรูษกลางคนจะรับสังอันใดต่อตนเอง\nมิคาดสุดท้ายยังคงเป็นการพบกันระหว่างเจ้าชีวิตทรงพระกรุณากับ\nขุนนางจงรักภักดี ในใจอดบังเกิดความผิดหวังมิได้ มันไม่ได้คาดหวังว่า\nบุรุษกลางคนนั้นจะวางพระองค์เป็นบิดาของตนเอง ที่ว่าผิดหวังเพียง\nผดหวงแทนสตรทชอเยยชงเหมย\nดูจากท่าทีที่ฮ่องเต้ทรงปฏิบัติต่อตนเอง แสดงว่าพระองค์ทรงแล้ง\nนำใจ อย่างน้อย ไม่ได้สํานึกบุญคุณหรือรําลึกนึกถึงมารดา หมายความ\nว่าต่อให้ตอนนี้ฮ่องเต้ไว้วางพระทัยตนเอง ต่อให้ยืดถือเป็นขุนนางคนสนิท\nก็เพียงเป็นขุนนางเท่านั้น\nหากว่าสักวันหนึ่งตนเองเปิดเผยชาติกําเนิดว่า ไม่ได้เป็น “ขุนนาง\nจงรักภักดี” ทีมีความดีความชอบในการถวายการอารักขา ก็จะมีส่วนร่วม\nในการขึ้นครองบัลลังก์ นึกถึงตอนนี้ ฟ่านเสียนลอบแค่นหัวร่อในใจ\nตนเองไม่มีความสนใจขึ้นเป็นฮ่องเต้ แต่ขึ้นครองบัลลังก์หรือไม่ มิใช่ปัญหา\nของตนเอง หากอยู่ทีบูรูษกลางคนนั้นให้ตนเองยืนอยู่ในแถวผู้สืบราช\nลลังก์หรือไม่','2026-04-17 09:49:11'),(243,10,240,'เฮอะ บิดาจึงไม่พิสมัย\nหลังจากรําร้องด่าทอในใจ ฟ่านเสียนค่อยสูดลมหายใจคําหนึ่ง ทราก\nว่าตนเองอัดอันตันใจโดยไม่มีเหตุผล เนื่องเพราะหนิงไฉเหยินเป็นเชละ\nหญิงชาวตงอี องค์ชายใหญ่จึงถูกผู้คนถอดถอนสิทธิในการสืบราชบัลลังก\nยิงอย่าว่าแต่ตนเองอยู่ในบทบาทที่ไม่อาจเห็นแสงเดือนแสงตะวัน\nประการ ครังกระโน้นมารดาเสียชีวิตอย่างลึกลับ คงมีปัญหาบางประการที่\nยังไม่ชําระสะสาง ดังนั้นวันนี้ฮ่องเต้จึงไม่กล้ายอมรับตนเอง\nทีสร้างความเคลือบแคลงสงสัยแก่ฟ่านเสียนคือ นับตั้งแต่วันที\nตนเองล่วงรู้ชาติกําเนิดของตนเอง ก็ไม่มีความคิดขึ้นครองบัลลังก์ เหตุใด\nวันนิจึงนิกเปรยบเทียบขนมา?\nเสียงติกคราหนึ่ง นำหิมะหยดหนึ่งหยดลงจากชายคาเก๋ง ตกลงบน\nบันไดหิน สุ้มเสียงนี้ปลุกฟ่านเสียนตื่นจากห้วงความคิด ทอดตามอง\nทิวทัศน์แรกหิมะตกนอกเก๋ง ลอบทอดถอนใจครุ่นคิด อาจบางทีสภาพ\nแวดล้อมในวังกดดันเกินไป ทําให้ตนเองนึกถึงเรื่องไร้สาระเหล่านั้น\nขันทีน้อยหงจู้หลุบคิวก้มสายตาบอกกล่าวว่า “ใต้เท้า ถีซือ ยังไม่\nถึงเวลาอาหารคํา ฝ่าบาทรับสังว่าท่านสามารถ เดินเล่นตามสบาย”\nสามารถเดินเล่นในอุทยานหลวงตามสบาย? ตนเองไม่ได้พักรักษา\nตัวที่อุทยานเหมยแล้ว ยังคงอย่าได้ละเมิดข้อห้ามแล้ว\nฟ่านเสียนสันศีรษะกล่าวว่า “เพียงชมดูในเก๋งก็พอ” มันพบว่าขันที\nน้อยสุ้มเสียงสันสะท้าน จึงหยีตาลงราวมีดสองเล่ม กวาดตาสํารวจดูขันที\nน้อยนี้เทียวหนึ่ง มองดูจนขันทีน้อยตื่นเต้นตึงเครียดอยู่บ้าง\n“ถูกแล้ว\n็หลังเหงือหรือ?\nถกแลว','2026-04-17 09:49:11'),(244,10,241,'ฟ่านเสียนยิมออกมากล่าวว่า “ไม่ต้องกลัว ฝ่าบาทเมื่อให้ท่านอยู่รับ\nฟัง ย่อมไว้วางใจท่าน”\nคําพูดนี้ไม่ผิด คําสนทนาระหว่างฮ่องเต้กับฟ่านเสียนในวันนี่ดู\nเหมือนธรรมดา แท้จริงแล้วมีข่าวสารที่ “อุดมสมบูรณ์” วันนี้หงจู้ค่อยทราบ\nจว การต่อสู้ช่วงชิงระหว่างสำนักตรวจสอบกับองค์ชายรอง การแต่งตั้งผู้\nดูแลท้องพระคลัง เป็นฮ่องเต้อนุญาตโดยปริยาย ฟ่านถีซือฉลาดปราด\nเปรือง เป็นที่พอพระทัยของฮ่องเต้ มิหน้าซําฟ่านถีซื่อกำลังจะมีความ\nเคลื่อนไหวใหญ่โต\nหากเรื่องเหล่านี้เผยแพร่ออกไป คงบังเกิดมรสุมอันปันป่วนแล้ว\nหงจู๋ขานรับอย่างน่าเวทนาว่า “บ่าวไม่กล้า”\nฟ่านเสียนมองดูใบหน้าอันขรุขระของขันทีน้อย พลันกล่าวด้วย\nความประหลาดใจว่า “ขันทีก็มีชิงชุนโต้ว หรือ?”\nหงจู๋ทวนคําชิงชุนโต้วอย่างงุนงง จากนั้นเข้าใจว่าหมายความ\nอย่างไร จึงกล่าวด้วยความขุ่นเคืองอยู่บ้างว่า “บ่าวก็ไม่ทราบ”\nที่นอกเก๋งเงียบสงบ ที่ห่างไปมีนางกํานัลเดินเห็นไปมา รอบบึงนำ\nเย็นเยือก มีลมโชยพัดมา ช่วยดับความรุ่มร้อนในใจคน ฟ่านเสียนยืมพลาง\nกลาววา “ทาน คอหงลู?','2026-04-17 09:49:11'),(245,10,242,'','2026-04-17 09:49:11'),(246,10,243,'ท่ยนยุทยานหสาน (3)\nหงจู้คิดไม่ถึงว่าใต้เท้าถีซือยังรู้จักชือของตนเอง รู้สึกมีหน้ามีตา\nไม่น้อย ขานรับว่า “ถูกแล้ว ยากนักทีใต้เท้าถีซือรู้จักชื่อของบ่าว”\nฟ่านเสียนกล่าวว่า คนรับใช้ใกล้ชิดของฝ่าบาทมีความสำคัญยิง เรา\nเป็นขนนางรังตําแหน่งถีซือสำนักตรวจสอบ ย่อมต้องระวังป้องกัน อย่า\nว่าแต่ก่อนหน้านี้ในขันทีน้อยประจําท้องพระโรงมีคนร้ายปะปนอยู่\nหงจู๋ใจหายวาบ ไม่กล้ากล่าวมากความ ฟ่านเสียนกล่าวเสียง\nอ่อนโยนว่า “ฝ่าบาทเมื่อไว้วางใจท่าน เราผู้เป็นขุนนางย่อมไว้วางใจ\nท่านด้วย ใช่แล้ว ฟังว่าเหล่าไต้ (คนแซ่ได้) ต้องทํางานหนัก?”\nหงจู๊กวาดมองมันแวบหนึ่ง กล่าวเป็นการหยั่งเชิงว่า “ถูกแล้ว ช่าง\nน่าอนาถนัก”\nฟ่านเสียนผงกศีรษะกล่าวว่า “ข้าพเจ้าไม่มีข้อกริ่งเกรงใด เหล่าไต้\nนมการคบหากบขาพเจา เป็นคนไม่เลว ขอเสียวกงกง (คาเรยกขนทน่อย)\nช่วยดูแลด้วย ”\nหงจู๋ยินดียิง เมื่อเดือนก่อนมันยังคาดหวังว่าจะอาศัยได้กงกงเชซือม\nไปสู่ขุนนางหนุ่มผู้นี้ อีกฝ่ายเมื่อกล่าวเซ่นนี้ก็ประเสริฐ จึงรีบกล่าวว่า\nต้เท้ามีคําสัง ไหนเลยกล้าไม่ปฏิบัติตาม?”','2026-04-17 09:49:11'),(247,10,244,'ฟ่านเสียนยิมพลางกล่าวว่า “รบกวนเสียวกงกงแล้ว หลังจากนี้ท\nบ้านมีปัญหาอันใด ให้บอกต่อข้าพเจ้าสักคํา” มันไม่ต้องบอกกล่าวอย่างชัต\n- : ฮฝ : ซัมล\nแจ้ง อีกฝ่ายสมควรรู้จักติดต่อกับตนเองผ่านทางอีกุ้ยผิง\nเมื่อกลับถึงตําหนักเส้าฟางของอีกุ้ยผิง บังเอิญพบกับองค์หญิงใหญ่\nแคว้นเปียฉีซึ่งกลับจากตําหนักไทเฮา ก่อนทีองค์หญิ ใหญ่จะเข้าพิธีวิวาห\nได้ถูกจัดให้พักอยู่ในวัง นางเห็นฟ่านเสียนนั่งอยู่บนเก้าอิ๋ล้อเลือน ต้องใจ\nหายวาบ แต่ว่าทั้งสองไม่สะดวกกับการกล่าวอันใด เพียงแสดงความเคารพ\nแล้วล่าถอยไป\nอกุ๊ยผิงชม้ายมองฟ่านเสียนแวบหนึ่ง กล่าวว่า “เดินทางกลับจาก\nทางเหนือด้วยกัน ไฉนห่างเหินถึงเพียงนี่?\nฟ่านเสียนในยามนี้ไม่ลืมสร้างพันธมิตร วางคนอยู่ในประเทศอื่น\nย่อมไม่ยอมพลาดบุคคลสำคัญเช่นองค์หญิงใหญ่ เพียงแต่อยู่ต่อหน้าผู้คน\nต้องแสร้งเป็นคนแปลกหน้า จึงกล่าว “จะอย่างไรศักดิฐานะแตกต่าง ยัง\nบูรุษสตรมข้อห้าม”\nอกยผงสพยอกวา เด็กผู้นี้ยังงดงามกว่าสตรี ไม่กลัวท่านคิดร้าย\nเพียงกลัวผู้อื่นตอแยท่าน”\nฟ่านเสียนสะดตุ้งเฮือกกล่าวว่า “ (น้าสาว) อย่าได้กล่าวเหลวไหล\nไป” พอเหลียวหน้ามอง เห็นองค์ชายสามยังนั่งคัดหนังสือ ไม่ทราบเพราะ\nเหตุใดต้องมีโทสะขึ้นมา ถามว่า “เรื่องนี้ไทเฮาอนุญาตจริงๆ?\nนำเสียงแสดงว่าไม่ยอมเชือ อิกุ้ยผิงผงกศีรษะยืนยัน ปากกล่าวว่า\nวันนี้เราค่อยทราบจากฝ่าบาท แต่ว่า นี้เป็นเรื่องทีดี ไทเฮาไหนเลย\nคัดค้านว”\nฟ่านเสียนครุ่นคิด เรื่องราวไม่รวบรัดเพียงนี่ มันขบคิดแล้วกล่าว\n“ข้าพเจ้าไปยังแดนเจียงหนั้น เสียวซัน (สามน้อย) ตามข้าพเจ้าไป ท่าน','2026-04-17 09:49:11'),(248,10,245,'หักใจได้หรือ?”\nอีกุ้ยผิงตอบว่า “แดนเจียงหนั้นธารนำใสทิวทัศน์งดงาม มีอันใด\nไม่อาจหักใจ?”\nนางพลันกวักมือให้ฟ่านเสียนเข้าใกล้กว่านี้ ฟ่านเสียนปฏิบัติตาม\nอยู่ห่างจากนางเพียงหนึ่งเชียะ สามารถสูดได้กลินหอมดังกล้วยไม้จากเรือน\nร่างสตรีสูงศักดิ ได้ยินนางลดสุ้มเสียงเบาลงกล่าวว่า “ท่านนำมันออกจาก\nวังยิงไกลยิงดี ทางที่ดีลากถ่วงสักหลายปี”\nฟ่านเสียนงงงันวูบ ค่อยทราบว่าอีกุ้ยผิงคิดอ่านในทางร้าย จึงสัน\nศีรษะกล่าวว่า “เอาแต่หลีกเลียงมิใชวิธีทีดี อีกประการ การไปตรวจท้อง\nพระคลังแดนเจียงหนั้นใช้เวลาไม่นาน ข้าพเจ้าไม่อาจลากถ่วงไป”\nอิกุ้ยผิงขบคิดดู รู้สึกมีเหตุผล ต้องทอดถอนใจกล่าวว่า “คําพูดนี่\nไม่ผิด ฝ่าบาทก็ไม่ยินยอมให้ท่านอยู่ห่างจากมหานคร”\nฟ่านเสียนขบคิดแล้วปลอบโยนว่า “เสียวซันอายุยังเยาว์ มิต้อง\nวุ่นวายใจแต่เนินๆ อีกประการ ไทเฮาอยู่ในวังเฝ้าดูเด็กเหล่านี้ ต้องไม่\nปล่อยให้ผู้ใดกระทําเรื่องหลุดจากกรอบ ” หยุดเล็กน้อยจึงกล่าวอีกว่า “จะ\nอย่างไรพวกเราต่างจากตําหนักหลังอืน คนที่ตรอกสังซูมีสิทธิมีเสียงอยู่บ้าง\nท่านพ่อก็ยังไม่ถอนตัว อย่างน้อยยังมีข้าพเจ้า\nอิกุ้ยผิงพอได้รับคํามันสัญญานี้ ค่อยคลายใจลง ดูจากสภาพการณ์\nฟ่านเสียนยิงมายิงทรงอิทธิพลในราชสำนัก ที่ผ่านมาในวังกับในราชสำนัก\nแยกออกเป็นเอกเทศ ขอเพียงมีคนอยู่ในราชสำนัก นางกับองค์ชายสาม\nสองแม่ลูกสมควรอยู่ในวังอย่างสุขสบาย\nในสายตาของอี๋กุ้ยผิงซึ่งยังรักษาความเปิดเผยอยู่หลายส่วน เห็นว่า\nหากตัวเองนึกถึงราชโอรสย่อมต้องแนบแน่นอยู่กับตระกูลฟ่าน\nฟ่านเสียนเหลือบมององค์ชายสามซึ่งแอบฟังอยู่ แต่ไม่ได้ยินอันใด\nแวบหนึ่ง ปากกล่าวว่า “เสียวซันติดตามข้าพเจ้าสู่แดนเจียงหนั้น มือยู่','2026-04-17 09:49:11'),(249,10,246,'เรื่องหนึ่งที่ท่านต้องอนุญาตข้าพเจ้า”\n“เรื่องอันใด?”\n“ข้าพเจ้าไม่เหมาะกับการเป็นครูบาอาจารย์ ได้แต่อบรมสังสอแ\nเตียนเซียเช่นตีติ บางครั้งอาจกล่าวที่ไม่คารวะ\nอีกุ้ยผิงพอฟังคําอบรมสังสอนเช่นตีตี ก็ยิมระรีนแจ่มใส ไม่ทันนึกถึง\nชะตากรรมของฟ่านซือเจ้อ รีบผงกศีรษะติดต่อกัน\nฟ่านเสียนครุ่นคิด สตรีนางนี้ไฉนยินดีราวกับถูกรางวัลลิวเหอไซ่\nจึงกล่าวเป็นเชิงเลียบเคียงดูว่า “ บางครั้ง อาจจะ ลงมือ\nอีกุ้ยผิงกล่าวตรงๆ ว่า “ต่อให้ลงเท้าก็แล้วแต่ท่าน ขอเพียงยังมีลม\nท่านจะขยีขยําอย่างไรก็ได้\nนางทอดถอนใจแล้วกล่าว “ท่านยังไม่ทราบ เหตุการณ์ทีหอหลังนั้น\nสร้างความแตกตื่นตระหนกแก่เรา ปรกติเพียงทราบว่ามันสนิทสนมกับ\nเหล่าเอ้อ (อันดับสอง) ผู้ใดทราบเหล่าเอ้อกลับยุยงผิงเอ๋อกระทําเรื่อง\nเช่นนั้น ดีที่ท่านระงับเหตุโดยเร็ว ไม่เช่นนั้นไม่ทราบว่าฝ่าบาทจะกริวถึง\nเพียงไหน”\nฟ่านเสียนลอบหัวร่อ ครุ่นคิดว่าราชโอรสของท่านผู้นี้ มิใช่คนใจบุญ\nสูนทาน ถึงแม้มีอายุแปดขวบ แต่ในสมองไม่ทราบซับซ้อนถึงเพียงไหน\nได้ยินอกุ้ยผิงกล่าวเบาๆ ว่า “อบรมสังสอนมันให้เรียบร้อยกว่านี้ ต่อให้\nภายหน้ากลับกลายเป็นจึงอ้องแหยที่อยู่ว่าง อย่างน้อยก็ปลอดภัยไว้เรื่อง\nฟ่านเสียนพอฟัง อดสะท้อนใจมิได้ โลกนี้มีแต่มารดาประเสริฐเลิศ\n1 บทเพลงนี้ขับขานได้ไม่ผิด ทารกที่กําพร้ามารดาคล้ายหญ้าที่ไร้ราก\nชาติกําเนิดของตนเองพิสูจน์ยืนยันความถูกต้องของเนื่อร้องนี้\nสอตเตอรี่','2026-04-17 09:49:11'),(250,10,247,'เนื่องจากยังไม่ถึงเวลาอาหารคํา ทางตําหนักไทเฮาไม่มีข่าวสารอัน\nใด ฟ้านเสียนยินดีที่อยู่ว่าง จึงจับเจ่าอยู่ในตําหนักเส้าฟาง สนทนาด้วย\nเรื่องสัพเพเหระ กับอีกุ้ยผิง ทั้งสองเกี่ยวดองอยู่ก่อน จึงไม่มี ข้อกริงเกรงอัน\nใด มิหน้าซําในวังทีเย็นยะเยือก คล้ายมีแต่ตําหนักของอืกุ๊ย ผิงยังมีนำใจ\nไมตรีอยู่\n“บ่าวคํานับเฉินจวินจู่ (องค์หญิงเฉิน)\nพร้อมกับเสียงร้องขานของนางกํานัลที่ต้านนอก หลินว่านเอ้อถูมือ\nน้อยๆ ทั้งสองข้างเดินเข้ามา วันนี้นางสวมกระโปรงหลายชั้นสีเขียวมรกต\nร่างท่อนบนสวมชุดกันหนาวสีแดงเข้ม ปกเสื้อใช้ขนสุนัขจิ้งจอกเย็บติดไว้\nสองเส้น จึงปุกปุยน่ารักยิ่ง\nฟ่านเสียนบนเก้าอี้ล้อเลื่อนยื่นสองมือออก\nหลินว่านเอ้อเดินเข้ามา วางมือลงบนฝ่ามืออันอบอุ่นของมัน ความ\nเคลื่อนไหวเป็นไปตามธรรมชาติ\nฟ่านเสียนบีบมือน้อยๆ ที่เย็นเฉียบอยู่บ้าง กล่าวด้วยความ\nประหลาดใจว่า “ไฉนรุดมาแล้ว?”\nหลินว่านเอ้อเชิดปากขึ้นกล่าวว่า “อยู่บ้านรอท่านเป็นเวลานาน ไม่\nคนมาถึง ต่อมาซูเหวินเม่าใช้คนมาบอกกล่าว ค่อยทราบว่าท่านถูก\nบิกตัวเข้าวัง ข้าพเจ้าจึงนำต้าเป่ากลับตัวตึก สุดท้ายเพิ่งมาถึงหน้าประตู\nขันทีสกัดไว้ ฉุดลากเข้าวัง ก่อนอื่นเข้าเฝ้าไทเฮา ฮองเฮา ดีที่\nเหนี้ยงเหนี้ยงทั้งหลายล้วนอยู่ในตําหนักไทเฮา มิต้องไปยังตําหนักต่างๆ\nหลังจากสนทนาอยู่หลายคําก็มาหาท่าน”\nฟ่านเสียนกล่าวว่า ใช่แล้ว ต้าเป่าเล่า?” ันห่วงใยทีส สุด คอตา\nจว (พชายภรรยา) ทีโง่งมนั้น\nหลินว่านเอ๋อกล่าวว่า “วางใจเถอะ เย่อเย่อยังอยู่ในบ้าน” พลางรับ\nผ้าขนหนูร้อนจากนางกํานัลมาเช็ดหน้าอย่างลวกๆ จากนั้นนั่งลงทีข้างกาย','2026-04-17 09:49:11'),(251,10,248,'อกุ้ยผิง ถามอย่างยิมแย้มว่า “สนทนาอันใด?\nอี๋กุ้ยผิงดูว่านางกํานัลส่งผ้าขนหนูร้อนให้จวินจู่เช็ดหน้า\nหนาวกับความร้อนปะทะกัน จากนั้นค่อยถ่ายทอดการจัดการของฮ่องเต้ไห\nหลินว่านเอ๋อมองดูฟ่านเสียนด้วยความประหลาดใจ กล่าวว่า\nกําหนดการเช่นนี่หรือ?\nฟ่านเสียนผงกศีรษะรับ ยักไหล่อย่างอับจนปัญญา ดูท่าการเดินทาง\nสู่แดนเจียงหนั้นคงครึกครีนสนุกสนานนัก\nปรากฏขันทีมาถ่ายทอดวาจา เชิญคนบุญหนักศักดิใหญ่ในตําหนัก\nเส้าฟางไปรับประทานอาหารที่ตําหนักหานกวง อกุยผงจงฉุดลากองคชาย\nสามไปล้างหน้าล้างตา และถือโอกาสแต่งเนื่อแต่งตัว\nฟ่านเสียนเห็นมีเวลาว่าง จึงกระซิบถามว่า “ให้ท่านไปแจ้งเรื่องนั้น\nต่อไทเฮาเหนี้ยงเหนี้ยง เป็นอย่างไรบ้าง?”\nหลินว่านเอ้อกวาดมองรอบข้างแวบหนึ่ง แล้วส่ายหน้ากล่าวเบาๆ\nว่า “ท่านคิดถอนหมันเย่อเย่อ กลับไม่หารือกับข้าพเจ้าก่อน อยู่ดีๆ บอก\nออกไป ไทเฮาไหนเลยยินยอม อีกประการข้าพเจ้าเป็นผู้เยาว์ บอกออกไป\nถือว่าเสียมารยาท”\nฟ่านเสียนทอดถอนใจกล่าวว่า “เย่อเย่อไม่ชมชอบ ข้าพเจ้าผู้เป็น\nเกอเกอยังมีหนทางใด แต่ว่าเรื่องนิบอกต่อท่านช้าเกินไปจริง ทั้งคิดอาศัย\n- 80 \' รื่องนี้ให้เรียบร\nเรื่องของหอโอบจันทร์ ในวังไม่พอใจต่อหงเฉิง จัดการเรื่องนี้ให้เรียบร้อย\nไหนเลยคาดคิดว่ามีปัญหาถึงเพียงนี่\nหลินว่านเอ้อขมวดคิวกล่าวว่า “นี้เป็นฝาบาทพระราชทานสมรส\nไหนเลยคิดถอนก็ถอนได้ ท่านผู้นี่ตามใจเย่อเย่อไปแล้ว”\nฟ่านเสียนหัวร่อพลางกล่าวว่า “มีเม่ยเม่ยคนเดียว ข้าพเจ้าไม่รัก\nถนอมนาง จะให้ผู้ใดรักถนอม?”','2026-04-17 09:49:11'),(252,10,249,'หลินว่านเอ้อกล่าวว่า “ข้าพเจ้าเห็นควรให้กงกง (คาเรยกพอผว)\nเข้าวัง ให้ท่านผู้เฒ่ากราบทูลต่อฝ่าบาท พวกเราทั้งสองยังมีนำหนัก\nไม่พอ”\nฟ่านเสียนกล่าวด้วยความกลัดกลุ้มใจว่า “ถึงแม้ทั้งสองตระกูลผิด\nพ้องหมองใจกัน แต่ท่านพ่อยังชมชอบหงเฉิง แม้แต่เรื่องทีหงเฉิงเทียวหอ\nนางโลม ท่านผู้เฒ่ายังเห็นว่าไม่นับเป็นอย่างไร บอกว่าเฝ้าดูหงเฉิงจน\nเติบใหญ่ ทั้งสองตระกูลสนิทสนมกลมเกลียว ไม่อาจแตกหักกันเพราะเอ้อ\nเตยนเซย (องคชายรอง) เป็นต้นเหตุ\nหลินว่านเอ้อหัวร่อคิกออกมากล่าวว่า “ครั้งกระโน้นกงกงท่องแม่นำ\nหลิวจิงจนมีชือเลืองลือ ย่อมไม่เห็นเป็นเรื่องใหญ่โตอยู่แล้ว” คําพูดพอกล่าว\nค่อยรู้สึกตัวว่าบุตรสะใภ้ไม่ควรหัวร่อเยาะพ่อผัว จึงหัวร่อเฮอะฮะกลบ\nเกลื่อนผ่านไป\nฟ่านเสียนนึกถึงเรื่องของเม่ยเม่ย จึงไม่หยอกล้อนาง หวนนึกถึง\nระหว่างนิฟ่านเย่อเย่อพอมีชือเสียงในตึกไท่อี หวังว่าทางด้านไห่ถังมีส่วน\nช่วยเหลือ อย่างน้อยสามารถยืดการแต่งงานออกไปอีกระยะหนึ่ง\nหลินว่านเฮ้อค่อยถามปัญหาสำคัญว่า “จิวจิวเบิกตัวท่านเข้าวังด้วย\nเรื่องอันใด สมควรไม่เพียงเรื่องของเหล่าซันเท่านั้น”\nฟ่านเสียนจับจ้องมองภรรยา พลันยืนมือเชยคางนางเบาๆ ยิมเล็ก\nน้อยไม่กล่าวว่ากระไร หรือจะให้ตนเองบอกต่อนางว่า จิวจิวของนาง\nมอบหมายให้เซียงกงของท่านจัดการมารดาบังเกิดเกล้าของท่านจนยากจน\nยามนั้นอีกุ้ยผิงกับพวกแต่งตัวเสร็จสินพากันออกมา ภายในตําหนัก\nพลันสว่างเจิดจ้า ฟ่านเสียนเหลียวหน้ามอง เห็นอิ๋กุ้ยผิงกับองค์หญิงใหญ่\nแห่งเปยฉีจูงมือกันออกมา ภายใต้เสือผ้าอาภรณ์ขับเน็น สตรีทั้งสองทั้งสูง\nสง่าทั้งงดงาม ฟ่านเสียนอดทอดถอนไจชมเชยมิได้','2026-04-17 09:49:11'),(253,10,250,'องค์หญิงใหญ่ยิมให้กับมัน เดินไปเคียงคู่กับหลินว่านเอ้อซึ่งรู้จักเก้า\nมาก่อน\nเทศกาลตั้งจี เฉกเช่นเทศกาลตรุษจีน วันนี้ราชสำนักชิงงดประทุง!\nกองทัพหยุดพักผ่อน ด่านตรวจปิดลง พ่อค้างดเดินทาง ไม่เพียงแต่\nมหานคร แม้แต่แคว้นเปยฉีทางเหนือก็ผ่านวันนี้อย่างเป็นสุข\nตามธรรมเนี้ยมรัฐชิง วันตั้งจีต้องรับประทานเนื่อแพะ ทุกบ้านซ่อง\nของมหานครปรากฏไอร้อนลอยออกจากห้องครัวที่ทั้งคับแคบและกว้าง\nขวาง ในไอร้อนแฝงกลินเผ็ดร้อนฉุนเฉียว ยังมีกลินสาบของเนื่อแพะ กลิน\nแปลกแยกของเครื่องยาจีน กลินหอมหวานของหัวไชเท้า ผสมผสานกัน\nอย่างลงตัว อบอวลอยู่ตามถนนตรอกซอย ชวนให้ผู้คนดมนำลายสอแท1!\nหยดหยาด\nภายในตําหนักหานกวง ที่โต๊ะแถวสุดท้าย ฟ่านเสียนมองดูเนื่อแพะ\nถูกหั้นเป็นชิ้นเล็กๆ ตลอดจนเห็ดและผักต่างๆ ในชาม ต้องลอบทอดถอน\nใจ เนื้อแพะในวังต่างกับชาวบ้านทั่วไป ปรุงรสอย่างประณีต แต่ขาดความ\nเผ็ดร้อนไป\nไม่มีเต้าหู้หัวไชเท้า เนื้อแพะนี้จะรับประทานอย่างไร ปัญหาสำคัญ\nคือเนื้อแพะเพียงแค่อุ่นเท่านั้น ไม่ลวกจนริมฝีปากด้านชา รับประทานลง\nไปมีรสชาติอันใด?\nดังนั้นมันเพียงฝืนใจดีมนำแกงในชาม พุ้ยข้าวรับประทาน ขบเคียว\nอย่างช้าๆ ยืดเวลาของ “งานเลียงในบ้าน” ที่ไร้รสชาติออกไป ทั้งเพ่งสายตา\nแน่วแน่ ไม่กลิงกลอกวุ่นวาย ฟังคําสนทนาของเชือพระวงศ์ โดยไม่เอ่ย\nปากสอดคํา โดดเดียวราวกับเก้าอิล้อเลือนที่ด้านหลัง\nตําหนักหานกวงเป็นตําหนักไทเฮา ถือเป็นสิงปลูกสร้างทักว้างขวาง\nวันรับประทานขนมบัวลอย','2026-04-17 09:49:11'),(254,10,251,'สุดในวังหลัง ถึงแม้เปรียบกับวังเปยฉีจะสมถะกว่า แต่ยังคงวิจิตรงดงาม\nดไฟสว่างไสว สาดส่องสิงของเครื่องประดับในตําหนักจนแวววาว\nราชโอรสทั้งหลายรับประทานอาหารอย่างเงียบงัน ไม่กล้ามองดูสตรี\nชราด้านบนสุด ตลอดจนฮ่องเต้กับฮองเฮาข้างกายสตรีชรา วันนี้เป็น\nเทศกาลตั้งจี่ ผู้คนมากันพร้อมหน้า รวมทั้งจิ้งอ้องและบุตรภรรยา ยังมืองค์\nชายรองที่ถูกจํากัดบริเวณล้วนเข้าวัง แต่ว่าองค์ชายรองกับหลี่หงเฉิงเห็น\nฟ่านเสียนเข้ามา เพียงงงงันวูบ หาได้อาละวาดออกมาไม่\nฟ่านเสียนที่หางตาชําเลืองมองสตรีชราที่โต๊ะตัวแรก นี่เป็นครั้งแรก\nทีมันเห็นฮองไทเฮา จากคิวขนงรอยย่นของพระนาง คล้ายยังรู้สึกถึงฝี\nและพระทัยอันเด็ดเดียวของสตริชรานางนี้ พระนางประทับอยู่ด้านบนล\nแม้แต่จิงอ้องทีปรกติขวัญกล้าบังอาจ ยังเรียบๆ ร้อยๆ กว่าเดิม\nถึงแม้คนไม่คุ้นเคย แต่คุ้นเคยกับตําหนักหลังนี้ ครั้งก่อนมัน\nประพฤติเป็นขุนโจรขโมยความหอม เคยแวะเวียนมาสองรอบ ค้นหา\nลูกกุญแจจากในช่องลับใต้พระแท่นบรรทมของสตรีชรา นึกถึงตอนนี้ต้อง\nรั้งสายตากลับมา รับประทานข้าวอย่างเงียบงัน\nแว่วเสียงไอของผู้ชราดังมา ฟ่านเสียนก้มศีรษะนิงเงียบงัน เมื่อครู่\nมันเหลือบมองพระพักตร์ฮองไทเฮาแวบหนึ่ง พบว่ามูมพระโอษฐ์ของ\nพระนางตกห้อยลง ก็ทราบว่าท่านผู้เฒ่ามีชีวิตอีกไม่กีปี\n“เฉินยาโถว มานั่งทีข้างกายไอเจีย\nฮองไทเฮาทอดพระเนตรหลานสาวซึ่งนั่งอยู่ไกลแวบหนึ่ง ทั้งเหลือบ\nพระเนตรไปทีฟ่านเสียนซึ่งซ่อนตัวอยู่ในเงามีด รับสังว่า “ทุบหลังทุบไหล่\nให้กับเรา”\nหลนวานเอ อลุกขึ้นอย่างอ่อนข้อย เดินถึงข้างพระวรกาย ฮองไทเฮา\nหมายถึงชอลิวเฮียง\nคําเรียกตัวเองของไทเฮาหรือฮองเฮา','2026-04-17 09:49:11'),(255,10,252,'กระซิบทีข้างพระกรรณของพระนาง ทั้งชม้ายมองฟ่านเสียนที่กำลัง\nรับประทานข้าว คล้ายเล่าเรื่องขบขันอันใด จริงดังคาดหมาย ฮองไทเฮ\'\nทรงพระสรวลออกมา รับสังว่า “ดูท่าเจ้าป้อนมันจนอิมหน้า กระทั้งข้า.\nปลาในวังยังรับประทานไม่ลง”\nพระเสาวนี้ย์แม้แผ่วเบา แต่ยังกระทบโสตทุกผู้คน ล้วนทราบว่ารับ\nสังถึงฟ่านเสียน\nฟ่านเสียนฉุกใจคิด มุมปากปรากฏรอยยิมวูบหนึ่ง ครุ่นคิดว่าว่าน\nเอ้อเป็นคนโปรดในวัง คาดว่าไม่แปลกปลอม ขอเพียงฮองไทเฮากับฮ่องเต้\nทรงโปรดนาง ย่อมมีศักดิฐานะอันโดดเด่นในวัง\nข ๕ ๕ ม & ม\nแต่มันยังตื่นเต้นตึงเครียดเล็กน้อย วันนี้เป็นครั้งแรกที่มันเข้าเฝ้า\nฮองไทเฮา แต่สายพระเนตรทีพระนางกวาดมายังตนเองเป็นครั้งคราว กลับ\nสร้างความเย็นเยือกแก่มัน ตามเหตุผลไหน่ไหน (พระอัยกี) ทอดพระเนตร\nหลานจากป่าดอย ไม่สมควรมีสายพระเนตรเช่นนี้ สายพระเนตรนั้นสับสน\nยิง ทั้งปลาบปลิมหนึ่งส่วน ภาคภูมิสองส่วน เคลือบแคลงสามส่วน\nส่วนเป็นความตื่นตัวและเกรียวกราด\nฮองไทเฮาพอรับสัง ทุกคนล้วนหยุดการรับประทาน ได้ยินพระนาง\nตรัสว่า “วันนี้ผู้คนมากันพร้อมหน้า ปีก่อนไอเจียไม่สบาย จึงไม่ได้พบปะ\nสังสรรค์ วันนี่เห็นรูปลักษณะของราชบุตรเขย ไอเจียบังเกิดความยินดี\nฮองไทเฮารับสังว่ายินดี แต่พระพักตร์ปราศจากความรู้สึกใด หันไป\nตรัสต่อฮ่องเต้ว่า “แต่ว่าเม่ยเม่ย (พระขนิษฐา) ของท่านต้องอยู่ที่แดนซิน\nหยาง ถือว่าไม่ถูกต้อง แม้แต่ราชบูตรเขยผู้นี่ยังอยู่ในมหานคร นางเป็น\nสตรีต้องออกจากวัง เราไม่ชมชอบ”\nฟ่านเสียนแค่นหัวร่อในใจ ทราบว่าในที่สุดเอ่ยถึงหัวข้อสำคัญแล้ว\nความหมายของพระนางชัดแจ้งยิง แม้แต่ตนเองที่เป็นราชบูตรเขยยัง\nสามารถเข้าร่วมงานเลี้ยงของราชวงศ์ เหตุใดจ่างกงจู่ไม่สามารถ?','2026-04-17 09:49:11'),(256,10,253,'พระเนตรฮ่องเต้ทอประกายวาบ ขานรับว่า “อากาศหนาวเย็นลง\nการเดินทางยากลําบาก รอถึงฤดูใบไม้ผลิ ก็ให้หวินรุ่ยกลับมาเถอะ”\nฮองไทเฮาพอทรงสดับเช่นนั้น จึงผงกพระเศียรด้วยความพอพระทัย\nฟ่านเสียนสังเกตเห็นแขนเสือข้างซ้ายขององค์ชายรองทีฝังตรงข้ามสัน\nระริก คาดว่าท่านพีที่ถูกตนเองจัดการอย่างสาหัสทราบว่ากำลังหนุนใกล้\nมาถึง สร้างความพลุ่งพล่านใจสุดระงับ\nแต่ว่าไทจือไฉนมีสีหน้าประหลาดพิกลอยู่บ้าง?\nหลังจากนั้นฟ่านเสียนไม่สนใจว่าบนโต๊ะสนทนาว่ากระไว งานเล่ยง\nของราชวงศ์ไร้ความสนุกสนานจริงๆ เพียงแต่บางครั้งได้ยินสอถงไทเลา\nรับสังถึงตนเอง กลับแสดงความชีดชาออกมา ทําให้มูมปากมันปรากฏนกม\nยิมเยาะเย้ยตนเองขึ้น\nมันฟังว่าขณะที่ตนเองรับบาดเจ็บ ฮองไทเฮาทรงสวดมนต์ให้กัา)\nตนเอง ทั้งพระราชทานไข่มูกให้ ความจริงเข้าใจว่าพระนางใจอ่อนแล้ว มิ\nคาดดูจากสภาพการณ์ เป็นตนเองเพ้อเจ้อไป\nเอาเถอะ ทั้งหมดประลองว่าผู้ใดใจแข็งกว่า พวกท่านทีเป็น\nครอบครัวเจ้าชีวิตไร้นำใจ ตัวเราเป็นตัวประหลาดตายแล้วเกิดใหม่ ไม่ได้\nใจอ่อนเท่าใด อย่างน้อยยังแข็งกว่าเนื้อแพะในนำแกงเย็นชีดอยู่สามส่วน\nในเมื่อเจ้าชีวิตมิใช่เจ้าชีวิต ขุนนางมิใช่ขุนนาง บิดามิใช่บิดา ผู้บุตร\nมิใช่ผู้บุตร ท่านย่ามิใช่ท่านย่า ผู้หลานมิใช่ผู้หลาน ตนเองยังนึกถึงความ\nสัมพันธ์ทางสายเลือดซึ่งไม่พึงมีไยกัน?\nถึงแม้ว่าฟ่านเสียนได้ชือว่าเป็นคนคัดลอกความเรียง แต่จะอย่างไร\nยังนิยมวรรณศิลป์ กอปรด้วยความทระนงถือดี เมื่ออยู่ในตําหนักหานกวง\n\' \' ส ญิ เซห\nแต่ถูกทอดทิงชีดชา กลับยืดอกขึ้น ถึงแม้แย้มยิม แต่ก็ไม่ประจบประแจง\nฮองไทเฮา ยิงไม่ลดตัวลงเป็นผู้หลานแลกกับการโปรดปราน','2026-04-17 09:49:11'),(257,10,254,'นอกจากฮองไทเฮาแล้ว เหล่าพระชายาและราชโอรสในตําหนักล้วน\nคุ้นเคยกับฟ่านเสียนเป็นอย่างดี ทราบว่าราชบุตรเขยผู้นี้ไม่ธรรมดา ความ\nจริงถนัดในการพะเน้าพะนอ ดังนั้นไม่เข้าใจว่าฟ่านเสียนไฉนไม่ฉวยโอกาส\nงานเลี้ยงในครอบครัวประจบเอาใจฮองไทเฮา\nฮองเตกลบทรงดารวา ฟ่านเสียนโกรธแค้นที่จ่างกงจู่กำลังจะก บส\nมหานคร จนเสียกิริยาไปบ้าง ฮองไทเฮาก็เข้าพระทัยว่า คนหนุ่มผู้นี้เย่อ\nหยิงยโสมาแต่กําเนิด พระทัยยิงไม่โปรดปราน\nฮองเฮาทอดพระเนตรเช่นนั้น ไม่เข้าพระทัยว่าฟ่านเสียนคิดทําอะไร\nหางพระเนตรจึงทอแววเคลือบแคลงสงสัย หนิงไฉเหยินกลับดิมสุราอย่าง\nอาจหาญ สูกุ๊ยเฟยเม้มริมฝีปาก ส่วนอิกุ้ยผิงหัวร่ออย่างโง่งม สรว้างความ\nเบิกบานพระทัยแก่ฮองไทเฮา ช่วยให้ฟ่านเสียนรอดพันจากการถูกจับตา\nส่วนบุคคลทีเหลือ องค์ชายใหญ่เลอะเลือนงมงาย องค์ชายรองลอบ\nกระหยิมยินดี องค์ชายสามนิยมเลือมใส ไทจือจิตใจเลือนลอย มีแต่จึงอ้อง\nที่คาดเดาใกล้เคียงกับความเป็นจริง ครุ่นคิดว่านักศึกษาหัวโบราณครําครี\nหลินว่านเอ้อทีข้างพระวรกายฮองไทเฮา ต้องกวาดมองฟ่านเสียน\nด้วยความห่วงใยแวบหนึ่ง\nใต้ราตรีเหน็บหนาว เกล็ดหิมะโปรยปรายอีกครา ทีประตูข้างของวัง\nหลวง ฟ่านเสียนนั่งบนเก้าอิล้อเลือน ก้มศีรษะใช้ความคิด หลินว่านเอือ\nหงเล่าวด้วยความเป็นห่วงว่า “เซียงกง ไม่เป็นไรกระมัง?”\nฟ่านเสียนตอบว่าไม่เป็นไร กล่าวว่า “ข้าพเจ้าเพียงสวมรอยเป็น\nเต็กปวยเกีย เท่านั้น”\nพยัคฆ์พิทักษ์กับกำลังกลุ่มย่อยของหวังฉีเหนี้ยนมาถึงแล้ว สองสามี\nตัวละพไนพเล็กตฟ้า สังกัดตึกหกหุนครึ่ง','2026-04-17 09:49:11'),(258,10,255,'ภรรยาขีนรถไป รถม้าแล่นกลับตึกตระกูลฟ่าน หลินว่านเอ้อภายในรถกล่าว\nด้วยความสงสัยอยากรู้ว่า เด็กปวยเกียเป็นใคร?\nฟ่านเสียนตอบว่า “คนที่กัมศีรษะชั่วชีวิต” จากนั้นยืมออกมากล่าว\nว่า “อย่าได้เอ่ยถึงมันแล้ว รีบกลับบ้านไปรับประทานเนื้อแพะเถอะ ท่าน\nพอกบพวกสมควรยงรออยู่','2026-04-17 09:49:11'),(259,10,256,'เมื่อดําเนินเหตุการณ์พ่านไปประมาณ 80 เบือร์เซ็นต์แล้ว\nผู้อ่านจึงจะค่อยๆ กระจ่างไนปริศนากุ้งหมด และอดไม่ได้ที่ต้องชูนิ้วไป่งให้\nเพื่อแสดงกวามซี่นบฝีมือบองพู้ประพันธ์\nหนังสือเล่มนี้เป็นหนังสือดีกีมีรางวัลการันด์จากภารไหวห\nของผู้อ่านเว็บไซต์ภาษางินว่า เป็นหนึ่งในสิบสุดยอดพลงานแห่งศวรรษ\nพบจึงขอเบียนคํานำเสนอสันๆ เพียงแก่นี้\nไม่จําเป็นต้องพรรณนบาอะไรมาก ส่วนอื๋นๆ กีเหลือ\nก่านผู้อ่านสามารถสัมพัสได้ด้วยตนแองตั้งแต่บทถี่หนึ่งเป็นต้นไป\nถ่อศักดิ์ ไธยรัศมีศักดิ์\nสำหรับกับพม ไม่ไต้แปลเรื่องจีนกำลังภายในแนวนี้เป็นเวลานานแล้ว ญี่\n! เมื่อพบเจอเจื่องกี่ถูกใจ จึงกถอดความเป็นภาษาไทยอย่างลืนไหล\nหวังว่าทํานผู้อํานจะได้รับความตื่นตาดืนใจ\nเนื่องเพราะตลอดทั้งเงื่องเกิดระลอกสลืนหนุนเนื่อง\nขมวดปมปริศนาไม่หมยุดหย่อน หากไม่อํานถึงหน้าสุดท้าย\nไม่สามารถกหาดเดาตอนจบยของเงื่องได้\nน.นแพรัตน์','2026-04-17 09:49:11');
